    def on_close(self) -> None:
        """Fecha a interface imediatamente, sem aguardar auxiliares."""
        if getattr(self, "_closing_now", False):
            return
        self._closing_now = True
        for active_run in tuple(self.panel_runs.values()):
            active_run.stop_now()
        processes = [self.scrcpy_process, *self.grid_scrcpy_processes.values(), *self.warm_scrcpy_processes.values()]
        pids = {int(process.pid) for process in processes if process is not None and process.poll() is None}
        # Um processo substituÃ­do durante uma troca antiga pode nÃ£o estar mais
        # nos mapas acima. Ainda assim ele Ã© filho direto desta instÃ¢ncia, logo
        # Ã© seguro encontrÃ¡-lo e encerrÃ¡-lo sem tocar em scrcpy externo.
        script = (
            f"Get-CimInstance Win32_Process -Filter 'ParentProcessId={os.getpid()}' | "
            "Where-Object { $_.Name -eq 'scrcpy.exe' } | Select-Object -ExpandProperty ProcessId"
        )
        try:
            result = subprocess.run(
                ["powershell.exe", "-NoProfile", "-NonInteractive", "-Command", script],
                capture_output=True, text=True, timeout=0.8,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
            pids.update(int(value.strip()) for value in result.stdout.splitlines() if value.strip().isdigit())
        except (OSError, subprocess.SubprocessError):
            pass
        for process in {item for item in processes if item is not None}:
            try:
                if process.poll() is None:
                    process.terminate()
            except OSError:
                pass
        # terminate() sozinho pode deixar o servidor SDL do scrcpy aberto por
        # alguns segundos. taskkill /T encerra a Ã¡rvore de cada janela antes
        # de a interface desaparecer, sem bloquear o fechamento do Iggents.
        for pid in pids:
            try:
                subprocess.Popen(
                    ["taskkill", "/PID", str(pid), "/T", "/F"],
                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                    creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                )
            except OSError:
                pass
        # O ADB mantém um servidor em segundo plano mesmo depois que o último
        # comando cliente termina. Como ele foi usado pelo Iggents nesta
        # sessão, encerre-o explicitamente para não deixar adb.exe aberto após
        # fechar o programa. Não usamos taskkill: o próprio ADB encerra apenas
        # o seu servidor e preserva qualquer outro processo do usuário.
        try:
            subprocess.run(
                [self.adb.path, "kill-server"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=1.5,
                creationflags=NO_CONSOLE,
            )
        except (OSError, subprocess.SubprocessError):
            pass
        self.destroy()

    def _start_maximized(self) -> None:
        """Abre maximizado, como uma janela normal do Windows."""
        try:
            self.state("zoomed")
        except tk.TclError:
            self.attributes("-zoomed", True)

    def _on_popup_mapped(self, event) -> None:
        """Dá foco às janelas auxiliares assim que terminarem de ser criadas."""
        window = event.widget
        if window is self or not isinstance(window, (tk.Toplevel, ctk.CTkToplevel)):
            return
        key = str(window)
        if key in self._prepared_popup_windows:
            return
        self._prepared_popup_windows.add(key)
        window.after_idle(lambda popup=window: self._prepare_popup_window(popup))

    def _restore_modal_popup(self, _event=None) -> None:
        """Ao restaurar o app, restaura também o popup modal que o bloqueia."""
        try:
            popup = self.grab_current()
            if not popup or popup is self or not popup.winfo_exists():
                return
            popup.after(30, lambda dialog=popup: self._bring_modal_popup_back(dialog))
        except tk.TclError:
            pass

    @staticmethod
    def _bring_modal_popup_back(dialog) -> None:
        try:
            if not dialog.winfo_exists():
                return
            if dialog.state() == "iconic":
                dialog.deiconify()
            dialog.lift()
        except tk.TclError:
            pass

    def _prepare_popup_window(self, window) -> None:
        """Traz um popup à frente, mostra todo o conteúdo útil e foca a edição."""
        try:
            if not window.winfo_exists():
                return
            window.update_idletasks()
            # Se o conteúdo pedir mais espaço que a geometria definida, a janela
            # cresce até caber na tela. Nunca diminuímos uma janela escolhida pelo usuário.
            screen_width, screen_height = window.winfo_screenwidth(), window.winfo_screenheight()
            width = min(max(window.winfo_width(), window.winfo_reqwidth() + 18), screen_width - 70)
            height = min(max(window.winfo_height(), window.winfo_reqheight() + 18), screen_height - 100)
            if width > window.winfo_width() or height > window.winfo_height():
                window.geometry(f"{width}x{height}")
            window.lift()
            # O scrcpy é uma janela nativa externa, posicionada sobre o canvas
            # do Tk. Em alguns Windows ela ignora o ``lift`` comum e acaba
            # cobrindo o diálogo. Elevamos o popup brevemente na ordem nativa
            # e o devolvemos logo depois ao nível normal, acima da tela viva.
            self._raise_popup_above_live_views(window)

            def focus_first_editable(widget) -> bool:
                for child in widget.winfo_children():
                    if isinstance(child, (tk.Entry, tk.Text, ttk.Entry, ctk.CTkEntry, ctk.CTkTextbox)):
                        try:
                            # ``focus_force`` faz o Windows trazer o Iggents e
                            # outras janelas do processo para frente. O foco
                            # normal basta quando o usuário abriu este diálogo.
                            child.focus_set()
                            return True
                        except tk.TclError:
                            continue
                    if focus_first_editable(child):
                        return True
                return False

            window.focus_set()
            focus_first_editable(window)
        except tk.TclError:
            pass

    def _raise_popup_above_live_views(self, window) -> None:
        """Garante que um diálogo do Iggents fique acima das janelas scrcpy."""
        try:
            if not window.winfo_exists() or window.overrideredirect():
                return
            self._suspend_grid_live_views_for_popup(window)
            user32 = ctypes.windll.user32
            handle = wintypes.HWND(window.winfo_id())
            flags = 0x0001 | 0x0002 | 0x0010 | 0x0040  # tamanho/posição/foco preservados
            # Não altere a ordem global das janelas scrcpy: usar HWND_BOTTOM
            # fazia outros programas do Windows aparecerem acima do app ao
            # abrir uma caixa de edição. O diálogo já é transitório do Iggents
            # e ``lift`` é suficiente dentro da ordem normal do aplicativo.
            window.lift()
        except (AttributeError, OSError, tk.TclError):
            pass

    def _suspend_grid_live_views_for_popup(self, popup) -> None:
        """Esconde as janelas nativas enquanto um diálogo do app estiver aberto."""
        key = str(popup)
        if key in self._grid_popups_hiding_live_views:
            return
        self._grid_popups_hiding_live_views.add(key)
        # A tela pode ficar visível provisoriamente apenas enquanto se inspeciona
        # um XML. Ao abrir qualquer outro popup (por exemplo, editar espera),
        # esse modo termina para nenhuma tela nativa cobrir o diálogo.
        inspected = str(self.grid_xml_inspection_serial or "")
        self.grid_xml_inspection_serial = ""
        if inspected:
            self.grid_xml_marker_bounds.pop(inspected, None)
            self._hide_grid_marker(inspected)
        self._hide_grid_markers()
        try:
            user32 = ctypes.windll.user32
            for hwnd in tuple(self.grid_scrcpy_windows.values()):
                if hwnd:
                    user32.ShowWindow(wintypes.HWND(hwnd), 0)  # SW_HIDE
        except (AttributeError, OSError):
            pass

        def restore(event, popup_key=key) -> None:
            if event.widget is not popup:
                return
            self._grid_popups_hiding_live_views.discard(popup_key)
            if not self._grid_popups_hiding_live_views:
                self.after(40, self._restore_grid_live_views_after_popup)

        popup.bind("<Destroy>", restore, add="+")

    def _restore_grid_live_views_after_popup(self) -> None:
        if self._grid_popups_hiding_live_views or self._live_views_hidden_by_minimize:
            return
        if not getattr(self, "app_view_var", None) or self.app_view_var.get() != "celulares":
            return
        for serial, process in tuple(self.grid_scrcpy_processes.items()):
            if process.poll() is None:
                self._place_grid_live_view(serial, process.pid, self.grid_view_session)

    def _visible_user_popup_open(self) -> bool:
        """Indica se um diálogo comum está aberto sobre as telas ao vivo."""
        try:
            return any(
                isinstance(child, (tk.Toplevel, ctk.CTkToplevel))
                and child.winfo_exists()
                and child.winfo_viewable()
                and not child.overrideredirect()
                for child in self.winfo_children()
            )
        except tk.TclError:
            return False

    def _keep_screen_awake(self, adb: Adb, serial: str) -> None:
        """Mantém a tela ligada quando a etapa específica solicitar."""
        if serial not in self.screen_timeout_by_serial:
            try:
                timeout = adb.command("shell", "settings", "get", "system", "screen_off_timeout", timeout=5).strip()
                if timeout.isdecimal():
                    self.screen_timeout_by_serial[serial] = timeout
            except (OSError, subprocess.SubprocessError, RuntimeError):
                pass
        # Alguns Redmi/MIUI repõem este valor após alguns minutos. Escrevê-lo
        # em cada reforço é seguro: o original continua guardado acima para
        # ser restaurado quando o switch for desligado.
        adb.command("shell", "settings", "put", "system", "screen_off_timeout", "2147483647", timeout=5)
        # ``true`` não depende do estado de carregamento USB. Era usado
        # somente ``usb``, que o MIUI pode ignorar quando considera a porta
        # apenas como dados, embora o ADB esteja conectado.
        try:
            adb.command("shell", "svc", "power", "stayon", "true", timeout=8)
        except (OSError, subprocess.SubprocessError, RuntimeError):
            # Androids mais antigos não aceitam ``true``; nesses a forma USB
            # ainda é melhor do que deixar o switch sem efeito.
            adb.command("shell", "svc", "power", "stayon", "usb", timeout=8)
        self.awake_serials.add(serial)

    def _release_screen_awake(self, adb: Adb, serial: str) -> None:
        """Desfaz o manter ligado e restaura o tempo original do telefone."""
        try:
            adb.command("shell", "svc", "power", "stayon", "false", timeout=8)
            previous_timeout = self.screen_timeout_by_serial.pop(serial, None)
            if previous_timeout:
                adb.command("shell", "settings", "put", "system", "screen_off_timeout", previous_timeout, timeout=5)
        finally:
            self.awake_serials.discard(serial)

    @staticmethod
    def _clear_legacy_auto_awake(adb: Adb) -> None:
        """Remove somente a configuração extrema deixada por versões antigas."""
        adb.keep_awake(False)
        timeout = adb.command("shell", "settings", "get", "system", "screen_off_timeout", timeout=5).strip()
        if timeout == "2147483647":
            adb.command("shell", "settings", "put", "system", "screen_off_timeout", "30000", timeout=5)

    def _screen_awake_watchdog(self) -> None:
        """Reforça a tela ligada de todos os celulares conectados.

        O Android puro honra ``stayon`` continuamente, mas alguns MIUI voltam
        ao bloqueio automático depois de uma economia de bateria. A cada 20 s
        reaplicamos a preferência só nos aparelhos marcados e acordamos um
        que tenha sido apagado por essa política.
        """
        if getattr(self, "_closing_now", False):
            return

        def job() -> None:
            if not self.screen_awake_watchdog_lock.acquire(blocking=False):
                return
            try:
                serials = {
                    str(profile.get("serial", ""))
                    for profile in self.device_profiles.values()
                    if profile.get("state") == "device" and str(profile.get("serial", ""))
                }
                for serial in serials:
                    try:
                        adb = Adb()
                        adb.path, adb.serial = self.adb.path, serial
                        self._keep_screen_awake(adb, serial)
                        power_state = adb.command("shell", "dumpsys", "power", timeout=6)
                        asleep = ("mWakefulness=Asleep" in power_state
                                  or "mWakefulness=Dozing" in power_state
                                  or "Display Power: state=OFF" in power_state)
                        if asleep:
                            adb.command("shell", "input", "keyevent", "KEYCODE_WAKEUP", timeout=6)
                    except (OSError, subprocess.SubprocessError, RuntimeError):
                        # Desconectados e aparelhos ainda autorizando ADB são
                        # tentados de novo no próximo ciclo, sem aviso falso.
                        continue
            finally:
                self.screen_awake_watchdog_lock.release()

        self._thread(job)
        self.after(20000, self._screen_awake_watchdog)

    def enable_dark_titlebar(self) -> None:
        """Usa a barra nativa escura e o tom de destaque do iggents no Windows."""
        try:
            self.update_idletasks()
            # O modo escuro do Windows precisa ser habilitado para o processo
            # antes de pintar a moldura. Isso Ã© o mesmo caminho usado por apps
            # nativos e preserva Alt+Tab, a barra de tarefas e Ã¡reas de trabalho.
            try:
                uxtheme = ctypes.WinDLL("uxtheme")
                set_preferred_app_mode = ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_int)(135, uxtheme)
                flush_menu_themes = ctypes.WINFUNCTYPE(None)(136, uxtheme)
                set_preferred_app_mode(2)  # ForceDark
                flush_menu_themes()
            except Exception:
                pass
            value = ctypes.c_int(1)
            hwnd = ctypes.windll.user32.GetParent(self.winfo_id()) or self.winfo_id()
            dwm = ctypes.windll.dwmapi
            try:
                ctypes.windll.uxtheme.SetWindowTheme(hwnd, "DarkMode_Explorer", None)
            except Exception:
                pass
            # 20 funciona nas versões recentes; 19 mantém a compatibilidade
            # com instalações do Windows 10 que ainda usam o atributo antigo.
            # Algumas versÃµes respondem ao atributo 19 e outras ao 20. Aplicar
            # ambos Ã© inofensivo e evita a barra branca em versÃµes intermediÃ¡rias.
            dwm.DwmSetWindowAttribute(hwnd, 19, ctypes.byref(value), ctypes.sizeof(value))
            dwm.DwmSetWindowAttribute(hwnd, 20, ctypes.byref(value), ctypes.sizeof(value))
            # A cor de legenda é aplicada pelo Windows 11. No Windows 10 o
            # modo escuro acima continua sendo usado normalmente.
            caption = ctypes.c_int(0x000000)  # preto
            text = ctypes.c_int(0x00D5A7FF)   # lilás suave: #ffa7d5
            for attr, color in ((35, caption), (36, text), (38, caption)):
                dwm.DwmSetWindowAttribute(hwnd, attr, ctypes.byref(color), ctypes.sizeof(color))
            rounded = ctypes.c_int(2)
            dwm.DwmSetWindowAttribute(hwnd, 33, ctypes.byref(rounded), ctypes.sizeof(rounded))
        except Exception:
            pass

    @staticmethod
    def _set_windows_app_identity() -> None:
        """Evita que o atalho .pyw apareça como uma janela genérica do Python."""
        try:
            ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(WINDOWS_APP_ID)
        except Exception:
            pass

    def _build_window_chrome(self) -> None:
        """Cria uma barra de título preta, independente do tema do Windows."""
        bar = tk.Frame(self, bg="#0c0c0e", height=36, highlightthickness=1, highlightbackground="#302d35")
        bar.pack(side="top", fill="x")
        bar.pack_propagate(False)
        self.window_chrome = bar

        if APP_ICON.exists():
            try:
                icon = Image.open(APP_ICON).convert("RGBA").resize((21, 21), Image.Resampling.LANCZOS)
                self.window_chrome_icon = ImageTk.PhotoImage(icon)
                icon_label = tk.Label(bar, image=self.window_chrome_icon, bg="#0c0c0e", cursor="fleur")
                icon_label.pack(side="left", padx=(11, 7))
                icon_label.bind("<ButtonPress-1>", self._start_window_drag)
                icon_label.bind("<B1-Motion>", self._drag_window)
                icon_label.bind("<Double-Button-1>", lambda _event: self._toggle_window_maximize())
            except Exception:
                pass

        title = tk.Label(bar, text=APP_NAME, bg="#0c0c0e", fg="#f1edf5", font=("Segoe UI Semibold", 10), cursor="fleur")
        title.pack(side="left", fill="y")
        title.bind("<ButtonPress-1>", self._start_window_drag)
        title.bind("<B1-Motion>", self._drag_window)
        title.bind("<Double-Button-1>", lambda _event: self._toggle_window_maximize())

        controls = tk.Frame(bar, bg="#0c0c0e")
        controls.pack(side="right", fill="y")

        def chrome_button(text: str, command, hover: str) -> tk.Label:
            widget = tk.Label(controls, text=text, width=5, bg="#0c0c0e", fg="#d9d4df", font=("Segoe UI", 10), cursor="hand2")
            widget.pack(side="left", fill="y")
            widget.bind("<Button-1>", lambda _event: command())
            widget.bind("<Enter>", lambda _event: widget.configure(bg=hover, fg="#ffffff"))
            widget.bind("<Leave>", lambda _event: widget.configure(bg="#0c0c0e", fg="#d9d4df"))
            return widget

        chrome_button("−", self._minimize_window, "#2b2830")
        self.window_maximize_button = chrome_button("□", self._toggle_window_maximize, "#2b2830")
        chrome_button("×", self.on_close, "#bf315d")
        for widget in (bar, controls):
            widget.bind("<ButtonPress-1>", self._start_window_drag)
            widget.bind("<B1-Motion>", self._drag_window)
            widget.bind("<Double-Button-1>", lambda _event: self._toggle_window_maximize())

    @staticmethod
    def _windows_work_area() -> tuple[int, int, int, int]:
        """Área útil, sem cobrir a barra de tarefas do Windows."""
        try:
            class Rect(ctypes.Structure):
                _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                           ("right", ctypes.c_long), ("bottom", ctypes.c_long)]
            rect = Rect()
            if ctypes.windll.user32.SystemParametersInfoW(48, 0, ctypes.byref(rect), 0):
                return rect.left, rect.top, rect.right, rect.bottom
        except Exception:
            pass
        return 0, 0, 1920, 1080

    def _maximize_window(self) -> None:
        if not self._window_maximized:
            self._normal_window_geometry = self.geometry()
        left, top, right, bottom = self._windows_work_area()
        self.geometry(f"{right - left}x{bottom - top}+{left}+{top}")
        self._window_maximized = True
        if hasattr(self, "window_maximize_button"):
            self.window_maximize_button.configure(text="❐")

    def _restore_window(self) -> None:
        self.geometry(self._normal_window_geometry)
        self._window_maximized = False
        if hasattr(self, "window_maximize_button"):
            self.window_maximize_button.configure(text="□")

    def _toggle_window_maximize(self) -> None:
        if self._window_maximized:
            self._restore_window()
        else:
            self._maximize_window()

    def _start_window_drag(self, event) -> None:
        if self._window_maximized:
            return
        self._drag_origin = (event.x_root - self.winfo_x(), event.y_root - self.winfo_y())

    def _drag_window(self, event) -> None:
        if not self._drag_origin or self._window_maximized:
            return
        dx, dy = self._drag_origin
        self.geometry(f"+{event.x_root - dx}+{event.y_root - dy}")

    def _minimize_window(self) -> None:
        self._restore_borderless_after_minimize = True
        self.overrideredirect(False)
        self.iconify()

    def _on_main_window_unmap(self, event=None) -> None:
        """Oculta as janelas nativas do scrcpy junto com o Iggents."""
        if event is not None and event.widget is not self:
            return
        self.after(20, self._hide_live_views_if_minimized)

    def _hide_live_views_if_minimized(self) -> None:
        try:
            if self.state() != "iconic":
                return
            self._live_views_hidden_by_minimize = True
            user32 = ctypes.windll.user32
            handles = [int(self.scrcpy_window_handle or 0),
                       *(int(hwnd or 0) for hwnd in self.grid_scrcpy_windows.values())]
            for hwnd in set(handles):
                if hwnd:
                    user32.ShowWindow(wintypes.HWND(hwnd), 0)  # SW_HIDE
            self._hide_live_touch_marker()
            for overlay, _canvas in self.grid_marker_windows.values():
                if overlay.winfo_exists():
                    overlay.withdraw()
        except (AttributeError, OSError, tk.TclError):
            pass

    def _on_main_window_map(self, event=None) -> None:
        if event is not None and event.widget is not self:
            return
        self.after(60, self._restore_live_views_after_minimize)

    def _restore_live_views_after_minimize(self) -> None:
        if not self._live_views_hidden_by_minimize or self.state() == "iconic":
            return
        self._live_views_hidden_by_minimize = False
        if getattr(self, "app_view_var", None) and self.app_view_var.get() == "celulares":
            for serial, process in tuple(self.grid_scrcpy_processes.items()):
                if process.poll() is None:
                    self._place_grid_live_view(serial, process.pid, self.grid_view_session)
        elif self.live_view_mode:
            self._resize_embedded_live_view(force=True)

    def _restore_borderless_window(self, _event=None) -> None:
        if not self._restore_borderless_after_minimize or self.state() == "iconic":
            return
        self._restore_borderless_after_minimize = False
        self.after(10, self._restore_borderless_chrome)

    def _restore_borderless_chrome(self) -> None:
        self.overrideredirect(True)
        if self._window_maximized:
            self._maximize_window()

    def _apply_theme(self) -> None:
        # Paleta propositalmente sóbria: fundo quase preto, cartões levemente
        # elevados e violeta discreto inspirado no novo ícone.
        ctk.set_appearance_mode("dark")
        self.configure(bg="#0d0d0f")
        style = ttk.Style(self)
        style.theme_use("clam")
        style.configure(".", background="#0d0d0f", foreground="#d6d2da", font=("Segoe UI", 10))
        style.configure("TFrame", background="#0d0d0f")
        style.configure("Card.TFrame", background="#1a1a1d")
        style.configure("TLabelframe", background="#1a1a1d", bordercolor="#36363c", relief="solid")
        style.configure("TLabelframe.Label", background="#1a1a1d", foreground="#d3b8fa", font=("Segoe UI Semibold", 10))
        style.configure("TLabel", background="#0d0d0f", foreground="#cbc7d0")
        style.configure("Card.TLabel", background="#1a1a1d", foreground="#cbc7d0")
        style.configure("TButton", background="#7038b6", foreground="#f3eef7", borderwidth=0, padding=(11, 7), font=("Segoe UI Semibold", 9))
        style.map("TButton", background=[("active", "#9958e8"), ("pressed", "#5f2fa0")])
        style.configure("TEntry", fieldbackground="#101013", foreground="#e4e0e8", insertcolor="#e4e0e8", bordercolor="#49494f", padding=5)
        style.configure("TCombobox", fieldbackground="#101013", background="#101013", foreground="#e4e0e8", arrowcolor="#c9c1d0", padding=4)
        style.map("TCombobox", fieldbackground=[("readonly", "#101013")], foreground=[("readonly", "#e4e0e8")])
        style.configure("Treeview", background="#161619", fieldbackground="#161619", foreground="#d4d0d8", rowheight=29,
                        borderwidth=0, relief="flat", bordercolor="#161619")
        style.configure("Treeview.Heading", background="#212126", foreground="#d5bbfa", relief="flat", font=("Segoe UI Semibold", 9), padding=8)
        # A árvore da grade é uma visualização de acompanhamento, não o
        # editor completo. Linhas e cabeçalho menores deixam mais etapas
        # visíveis sem alterar o conforto da árvore principal.
        style.configure("GridCompact.Treeview", rowheight=22, font=("Segoe UI", 9))
        style.configure("GridCompact.Treeview.Heading", font=("Segoe UI Semibold", 8), padding=4)
        style.map("Treeview", background=[("selected", "#7037b5")], foreground=[("selected", "#ffffff")])
        style.layout("Treeview", [("Treeview.treearea", {"sticky": "nswe"})])
        style.configure("Horizontal.TProgressbar", background="#df4b82", troughcolor="#29292e", bordercolor="#29292e", lightcolor="#df4b82", darkcolor="#df4b82")
        # Barras discretas, sem as setas e o branco intenso do tema do Windows.
        for scrollbar_style, orient in (("Vertical.TScrollbar", "vertical"), ("Horizontal.TScrollbar", "horizontal")):
            style.configure(scrollbar_style, background="#4c4358", troughcolor="#111114", bordercolor="#111114",
                            lightcolor="#4c4358", darkcolor="#4c4358", arrowcolor="#111114", width=11, arrowsize=0)
            style.map(scrollbar_style, background=[("active", "#715e86"), ("pressed", "#8a70a8")])
            if orient == "vertical":
                style.layout(scrollbar_style, [("Vertical.Scrollbar.trough", {"sticky": "ns", "children": [
                    ("Vertical.Scrollbar.thumb", {"expand": "1", "sticky": "nswe"})
                ]})])
            else:
                style.layout(scrollbar_style, [("Horizontal.Scrollbar.trough", {"sticky": "ew", "children": [
                    ("Horizontal.Scrollbar.thumb", {"expand": "1", "sticky": "nswe"})
                ]})])

    def _apply_logo_palette(self) -> None:
        """Troca as antigas superfícies azuladas por preto, grafite e violeta.

        A interface já possui muitos controles criados em momentos diferentes.
        Esta passada única conserva o funcionamento de cada um e unifica suas
        cores com os tons violeta/rosa presentes no ícone.
        """
        palette = {
            "#171b26": "#0d0d0f", "#202737": "#17171a", "#222938": "#101013",
            "#293246": "#202024", "#2a3345": "#2c2c31", "#303a4d": "#36363c",
            "#334155": "#28282d", "#374151": "#36363c", "#39455b": "#29292e",
            "#465166": "#49494f", "#4a5870": "#414147", "#5a6884": "#56565e",
            "#2f6fed": "#753dc4", "#4b82ee": "#9256e8", "#2458c8": "#5e2fa5",
            "#2d5eb8": "#7039ba", "#8fb7ff": "#c8a4ff", "#a9c7ff": "#d1b6ff",
            "#0d1119": "#0d0d0f", "#151d2b": "#1a1a1d", "#111925": "#161619",
            "#101724": "#101013", "#33435d": "#3b3b41", "#3b4b66": "#49494f",
            "#2b3850": "#29292e", "#3a4c69": "#414147", "#28364c": "#333339",
            "#2d3b52": "#393940", "#1a2536": "#212126", "#365fbe": "#7039ba",
            "#547cf0": "#7b40c9", "#6b90ff": "#9958e8", "#3f65d0": "#5f2fa0",
            "#e7edf7": "#d1ccd6", "#edf3fb": "#d5d0d9", "#eef4ff": "#d8d3dc",
            "#d5e4f4": "#cbc6d0", "#d8e4f6": "#cec9d3", "#dce5f2": "#d0cbd5",
            "#dbe5f2": "#cec9d3", "#c8d5e5": "#c4bfc9", "#b6c4d5": "#b8b3be",
            "#aebbd0": "#aaa5b1", "#aebaca": "#aaa5b1", "#9eafc5": "#9c98a3",
            "#9eafc4": "#9c98a3", "#98a7bb": "#96919d", "#8c9aaf": "#8b8692",
            "#f8fafc": "#e4e0e8", "#ffffff": "#f1edf4", "#fff7f4": "#eee9f0",
        }
        options = ("bg", "background", "fg", "foreground", "highlightbackground",
                   "selectbackground", "insertbackground", "fg_color", "border_color",
                   "hover_color", "button_color", "button_hover_color", "progress_color",
                   "text_color")

        def repaint(widget) -> None:
            for option in options:
                try:
                    value = widget.cget(option)
                    if isinstance(value, str) and value.lower() in palette:
                        widget.configure(**{option: palette[value.lower()]})
                except (tk.TclError, ValueError, AttributeError):
                    continue
            for child in widget.winfo_children():
                repaint(child)

        repaint(self.content)

    def _build_scrollable_content(self) -> None:
        """Mantém toda a interface acessível quando há muitos telefones ou etapas."""
        self.main_canvas = tk.Canvas(self, bg="#0d0d0f", highlightthickness=0, borderwidth=0)
        scrollbar = ttk.Scrollbar(self, orient="vertical", command=self.main_canvas.yview)
        def canvas_scrolled(first, last) -> None:
            scrollbar.set(first, last)
            # O scrcpy e a máscara são janelas nativas sobre a caixa Tk. Ao
            # rolar o Canvas, Tk não emite um Configure na caixa; portanto a
            # posição precisa ser recalculada também por esta rota.
            # A m\u00e1scara \u00e9 uma janela nativa separada. Esconda-a j\u00e1 no
            # primeiro evento de rolagem para ela jamais ficar sobre uma
            # regi\u00e3o que deixou de ser a caixa do telefone.
            self._hide_live_touch_marker()
            self._schedule_live_view_layout()

        self.main_canvas.configure(yscrollcommand=canvas_scrolled)
        scrollbar.pack(side="right", fill="y")
        self.main_canvas.pack(side="left", fill="both", expand=True)
        self.content = tk.Frame(self.main_canvas, bg="#0d0d0f")
        self._content_window = self.main_canvas.create_window((0, 0), window=self.content, anchor="nw")

        def update_region(_event=None) -> None:
            bbox = self.main_canvas.bbox("all")
            if bbox:
                # O conteúdo começa sempre no topo real (0, 0). Sem essa
                # normalização o Canvas podia manter uma região negativa e
                # revelar um vazio enorme antes do cabeçalho.
                self.main_canvas.configure(scrollregion=(0, 0, max(bbox[2], self.main_canvas.winfo_width()),
                                                         max(bbox[3], self.main_canvas.winfo_height())))

        def fit_width(event) -> None:
            self.main_canvas.itemconfigure(self._content_window, width=event.width)

        self.content.bind("<Configure>", update_region)
        self.main_canvas.bind("<Configure>", fit_width)
        self.bind_all("<MouseWheel>", self._scroll_main_content, add="+")

    def _scroll_main_content(self, event) -> None:
        """Rola a página; a lista lateral só segura o scroll enquanto couber."""
        x, y = self.winfo_pointerx(), self.winfo_pointery()
        # Em Celulares, a roda sobre a lista compacta percorre somente suas
        # tarefas; a página geral não pode deslocar essa área de trabalho.
        for compact in tuple(getattr(self, "device_grid_flow_trees", {}).values()):
            try:
                if (compact.winfo_exists()
                        and compact.winfo_rootx() <= x <= compact.winfo_rootx() + compact.winfo_width()
                        and compact.winfo_rooty() <= y <= compact.winfo_rooty() + compact.winfo_height()):
                    step = -int(event.delta / 120)
                    if step:
                        compact.yview_scroll(step, "units")
                    return "break"
            except tk.TclError:
                continue
        action_canvas = getattr(self, "action_buttons_canvas", None)
        if action_canvas and action_canvas.winfo_rootx() <= x <= action_canvas.winfo_rootx() + action_canvas.winfo_width() and action_canvas.winfo_rooty() <= y <= action_canvas.winfo_rooty() + action_canvas.winfo_height():
            step = -int(event.delta / 120)
            first, last = action_canvas.yview()
            at_top = step < 0 and first <= 0.001
            at_bottom = step > 0 and last >= 0.999
            if not (at_top or at_bottom):
                action_canvas.yview_scroll(step, "units")
                return "break"
        if self.main_canvas.winfo_rootx() <= x <= self.main_canvas.winfo_rootx() + self.main_canvas.winfo_width() and self.main_canvas.winfo_rooty() <= y <= self.main_canvas.winfo_rooty() + self.main_canvas.winfo_height():
            self.main_canvas.yview_scroll(-int(event.delta / 120), "units")
        return "break"

    def _schedule_live_view_layout(self) -> None:
        """Reposiciona/hide a máscara quando o conteúdo principal é rolado."""
        if self._live_layout_pending:
            return
        self._live_layout_pending = True

        def apply_layout() -> None:
            self._live_layout_pending = False
            if not getattr(self, "live_view_mode", False) or not hasattr(self, "preview_canvas"):
                self._hide_live_touch_marker()
                return
            try:
                if not self.preview_canvas.winfo_ismapped():
                    self._hide_live_touch_marker()
                    return
                # Se a caixa da tela saiu do viewport da interface, nenhuma
                # parte da máscara pode ficar solta sobre o restante da janela.
                if hasattr(self, "main_canvas"):
                    px, py = self.preview_canvas.winfo_rootx(), self.preview_canvas.winfo_rooty()
                    pw, ph = self.preview_canvas.winfo_width(), self.preview_canvas.winfo_height()
                    cx, cy = self.main_canvas.winfo_rootx(), self.main_canvas.winfo_rooty()
                    cw, ch = self.main_canvas.winfo_width(), self.main_canvas.winfo_height()
                    if px + pw <= cx or px >= cx + cw or py + ph <= cy or py >= cy + ch:
                        self._hide_live_touch_marker()
                        return
                self._resize_embedded_live_view(force=True)
            except tk.TclError:
                self._hide_live_touch_marker()

        self.after_idle(apply_layout)

    def _scroll_stage_tree(self, event):
        """Com o mouse na lista central, a roda nunca rola a página geral."""
        step = -int(event.delta / 120)
        if not step:
            return "break"
        self.tree.yview_scroll(step, "units")
        return "break"

    def _scroll_execution_log(self, event):
        step = -int(event.delta / 120)
        if not step:
            return "break"
        self.inline_log_text.yview_scroll(step, "units")
        return "break"

    def _scroll_embedded_panel_widget(self, event, widget) -> str:
        """Rola só o componente compacto sob o mouse, nunca a página geral."""
        step = -int(event.delta / 120)
        if step:
            widget.yview_scroll(step, "units")
        return "break"

    def _resize_stage_columns(self, event=None) -> None:
        """Mantém todas as colunas visíveis dentro da largura da lista."""
        if not hasattr(self, "tree"):
            return
        available = max(1, int(event.width if event else self.tree.winfo_width()))
        # Grupo, ação, início, fim, duração, espera. Os mínimos impedem que
        # cabeçalhos e tempos fiquem ilegíveis em janelas menores.
        weights = (0.30, 0.14, 0.18, 0.18, 0.11, 0.09)
        minimums = (155, 82, 96, 96, 72, 62)
        widths = [max(minimum, round(available * weight)) for weight, minimum in zip(weights, minimums)]
        overflow = sum(widths) - available
        if overflow > 0:
            # Reduz as colunas de texto primeiro, preservando os campos de
            # duração e espera que normalmente são valores curtos.
            for index in (0, 2, 3, 1):
                reducible = max(0, widths[index] - minimums[index])
                cut = min(reducible, overflow)
                widths[index] -= cut
                overflow -= cut
                if overflow <= 0:
                    break
        for column, width in zip(("#0", "kind", "start", "end", "duration", "delay"), widths):
            self.tree.column(column, width=width)

    def _align_device_status_indicators(self) -> None:
        """Desenha cada indicador no centro exato da linha correspondente."""
        if not hasattr(self, "device_status_canvas"):
            return
        canvas = self.device_status_canvas
        canvas.delete("all")
        rail_height = self.device_list.winfo_height()
        canvas.configure(height=rail_height)
        self.device_switch_rail.configure(height=rail_height)
        for index, state in enumerate(self.device_status_states):
            bounds = self.device_list.bbox(index)
            if not bounds:
                continue
            _x, y, _width, height = bounds
            center_y = y + height / 2
            color = "#22c55e" if state == "device" else "#7c8798"
            canvas.create_oval(9, center_y - 4, 17, center_y + 4, fill=color, outline="")
        for index, switch in enumerate(self.device_row_switches):
            bounds = self.device_list.bbox(index)
            if not bounds or index >= len(self.device_status_states) or self.device_status_states[index] != "device":
                switch.place_forget()
                continue
            _x, y, _width, height = bounds
            switch.place(x=0, y=round(y + (height - 20) / 2))
        for index, switch in enumerate(self.device_screen_switches):
            bounds = self.device_list.bbox(index)
            if not bounds or index >= len(self.device_status_states) or self.device_status_states[index] != "device":
                switch.place_forget()
                continue
            _x, y, _width, height = bounds
            switch.place(x=112, y=round(y + (height - 20) / 2))

    def _vars(self) -> None:
        self.flow_var = tk.StringVar(value=self.panels[0]["id"])
        self.version_var = tk.StringVar(value="Versão 1 (atual)")
        self.version_paths: dict[str, Path] = {}
        self.current_version_label = "Versão 1 (atual)"
        self.version_menu_updating = False
        self.nickname_var = tk.StringVar()
        self.model_var = tk.StringVar()
        self.device_active_var = tk.BooleanVar(value=True)
        self.recording_choice = tk.StringVar()
        self.raw_x_var = tk.StringVar(value="1080")
        self.raw_y_var = tk.StringVar(value="1920")
        legacy_delay_jitter = str(self.settings.get("delay_jitter", "20"))
        self.delay_jitter_down = tk.StringVar(value=str(self.settings.get("delay_jitter_down", legacy_delay_jitter)))
        self.delay_jitter_up = tk.StringVar(value=str(self.settings.get("delay_jitter_up", legacy_delay_jitter)))
        self.position_jitter = tk.StringVar(value=str(self.settings.get("position_jitter", "0")))
        self.end_position_jitter = tk.StringVar(value=str(self.settings.get("end_position_jitter", self.settings.get("position_jitter", "0"))))
        self.speed_jitter = tk.StringVar(value=str(self.settings.get("speed_jitter", "15")))
        self.variations_enabled = tk.BooleanVar(value=bool(self.settings.get("variations_enabled", True)))
        try:
            saved_minimum_delay = max(0, int(self.settings.get("minimum_delay", 400)))
        except (TypeError, ValueError):
            saved_minimum_delay = 400
        self.minimum_delay = tk.StringVar(value=str(saved_minimum_delay))
        self.start_delay_max = tk.StringVar(value=str(self.settings.get("start_delay_max", "0")))
        self.show_touches_var = tk.BooleanVar(value=bool(self.settings.get("show_touches", False)))
        self.progress_value = tk.DoubleVar(value=0)
        self.progress_text = tk.StringVar(value="Aguardando execução.")
        self.action_search_var = tk.StringVar()
        self.action_search_count = tk.StringVar()
        self.tree_search_var = tk.StringVar()
        self.tree_search_count = tk.StringVar()
        self._tree_search_matches: list[str] = []
        self._tree_search_index = -1
        self.execution_log: list[str] = []
        self.nav_rc_debug_xml: dict[str, list[tuple[str, str]]] = {}
        self.log_window: tk.Toplevel | None = None
        self.log_text: tk.Text | None = None
        self.inline_log_text: tk.Text | None = None
        self._last_logged_status = ""
        for variable in (self.delay_jitter_down, self.delay_jitter_up, self.position_jitter, self.end_position_jitter, self.speed_jitter, self.minimum_delay, self.start_delay_max, self.show_touches_var, self.variations_enabled):
            variable.trace_add("write", self._save_settings)
        self.variations_enabled.trace_add("write", self._update_variation_controls)
        self.action_search_var.trace_add("write", self._filter_action_buttons)
        self.tree_search_var.trace_add("write", self._filter_tree_steps)
        self.status = tk.StringVar(value="Conecte o telefone e autorize a depuração USB.")
        self.status.trace_add("write", self._status_to_log)

    def _update_variation_controls(self, *_args) -> None:
        """Mantém visíveis os valores, mas deixa claro quando não são usados."""
        if not hasattr(self, "variation_entries"):
            return
        state = "normal" if self.variations_enabled.get() else "disabled"
        for entry in self.variation_entries:
            entry.configure(state=state)
        if hasattr(self, "status"):
            self.status.set("Novas etapas gravadas usarão variações." if self.variations_enabled.get()
                            else "Novas etapas gravadas ficarão sem variações.")

