    def _build_device_grid_view(self) -> None:
        """Monta a tela de dispositivos conectados, separada do editor."""
        view = self.device_grid_view
        for child in view.winfo_children():
            child.destroy()
        heading = tk.Frame(view, bg="#0d0d0f")
        heading.pack(fill="x", pady=(0, 12))
        tk.Label(heading, text="Celulares conectados", bg="#0d0d0f", fg="#eef3fb",
                 font=("Segoe UI Semibold", 16)).pack(side="left")
        tk.Label(heading, text="Ctrl: gravar toque/arrasto • Alt: reposicionar etapa", bg="#0d0d0f", fg="#94a3b8",
                 font=("Segoe UI", 10)).pack(side="left", padx=(12, 0), pady=(5, 0))
        ctk.CTkButton(heading, text="Atualizar", command=self.refresh_connected_devices_and_views, width=94, height=30,
                      corner_radius=8, fg_color="#2b3850", hover_color="#3a4c69").pack(side="right")
        # A grade é uma área de execução completa: este botão interrompe todas
        # as execuções em curso, mesmo que pertençam a cartões/painéis distintos.
        ctk.CTkButton(heading, text="■■ Parar todos", command=self.stop_all_panels, width=118, height=30,
                      corner_radius=8, fg_color="#7f2937", hover_color="#a23b4b").pack(side="right", padx=(0, 8))
        self.device_grid_log_toggle = ctk.CTkButton(
            heading,
            text="Ocultar logs" if self.device_grid_logs_visible else "Exibir logs",
            command=self.toggle_device_grid_logs,
            width=108,
            height=30,
            corner_radius=8,
            fg_color="#34255a",
            hover_color="#4a3479",
        )
        self.device_grid_log_toggle.pack(side="right", padx=(0, 8))
        ctk.CTkButton(
            heading, text="Limpar todos logs", command=self.clear_all_device_grid_logs,
            width=132, height=30, corner_radius=8, fg_color="#39455b", hover_color="#4a5870",
        ).pack(side="right", padx=(0, 8))
        self.device_grid_layout_toggle = ctk.CTkButton(
            heading, text="Juntar painéis", command=self.toggle_device_grid_layout,
            width=122, height=30, corner_radius=8, fg_color="#39455b", hover_color="#4a5870",
        )
        self.device_grid_layout_toggle.pack(side="right", padx=(0, 8))
        self.device_grid_all_flows_toggle = ctk.CTkButton(
            heading, text="Abrir todas etapas", command=self.toggle_all_device_grid_flow_panels,
            width=136, height=30, corner_radius=8, fg_color="#34255a", hover_color="#4a3479",
        )
        self.device_grid_all_flows_toggle.pack(side="right", padx=(0, 8))
        self.device_grid_cards = tk.Frame(view, bg="#0d0d0f")
        self.device_grid_cards.pack(fill="both", expand=True)
        self._refresh_device_grid()

    def toggle_device_grid_layout(self) -> None:
        self.device_grid_layout_mode = "together" if self.device_grid_layout_mode == "panel" else "panel"
        if hasattr(self, "device_grid_layout_toggle"):
            self.device_grid_layout_toggle.configure(
                text="Separar por painel" if self.device_grid_layout_mode == "together" else "Juntar painéis"
            )
        self._refresh_device_grid(preserve_live_views=True)

    def toggle_all_device_grid_flow_panels(self) -> None:
        """Abre ou fecha de uma vez os resumos de etapas dos celulares ativos."""
        eligible = {
            str(profile.get("serial", "")) for profile in self.device_profiles.values()
            if profile.get("state") == "device" and profile.get("active")
            and str(profile.get("active_panel", "")).strip()
        }
        if not eligible:
            self.status.set("Nenhum celular com painel ativo para abrir as etapas.")
            return
        if eligible.issubset(self.device_grid_expanded_serials):
            self.device_grid_expanded_serials.difference_update(eligible)
            self.status.set("Listas de etapas fechadas.")
        else:
            self.device_grid_expanded_serials.update(eligible)
            self.status.set("Listas de etapas abertas.")
        self._refresh_device_grid(preserve_live_views=True)

    def toggle_device_grid_logs(self) -> None:
        """Alterna os mini logs sem reiniciar as telas ao vivo."""
        self.device_grid_logs_visible = not self.device_grid_logs_visible
        if hasattr(self, "device_grid_log_toggle"):
            self.device_grid_log_toggle.configure(
                text="Ocultar logs" if self.device_grid_logs_visible else "Exibir logs"
            )
        for widget in tuple(self.device_grid_log_widgets.values()):
            if not widget.winfo_exists():
                continue
            serial = str(getattr(widget, "device_grid_serial", ""))
            holder = getattr(widget, "device_grid_log_holder", widget)
            if self.device_grid_logs_visible or serial in self.device_grid_expanded_serials:
                holder.pack(fill="both", expand=False, pady=(0, 5))
            else:
                holder.pack_forget()
        # O log escondido nÃ£o deve deixar uma caixa vazia: cada cartÃ£o volta
        # ao tamanho da tela ao vivo mais seu rodapÃ©.
        for card in tuple(self.device_grid_card_widgets.values()):
            if not card.winfo_exists():
                continue
            serial = str(getattr(card, "device_grid_serial", ""))
            show_log = self.device_grid_logs_visible or serial in self.device_grid_expanded_serials
            card.configure(height=810 if show_log else 590)
            grid_info = card.grid_info()
            if grid_info:
                card.master.grid_rowconfigure(
                    int(grid_info["row"]),
                    minsize=820 if show_log else 600,
                )

    def _grid_log_is_visible(self, serial: str) -> bool:
        """Logs gerais podem ficar ocultos, mas o cartão aberto sempre os mostra."""
        return bool(self.device_grid_logs_visible or serial in self.device_grid_expanded_serials)

    def toggle_device_grid_flow_panel(self, serial: str, panel: str) -> None:
        """Abre/fecha o resumo de fluxo ao lado do telefone na grade."""
        if not panel or panel == "__unassigned__":
            self.status.set("Este celular não possui um painel ativo para exibir etapas.")
            return
        if serial in self.device_grid_expanded_serials:
            self.device_grid_expanded_serials.remove(serial)
            self.status.set(f"Fluxo compacto fechado para {serial}.")
        else:
            self.device_grid_expanded_serials.add(serial)
            self.status.set(f"Fluxo compacto aberto para {serial}.")
        # Abrir o fluxo só reorganiza os cartões. As janelas scrcpy em si
        # permanecem vivas e são encaixadas novamente nos novos hosts.
        self._refresh_device_grid(preserve_live_views=True)

    def _grid_prepare_panel_context(self, serial: str, panel: str) -> None:
        """Sincroniza os controles compactos com o telefone e painel do cartão."""
        if panel and panel != "__unassigned__" and self.flow_var.get() != panel:
            self.select_flow(panel)
        # A troca de painel restaura a última seleção daquele painel. Selecionar
        # o cartão só depois disso evita que "Executar daqui" herde o telefone
        # anterior e misture execuções de painéis diferentes.
        self._select_grid_device(serial)

    def _reload_compact_trees_for_panel(self, panel: str) -> None:
        """Reflete no cartão as alterações feitas por um diálogo do editor."""
        for serial, tree in tuple(self.device_grid_flow_trees.items()):
            try:
                if tree.winfo_exists() and str(getattr(tree, "grid_panel", "")) == str(panel):
                    self._reload_compact_flow_tree(
                        tree, serial, panel, getattr(tree, "grid_fallback_model", "")
                    )
            except tk.TclError:
                pass

    def _grid_run_panel_action(self, serial: str, panel: str, action: str) -> None:
        if action == "record":
            # A gravação depende da seleção e da árvore principal para saber
            # onde inserir a nova etapa.
            self._grid_prepare_panel_context(serial, panel)
            self.start_recording()
        elif action == "stop":
            # O cartão já informa o painel certo; não troque a tela principal
            # apenas para entregar um sinal de parada.
            self.stop_device_execution(serial, panel)
        elif action == "stop_all":
            # Para todos os cartões deste painel, sem encerrar uma gravação
            # que possa estar sendo feita em outro telefone/painel.
            self.stop_all(panel, stop_recording=False)
        else:
            # O cartão pertence a um telefone específico. Portanto sua
            # execução nunca dispara os outros telefones do mesmo painel, nem
            # precisa reconstruir a árvore principal ao trocar de celular.
            self.run_macro(refresh_first=False, run_all_panels=False, only_serial=serial,
                           target_panel=panel)

    def run_all_devices_in_grid_panel(self, panel: str) -> None:
        """Inicia todos os celulares ativos atribuídos ao painel indicado."""
        if not panel or panel == "__unassigned__":
            self.status.set("Atribua os celulares a um painel antes de executar.")
            return
        try:
            maximum = max(0, float(self.start_delay_max.get().strip() or "0"))
        except ValueError:
            messagebox.showwarning("Início aleatório", "Informe um número válido de segundos.")
            return
        self.status.set(f"Iniciando todos os celulares de {self.panel_name(panel)}; início aleatório de até {maximum:g} s.")
        self.run_macro(refresh_first=False, run_all_panels=False, target_panel=panel)

    def stop_device_execution(self, serial: str, panel: str) -> None:
        """Para somente o celular acionado no cartão de Celulares."""
        active_run = self.panel_runs.get(str(panel))
        if active_run is None:
            self.status.set("Este celular não está em execução.")
            return
        with active_run.worker_lock:
            stop_event = active_run.device_stop_events.get(str(serial))
        if stop_event is None:
            self.status.set("Este celular não está em execução neste painel.")
            return
        stop_event.set()
        # A etapa pode estar em um ADB demorado (uiautomator, instalação,
        # swipe etc.). Encerramos somente os subprocessos pertencentes a este
        # serial; os processos dos demais celulares do mesmo painel ficam
        # intactos e seus workers seguem sem esperar por este encerramento.
        with active_run.process_lock:
            processes = tuple(active_run.active_processes_by_serial.get(str(serial), set()))
        for process in processes:
            try:
                if process.poll() is None:
                    process.terminate()
            except (AttributeError, OSError):
                pass
        self._append_execution_log("Execução deste celular interrompida.", str(panel), str(serial))
        self.status.set("Encerrando somente a execução deste celular…")

    def _current_execution_target(self) -> tuple[str, str] | None:
        """Retorna somente o celular que a pessoa estÃ¡ manipulando agora."""
        in_grid = bool(getattr(self, "app_view_var", None) and self.app_view_var.get() == "celulares")
        if in_grid:
            serial = str(getattr(self, "grid_edit_serial", "") or "")
            panel = str(getattr(self, "grid_focused_panel", "") or "")
            if serial and panel:
                return panel, serial
        selected = self.selected_profiles()
        if len(selected) == 1 and selected[0].get("state") == "device":
            return self.flow_var.get(), str(selected[0].get("serial", ""))
        return None

    def stop_current_device(self) -> None:
        """Parada normal: nunca atravessa para outro celular/painel."""
        target = self._current_execution_target()
        if target:
            panel, serial = target
            active_run = self.panel_runs.get(panel)
            if active_run and serial in active_run.active_serials:
                self.stop_device_execution(serial, panel)
                return
        # GravaÃ§Ã£o Ã© uma Ãºnica sessÃ£o local, portanto o botÃ£o comum ainda
        # pode encerrÃ¡-la. NÃ£o usa stop_all nem afeta execuÃ§Ãµes paralelas.
        if self.stop_recording():
            return
        self.status.set("O celular que estÃ¡ sendo manipulado nÃ£o estÃ¡ em execução.")

    def _grid_run_from_item(self, serial: str, panel: str, tree: ttk.Treeview) -> None:
        # A grade compacta usa exatamente o mesmo caminho da lista principal.
        # Isso preserva Nav-R/Nav-S, loops e subgrupos sem uma interpretacao
        # reduzida dos indices da arvore compacta.
        if not self._grid_activate_tree_item(serial, panel, tree):
            self.status.set("Selecione uma etapa ou grupo no cartao do celular.")
            return
        self.run_from_selection(only_serial=serial)
        return
        selected = tree.selection()
        item = tree.focus() if tree.focus() in selected else (selected[0] if selected else "")
        mapping = getattr(tree, "grid_execution_items", {})
        target = mapping.get(item)
        if not target:
            self.status.set("Selecione uma etapa ou grupo no cartão do celular.")
            return
        self._grid_prepare_panel_context(serial, panel)
        kind, group_index, path = target
        if kind == "group":
            self.run_macro(refresh_first=False, run_all_panels=False, only_serial=serial,
                           start_group_index=group_index)
        elif kind == "action":
            self.run_macro(refresh_first=False, run_all_panels=False, only_serial=serial,
                           start_group_index=group_index, start_action_index=path[0],
                           start_inside_special_group=True)
        else:
            self.run_macro(refresh_first=False, run_all_panels=False, only_serial=serial,
                           start_group_index=group_index, start_nested_path=list(path),
                           start_nested_parent_index=path[0] if path else None,
                           start_nested_action_index=path[1] if len(path) > 1 else 0)

    def _grid_run_selected_item(self, serial: str, panel: str, tree: ttk.Treeview) -> None:
        if not self._grid_activate_tree_item(serial, panel, tree):
            self.status.set("Selecione uma etapa no cartão do celular.")
            return
        self.run_selected_action(only_serial=serial)

    def _grid_activate_tree_item(self, serial: str, panel: str, tree: ttk.Treeview) -> bool:
        """Leva a seleção do cartão compacto para a árvore principal."""
        self._focus_grid_task_tree(serial, panel)
        selected = tree.selection()
        if not selected:
            return False
        self._grid_prepare_panel_context(serial, panel)
        mapped = getattr(tree, "grid_source_items", {})
        source_items = [mapped[item] for item in selected if mapped.get(item) and self.tree.exists(mapped[item])]
        if not source_items:
            return False
        # A seleção compacta também precisa carregar o estado aberto/fechado
        # do contêiner. A rotina central de inserção decide entre filho e irmão
        # a partir desse estado; sem esta sincronização um grupo minimizado no
        # cartão podia continuar aberto na árvore principal invisível.
        for compact_item in selected:
            source_item = mapped.get(compact_item, "")
            if source_item and self.tree.exists(source_item) and tree.get_children(compact_item):
                self.tree.item(source_item, open=bool(tree.item(compact_item, "open")))
        focused = tree.focus()
        source_focus = mapped.get(focused) if focused in selected else source_items[0]
        self.tree.selection_set(source_items)
        self.tree.focus(source_focus if source_focus in source_items else source_items[0])
        self.tree.see(source_focus if source_focus in source_items else source_items[0])
        return True

    def _focus_grid_task_tree(self, serial: str, panel: str) -> None:
        """Define o único cartão autorizado a receber Ctrl/Alt na grade."""
        self.grid_edit_serial = str(serial)
        self.grid_focused_panel = str(panel)

    def _grid_tree_shortcut(self, serial: str, panel: str, tree: ttk.Treeview, command: str):
        if command == "run_one":
            self._grid_run_selected_item(serial, panel, tree)
            return "break"
        if command == "run_from":
            self._grid_run_from_item(serial, panel, tree)
            return "break"
        if command == "run":
            self._grid_run_panel_action(serial, panel, "run")
            return "break"
        if command == "select_all":
            # Ctrl+A também deve funcionar sem uma seleção prévia.
            self._grid_prepare_panel_context(serial, panel)
            self.select_all_tree()
            self._reload_compact_flow_tree(tree, serial, panel, getattr(tree, "grid_fallback_model", ""))
            return "break"
        if command in {"focus_start", "focus_end"}:
            # O Treeview compacto Ã© apenas outra visÃ£o da Ã¡rvore principal.
            # Primeiro selecionamos o extremo no cartÃ£o e, em seguida,
            # sincronizamos a seleÃ§Ã£o principal para que Home/End tenham o
            # mesmo resultado nas duas telas.
            items: list[str] = []

            def collect(parent: str = "") -> None:
                for item in tree.get_children(parent):
                    items.append(item)
                    collect(item)

            collect()
            if not items:
                return "break"
            target = items[0] if command == "focus_start" else items[-1]
            tree.selection_set(target)
            tree.focus(target)
            tree.see(target)
            if self._grid_activate_tree_item(serial, panel, tree):
                self.focus_tree_boundary("start" if command == "focus_start" else "end")
                self._reload_compact_flow_tree(tree, serial, panel, getattr(tree, "grid_fallback_model", ""))
            return "break"
        if command in {"boundary_start", "boundary_end"} and not tree.selection() and tree.focus():
            tree.selection_set(tree.focus())
        if not self._grid_activate_tree_item(serial, panel, tree):
            return "break"
        # A árvore principal é a fonte única de verdade para seleção, foco e
        # abertura de grupos. Assim Ctrl+A/Ctrl+E e as seleções por faixa da
        # versão compacta não criam um comportamento paralelo que se perde
        # quando uma etapa é apagada, movida ou colada.
        if command == "expand":
            self.toggle_selected_tree_groups()
            self._reload_compact_flow_tree(tree, serial, panel, getattr(tree, "grid_fallback_model", ""))
            return "break"
        if command in {"boundary_start", "boundary_end"}:
            self.select_tree_boundary("start" if command == "boundary_start" else "end")
            self._reload_compact_flow_tree(tree, serial, panel, getattr(tree, "grid_fallback_model", ""))
            return "break"
        callbacks = {
            "delete": self.delete_selected, "rename": self.rename_group,
            "toggle": self.toggle_enabled_selected, "variation": self.configure_selected_variation,
            "variation_toggle": self.shortcut_toggle_variation,
            "configure": self.configure_selected_from_shortcut, "up": lambda: self.move_selected(-1),
            "down": lambda: self.move_selected(1), "copy": self.copy_selected,
            "cut": self.cut_selected, "paste": self.paste_clipboard,
            "undo": self.undo, "redo": self.redo,
        }
        callback = callbacks.get(command)
        if callback:
            callback()
            # Copiar, selecionar e expandir não devem reconstruir a grade:
            # uma reconstrução encerra e religa todos os scrcpy sem necessidade.
            if command in {"delete", "cut", "paste", "undo", "redo", "up", "down", "toggle", "rename", "variation", "variation_toggle", "configure"}:
                self.after_idle(lambda: self._reload_compact_flow_tree(tree, serial, panel, getattr(tree, "grid_fallback_model", "")))
        return "break"

    def _grid_compact_tree_selected(self, serial: str, panel: str, tree: ttk.Treeview) -> None:
        # Selecionar uma etapa serve apenas para exibir a máscara. Antes isso
        # chamava ``populate_profile`` para cada clique e recarregava o painel
        # inteiro, causando atraso visível. A sincronização com a árvore
        # principal fica para editar, executar ou gravar via Ctrl.
        self._focus_grid_task_tree(serial, panel)
        self._hide_live_touch_marker()
        selected = tree.selection()
        compact_item = tree.focus() if tree.focus() in selected else (selected[0] if selected else "")
        source_item = getattr(tree, "grid_source_items", {}).get(compact_item)
        source_items = [
            source for item in selected
            if (source := getattr(tree, "grid_source_items", {}).get(item))
        ]
        if source_items:
            # Não sincronizamos a árvore principal a cada clique — isso
            # recarregaria o editor escondido — mas a seleção continua sendo
            # recuperável quando a pessoa retornar para ele.
            self.grid_last_stage_context = {
                "serial": str(serial), "panel": str(panel),
                "items": tuple(source_items), "focus": str(source_item or source_items[0]),
            }
        if source_item:
            self.grid_marker_selected_items[serial] = source_item
        revision = self.grid_marker_revisions.get(serial, 0) + 1
        self.grid_marker_revisions[serial] = revision
        self._update_grid_touch_marker(serial, source_item)
        # A janela SDL pode terminar um reposicionamento logo depois do clique
        # e cobrir uma máscara desenhada no mesmo ciclo do Tk. Reafirmamos a
        # seleção depois de a janela nativa estabilizar, sem reconstruir a
        # grade nem mudar o item marcado.
        def reaffirm_marker(target=serial, item=source_item, expected=revision) -> None:
            if self.grid_marker_revisions.get(target) == expected:
                self._update_grid_touch_marker(target, item)
        self.after(45, reaffirm_marker)

    def _grid_edit_compact_tree_cell(self, serial: str, panel: str, tree: ttk.Treeview, event) -> None:
        """Edita início, duração e espera do cartão com um único clique."""
        compact_item = tree.identify_row(event.y)
        compact_column = tree.identify_column(event.x)
        if not compact_item or compact_column not in ("#2", "#3", "#4"):
            return
        tree.selection_set(compact_item)
        tree.focus(compact_item)
        if not self._grid_activate_tree_item(serial, panel, tree):
            return
        source = getattr(tree, "grid_source_items", {}).get(compact_item, "")
        # A árvore principal fica fora da tela enquanto a grade está aberta.
        # Portanto a espera da versão compacta não pode depender do bbox dela.
        if compact_column == "#4":
            updated_delay = self._edit_grid_compact_delay(serial, panel, getattr(tree, "grid_fallback_model", ""), source)
            self._reload_compact_flow_tree(tree, serial, panel, getattr(tree, "grid_fallback_model", ""))
            if updated_delay is not None and tree.exists(compact_item):
                tree.set(compact_item, "wait", f"{updated_delay} ms")
            return
        main_column = "#2" if compact_column == "#2" else "#4"
        try:
            bbox = self.tree.bbox(source, main_column)
        except tk.TclError:
            return
        if not bbox:
            return
        proxy_event = type("CompactTreeEvent", (), {"x": bbox[0] + 3, "y": bbox[1] + 3})()
        self.edit_action_cell(proxy_event)
        self._reload_compact_flow_tree(tree, serial, panel, getattr(tree, "grid_fallback_model", ""))

    def _edit_grid_compact_delay(self, serial: str, panel: str, fallback_model: str, source_item: str) -> int | None:
        """Edita a espera no arquivo do modelo exibido no cartão.

        A grade pode mostrar modelos diferentes ao mesmo tempo. Usar
        ``self.macros`` aqui alterava somente o modelo que estava selecionado
        anteriormente na tela Fluxo, embora o cartão exibisse outro arquivo.
        """
        if not source_item:
            return None
        parts = source_item.split(":")
        saved = self.saved_names.get(serial, {})
        model = self._profile_model(saved, fallback_model, panel)
        # A comparação visual de nomes ("A14" x "a14") não é suficiente:
        # ambos apontam para o mesmo arquivo de macro. Use a mesma chave que
        # define o arquivo para não salvar em uma cópia diferente da que o
        # cartão irá recarregar.
        is_current_model = (
            panel == self.flow_var.get()
            and self._model_file_key(model) == self._model_file_key(self.device_model)
        )
        # O arquivo é a fonte de verdade dos cartões. Alterar apenas a cópia
        # em memória fazia o valor reaparecer e depois voltar ao anterior.
        path = MACROS_DIR / f"{self._model_file_key(model)}_{panel}.json"
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
            groups = payload.get("groups", [])
        except (OSError, ValueError, json.JSONDecodeError):
            self.status.set("Não foi possível abrir o fluxo deste celular para editar a espera.")
            return None

        def nested_values(action):
            kind = action.kind if isinstance(action, Action) else str(action.get("kind", ""))
            field = ("nested_actions" if kind == "subgroup" else
                     "branch_actions" if kind in ("xml_logic", "xml_any_tap") else
                     "nav_rc_actions" if kind == "navigate_rc" else
                     "nav_actions" if kind in ("navigate_r", "navigate_s") else None)
            return (getattr(action, field, None) if isinstance(action, Action) else action.get(field)) if field else None

        try:
            group = groups[int(parts[1])]
        except (IndexError, ValueError, TypeError):
            return None
        if parts[0] == "g":
            if not group.get("navigation_s"):
                return None
            value = simpledialog.askinteger(
                "Espera antes do Nav-S", "Aguardar quantos milissegundos antes de iniciar o Nav-S?",
                initialvalue=max(0, int(group.get("nav_start_delay_ms", 0))), minvalue=0, parent=self,
            )
            if value is None:
                return None
            group["nav_start_delay_ms"] = value
            path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
            if is_current_model:
                self.load_model_groups(panel, model)
                self.refresh_tree()
            self.status.set(f"Nav-S aguardará {value} ms antes de verificar o XML.")
            return value

        is_nested = bool(parts and parts[0]) and set(parts[0]) == {"s"}
        if parts[0] != "a" and not is_nested:
            return None
        try:
            actions = group.get("actions", [])
            indexes = [int(value) for value in parts[2:]]
            for index in indexes[:-1]:
                action = actions[index]
                actions = nested_values(action) or []
            action = actions[indexes[-1]]
        except (IndexError, ValueError, TypeError):
            return None
        value = simpledialog.askinteger(
            "Editar espera", "Aguardar quantos milissegundos depois desta etapa?",
            initialvalue=max(0, int(action.delay_ms if isinstance(action, Action) else action.get("delay_ms", 0))), minvalue=0, parent=self,
        )
        if value is None:
            return None
        if isinstance(action, Action):
            action.delay_ms = value
        else:
            action["delay_ms"] = value
        path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        if is_current_model:
            self.load_model_groups(panel, model)
            self.refresh_tree()
        self.status.set(f"Espera da etapa atualizada para {value} ms.")
        return value

    def _grid_groups_for_device(self, serial: str, panel: str, fallback_model: str) -> list[dict]:
        """Lê as etapas corretas para o modelo daquele telefone sem trocar a tela aberta."""
        saved = self.saved_names.get(serial, {})
        model = self._profile_model(saved, fallback_model, panel)
        path = MACROS_DIR / f"{self._model_file_key(model)}_{panel}.json"
        if path.exists():
            try:
                return self._groups_from_data(json.loads(path.read_text(encoding="utf-8")), migrate_inline_nav_s=False)
            except (OSError, ValueError, json.JSONDecodeError):
                return []
        # Fluxos ainda não salvos só existem na edição principal.
        if (panel == self.flow_var.get()
                and self._model_file_key(model) == self._model_file_key(self.device_model)):
            return self.macros.get(panel, [])
        return []

    def _reload_compact_flow_tree(self, tree: ttk.Treeview, serial: str, panel: str, fallback_model: str) -> None:
        """Atualiza somente a árvore compacta, sem reiniciar as telas ao vivo."""
        # A árvore compacta é outra visualização da principal. Mantemos a
        # posição de rolagem; abertura/foco/seleção são restaurados abaixo a
        # partir da árvore principal, que é a fonte de verdade.
        try:
            previous_scroll = tree.yview()[0]
        except tk.TclError:
            previous_scroll = 0.0
        tree.delete(*tree.get_children())
        tree.grid_execution_items = {}
        tree.grid_source_items = {}

        def source_item(kind: str, group_index: int, path: tuple[int, ...]) -> str:
            if kind == "group":
                return f"g:{group_index}"
            if kind == "action":
                return f"a:{group_index}:{path[0]}"
            return f"{'s' * (len(path) - 1)}:{group_index}:" + ":".join(str(value) for value in path)

        labels = {
            "tap": "Toque", "swipe": "Arrasto", "xml_tap": "XML", "xml_logic": "XML condicional", "xml_list": "Lista de XMLs",
            "subgroup": "Subgrupo", "navigate_r": "Nav-R", "navigate_s": "Nav-S", "navigate_rc": "Nav-R-C",
            "number_code_not_received": "Código não chegou",
        }

        def schedule_divider_text(action: Action) -> str:
            if action.kind == "schedule_divider_end":
                return "────────────────────────────────"
            interval = (
                f"{action.schedule_time_min}–{action.schedule_time_max}"
                if action.schedule_time_min and action.schedule_time_max else "intervalo"
            )
            period = (action.text_value or action.label or "HORÁRIO").upper()
            return f"────────  {interval} · {period}  ────────"

        def action_start(action: Action) -> str:
            if action.kind == "xml_tap":
                return action.selector_value or "XML"
            if action.kind in ("xml_logic", "xml_group_gate", "xml_restart_loop"):
                return action.selector_value or "texto"
            if action.kind == "navigate_s":
                return action.nav_s_query or "XML"
            if action.kind == "xml_any_tap":
                return f"{len(action.branch_actions or [])} XML"
            if action.kind == "xml_list":
                return f"{len(action.xml_list_queries or [])} XML"
            if action.kind in ("tap", "swipe", "nav_rc_scroll"):
                return f"{action.x}, {action.y}"
            if action.kind == "key":
                return action.keycode or "tecla"
            return action.selector_value or action.text_value or "—"

        def action_duration(action: Action) -> str:
            if action.kind == "xml_tap":
                return f"{action.timeout_s:g} s"
            if action.kind == "swipe":
                return f"{action.duration_ms} ms"
            return "—"

        def draw_actions(parent_id: str, group_index: int, actions: list[Action], path_prefix: list[int]) -> None:
            for index, raw in enumerate(actions):
                action = raw if isinstance(raw, Action) else Action(**raw)
                path = [*path_prefix, index]
                item_id = f"grid:{serial}:{panel}:{group_index}:" + ":".join(str(value) for value in path)
                is_schedule_divider = action.kind in ("schedule_divider", "schedule_divider_end")
                tree.insert(parent_id, "end", iid=item_id,
                            text=schedule_divider_text(action) if is_schedule_divider else (action.label or f"Etapa {index + 1}"),
                            values=("", "", "", "") if is_schedule_divider else
                            (labels.get(action.kind, action.kind), action_start(action), action_duration(action), f"{action.delay_ms} ms"),
                            tags=("schedule_divider",) if is_schedule_divider else (), open=False)
                item_kind = "action" if not path_prefix else "nested"
                target = (item_kind, group_index, tuple(path))
                tree.grid_execution_items[item_id] = target
                tree.grid_source_items[item_id] = source_item(*target)
                nested = self._container_actions(action)
                if nested:
                    draw_actions(item_id, group_index, nested, path)

        for group_index, group in enumerate(self._grid_groups_for_device(serial, panel, fallback_model)):
            group_id = f"grid:{serial}:{panel}:g:{group_index}"
            if group.get("schedule_divider_group"):
                divider_values = group.get("actions") or []
                divider = divider_values[0] if divider_values else None
                if isinstance(divider, dict):
                    divider = Action(**divider)
                if isinstance(divider, Action):
                    tree.insert("", "end", iid=group_id, text=schedule_divider_text(divider),
                                values=("", "", "", ""), tags=("schedule_divider",), open=False)
                    tree.grid_execution_items[group_id] = ("group", group_index, ())
                    tree.grid_source_items[group_id] = source_item("group", group_index, ())
                continue
            tree.insert("", "end", iid=group_id, text=str(group.get("name") or f"Grupo {group_index + 1}"),
                        values=(f"{len(group.get('actions') or [])} etapa(s)", "", "", ""), open=False)
            tree.grid_execution_items[group_id] = ("group", group_index, ())
            tree.grid_source_items[group_id] = source_item("group", group_index, ())
            draw_actions(group_id, group_index, group.get("actions") or [], [])

        # A pesquisa da grade não muda a macro: apenas oculta as linhas que
        # não combinam, preservando os pais dos resultados encontrados.
        query = str(getattr(tree, "grid_search_var", tk.StringVar(value="")).get()).strip()
        queries = [part.strip() for part in query.split(",") if part.strip()]
        search_matches: list[tuple[float, str]] = []

        def walk(item_parent: str = ""):
            for item in tree.get_children(item_parent):
                yield item
                yield from walk(item)

        for item in walk():
            tags = tuple(tag for tag in tree.item(item, "tags") if tag != "search_match")
            tree.item(item, tags=tags)
            if not queries:
                continue
            values = " ".join(str(value) for value in tree.item(item, "values"))
            searchable = f"{tree.item(item, 'text')} {values}"
            scores = [self._action_search_score(term, searchable) for term in queries]
            valid_scores = [float(score) for score in scores if score is not None]
            if valid_scores:
                search_matches.append((max(valid_scores), item))

        search_matches.sort(key=lambda entry: -entry[0])
        query_changed = query != getattr(tree, "grid_search_last_query", "")
        tree.grid_search_last_query = query
        tree.grid_search_matches = [item for _score, item in search_matches]
        for _score, item in search_matches:
            tags = tuple(tree.item(item, "tags"))
            if "running" not in tags:
                tree.item(item, tags=(*tags, "search_match"))
            parent = tree.parent(item)
            while parent:
                tree.item(parent, open=True)
                parent = tree.parent(parent)

        # Não deixe Delete/Ctrl+X/Ctrl+V/mover/undo recolher a árvore inteira
        # só porque o cartão precisou redesenhar suas linhas. O estado já
        # calculado na lista normal é reaplicado à lista compacta.
        reverse_items = {source: compact for compact, source in tree.grid_source_items.items()}
        try:
            for source, compact in reverse_items.items():
                if self.tree.exists(source):
                    tree.item(compact, open=bool(self.tree.item(source, "open")))
            if queries:
                for item in tree.grid_search_matches:
                    parent = tree.parent(item)
                    while parent:
                        tree.item(parent, open=True)
                        parent = tree.parent(parent)
            selected = [reverse_items[source] for source in self.tree.selection() if source in reverse_items]
            if selected:
                tree.selection_set(selected)
                focused = self.tree.focus()
                tree.focus(reverse_items.get(focused, selected[0]))
            show_first_match = bool(search_matches and query_changed)
            if show_first_match:
                tree.see(search_matches[0][1])
            else:
                tree.yview_moveto(previous_scroll)
            # ttk calcula a altura real somente depois de voltar ao loop do
            # Tk. Reaplicar a mesma fraÃ§Ã£o depois da montagem impede que um
            # Delete em uma lista compacta pule para o inÃ­cio.
            if not show_first_match:
                tree.after_idle(lambda widget=tree, position=previous_scroll:
                                widget.yview_moveto(position) if widget.winfo_exists() else None)
                tree.after(55, lambda widget=tree, position=previous_scroll:
                           widget.yview_moveto(position) if widget.winfo_exists() else None)
        except tk.TclError:
            pass

    def _build_device_grid_flow_panel(self, parent: tk.Widget, serial: str, panel: str, fallback_model: str) -> None:
        """Cria o painel compacto de controles e etapas da grade de celulares."""
        # Este resumo precisa acompanhar o celular, não disputar largura com
        # ele. Duas colunas são suficientes durante a execução: a etapa e a
        # ação atual. Os demais detalhes continuam disponíveis no editor.
        detail_width = 205
        detail = tk.Frame(parent, bg="#171b26", width=detail_width, height=810,
                          highlightthickness=1, highlightbackground="#6940a8")
        detail.pack_propagate(False)
        tk.Label(detail, text=f"{self.panel_name(panel)} · fluxo", bg="#171b26", fg="#e9d5ff",
                 font=("Segoe UI Semibold", 11)).pack(anchor="w", padx=8, pady=(7, 4))
        toolbar = tk.Frame(detail, bg="#171b26")
        toolbar.pack(fill="x", padx=6, pady=(0, 7))
        toolbar_top = tk.Frame(toolbar, bg="#171b26")
        toolbar_top.pack(fill="x", pady=(0, 4))
        toolbar_bottom = tk.Frame(toolbar, bg="#171b26")
        toolbar_bottom.pack(fill="x")
        # Grade fixa, igual ao layout de referência: duas ações grandes na
        # primeira linha e três ações iguais na segunda. ``pack`` tentava
        # acomodar seis botões e acabava reduzindo/ocultando comandos.
        for column in range(2):
            toolbar_top.grid_columnconfigure(column, weight=1, uniform="compact-top")
        for column in range(3):
            toolbar_bottom.grid_columnconfigure(column, weight=1, uniform="compact-bottom")
        controls = (
            ("● Gravar", "record", "#6d35bb"),
            ("■ Parar", "stop", "#a8394c"),
            ("▶▶ Executar daqui", "run_from", "#39455b"),
            ("▶ Etapa", "run_one", "#39455b"),
            ("▶ Executar", "run", "#39455b"),
        )
        compact_labels = {
            "record": "Gravar", "stop": "Parar", "run": "Executar",
            "run_from": "Daqui", "run_one": "Etapa",
        }
        for index, (text, action, color) in enumerate(controls):
            row = toolbar_top if index < 2 else toolbar_bottom
            ctk.CTkButton(row, text=compact_labels[action],
                          command=(lambda: self._grid_run_from_item(serial, panel, compact))
                          if action == "run_from"
                          else (lambda: self._grid_run_selected_item(serial, panel, compact))
                          if action == "run_one"
                          else (lambda value=action: self._grid_run_panel_action(serial, panel, value)),
                          height=28, corner_radius=7, fg_color=color,
                           hover_color="#8552c7" if action != "stop" else "#c34a5d").grid(
                               row=0, column=index if index < 2 else index - 2,
                               sticky="ew", padx=(0, 4) if index not in (1, 4) else 0,
                           )
        search_var = tk.StringVar()
        search_box = ctk.CTkEntry(
            detail, textvariable=search_var, height=28,
            placeholder_text="Pesquisar etapa neste fluxo…",
        )
        search_box.pack(fill="x", padx=6, pady=(0, 7))
        groups = self._grid_groups_for_device(serial, panel, fallback_model)
        tree_frame = tk.Frame(detail, bg="#0c0e14", highlightthickness=1, highlightbackground="#30394a")
        # Reserva o rodapé dos controles: a árvore cresce apenas até antes
        # dele e nunca pode empurrar “Executar daqui” para fora do cartão.
        tree_frame.pack(fill="both", expand=True, padx=6, pady=(0, 43))
        compact = ttk.Treeview(tree_frame, style="GridCompact.Treeview",
                               columns=("kind", "start", "duration", "wait"), show="tree headings", height=24,
                               selectmode="extended")
        compact.heading("#0", text="Grupo / etapa")
        compact.heading("kind", text="Ação")
        compact.heading("start", text="Início")
        compact.heading("duration", text="Duração")
        compact.heading("wait", text="Espera")
        compact["displaycolumns"] = ("kind",)
        compact.column("#0", width=120, minwidth=108, stretch=True)
        compact.column("kind", width=54, minwidth=50, anchor="w", stretch=False)
        compact.column("start", width=80, anchor="w", stretch=False)
        compact.column("duration", width=55, anchor="e", stretch=False)
        compact.column("wait", width=1, stretch=False)
        compact.pack(side="left", fill="both", expand=True, padx=1, pady=1)
        compact_scroll = ttk.Scrollbar(tree_frame, orient="vertical", command=compact.yview)
        compact_scroll.pack(side="right", fill="y", pady=1)
        compact.configure(yscrollcommand=compact_scroll.set)
        compact.tag_configure("running", background="#1e654a", foreground="#ffffff")
        compact.tag_configure("search_match", background="#3a2851", foreground="#f0d9ff")
        compact.tag_configure("schedule_divider", background="#252138", foreground="#dac4ff")
        compact.grid_fallback_model = fallback_model
        compact.grid_panel = panel
        compact.grid_search_var = search_var
        compact.grid_search_entry = search_box
        self._reload_compact_flow_tree(compact, serial, panel, fallback_model)
        self.device_grid_flow_trees[serial] = compact
        self._render_grid_running_step(
            serial, self.device_execution_states.get(serial, {}).get("running")
        )
        compact.bind("<<TreeviewSelect>>", lambda _event: self._grid_compact_tree_selected(serial, panel, compact))
        compact.bind("<FocusIn>", lambda _event, target=serial, value=panel: self._focus_grid_task_tree(target, value), add="+")
        compact.bind("<ButtonPress-1>", lambda _event, target=serial, value=panel: self._focus_grid_task_tree(target, value), add="+")
        # No painel Celulares Ctrl+F mantém o mesmo propósito da tela
        # principal: abrir a busca de etapas para adicionar ao fluxo.
        compact.bind("<Control-f>", self.focus_action_search)
        compact.bind("<Control-F>", self.focus_action_search)
        search_box.bind("<Control-f>", self.focus_action_search)
        search_box.bind("<Control-F>", self.focus_action_search)
        search_var.trace_add(
            "write", lambda *_args: self._reload_compact_flow_tree(
                compact, serial, panel, getattr(compact, "grid_fallback_model", "")
            ) if compact.winfo_exists() else None,
        )
        compact.bind("<ButtonRelease-1>",
                     lambda event: self._grid_edit_compact_tree_cell(serial, panel, compact, event), add="+")
        for scroll_target in (compact, compact_scroll, tree_frame):
            scroll_target.bind(
                "<MouseWheel>",
                lambda event, target=compact: self._scroll_embedded_panel_widget(event, target),
                add="+",
            )
        footer = tk.Frame(detail, bg="#171b26")
        footer.place(x=6, y=772, width=detail_width - 12, height=31)
        ctk.CTkButton(footer, text="Parar todos",
                      command=lambda: self.stop_all(panel, stop_recording=False),
                      width=88, height=28, corner_radius=7,
                      fg_color="#7f2937", hover_color="#c34a5d").pack(side="left")
        ctk.CTkButton(footer, text="Fechar",
                      command=lambda: self.toggle_device_grid_flow_panel(serial, panel),
                      width=64, height=28, corner_radius=7, fg_color="#2b2d35", hover_color="#3b3e49").pack(side="right")
        shortcuts = {
            "<Alt-Down>": "run_from", "<space>": "run", "<Delete>": "delete", "<F2>": "rename",
            "<F3>": "toggle", "<F4>": "variation_toggle", "<F5>": "variation", "<F6>": "run_one", "<Control-Return>": "configure",
            "<Control-Up>": "up", "<Control-Down>": "down", "<Control-c>": "copy", "<Control-x>": "cut",
            "<Control-v>": "paste", "<Control-z>": "undo", "<Control-y>": "redo", "<Control-e>": "expand", "<Control-a>": "select_all",
            "<Home>": "focus_start", "<End>": "focus_end",
            "<Shift-Home>": "boundary_start", "<Shift-End>": "boundary_end",
            "<Control-Shift-Home>": "boundary_start", "<Control-Shift-End>": "boundary_end",
        }
        for sequence, command in shortcuts.items():
            compact.bind(sequence, lambda _event, value=command: self._grid_tree_shortcut(serial, panel, compact, value))
        compact.bind("<Alt-Double-Button-1>",
                     lambda _event: self._grid_tree_shortcut(serial, panel, compact, "run_from"), add="+")
        compact.bind("<Shift-Double-Button-1>",
                     lambda _event: self._grid_tree_shortcut(serial, panel, compact, "run_one"), add="+")
        return detail

    def _append_device_grid_log(self, serial: str | None, entry: str) -> None:
        """Guarda e exibe uma mensagem no cartão do telefone correspondente."""
        if not serial:
            return
        serial = str(serial)
        entries = self.device_logs_by_serial.setdefault(serial, [])
        entries.append(entry)
        if len(entries) > 120:
            del entries[:-120]
        widget = self.device_grid_log_widgets.get(serial)
        if not widget or not widget.winfo_exists():
            return
        widget.configure(state="normal")
        widget.insert("end", entry + "\n")
        widget.see("end")
        widget.configure(state="disabled")

    def clear_device_grid_log(self, serial: str) -> None:
        """Limpa somente o histórico exibido no cartão desse telefone."""
        self.device_logs_by_serial[serial] = []
        widget = self.device_grid_log_widgets.get(serial)
        if widget and widget.winfo_exists():
            widget.configure(state="normal")
            widget.delete("1.0", "end")
            widget.configure(state="disabled")

    def clear_all_device_grid_logs(self) -> None:
        """Limpa de uma vez os históricos e mini logs de todos os cartões."""
        serials = set(self.device_logs_by_serial) | set(self.device_grid_log_widgets)
        for serial in serials:
            self.device_logs_by_serial[str(serial)] = []
        for widget in tuple(self.device_grid_log_widgets.values()):
            try:
                if widget.winfo_exists():
                    widget.configure(state="normal")
                    widget.delete("1.0", "end")
                    widget.configure(state="disabled")
            except tk.TclError:
                continue
        self.status.set("Logs de todos os celulares limpos.")

    def show_device_grid_xml(self, serial: str, panel: str) -> None:
        """Abre o XML do telefone correspondente ao log da grade."""
        self._grid_prepare_panel_context(serial, panel)
        self.show_current_xml_viewer()

    def _preload_device_grid(self) -> None:
        """Monta os cartÃµes ocultos sem iniciar uma segunda tela scrcpy.

        A lista de aparelhos Ã© atualizada de forma assÃ­ncrona. Preparar a
        grade neste ponto elimina a primeira espera ao entrar em Celulares;
        quando a aba abre, resta apenas mover as janelas scrcpy reservadas
        para os respectivos hosts jÃ¡ existentes.
        """
        self.device_grid_preload_pending = False
        if getattr(self, "_closing_now", False) or not hasattr(self, "device_grid_cards"):
            return
        self._refresh_device_grid()

    def _schedule_device_grid_preload(self) -> None:
        """Agrupa atualizaÃ§Ãµes consecutivas da lista em uma Ãºnica montagem."""
        if self.device_grid_preload_pending:
            return
        self.device_grid_preload_pending = True
        self.after_idle(self._preload_device_grid)

    def _refresh_device_grid(self, preserve_live_views: bool = False) -> None:
        if not hasattr(self, "device_grid_cards"):
            return
        # Uma alteração de layout (abrir/fechar etapas) não precisa matar e
        # reiniciar cada scrcpy. Mantemos a sessão e, ao terminar de montar os
        # cartões, somente movemos as janelas já existentes.
        if not preserve_live_views:
            self.grid_view_session += 1
        session = self.grid_view_session
        self.grid_detail_build_generation += 1
        detail_generation = self.grid_detail_build_generation
        # Durante a reconstrução as caixas dos cartões ainda mudam de lugar.
        # Esconder primeiro evita que uma máscara fique visível sobre o
        # telefone que acabou ocupando a posição antiga.
        self._hide_grid_markers()
        if not preserve_live_views:
            self._stop_grid_live_views(terminate=False)
        cards = self.device_grid_cards
        for child in cards.winfo_children():
            child.destroy()
        profiles = [profile for profile in self.device_profiles.values() if profile.get("state") == "device"]
        eligible_serials = {
            str(profile.get("serial", "")) for profile in profiles
            if profile.get("active") and str(profile.get("active_panel", "")).strip()
        }
        if hasattr(self, "device_grid_all_flows_toggle"):
            self.device_grid_all_flows_toggle.configure(
                text="Fechar todas etapas" if eligible_serials and eligible_serials.issubset(self.device_grid_expanded_serials)
                else "Abrir todas etapas"
            )
        if not profiles:
            tk.Label(cards, text="Nenhum celular conectado no momento.", bg="#0d0d0f", fg="#94a3b8",
                     font=("Segoe UI", 12)).pack(anchor="center", pady=80)
            return
        self.device_grid_hosts = {}
        self.device_grid_screen_labels = {}
        self.device_grid_log_widgets = {}
        self.device_grid_card_widgets = {}
        self.device_grid_title_details = {}
        self.device_grid_flow_trees = {}
        self.grid_macro_screens.clear()
        # A seleção pertence ao serial, não ao widget que acabou de ser
        # recriado. Preservá-la permite restaurar a máscara correta depois da
        # atualização/redisposição dos cartões.
        # CartÃµes seguem a largura de uma tela vertical. Assim a grade usa o
        # espaÃ§o para colocar mais celulares lado a lado, sem sobras enormes
        # dentro de cada cartÃ£o.
        # A tela Android continua com 480 px de altura. Nos aparelhos
        # verticais conectados, 220 px de host preservam exatamente a mesma
        # escala da imagem (limitada pela altura), removendo só as faixas
        # cinzas laterais que sobravam dentro do cartão.
        card_width = 230
        screen_host_width = 220
        detail_width = 205
        available_width = max(cards.winfo_width(), self.winfo_width() - 48)
        # Capacidade real horizontal. Não limite pelo número de celulares:
        # ao abrir etapas, o cartão auxiliar precisa de uma segunda coluna
        # mesmo que exista apenas um telefone nesse painel.
        # A coluna de etapas foi compactada, sem mudar a área da tela ao vivo.
        # A grade trabalha em pares de colunas para os celulares poderem
        # permanecer com suas etapas abertas.
        columns = max(2, (available_width // (card_width + detail_width)) * 2)
        # Uma faixa por painel evita que celulares de fluxos diferentes
        # apareÃ§am na mesma linha horizontal. Os conectados sem ativaÃ§Ã£o
        # tambÃ©m ficam claros em uma faixa prÃ³pria.
        by_panel: dict[str, list[dict]] = {}
        for profile in profiles:
            is_active = bool(profile.get("active", False))
            assigned = str(profile.get("active_panel", "")).strip()
            by_panel.setdefault(assigned if is_active and assigned else "__unassigned__", []).append(profile)
        configured_order = [str(panel.get("id", "")) for panel in self.panels]
        panel_order = [panel_id for panel_id in configured_order if panel_id in by_panel]
        panel_order.extend(sorted(panel_id for panel_id in by_panel if panel_id not in panel_order and panel_id != "__unassigned__"))
        if "__unassigned__" in by_panel:
            panel_order.append("__unassigned__")

        entries: list[tuple[tk.Frame, int, int, dict, str, bool, bool]] = []
        if self.device_grid_layout_mode == "together":
            section_cards = tk.Frame(cards, bg="#0d0d0f"); section_cards.pack(anchor="w")
            for column in range(columns): section_cards.grid_columnconfigure(column, weight=0, minsize=card_width)
            slot = 0
            for panel_id in panel_order:
                panel_profiles = sorted(by_panel[panel_id], key=lambda item: str(self.saved_names.get(str(item.get("serial", "")), {}).get("name", "")).casefold())
                for position, profile in enumerate(panel_profiles):
                    serial = str(profile.get("serial", ""))
                    entries.append((section_cards, slot, columns, profile, panel_id, False, position == 0))
                    slot += 1
                    if serial in self.device_grid_expanded_serials and panel_id != "__unassigned__":
                        entries.append((section_cards, slot, columns, profile, panel_id, True, False)); slot += 1
        else:
            for panel_id in panel_order:
                section = tk.Frame(cards, bg="#0d0d0f"); section.pack(fill="x", anchor="w", pady=(0, 18))
                title = "Conectados sem painel ativo" if panel_id == "__unassigned__" else self.panel_name(panel_id)
                section_heading = tk.Frame(section, bg="#0d0d0f")
                section_heading.pack(fill="x", pady=(0, 7))
                tk.Label(section_heading, text=title, bg="#0d0d0f", fg="#d8b4fe", font=("Segoe UI Semibold", 14)).pack(side="left")
                if panel_id != "__unassigned__":
                    ctk.CTkButton(section_heading, text="▶ Iniciar todos",
                                  command=lambda target_panel=panel_id: self.run_all_devices_in_grid_panel(target_panel),
                                  width=112, height=28, corner_radius=7, fg_color="#6d35bb", hover_color="#8552c7").pack(side="right")
                    ctk.CTkEntry(section_heading, textvariable=self.start_delay_max, width=56, height=28,
                                 corner_radius=7, fg_color="#222938", border_color="#465166", text_color="#f8fafc").pack(side="right", padx=(6, 3))
                    tk.Label(section_heading, text="Início aleatório até (s):", bg="#0d0d0f", fg="#94a3b8",
                             font=("Segoe UI", 10)).pack(side="right")
                section_cards = tk.Frame(section, bg="#0d0d0f"); section_cards.pack(anchor="w")
                panel_profiles = sorted(by_panel[panel_id], key=lambda item: str(self.saved_names.get(str(item.get("serial", "")), {}).get("name", "")).casefold())
                expanded_count = sum(1 for profile in panel_profiles if str(profile.get("serial", "")) in self.device_grid_expanded_serials and panel_id != "__unassigned__")
                section_columns = min(columns, max(1, len(panel_profiles) + expanded_count))
                for column in range(section_columns): section_cards.grid_columnconfigure(column, weight=0, minsize=card_width)
                slot = 0
                for profile in panel_profiles:
                    serial = str(profile.get("serial", ""))
                    entries.append((section_cards, slot, section_columns, profile, panel_id, False, False)); slot += 1
                    if serial in self.device_grid_expanded_serials and panel_id != "__unassigned__":
                        entries.append((section_cards, slot, section_columns, profile, panel_id, True, False)); slot += 1
        detail_jobs: list[tuple[tk.Frame, tk.Frame, int, int, str, str, str]] = []
        for section_cards, index, section_columns, profile, panel_id, is_detail, panel_starts_here in entries:
            serial = str(profile.get("serial", ""))
            saved = self.saved_names.get(serial, {})
            nickname = str(saved.get("name") or "Sem apelido")
            group = str(profile.get("group") or profile.get("model") or "Sem modelo")
            identity = self._device_current_name(serial) or "Sem identidade"
            row, column = divmod(index, section_columns)
            # Reserva uma faixa própria para o código e a identidade no rodapé.
            # Antes o vídeo ocupava essa área no limite inferior do cartão.
            # A tela conserva a altura original; o cartão cresce para o mini
            # log ocupar cerca de metade dela, sem reduzir a visualização.
            show_log = self._grid_log_is_visible(serial)
            card_height = 810 if show_log else 590
            section_cards.grid_rowconfigure(row, weight=0, minsize=820 if (show_log or is_detail) else 600)
            if is_detail:
                # As colunas alternam celular e etapas compactas.
                section_cards.grid_columnconfigure(column, weight=0, minsize=detail_width)
                placeholder = tk.Frame(section_cards, bg="#171b26", width=detail_width, height=810,
                                       highlightthickness=1, highlightbackground="#6940a8")
                placeholder.grid(row=row, column=column, sticky="n", padx=0, pady=0)
                placeholder.pack_propagate(False)
                tk.Label(placeholder, text="Carregando etapas…", bg="#171b26", fg="#bda4e6",
                         font=("Segoe UI", 10)).pack(anchor="center", expand=True)
                detail_jobs.append((section_cards, placeholder, row, column, serial, panel_id, group))
                continue
            card = tk.Frame(section_cards, bg="#171b26", width=card_width, height=card_height,
                            highlightthickness=1, highlightbackground="#374151", cursor="hand2")
            card.grid(row=row, column=column, sticky="n", padx=0, pady=0)
            card.pack_propagate(False)
            card.device_grid_serial = serial
            self.device_grid_card_widgets[serial] = card
            if panel_starts_here:
                title = "Sem painel ativo" if panel_id == "__unassigned__" else self.panel_name(panel_id)
                tk.Label(card, text=f"Painel: {title}", bg="#2a1d43", fg="#dfc8ff", font=("Segoe UI Semibold", 9)).pack(anchor="w", fill="x")
            status = tk.Label(card, text="●  Conectado", bg="#171b26", fg="#37d67a", font=("Segoe UI Semibold", 10))
            status.pack(anchor="w")
            tk.Label(card, text=f"{group}  •  {nickname}", bg="#171b26", fg="#f1f5f9", font=("Segoe UI Semibold", 12)).pack(anchor="w", pady=(5, 0))
            title_detail = tk.Label(card, text=self._device_grid_account_proxy_text(serial), bg="#171b26", fg="#aebbd0",
                                    font=("Segoe UI", 9), anchor="w")
            title_detail.pack(anchor="w", fill="x", pady=(1, 0))
            self.device_grid_title_details[serial] = title_detail
            screen_host = tk.Frame(card, bg="#090b10", width=screen_host_width, height=480,
                                   highlightthickness=1, highlightbackground="#30394a")
            # Não expanda no eixo X: a janela SDL respeita o host e, ao
            # preenchê-lo até 290 px, criava as bordas laterais sem aumentar a
            # tela Android propriamente dita.
            screen_host.pack(anchor="n", expand=False, pady=(8, 4))
            screen_host.pack_propagate(False)
            screen_label = tk.Label(screen_host, text="Iniciando tela ao vivo…", bg="#090b10", fg="#94a3b8",
                                    font=("Segoe UI", 10), cursor="hand2")
            screen_label.pack(fill="both", expand=True)
            for click_target in (screen_host, screen_label):
                click_target.bind("<ButtonPress-1>", lambda event, target=serial: self._grid_pointer_start(target, event))
                click_target.bind("<ButtonRelease-1>", lambda event, target=serial: self._grid_pointer_end(target, event))
                click_target.bind("<MouseWheel>", lambda event, target=serial: self._grid_mouse_wheel(target, event))
            self.device_grid_hosts[serial] = screen_host
            self.device_grid_screen_labels[serial] = screen_label
            log_holder = tk.Frame(card, bg="#0c0e14", height=180)
            log_holder.pack_propagate(False)
            # Os comandos ficam em uma faixa própria. Antes eram posicionados
            # sobre o Text e encobriam a última linha do log.
            log_actions = tk.Frame(log_holder, bg="#0c0e14", height=31)
            log_actions.pack(side="bottom", fill="x", padx=6, pady=(2, 5))
            log_actions.pack_propagate(False)
            log_content = tk.Frame(log_holder, bg="#0c0e14")
            log_content.pack(side="top", fill="both", expand=True)
            device_log = tk.Text(
                log_content, height=15, bg="#0c0e14", fg="#cbd5e1", insertbackground="#cbd5e1",
                relief="flat", highlightthickness=1, highlightbackground="#30394a",
                font=("Consolas", 8), wrap="word", state="disabled", cursor="arrow", padx=7, pady=6,
            )
            log_scroll = ttk.Scrollbar(log_content, orient="vertical", command=device_log.yview)
            device_log.configure(yscrollcommand=log_scroll.set)
            device_log.pack(side="left", fill="both", expand=True)
            log_scroll.pack(side="right", fill="y")
            clear_log_button = ctk.CTkButton(
                log_actions,
                text="Limpar",
                command=lambda target=serial: self.clear_device_grid_log(target),
                width=62,
                height=23,
                corner_radius=6,
                fg_color="#2d303a",
                hover_color="#454957",
                font=("Segoe UI", 10),
            )
            clear_log_button.pack(side="right")
            view_xml_button = ctk.CTkButton(
                log_actions,
                text="Ver XML",
                command=lambda target=serial, target_panel=panel_id: self.show_device_grid_xml(target, target_panel),
                width=72,
                height=23,
                corner_radius=6,
                fg_color="#39455b",
                hover_color="#4a5870",
                font=("Segoe UI", 10),
            )
            view_xml_button.pack(side="right", padx=(0, 6))
            # O bind_all da página principal ainda existe para o restante da
            # interface. Estes binds consomem a roda antes dela chegar lá.
            for scroll_target in (log_holder, device_log, log_scroll, clear_log_button, view_xml_button):
                scroll_target.bind(
                    "<MouseWheel>",
                    lambda event, target=device_log: self._scroll_embedded_panel_widget(event, target),
                    add="+",
                )
            device_log.device_grid_serial = serial
            device_log.device_grid_log_holder = log_holder
            if show_log:
                log_holder.pack(fill="both", expand=False, pady=(0, 5))
            self.device_grid_log_widgets[serial] = device_log
            previous_entries = self.device_logs_by_serial.get(serial, [])
            if previous_entries:
                device_log.configure(state="normal")
                device_log.insert("1.0", "\n".join(previous_entries) + "\n")
                device_log.see("end")
                device_log.configure(state="disabled")
            tk.Label(card, text=f"{serial}   •   {identity}", bg="#171b26", fg="#8795aa", font=("Consolas", 9)).pack(anchor="w", pady=(0, 4))
            assigned_panel = panel_id if panel_id != "__unassigned__" else ""
            ctk.CTkButton(
                card,
                text="Fechar etapas" if serial in self.device_grid_expanded_serials else "Abrir etapas",
                command=lambda target=serial, target_panel=assigned_panel: self.toggle_device_grid_flow_panel(target, target_panel),
                width=112, height=25, corner_radius=7, fg_color="#34255a", hover_color="#4a3479",
            ).place(x=card_width - 119, y=6)
            for widget in card.winfo_children():
                widget.bind("<Button-1>", lambda _event, target=serial: self._select_grid_device(target))
            card.bind("<Button-1>", lambda _event, target=serial: self._select_grid_device(target))

        def build_next_detail(position: int = 0) -> None:
            if position >= len(detail_jobs) or detail_generation != self.grid_detail_build_generation:
                return
            parent, placeholder, row, column, serial, panel_id, group = detail_jobs[position]
            try:
                if placeholder.winfo_exists():
                    placeholder.destroy()
                    detail = self._build_device_grid_flow_panel(parent, serial, panel_id, group)
                    detail.grid(row=row, column=column, sticky="n", padx=0, pady=0)
            except tk.TclError:
                pass
            # Uma árvore por ciclo mantém animações, logs e telas vivas
            # responsivos mesmo quando todos os cartões são abertos de uma vez.
            self.after(1, lambda next_position=position + 1: build_next_detail(next_position))

        if detail_jobs:
            self.after(1, build_next_detail)
        if preserve_live_views:
            def reposition_live_views() -> None:
                for serial, process in tuple(self.grid_scrcpy_processes.items()):
                    if process.poll() is None:
                        self._place_grid_live_view(serial, process.pid, session)
                # Uma reconciliação pode ter incluído um telefone novo. As
                # telas que permaneceram conectadas já estão no mapa acima;
                # esta chamada apenas encaixa a reserva do novo cartão, sem
                # reiniciar as outras.
                self._start_grid_live_views(profiles, session)
            self.after(60, reposition_live_views)
        else:
            self.after(60, lambda values=profiles, token=session: self._start_grid_live_views(values, token))

    def _device_grid_account_proxy_text(self, serial: str) -> str:
        """Identidade e proxy atualmente usados pelo telefone da grade."""
        account = self._load_fixed_accounts().get(serial, {})
        normal_user = str(account.get("usuario", "")).strip().lstrip("@")
        identity = f"@{normal_user}" if normal_user else self._device_identity_label(serial)
        try:
            proxy = str(RuntimeVariables(serial, RUNTIME_DIR).get("PROXY_ROOT_LABEL", "")).strip()
        except (OSError, RuntimeError, ValueError):
            proxy = ""
        values = [identity] if identity else []
        if proxy:
            values.append(f"Proxy: {proxy}")
        if self.device_execution_states.get(str(serial), {}).get("paused"):
            values.append("⏸ reconectando")
        return "  •  ".join(values)

    def _refresh_device_grid_title(self, serial: str) -> None:
        label = self.device_grid_title_details.get(serial)
        try:
            if label and label.winfo_exists():
                label.configure(text=self._device_grid_account_proxy_text(serial))
        except tk.TclError:
            pass

    def _select_grid_device(self, serial: str) -> None:
        for index in range(self.device_list.size()):
            profile = self.device_profiles.get(self.device_list.get(index), {})
            if profile.get("serial") == serial:
                current = self.device_list.curselection()
                if current and current[0] == index:
                    return
                self.device_list.selection_clear(0, tk.END)
                self.device_list.selection_set(index)
                self.device_list.activate(index)
                self.populate_profile()
                self.status.set(f"Celular selecionado na grade: {serial}.")
                break

    def _grid_phone_point(self, serial: str, event) -> tuple[int, int] | None:
        """Converte o ponto clicado na mini-tela para a resolução real."""
        label = self.device_grid_screen_labels.get(serial)
        if not label or not label.winfo_exists():
            return None
        shown_size = getattr(label, "grid_shown_size", None)
        source_size = getattr(label, "grid_source_size", None)
        if not shown_size or not source_size:
            return None
        shown_w, shown_h = shown_size
        source_w, source_h = source_size
        offset_x = max(0, (label.winfo_width() - shown_w) // 2)
        offset_y = max(0, (label.winfo_height() - shown_h) // 2)
        local_x = min(max(0, int(event.x) - offset_x), shown_w - 1)
        local_y = min(max(0, int(event.y) - offset_y), shown_h - 1)
        return round(local_x * source_w / shown_w), round(local_y * source_h / shown_h)

    def _grid_screen_size(self, serial: str) -> tuple[int, int] | None:
        cached = self.device_calibrations.get(serial)
        if cached:
            return tuple(cached[0])
        try:
            adb = Adb(); adb.path, adb.serial = self.adb.path, serial
            size = adb.screen_size(timeout=3)
            self.device_calibrations[serial] = (tuple(size), tuple(size))
            return tuple(size)
        except Exception:
            return None

    def _grid_macro_coordinate_screen(self, serial: str) -> tuple[int, int]:
        """Retorna a resolução-base da macro pertencente a este cartão.

        A grade pode mostrar cartões de modelos e painéis diferentes. Usar a
        macro aberta no editor para todos eles desloca a máscara e também faz
        um Alt+clique salvar a posição na escala errada.
        """
        panel = self._grid_panel_for_serial(serial)
        profile = next((item for item in self.device_profiles.values()
                        if str(item.get("serial", "")) == str(serial)), {})
        model = self._profile_model(self.saved_names.get(str(serial), {}),
                                    str(profile.get("model", "")), panel)
        if panel and panel == self.flow_var.get() and self._model_file_key(model) == self._model_file_key(self.device_model):
            return self._macro_coordinate_screen()
        cache_key = (str(serial), panel, self._model_file_key(model))
        cached = self.grid_macro_screens.get(cache_key)
        if cached:
            return cached
        if panel:
            path = MACROS_DIR / f"{self._model_file_key(model)}_{panel}.json"
            try:
                data = json.loads(path.read_text(encoding="utf-8"))
                screen = data.get("screen", ()) if isinstance(data, dict) else ()
                width, height = int(screen[0]), int(screen[1])
                if width > 0 and height > 0:
                    self.grid_macro_screens[cache_key] = (width, height)
                    return width, height
            except (OSError, ValueError, IndexError, TypeError, json.JSONDecodeError):
                pass
        result = self._grid_screen_size(serial) or self._macro_coordinate_screen()
        self.grid_macro_screens[cache_key] = result
        return result

    def _grid_scrcpy_bounds(self, serial: str) -> tuple[int, int, int, int] | None:
        host = self.device_grid_hosts.get(serial)
        if not host or not host.winfo_exists():
            return None
        try:
            return host.winfo_rootx(), host.winfo_rooty(), host.winfo_width(), host.winfo_height()
        except tk.TclError:
            return None

    def _grid_point_to_macro(self, serial: str, x: int, y: int) -> tuple[int, int] | None:
        bounds = self._grid_scrcpy_bounds(serial)
        screen = self._grid_screen_size(serial)
        if not bounds or not screen:
            return None
        left, top, width, height = bounds
        scale = min(width / screen[0], height / screen[1])
        shown_w, shown_h = max(1, round(screen[0] * scale)), max(1, round(screen[1] * scale))
        image_left, image_top = left + (width - shown_w) // 2, top + (height - shown_h) // 2
        if not (image_left <= x < image_left + shown_w and image_top <= y < image_top + shown_h):
            return None
        device_x = round((x - image_left) * (screen[0] - 1) / max(1, shown_w - 1))
        device_y = round((y - image_top) * (screen[1] - 1) / max(1, shown_h - 1))
        macro_w, macro_h = self._grid_macro_coordinate_screen(serial)
        return (round(device_x * (macro_w - 1) / max(1, screen[0] - 1)),
                round(device_y * (macro_h - 1) / max(1, screen[1] - 1)))

    def _ensure_grid_marker(self, serial: str) -> tk.Canvas | None:
        existing = self.grid_marker_windows.get(serial)
        if existing and existing[0].winfo_exists():
            return existing[1]
        try:
            overlay = tk.Toplevel(self); overlay.withdraw(); overlay.overrideredirect(True)
            overlay.configure(bg="#010203"); overlay.wm_attributes("-transparentcolor", "#010203"); overlay.wm_attributes("-topmost", True)
            canvas = tk.Canvas(overlay, bg="#010203", highlightthickness=0, borderwidth=0)
            canvas.pack(fill="both", expand=True)
            canvas.bind("<Button-1>", lambda event, target=serial: self._handle_grid_xml_picker_click(target, event))
            hwnd = wintypes.HWND(overlay.winfo_id()); user32 = ctypes.windll.user32
            style = user32.GetWindowLongPtrW(hwnd, -20)
            user32.SetWindowLongPtrW(hwnd, -20, style | 0x20 | 0x08000000)
            user32.SetWindowPos(hwnd, wintypes.HWND(-1), 0, 0, 0, 0, 0x0020 | 0x0010 | 0x0001 | 0x0002)
            self.grid_marker_windows[serial] = (overlay, canvas)
            return canvas
        except (AttributeError, OSError, tk.TclError):
            return None

    def _set_grid_marker_mouse_intercept(self, serial: str, enabled: bool) -> None:
        marker = self.grid_marker_windows.get(serial)
        if not marker:
            return
        try:
            overlay, canvas = marker
            overlay.wm_attributes("-transparentcolor", "" if enabled else "#010203")
            overlay.wm_attributes("-alpha", 0.02 if enabled else 1.0)
            canvas.configure(bg="#010204" if enabled else "#010203")
            user32 = ctypes.windll.user32; hwnd = wintypes.HWND(overlay.winfo_id())
            style = int(user32.GetWindowLongPtrW(hwnd, -20))
            user32.SetWindowLongPtrW(hwnd, -20, (style & ~0x20) if enabled else (style | 0x20))
        except (AttributeError, OSError, tk.TclError):
            pass

    def _grid_point_to_device(self, serial: str, x: int, y: int) -> tuple[int, int] | None:
        bounds = self._grid_scrcpy_bounds(serial); screen = self._grid_screen_size(serial)
        if not bounds or not screen:
            return None
        left, top, width, height = bounds; scale = min(width / screen[0], height / screen[1])
        shown_w, shown_h = max(1, round(screen[0] * scale)), max(1, round(screen[1] * scale))
        image_left, image_top = left + (width - shown_w) // 2, top + (height - shown_h) // 2
        if not (image_left <= x < image_left + shown_w and image_top <= y < image_top + shown_h):
            return None
        return (round((x - image_left) * (screen[0] - 1) / max(1, shown_w - 1)),
                round((y - image_top) * (screen[1] - 1) / max(1, shown_h - 1)))

    def _handle_grid_xml_picker_click(self, serial: str, event) -> str:
        picker = self.grid_xml_picker
        if not picker or str(picker.get("serial", "")) != str(serial):
            return "break"
        point = self._grid_point_to_device(serial, int(event.x_root), int(event.y_root))
        if point is None:
            return "break"
        x, y = point; matches = []
        for attrs in picker.get("elements", []):
            values = list(map(int, re.findall(r"\d+", attrs.get("bounds", ""))))
            if len(values) == 4 and values[0] <= x <= values[2] and values[1] <= y <= values[3]:
                matches.append(((values[2] - values[0]) * (values[3] - values[1]), attrs))
        callback = picker.get("callback")
        self.grid_xml_picker = None
        self._set_grid_marker_mouse_intercept(serial, False)
        self._hide_grid_marker(serial)
        if callable(callback):
            self.after(0, lambda: callback([attrs for _area, attrs in sorted(matches, key=lambda item: item[0])]))
        return "break"

    def _hide_grid_markers(self) -> None:
        for overlay, _canvas in tuple(self.grid_marker_windows.values()):
            try:
                if overlay.winfo_exists(): overlay.withdraw()
            except tk.TclError:
                pass

    def _hide_grid_marker(self, serial: str) -> None:
        marker = self.grid_marker_windows.get(serial)
        if not marker:
            return
        try:
            if marker[0].winfo_exists():
                marker[0].withdraw()
        except tk.TclError:
            pass

    def _grid_action_for_tree_item(self, serial: str, source_item: str | None) -> Action | None:
        """Obtém a ação no modelo que pertence ao cartão, não ao editor oculto."""
        if not source_item:
            return None
        tree = self.device_grid_flow_trees.get(serial)
        panel = str(getattr(tree, "grid_panel", "")) if tree else self._grid_panel_for_serial(serial)
        profile = next((value for value in self.device_profiles.values()
                        if str(value.get("serial", "")) == serial), {})
        fallback_model = (str(getattr(tree, "grid_fallback_model", "")) if tree else
                          str(profile.get("model", "")))
        parts = source_item.split(":")
        if len(parts) < 3 or parts[0] == "g":
            return None
        try:
            group = self._grid_groups_for_device(serial, panel, fallback_model)[int(parts[1])]
            actions = group.get("actions", [])
            indexes = [int(value) for value in parts[2:]]
            for index in indexes[:-1]:
                action = actions[index]
                actions = self._container_actions(action) or []
            action = actions[indexes[-1]]
            return action if isinstance(action, Action) else Action(**action)
        except (IndexError, TypeError, ValueError):
            return None

    def _update_grid_touch_marker(self, serial: str, tree_item: str | None = None) -> None:
        """Mostra em tempo real toque, arrasto ou área XML do cartão."""
        bounds = self._grid_scrcpy_bounds(serial)
        screen = self._grid_screen_size(serial)
        if tree_item:
            self.grid_marker_selected_items[serial] = tree_item
        # O clique explícito deve aparecer de imediato. A próxima atualização
        # real da execução volta a assumir a máscara desse mesmo telefone.
        candidates = (
            tree_item,
            self.device_execution_states.get(serial, {}).get("running"),
            self.grid_marker_selected_items.get(serial),
        )
        source_item = next((candidate for candidate in candidates if candidate), None)
        action = self._grid_action_for_tree_item(serial, source_item)
        # Uma árvore compacta pode ser recriada entre o evento e o desenho.
        # Se a referência antiga não existir mais, mantenha a última seleção
        # válida do próprio cartão em vez de esconder a máscara sem motivo.
        if action is None:
            selected_item = self.grid_marker_selected_items.get(serial)
            if selected_item and selected_item != source_item:
                fallback = self._grid_action_for_tree_item(serial, selected_item)
                if fallback is not None:
                    source_item, action = selected_item, fallback
        xml_marker = self.grid_xml_marker_bounds.get(serial)
        picker_active = bool(self.grid_xml_picker and str(self.grid_xml_picker.get("serial", "")) == str(serial))
        try:
            user32 = ctypes.windll.user32
            modifier_active = bool((user32.GetAsyncKeyState(0x11) | user32.GetAsyncKeyState(0x12)) & 0x8000)
        except (AttributeError, OSError):
            modifier_active = False
        if not bounds or not screen or (action is None and xml_marker is None and not picker_active and not modifier_active):
            self._hide_grid_marker(serial)
            return
        canvas = self._ensure_grid_marker(serial)
        overlay_data = self.grid_marker_windows.get(serial)
        if canvas is None or not overlay_data:
            return
        left, top, width, height = bounds
        try:
            card_macro_screen = self._grid_macro_coordinate_screen(serial)
            macro_screen = self._action_coordinate_screen(action, card_macro_screen, None) if action else card_macro_screen
            scale = min(width / screen[0], height / screen[1])
            shown_w, shown_h = max(1, round(screen[0] * scale)), max(1, round(screen[1] * scale))
            offset_x, offset_y = (width - shown_w) // 2, (height - shown_h) // 2
            def point(px: int, py: int) -> tuple[int, int]:
                dx = round(px * (screen[0] - 1) / max(1, macro_screen[0] - 1))
                dy = round(py * (screen[1] - 1) / max(1, macro_screen[1] - 1))
                return (offset_x + round(dx * (shown_w - 1) / max(1, screen[0] - 1)),
                        offset_y + round(dy * (shown_h - 1) / max(1, screen[1] - 1)))
            canvas.configure(width=width, height=height); canvas.delete("all")
            # A mesma película usada pelo seletor XML bloqueia o scrcpy durante
            # Ctrl/Alt; o gesto é tratado pelo editor e nunca toca o telefone.
            self._set_grid_marker_mouse_intercept(serial, picker_active or modifier_active)
            if picker_active:
                canvas.create_rectangle(2, 2, width - 3, height - 3, outline="#36d399", width=2)
                canvas.create_text(width // 2, 20, text="Clique para escolher o elemento XML",
                                   fill="#36d399", font=("Segoe UI", 10, "bold"))
            if xml_marker is not None:
                xml_bounds, xml_source_size = xml_marker
                xml_w, xml_h = max(1, xml_source_size[0]), max(1, xml_source_size[1])
                x1, y1 = (
                    offset_x + round(xml_bounds[0] * (shown_w - 1) / max(1, xml_w - 1)),
                    offset_y + round(xml_bounds[1] * (shown_h - 1) / max(1, xml_h - 1)),
                )
                x2 = offset_x + round(xml_bounds[2] * (shown_w - 1) / max(1, xml_w - 1))
                y2 = offset_y + round(xml_bounds[3] * (shown_h - 1) / max(1, xml_h - 1))
                canvas.create_rectangle(x1, y1, x2, y2, outline="#36d399", width=4)
                canvas.create_rectangle(x1 + 3, y1 + 3, x2 - 3, y2 - 3, outline="#ffd23f", width=1)
                canvas.create_text(x1 + 7, max(12, y1 - 9), text="XML", anchor="w", fill="#36d399", font=("Segoe UI", 10, "bold"))
            elif action and action.kind == "tap":
                start = point(action.x, action.y)
                canvas.create_oval(start[0]-12, start[1]-12, start[0]+12, start[1]+12, outline="#ffd23f", width=3)
                canvas.create_line(start[0]-18, start[1], start[0]+18, start[1], fill="#ff5a78", width=2)
                canvas.create_line(start[0], start[1]-18, start[0], start[1]+18, fill="#ff5a78", width=2)
            elif action and action.kind in ("swipe", "nav_rc_scroll"):
                start = point(action.x, action.y)
                end = point(action.x2 if action.x2 is not None else action.x, action.y2 if action.y2 is not None else action.y)
                canvas.create_line(*start, *end, fill="#ffd23f", width=4)
                for px, py, color in ((*start, "#36d399"), (*end, "#ff5a78")):
                    canvas.create_oval(px-8, py-8, px+8, py+8, fill=color, outline="#121722", width=2)
            overlay, _ = overlay_data
            overlay.geometry(f"{width}x{height}+{left}+{top}")
            overlay.deiconify()
            # O scrcpy é uma janela nativa independente e ignora o ``lift``
            # do Tk em parte dos PCs. A máscara precisa subir explicitamente
            # acima dele, sem ativar nem roubar o foco da janela.
            ctypes.windll.user32.SetWindowPos(
                wintypes.HWND(overlay.winfo_id()), wintypes.HWND(-1), left, top, width, height,
                0x0010 | 0x0040,
            )
            overlay.lift()
        except (AttributeError, OSError, TypeError, ValueError, tk.TclError):
            return

    def _grid_pointer_start(self, serial: str, event) -> str:
        try:
            user32 = ctypes.windll.user32
            ctrl = bool(user32.GetAsyncKeyState(0x11) & 0x8000)
            alt = bool(user32.GetAsyncKeyState(0x12) & 0x8000)
            if ctrl or alt:
                if str(serial) != str(self.grid_edit_serial):
                    self.status.set("Selecione primeiro uma etapa na lista deste celular antes de usar Ctrl ou Alt.")
                    return "break"
                self.grid_modified_pointer_serials.add(serial)
                # Reposicionar não pode depender da sondagem global do mouse.
                # Ela continua ativa para a gravação com Ctrl, mas o Alt só
                # pode alterar uma etapa quando este clique chegou de fato à
                # tela deste cartão.
                if alt and not ctrl:
                    self._move_grid_selected_action(serial, event.x_root, event.y_root)
                    self.grid_edit_mouse_down = True
                elif ctrl and not alt:
                    panel = self._grid_panel_for_serial(serial) or self.flow_var.get()
                    start = self._grid_point_to_macro(serial, event.x_root, event.y_root)
                    if panel and start:
                        # Registra no próprio evento do cartão. A sondagem
                        # global continua apenas como reserva para scrcpy,
                        # mas não pode mais perder um arrasto curto.
                        began = time.monotonic()
                        held_since = self.grid_ctrl_held_since.get(serial, began)
                        self.grid_ctrl_record_starts[serial] = (start[0], start[1], began, max(0, round((began - held_since) * 1000)))
                        self.grid_edit_mouse_down = True
                        self.status.set("Gravando na tela do celular: solte o mouse para salvar o toque ou arrasto.")
                return "break"
        except (AttributeError, OSError):
            pass
        self._select_grid_device(serial)
        point = self._grid_phone_point(serial, event)
        if point:
            if not hasattr(self, "grid_drag_starts"):
                self.grid_drag_starts = {}
            self.grid_drag_starts[serial] = point
        return "break"

    def _grid_send_gesture(self, serial: str, start: tuple[int, int], end: tuple[int, int] | None = None) -> None:
        def send() -> None:
            try:
                adb = Adb()
                adb.path, adb.serial = self.adb.path, serial
                if end is None or start == end:
                    adb.command("shell", "input", "tap", str(start[0]), str(start[1]), timeout=12)
                else:
                    adb.command("shell", "input", "swipe", str(start[0]), str(start[1]), str(end[0]), str(end[1]), "260", timeout=12)
            except Exception as error:
                self.events.put(("error", f"Não foi possível enviar o gesto ao telefone {serial}: {error}"))
        self._thread(send)

    def _grid_pointer_end(self, serial: str, event) -> str:
        if serial in self.grid_modified_pointer_serials:
            self.grid_modified_pointer_serials.discard(serial)
            return "break"
        try:
            user32 = ctypes.windll.user32
            if user32.GetAsyncKeyState(0x11) & 0x8000 or user32.GetAsyncKeyState(0x12) & 0x8000:
                return "break"
        except (AttributeError, OSError):
            pass
        end = self._grid_phone_point(serial, event)
        start = getattr(self, "grid_drag_starts", {}).pop(serial, None)
        if not start or not end:
            return "break"
        if max(abs(end[0] - start[0]), abs(end[1] - start[1])) < 12:
            end = None
        self._grid_send_gesture(serial, start, end)
        return "break"

    def _grid_mouse_wheel(self, serial: str, event) -> str:
        point = self._grid_phone_point(serial, event)
        label = self.device_grid_screen_labels.get(serial)
        source_size = getattr(label, "grid_source_size", None) if label else None
        if not point or not source_size:
            return "break"
        distance = max(120, round(source_size[1] * 0.25))
        # Rolar para baixo desloca o conteúdo para baixo (dedo sobe).
        end_y = point[1] - distance if event.delta < 0 else point[1] + distance
        end_y = min(max(1, end_y), source_size[1] - 2)
        self._grid_send_gesture(serial, point, (point[0], end_y))
        return "break"

    def _grid_serial_under_cursor(self, point) -> str | None:
        for serial in self.device_grid_hosts:
            bounds = self._grid_scrcpy_bounds(serial)
            if bounds:
                left, top, width, height = bounds
                if left <= point.x < left + width and top <= point.y < top + height:
                    return serial
        return None

    def _grid_panel_for_serial(self, serial: str) -> str:
        profile = next((item for item in self.device_profiles.values() if str(item.get("serial", "")) == serial), {})
        return str(profile.get("active_panel", "")).strip()

    def _set_grid_scrcpy_passthrough(self, serial: str, enabled: bool) -> None:
        hwnd = int(self.grid_scrcpy_windows.get(serial, 0) or 0)
        if not hwnd:
            return
        try:
            user32 = ctypes.windll.user32
            if enabled and serial not in self.grid_scrcpy_original_exstyles:
                style = int(user32.GetWindowLongPtrW(wintypes.HWND(hwnd), -20))
                self.grid_scrcpy_original_exstyles[serial] = style
                user32.SetWindowLongPtrW(wintypes.HWND(hwnd), -20, style | 0x20 | 0x08000000)
                user32.SetWindowPos(wintypes.HWND(hwnd), wintypes.HWND(0), 0, 0, 0, 0,
                                    0x0020 | 0x0001 | 0x0002 | 0x0010)
            elif not enabled and serial in self.grid_scrcpy_original_exstyles:
                user32.SetWindowLongPtrW(wintypes.HWND(hwnd), -20, self.grid_scrcpy_original_exstyles.pop(serial))
                user32.SetWindowPos(wintypes.HWND(hwnd), wintypes.HWND(0), 0, 0, 0, 0,
                                    0x0020 | 0x0001 | 0x0002 | 0x0010)
        except (AttributeError, OSError):
            self.grid_scrcpy_original_exstyles.pop(serial, None)

    def _move_grid_selected_action(self, serial: str, cursor_x: int, cursor_y: int) -> None:
        """Reposiciona uma única etapa por um Alt+clique entregue ao cartão.

        Não use esta operação em um loop de leitura global: uma tecla Alt
        pressionada enquanto o foco troca de janela não é uma autorização para
        salvar uma coordenada nova na macro.
        """
        if str(serial) != str(self.grid_edit_serial):
            return
        panel = self._grid_panel_for_serial(serial) or self.flow_var.get()
        if not panel:
            return
        self._grid_prepare_panel_context(serial, panel)
        source_item = self.grid_marker_selected_items.get(serial, "")
        if not source_item or not self.tree.exists(source_item):
            return
        self.tree.selection_set(source_item)
        self.tree.focus(source_item)
        location = self._tree_action_container(source_item)
        new_point = self._grid_point_to_macro(serial, cursor_x, cursor_y)
        if location is None or new_point is None:
            return
        _group, actions, index = location
        action = actions[index]
        if action.kind not in ("tap", "swipe"):
            return
        x, y = new_point
        screen_w, screen_h = self._grid_macro_coordinate_screen(serial)
        self.push_undo()
        if action.kind == "tap":
            action.x, action.y = x, y
        else:
            delta_x = (action.x2 or action.x) - action.x
            delta_y = (action.y2 or action.y) - action.y
            action.x, action.y = x, y
            action.x2 = max(0, min(screen_w - 1, x + delta_x))
            action.y2 = max(0, min(screen_h - 1, y + delta_y))
        self.refresh_tree()
        self.tree.selection_set(source_item)
        self.tree.focus(source_item)
        self.save_macro(quiet=True)
        compact = self.device_grid_flow_trees.get(serial)
        if compact and compact.winfo_exists():
            self._reload_compact_flow_tree(
                compact, serial, panel, getattr(compact, "grid_fallback_model", "")
            )
            compact_item = next((candidate for candidate, source in compact.grid_source_items.items()
                                 if source == source_item and compact.exists(candidate)), "")
            if compact_item:
                compact.selection_set(compact_item)
                compact.focus(compact_item)
                compact.see(compact_item)
        self._update_grid_touch_marker(serial, source_item)
        self.status.set("Posição atualizada na tela do celular.")

    def _poll_grid_coordinate_editing(self) -> None:
        """Ctrl grava e Alt reposiciona diretamente nas telas da grade."""
        if not getattr(self, "app_view_var", None) or self.app_view_var.get() != "celulares":
            self.grid_edit_mouse_down = False
            return
        try:
            user32 = ctypes.windll.user32
            point = wintypes.POINT(); user32.GetCursorPos(ctypes.byref(point))
            hovered_serial = self._grid_serial_under_cursor(point)
            target_serial = str(self.grid_edit_serial or "")
            # A lista compacta define o alvo. Se o mouse saiu da tela desse
            # alvo, nÃ£o convertemos a posiÃ§Ã£o para outro aparelho nem
            # continuamos uma gravaÃ§Ã£o no cartÃ£o errado.
            serial = target_serial if target_serial and hovered_serial == target_serial else None
            down = bool(user32.GetAsyncKeyState(0x01) & 0x8000)
            ctrl = bool(user32.GetAsyncKeyState(0x11) & 0x8000)
            alt = bool(user32.GetAsyncKeyState(0x12) & 0x8000)
            now = time.monotonic()
            if ctrl and serial:
                self.grid_ctrl_held_since.setdefault(serial, now)
            elif not ctrl:
                self.grid_ctrl_held_since.clear()
            if alt and serial:
                if self.grid_alt_armed_serial != serial:
                    self.grid_alt_armed_serial = serial
                    self.grid_alt_armed_at = time.monotonic()
            elif not alt:
                self.grid_alt_armed_serial = ""
                self.grid_alt_armed_at = 0.0
            for target in tuple(self.grid_scrcpy_windows):
                # Mesmo sobre um cartÃ£o que nÃ£o Ã© o alvo, Ctrl/Alt nunca
                # podem vazar como toque normal para o telefone. Fazemos a
                # janela nativa passar o clique ao host, que o descarta pela
                # regra do ``grid_edit_serial``.
                self._set_grid_scrcpy_passthrough(target, bool(target == hovered_serial and (ctrl or alt)))
                self._set_grid_marker_mouse_intercept(
                    target,
                    bool(target == hovered_serial and (ctrl or alt))
                    or bool(self.grid_xml_picker and str(self.grid_xml_picker.get("serial", "")) == str(target)),
                )
            if self.grid_ctrl_record_starts and not down:
                target, start = next(iter(self.grid_ctrl_record_starts.items()))
                self.grid_ctrl_record_starts.pop(target, None)
                if hovered_serial != target or target != target_serial:
                    self.status.set("Gravação cancelada: o gesto saiu da tela do celular selecionado.")
                    self.grid_edit_mouse_down = False
                    return
                panel = self._grid_panel_for_serial(target) or self.flow_var.get()
                if panel:
                    self._grid_prepare_panel_context(target, panel)
                    compact = self.device_grid_flow_trees.get(target)
                    # A gravação da grade usa a mesma rotina de inserção da
                    # tela principal. Portanto, antes de soltar o mouse,
                    # restaura a linha escolhida no cartão deste celular.
                    # Sem isso a árvore principal podia continuar selecionando
                    # uma etapa de outro cartão e a nova ação entrava no lugar
                    # errado dentro da lista.
                    source_item = self.grid_marker_selected_items.get(target, "")
                    # ``_grid_prepare_panel_context`` pode reconstruir a
                    # árvore central. Reaplicamos aqui (no instante da
                    # inserção) o estado do grupo no cartão: fechado cria um
                    # irmão abaixo; aberto recebe o novo filho.
                    if compact and compact.winfo_exists() and source_item:
                        compact_item = next(
                            (item for item, source in getattr(compact, "grid_source_items", {}).items()
                             if source == source_item and compact.exists(item)),
                            "",
                        )
                        if compact_item and compact.get_children(compact_item) and self.tree.exists(source_item):
                            self.tree.item(source_item, open=bool(compact.item(compact_item, "open")))
                    if source_item and self.tree.exists(source_item):
                        self.tree.selection_set(source_item)
                        self.tree.focus(source_item)
                        self.tree.see(source_item)
                    end = self._grid_point_to_macro(target, point.x, point.y)
                    if end:
                        self._append_live_preview_gesture(start, end)
                        compact = self.device_grid_flow_trees.get(target)
                        if compact and compact.winfo_exists():
                            self._reload_compact_flow_tree(
                                compact, target, panel, getattr(compact, "grid_fallback_model", "")
                            )
                        self._update_grid_touch_marker(target)
            if down and not self.grid_edit_mouse_down and serial:
                panel = self._grid_panel_for_serial(serial) or self.flow_var.get()
                if panel and ctrl and not alt:
                    self._grid_prepare_panel_context(serial, panel)
                    start = self._grid_point_to_macro(serial, point.x, point.y)
                    if start:
                        began = time.monotonic()
                        held_since = self.grid_ctrl_held_since.get(serial, began)
                        self.grid_ctrl_record_starts[serial] = (start[0], start[1], began, max(0, round((began - held_since) * 1000)))
                        self.status.set("Gravando na tela do celular: solte o mouse para salvar o toque ou arrasto.")
                elif (panel and alt and self.grid_alt_armed_serial == serial
                      and time.monotonic() - self.grid_alt_armed_at >= 0.12):
                    # scrcpy é uma janela nativa e pode consumir o clique. O
                    # atalho só vale após Alt armado sobre ESTE cartão e para a
                    # etapa já selecionada dele; trocar janelas ou outro cartão
                    # não fornece autorização para gravar coordenadas.
                    self._move_grid_selected_action(serial, point.x, point.y)
            self.grid_edit_mouse_down = down
        except (AttributeError, OSError, tk.TclError, RuntimeError):
            self.grid_edit_mouse_down = False

    def _start_grid_live_views(self, profiles: list[dict], session: int) -> None:
        """Mostra vídeo fluido em cada cartão usando o mesmo scrcpy da prévia."""
        if (session != self.grid_view_session or not getattr(self, "app_view_var", None)
                or self.app_view_var.get() != "celulares"):
            return
        # Uma nova grade inicia as prévias; não pode herdar o marcador de
        # parada deixado pela troca anterior para o Fluxo.
        self.grid_capture_stop.clear()
        # Cada telefone é independente. A fila antiga só iniciava o próximo
        # depois de a janela anterior estar pronta, fazendo seis aparelhos
        # parecerem travados um esperando pelo outro. Damos uma pequena
        # separação entre os launches, mas todos seguem seu próprio ciclo de
        # criação/reposicionamento em paralelo.
        for index in range(len(profiles)):
            self.after(index * 70, lambda position=index: self._start_next_grid_live_view(
                profiles, session, position, advance=False
            ))

    def _start_next_grid_live_view(self, profiles: list[dict], session: int, index: int,
                                   advance: bool = True) -> None:
        if (session != self.grid_view_session or not getattr(self, "app_view_var", None)
                or self.app_view_var.get() != "celulares" or index >= len(profiles)):
            return
        profile = profiles[index]
        serial = str(profile.get("serial", ""))
        if not serial or serial not in self.device_grid_hosts:
            if advance:
                self.after(0, lambda: self._start_next_grid_live_view(profiles, session, index + 1))
            return
        # A mesma janela já preparada para o Fluxo é encaixada no cartão.
        warmed = self.warm_scrcpy_processes.get(serial)
        if warmed and not self._scrcpy_process_matches_serial(warmed, serial):
            self.warm_scrcpy_processes.pop(serial, None)
            self.warm_scrcpy_windows.pop(serial, None)
            warmed = None
        if warmed and warmed.poll() is None:
            self.grid_scrcpy_processes[serial] = warmed
            self.after(0, lambda current=serial, pid=warmed.pid, token=session:
                       self._place_grid_live_view(
                           current, pid, token,
                           on_ready=(lambda: self._start_next_grid_live_view(profiles, session, index + 1))
                           if advance else None,
                        ))
            return
        # The reservation manager is the sole process creator.  The grid only
        # requests the serial and retries placement when its SDL becomes ready.
        self._queue_warm_live_view(serial)
        if advance:
            self.after(0, lambda: self._start_next_grid_live_view(profiles, session, index + 1))
        else:
            self.after(200, lambda: self._start_next_grid_live_view(profiles, session, index, advance=False))
        return
        # Se a reserva ainda estava apenas na fila, a grade passa a ser a
        # Ãºnica responsÃ¡vel por iniciÃ¡-la. Sem remover essa pendÃªncia, ao
        # voltar para Fluxo a fila criava uma segunda janela para o serial.
        self.warm_scrcpy_queue = [queued for queued in self.warm_scrcpy_queue if queued != serial]
        self.warm_scrcpy_retry_pending.discard(serial)
        next_started = False

        def start_next_once() -> None:
            nonlocal next_started
            if next_started:
                return
            next_started = True
            if advance:
                self.after(80, lambda: self._start_next_grid_live_view(profiles, session, index + 1))
        try:
            process = subprocess.Popen(
                [str(executable), "--serial", serial,
                 "--window-title", f"iggents grade {session} {serial}",
                 "--window-borderless", "--window-x", "-32000", "--window-y", "-32000", "--no-audio",
                 # O cartão tem cerca de 270 × 480 px. Transmitir 1080p/60
                 # para seis cartões só ocupa USB/GPU e compete com ADB/XML;
                 # 540p/20 fps preserva a leitura e deixa margem para as
                 # execuções e uma gravação rodarem simultaneamente.
                 "--max-size=540", "--max-fps=20", "--video-bit-rate=2M", "--render-driver=opengl"],
                cwd=str(executable.parent), stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                startupinfo=self._hidden_scrcpy_startupinfo(),
            )
            self.grid_scrcpy_processes[serial] = process
            self.warm_scrcpy_processes[serial] = process
            self.after(120, lambda current=serial, pid=process.pid, token=session:
                       self._place_grid_live_view(current, pid, token, on_ready=start_next_once))
        except OSError:
            start_next_once()
            return
        # Não deixe um telefone que não criou janela travar a fila inteira.
        self.after(5000, start_next_once)

    def _place_grid_live_view(self, serial: str, process_id: int, session: int, attempt: int = 0,
                              on_ready=None) -> None:
        if session != self.grid_view_session or self.app_view_var.get() != "celulares":
            return
        process = self.grid_scrcpy_processes.get(serial)
        host = self.device_grid_hosts.get(serial)
        if not process or process.pid != process_id or not host or not host.winfo_exists():
            return
        if process.poll() is not None:
            self._recover_grid_live_view(serial, session)
            return
        # Calls can arrive after refresh/reconnection.  Before moving a SDL to
        # a card, confirm that the process command still belongs to THIS
        # serial.  PID alone cannot authorize showing the Note 12 in the A21s
        # card when a stale map entry survived a reconciliation.
        if not self._scrcpy_process_matches_serial(process, serial):
            self.grid_scrcpy_processes.pop(serial, None)
            self.grid_scrcpy_windows.pop(serial, None)
            self._queue_warm_live_view(serial)
            return
        # As reservas nascem fora da tela e alguns SDL as reportam como
        # ocultas. Procurar somente janelas visíveis fazia a grade aguardar
        # indefinidamente mesmo com o scrcpy saudável já aberto.
        # Reencontre sempre pelo PID atual. Reusar só o HWND em cache permite
        # que uma alça reciclada pelo Windows faça um cartão mostrar a tela de
        # outro celular após reconectar/atualizar a grade.
        hwnd = self._window_for_process(process.pid, include_hidden=True)
        if not hwnd:
            # Alguns aparelhos (em especial os Samsung) levam vários segundos
            # para terminar de iniciar o servidor e criar a janela SDL. Antes
            # a grade desistia após ~2,8 s: o processo continuava vivo, mas a
            # tela ficava vazia e a janela aparecia solta depois. Mantemos a
            # associação serial -> janela até 15 s, sem criar outro processo.
            if attempt < 75:
                self.after(200, lambda: self._place_grid_live_view(serial, process_id, session, attempt + 1, on_ready))
            else:
                self._recover_grid_live_view(serial, session)
            return
        picker_for_serial = bool(self.grid_xml_picker and str(self.grid_xml_picker.get("serial", "")) == str(serial))
        inspecting_serial = str(self.grid_xml_inspection_serial) == str(serial)
        if (self._live_views_hidden_by_minimize or self.state() == "iconic"
                or (self._grid_popups_hiding_live_views and not (picker_for_serial or inspecting_serial))
                or self._grid_action_drawer_hides_live_views):
            try:
                ctypes.windll.user32.ShowWindow(wintypes.HWND(hwnd), 0)
            except (AttributeError, OSError):
                pass
            self.grid_scrcpy_windows[serial] = hwnd
            return
        try:
            width, height = host.winfo_width(), host.winfo_height()
            if width < 50 or height < 50:
                if attempt < 75:
                    self.after(200, lambda: self._place_grid_live_view(serial, process_id, session, attempt + 1, on_ready))
                return
            user32 = ctypes.windll.user32
            # O scrcpy permanece top-level com o Iggents como dono. Reparentear
            # a janela SDL como filha do Tk encerra o vídeo em alguns aparelhos.
            # A prévia usa este mesmo modo estável.
            user32.SetWindowLongPtrW(hwnd, -8, self.winfo_id())
            # A tela nativa não toma o foco do editor: assim Ctrl+C/V/X/A/E
            # continuam chegando à árvore de etapas, tanto no Fluxo quanto em
            # Celulares. O clique ainda é entregue normalmente ao scrcpy.
            style = int(user32.GetWindowLongPtrW(wintypes.HWND(hwnd), -20))
            user32.SetWindowLongPtrW(wintypes.HWND(hwnd), -20, style | 0x08000000)  # WS_EX_NOACTIVATE
            # Enquanto um diálogo está aberto, a tela nativa fica abaixo dele.
            # Ao fechar o diálogo, a próxima atualização volta a encaixá-la
            # normalmente sobre seu cartão.
            # HWND_BOTTOM altera a ordem global do Windows e faz outros
            # programas aparecerem quando o editor de espera é aberto.
            user32.SetWindowPos(hwnd, 0, host.winfo_rootx(), host.winfo_rooty(), width, height, 0x0010 | 0x0040)
            # Mostra sem ganhar foco. É importante depois de recuperar uma
            # reserva que havia sido escondida pelo painel anterior.
            user32.ShowWindow(wintypes.HWND(hwnd), 8)  # SW_SHOWNA
            self.grid_scrcpy_windows[serial] = hwnd
            self.warm_scrcpy_windows[serial] = hwnd
            self.grid_scrcpy_recovery_attempts.pop(serial, None)
            if callable(on_ready):
                on_ready()
            if serial in self.grid_marker_windows:
                self._update_grid_touch_marker(serial)
            if not getattr(host, "grid_live_configure_bound", False):
                host.grid_live_configure_bound = True
                host.bind("<Configure>", lambda _event, current=serial, pid=process_id, token=session:
                          self._place_grid_live_view(current, pid, token), add="+")
            # Scrcpy precisa ficar como uma janela nativa independente para
            # não interromper alguns modelos Android. Por isso a posição deve
            # acompanhar explicitamente a caixa Tk: ao rolar a tela, o host
            # muda de lugar sem disparar sempre um <Configure>.
            poll_key = (serial, process_id, session)
            if poll_key not in self.grid_live_position_pollers:
                self.grid_live_position_pollers.add(poll_key)
                self.after(80, lambda key=poll_key: self._poll_grid_live_view_position(*key))
        except (AttributeError, OSError, tk.TclError):
            return

    def _recover_grid_live_view(self, serial: str, session: int) -> None:
        """Recria somente a tela que não chegou a formar janela SDL."""
        if (session != self.grid_view_session or not getattr(self, "app_view_var", None)
                or self.app_view_var.get() != "celulares"):
            return
        attempts = self.grid_scrcpy_recovery_attempts.get(serial, 0)
        if attempts >= 2:
            label = self.device_grid_screen_labels.get(serial)
            if label and label.winfo_exists():
                label.configure(text="Não foi possível iniciar esta tela. Atualize para tentar novamente.", image="")
            return
        self.grid_scrcpy_recovery_attempts[serial] = attempts + 1
        process = self.grid_scrcpy_processes.pop(serial, None)
        warm_process = self.warm_scrcpy_processes.pop(serial, None)
        self.grid_scrcpy_windows.pop(serial, None)
        self.warm_scrcpy_windows.pop(serial, None)
        for candidate in {item for item in (process, warm_process) if item is not None}:
            try:
                if candidate.poll() is None:
                    candidate.terminate()
            except OSError:
                pass
        profile = next((item for item in self.device_profiles.values()
                        if str(item.get("serial", "")) == str(serial)
                        and item.get("state") == "device"), None)
        if profile:
            # A nova tentativa é exclusiva deste cartão: os celulares que já
            # exibem vídeo não são reiniciados nem esperam por ele.
            self.after(350, lambda current=dict(profile), token=session:
                       self._start_grid_live_views([current], token))

    def _poll_grid_live_view_position(self, serial: str, process_id: int, session: int) -> None:
        """Mantém a janela scrcpy colada ao seu cartão mesmo durante a rolagem."""
        key = (serial, process_id, session)
        if (session != self.grid_view_session or not getattr(self, "app_view_var", None)
                or self.app_view_var.get() != "celulares"):
            self.grid_live_position_pollers.discard(key)
            return
        process = self.grid_scrcpy_processes.get(serial)
        host = self.device_grid_hosts.get(serial)
        if not process or process.pid != process_id or process.poll() is not None or not host or not host.winfo_exists():
            self.grid_live_position_pollers.discard(key)
            return
        self._place_grid_live_view(serial, process_id, session)
        self.after(80, lambda item=key: self._poll_grid_live_view_position(*item))

    def _stop_grid_live_views(self, terminate: bool = True) -> None:
        """Fecha as telas simultâneas da grade sem mexer na visualização do Fluxo."""
        self.grid_capture_stop.set()
        self.grid_live_position_pollers.clear()
        self._hide_grid_markers()
        # Se a troca ocorreu com Ctrl/Alt pressionado, restaura o estilo da
        # janela antes de ocultÃ¡-la. Limpar somente o mapa deixava o scrcpy
        # transparente a cliques quando voltava para o Fluxo.
        try:
            user32 = ctypes.windll.user32
            for serial, style in tuple(self.grid_scrcpy_original_exstyles.items()):
                hwnd = int(self.grid_scrcpy_windows.get(serial, 0) or 0)
                if hwnd:
                    user32.SetWindowLongPtrW(wintypes.HWND(hwnd), -20, int(style))
        except (AttributeError, OSError):
            pass
        self.grid_scrcpy_original_exstyles.clear()
        processes = list(getattr(self, "grid_scrcpy_processes", {}).values())
        self.grid_scrcpy_processes.clear()
        self.grid_scrcpy_windows.clear()
        self.grid_scrcpy_recovery_attempts.clear()
        if not terminate:
            for process in processes:
                if process.poll() is None:
                    hwnd = self._window_for_process(process.pid, include_hidden=True)
                    if hwnd:
                        try:
                            ctypes.windll.user32.SetWindowPos(
                                wintypes.HWND(hwnd), 0, -32000, -32000, 2, 2, 0x0010 | 0x0040
                            )
                        except (AttributeError, OSError):
                            pass
            return
        for process in processes:
            if process.poll() is not None:
                continue
            try:
                process.terminate()
                process.wait(timeout=0.4)
            except subprocess.TimeoutExpired:
                try:
                    process.kill()
                except OSError:
                    pass
            except OSError:
                continue

    def _dispose_disconnected_live_view(self, serial: str) -> None:
        """Remove exclusivamente a reserva e a janela do aparelho que saiu.

        A atualização da lista não pode usar a limpeza geral da grade: ela
        também contém as janelas saudáveis que continuam conectadas. Cada
        serial possui uma única reserva, podendo estar na prévia do Fluxo ou
        em um cartão de Celulares; por isso todos os mapas são reconciliados
        aqui antes de reconstruir somente os widgets Tk da lista.
        """
        serial = str(serial or "")
        if not serial:
            return
        self.warm_scrcpy_queue = [item for item in self.warm_scrcpy_queue if item != serial]
        self.warm_scrcpy_retry_pending.discard(serial)
        self.warm_scrcpy_retry_attempts.pop(serial, None)
        self.grid_scrcpy_recovery_attempts.pop(serial, None)
        self._hide_grid_marker(serial)
        self.grid_marker_selected_items.pop(serial, None)
        self.grid_xml_marker_bounds.pop(serial, None)
        self.grid_xml_inspection_serial = "" if self.grid_xml_inspection_serial == serial else self.grid_xml_inspection_serial

        grid_hwnd = int(self.grid_scrcpy_windows.pop(serial, 0) or 0)
        warm_hwnd = int(self.warm_scrcpy_windows.pop(serial, 0) or 0)
        original_style = self.grid_scrcpy_original_exstyles.pop(serial, None)
        if original_style is not None and grid_hwnd:
            try:
                ctypes.windll.user32.SetWindowLongPtrW(wintypes.HWND(grid_hwnd), -20, int(original_style))
            except (AttributeError, OSError):
                pass

        candidates = [
            self.grid_scrcpy_processes.pop(serial, None),
            self.warm_scrcpy_processes.pop(serial, None),
        ]
        is_primary = str(self.scrcpy_serial or "") == serial
        if is_primary:
            candidates.append(self.scrcpy_process)
            self.live_view_session += 1
            self.live_view_mode = False
            self.live_view_edit_mode = False
            self.live_view_uses_warm_pool = False
            self._live_ctrl_record_start = None
            self._live_ctrl_record_mouse_down = False
            self._set_scrcpy_alt_passthrough(False)
            self._hide_live_touch_marker()
            self.scrcpy_process = None
            self.scrcpy_window_handle = 0
            self.scrcpy_window_title = ""
            self.scrcpy_window_bounds = None
            self.scrcpy_client_bounds = None
            self.scrcpy_serial = ""
            if getattr(self, "app_view_var", None) and self.app_view_var.get() == "fluxo":
                self._set_preview_message("O celular foi desconectado")

        for hwnd in {grid_hwnd, warm_hwnd}:
            if hwnd:
                try:
                    ctypes.windll.user32.ShowWindow(wintypes.HWND(hwnd), 0)
                except (AttributeError, OSError):
                    pass
        terminated: set[int] = set()
        for process in candidates:
            if not process or process.poll() is not None or process.pid in terminated:
                continue
            terminated.add(process.pid)
            try:
                process.terminate()
            except OSError:
                continue
            try:
                subprocess.Popen(
                    ["taskkill", "/PID", str(process.pid), "/T", "/F"],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                )
            except OSError:
                pass

        # Se o scrcpy caiu sozinho quando o cabo saiu, seu cliente ADB pode
        # sobreviver sem pai. Um novo scrcpy então chega a iniciar, porém pode
        # disputar o servidor antigo no próprio celular e nunca entregar o
        # vídeo ao cartão. Removemos apenas esses ADBs órfãos: clientes cujo
        # pai ainda é um scrcpy seguem intactos, inclusive os de outros apps.
        self.after(220, lambda target=serial: self._cleanup_orphaned_scrcpy_adb(target))

    def _cleanup_orphaned_scrcpy_adb(self, serial: str) -> None:
        """Encerra ADBs de scrcpy sem processo-pai, restritos a um serial."""
        if getattr(self, "_closing_now", False) or not serial:
            return
        escaped = str(serial).replace("'", "''")
        script = (
            "$all = Get-CimInstance Win32_Process; "
            "$byPid = @{}; foreach ($item in $all) { $byPid[[int]$item.ProcessId] = $item }; "
            f"$targets = $all | Where-Object {{ $_.Name -eq 'adb.exe' -and $_.CommandLine -like '*{escaped}*' "
            "-and $_.CommandLine -like '*com.genymobile.scrcpy.Server*' "
            "-and (-not $byPid.ContainsKey([int]$_.ParentProcessId) "
            "-or $byPid[[int]$_.ParentProcessId].Name -ne 'scrcpy.exe') }; "
            "$targets | Select-Object -ExpandProperty ProcessId"
        )
        try:
            result = subprocess.run(
                ["powershell.exe", "-NoProfile", "-NonInteractive", "-Command", script],
                capture_output=True, text=True, timeout=1.5, creationflags=NO_CONSOLE,
            )
            for value in result.stdout.splitlines():
                if not value.strip().isdigit():
                    continue
                subprocess.Popen(
                    ["taskkill", "/PID", value.strip(), "/T", "/F"],
                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                    creationflags=NO_CONSOLE,
                )
        except (OSError, subprocess.SubprocessError):
            pass

    def _close_orphaned_scrcpy_views(self, wait: bool = False) -> None:
        """Fecha somente scrcpy iniciado por esta instância do Iggents.

        Isso cobre uma janela de prévia que tenha sobrevivido a uma troca de
        tela, sem tocar em nenhum scrcpy aberto fora do programa.
        """
        script = (
            f"Get-CimInstance Win32_Process -Filter 'ParentProcessId={os.getpid()}' | "
            "Where-Object { $_.Name -eq 'scrcpy.exe' } | Select-Object -ExpandProperty ProcessId"
        )
        try:
            result = subprocess.run(
                ["powershell.exe", "-NoProfile", "-NonInteractive", "-Command", script],
                capture_output=True, text=True, timeout=5,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
            for value in result.stdout.splitlines():
                if not value.strip().isdigit():
                    continue
                command = ["taskkill", "/PID", value.strip(), "/T", "/F"]
                if wait:
                    subprocess.run(command, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                                   timeout=4, creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
                else:
                    subprocess.Popen(command, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                                     creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        except (OSError, subprocess.SubprocessError):
            pass

    def show_app_view(self, view: str) -> None:
        """Alterna entre a tela de edição de fluxo e a grade de celulares."""
        if not hasattr(self, "device_grid_view"):
            return
        if view == "celulares":
            self.stop_live_view()
            for widget in self._editor_root_widgets:
                widget.pack_forget()
            self.app_view_var.set("celulares")
            self.device_grid_view.pack(fill="both", expand=True, padx=22, pady=(0, 20))
            # Os cartões são pré-montados quando os aparelhos são detectados.
            # Não consulte ADB nem destrua/recrie a grade nesta troca: isso
            # era justamente a espera percebida na primeira entrada e em cada
            # retorno à aba. Caso a lista ainda não tenha chegado, fazemos a
            # montagem local com os perfis que já existirem.
            profiles = [item for item in self.device_profiles.values() if item.get("state") == "device"]
            expected = {str(item.get("serial", "")) for item in profiles}
            if expected and not expected.issubset(set(self.device_grid_hosts)):
                self._refresh_device_grid()
            self.update_idletasks()
            if profiles:
                self._start_grid_live_views(profiles, self.grid_view_session)
            self.view_flow_button.configure(fg_color="#2b3850")
            self.view_devices_button.configure(fg_color="#6d34bd")
        else:
            self._stop_grid_live_views(terminate=False)
            self.device_grid_view.pack_forget()
            for widget in self._editor_root_widgets:
                info = self._editor_pack_info.get(widget)
                if info:
                    widget.pack(**info)
            self.app_view_var.set("fluxo")
            self._restore_grid_stage_context_in_flow()
            self._render_execution_state()
            self.view_flow_button.configure(fg_color="#6d34bd")
            self.view_devices_button.configure(fg_color="#2b3850")
            # O telefone que já estava selecionado volta pela mesma reserva
            # coletiva dos demais. Só depois de todas as telas estarem
            # disponíveis a rotina final encaixa a escolhida na prévia.
            self._prepare_all_device_visuals(list(self.device_profiles.values()))

    def shortcut_show_app_view(self, view: str):
        """Alterna de visualização pelos atalhos Ctrl+1 e Ctrl+2."""
        self.show_app_view(view)
        return "break"

    def _restore_grid_stage_context_in_flow(self) -> None:
        """Restaura no editor o telefone e as etapas escolhidas na grade."""
        context = getattr(self, "grid_last_stage_context", {})
        serial = str(context.get("serial", "")).strip()
        panel = str(context.get("panel", "")).strip()
        items = tuple(str(item) for item in context.get("items", ()) if item)
        if not serial or not items:
            return
        if panel and panel != "__unassigned__" and self.flow_var.get() != panel:
            self.select_flow(panel)
        self._select_grid_device(serial)
        available = [item for item in items if self.tree.exists(item)]
        if not available:
            return
        focus = str(context.get("focus", ""))
        if focus not in available:
            focus = available[0]
        # Um filho pode ter sido escolhido com o grupo recolhido no editor.
        # Abrir seus ancestrais garante que ``see`` revele exatamente a etapa.
        parent = self.tree.parent(focus)
        while parent:
            self.tree.item(parent, open=True)
            parent = self.tree.parent(parent)
        self.tree.selection_set(available)
        self.tree.focus(focus)
        self.tree.see(focus)
        self.tree.focus_set()

    def _thread(self, target) -> threading.Thread:
        thread = threading.Thread(target=target, daemon=True)
        thread.start()
        return thread

    def _filter_action_buttons(self, *_args) -> None:
        """Filtra os atalhos de etapas pela busca lateral, sem alterar a macro."""
        if not hasattr(self, "_action_buttons"):
            return
        query = self.action_search_var.get().strip()
        strict_matches = []
        fuzzy_matches = []
        for index, item in enumerate(self._action_buttons):
            button, search_text, _options, _command = item
            button.pack_forget()
            if not query:
                strict_matches.append((0.0, index, item))
                continue
            strict_score = self._action_search_score(query, search_text, allow_fuzzy=False)
            if strict_score is not None:
                strict_matches.append((float(strict_score), index, item))
                continue
            fuzzy_score = self._action_search_score(query, search_text)
            if fuzzy_score is not None:
                fuzzy_matches.append((float(fuzzy_score), index, item))
        # Quando existir correspondência direta, não poluímos o resultado com
        # aproximações como "editar" para uma pesquisa por "digitar".
        matches = strict_matches or fuzzy_matches
        matches.sort(key=lambda item: (-item[0], item[1]))
        self._filtered_action_buttons = [item[2] for item in matches]
        for button, _search_text, options, _command in self._filtered_action_buttons:
            button.pack(**options)
        self.action_search_count.set(f"{len(matches)} etapa(s) disponível(is)")

    @staticmethod
    def _search_words(value: str) -> list[str]:
        """Normaliza acentos e separadores para a busca por palavras."""
        normalized = unicodedata.normalize("NFKD", value.casefold()).encode("ascii", "ignore").decode("ascii")
        return re.findall(r"[a-z0-9]+", normalized)

    @classmethod
    def _matches_action_search(cls, query: str, search_text: str) -> bool:
        """Aceita palavras em qualquer ordem e pequenos erros de digitação.

        Ex.: ``sms comprar`` e ``smspoool comprar`` encontram
        ``SMSPool: comprar número`` sem exigir a frase exata.
        """
        return cls._action_search_score(query, search_text) is not None

    @classmethod
    def _action_search_score(cls, query: str, search_text: str, allow_fuzzy: bool = True) -> float | None:
        """Pontua resultados: frases e títulos mais exatos ficam primeiro."""
        wanted = cls._search_words(query)
        available = cls._search_words(search_text)
        if not wanted:
            return 0.0
        if not available:
            return None
        score = 0.0
        for word in wanted:
            if word in available:
                score += 100.0
                continue
            # Termos curtos como o "R" de Nav-R não podem validar qualquer
            # palavra maior por acidente, como ocorria na busca por "digitar".
            contained = [candidate for candidate in available if len(word) >= 3 and len(candidate) >= 3
                         and (word in candidate or candidate in word)]
            if contained:
                score += 72.0 + max(min(len(word), len(candidate)) for candidate in contained)
                continue
            if not allow_fuzzy:
                return None
            similar = [difflib.SequenceMatcher(None, word, candidate).ratio()
                       for candidate in available if len(word) >= 4 and len(candidate) >= 4]
            best_similarity = max(similar, default=0.0)
            if best_similarity >= 0.76:
                score += 38.0 + best_similarity * 20.0
                continue
            return None
        phrase = " ".join(wanted)
        source = " ".join(available)
        phrase_position = source.find(phrase)
        if phrase_position >= 0:
            # Privilegia a ação cujo título começa pela mesma frase buscada.
            score += 500.0 - min(200.0, float(phrase_position))
        return score

    def _status_to_log(self, *_args) -> None:
        """Registra somente eventos úteis; andamento visual fica na árvore."""
        if self._suppress_status_log:
            return
        message = self.status.get().strip()
        low_value_prefixes = (
            "Atualizando os telefones", "Telefones conectados", "Iniciando em paralelo",
            "Iniciando macro", "Novas etapas gravadas", "Painel selecionado:",
            "Aguardando execução.", "Posição da etapa atualizada pela prévia.",
        )
        if message.startswith(low_value_prefixes):
            return
        if message and message != self._last_logged_status:
            self._last_logged_status = message
            self._append_execution_log(message)

    def _append_execution_log(self, entry: str, panel: str | None = None, serial: str | None = None) -> None:
        panel = str(panel or self.flow_var.get())
        stamped = f"[{datetime.now().strftime('%H:%M:%S')}] {entry}"
        entries = self.execution_logs_by_panel.setdefault(panel, [])
        entries.append(stamped)
        if len(entries) > 500:
            del entries[:-500]
        # Compatibilidade com a janela de log antiga; ela sempre representa o
        # painel atualmente aberto.
        if panel == self.flow_var.get():
            self.execution_log = entries
        else:
            self.execution_log = self.execution_logs_by_panel.get(self.flow_var.get(), [])
        if panel == self.flow_var.get():
            self._pending_log_widget_entries.append(stamped)
        self._append_device_grid_log(serial, stamped)

    def _flush_execution_log_widgets(self) -> None:
        """Escreve o lote pendente do log em uma única atualização visual."""
        entries = self._pending_log_widget_entries
        if not entries:
            return
        self._pending_log_widget_entries = []
        text = "\n".join(entries) + "\n"
        if self.log_text and self.log_window and self.log_window.winfo_exists():
            self.log_text.configure(state="normal")
            self.log_text.insert("end", text)
            self.log_text.see("end")
            self.log_text.configure(state="disabled")
        if self.inline_log_text and self.inline_log_text.winfo_exists():
            self.inline_log_text.configure(state="normal")
            self.inline_log_text.insert("end", text)
            self.inline_log_text.see("end")
            self.inline_log_text.configure(state="disabled")

    def _clear_inline_log(self) -> None:
        panel = self.flow_var.get()
        self.execution_logs_by_panel[panel] = []
        self.execution_log = self.execution_logs_by_panel[panel]
        self._pending_log_widget_entries = []
        if self.inline_log_text and self.inline_log_text.winfo_exists():
            self.inline_log_text.configure(state="normal")
            self.inline_log_text.delete("1.0", "end")
            self.inline_log_text.configure(state="disabled")
        if self.log_text and self.log_window and self.log_window.winfo_exists():
            self.log_text.configure(state="normal")
            self.log_text.delete("1.0", "end")
            self.log_text.configure(state="disabled")

    def show_execution_log(self) -> None:
        if self.log_window and self.log_window.winfo_exists():
            self.log_window.lift(); self.log_window.focus_force(); return
        window = tk.Toplevel(self)
        window.title("Log de execução")
        window.geometry("760x460")
        window.minsize(560, 300)
        window.configure(bg="#171b26")
        self.log_window = window
        text = tk.Text(window, bg="#202737", fg="#e7edf7", insertbackground="#ffffff", wrap="word", relief="flat", padx=10, pady=10)
        text.pack(fill="both", expand=True, padx=14, pady=(14, 8))
        if self.execution_log:
            text.insert("1.0", "\n".join(self.execution_log) + "\n")
        text.configure(state="disabled")
        self.log_text = text
        def clear() -> None:
            self.execution_log.clear(); text.configure(state="normal"); text.delete("1.0", "end"); text.configure(state="disabled")
            if self.inline_log_text and self.inline_log_text.winfo_exists():
                self.inline_log_text.configure(state="normal")
                self.inline_log_text.delete("1.0", "end")
                self.inline_log_text.configure(state="disabled")
        def close() -> None:
            self.log_text = None; self.log_window = None; window.destroy()
        ctk.CTkButton(window, text="Limpar log", command=clear, width=110, height=30, corner_radius=8,
                      fg_color="#39455b", hover_color="#4a5870").pack(side="left", padx=14, pady=(0, 14))
        ctk.CTkButton(window, text="Fechar", command=close, width=90, height=30, corner_radius=8,
                      fg_color="#39455b", hover_color="#4a5870").pack(side="right", padx=14, pady=(0, 14))
        window.protocol("WM_DELETE_WINDOW", close)

    def clear_action_search(self) -> None:
        self.action_search_var.set("")

    def _filter_tree_steps(self, *_args) -> None:
        """Destaca etapas já presentes no fluxo sem alterar a macro."""
        if not hasattr(self, "tree"):
            return
        query = self.tree_search_var.get().strip()
        # Cada termo separado por vírgula é uma busca independente. Assim,
        # "curtir, patrocinado" destaca as etapas de qualquer um dos dois.
        queries = [part.strip() for part in query.split(",") if part.strip()]
        matches: list[tuple[float, str]] = []

        def walk(parent: str = ""):
            for item in self.tree.get_children(parent):
                yield item
                yield from walk(item)

        for item in walk():
            tags = tuple(tag for tag in self.tree.item(item, "tags") if tag != "search_match")
            self.tree.item(item, tags=tags)
            if not queries:
                continue
            values = " ".join(str(value) for value in self.tree.item(item, "values"))
            text = f"{self.tree.item(item, 'text')} {values}"
            scores = [self._action_search_score(term, text) for term in queries]
            valid_scores = [float(score) for score in scores if score is not None]
            if valid_scores:
                matches.append((max(valid_scores), item))

        matches.sort(key=lambda entry: -entry[0])
        query_changed = query != getattr(self, "_tree_search_last_query", "")
        self._tree_search_last_query = query
        self._tree_search_matches = [item for _score, item in matches]
        self._tree_search_index = -1
        self.tree_search_count.set(f"{len(matches)} encontrada(s)" if queries else "")
        for _score, item in matches:
            tags = tuple(self.tree.item(item, "tags"))
            if "running" not in tags:
                self.tree.item(item, tags=(*tags, "search_match"))
            parent = self.tree.parent(item)
            while parent:
                self.tree.item(parent, open=True)
                parent = self.tree.parent(parent)
        if matches and query_changed:
            self.tree.see(matches[0][1])

    def next_tree_search_result(self, _event=None):
        """Vai para o próximo resultado da busca no fluxo."""
        matches = [item for item in self._tree_search_matches if self.tree.exists(item)]
        if not matches:
            return "break"
        self._tree_search_index = (self._tree_search_index + 1) % len(matches)
        item = matches[self._tree_search_index]
        self.tree.selection_set(item)
        self.tree.focus(item)
        self.tree.see(item)
        self.tree.focus_set()
        return "break"

    def clear_tree_search(self) -> None:
        self.tree_search_var.set("")

    def focus_tree_search(self, _event=None):
        self.tree_search_entry.focus_set()
        self.tree_search_entry.select_range(0, "end")
        return "break"

    def focus_action_search(self, _event=None):
        # Em Celulares a lateral é exibida sobre a própria grade, mantendo o
        # cartão e a seleção que receberão a nova etapa.
        if getattr(self, "app_view_var", None) and self.app_view_var.get() == "celulares":
            tree = getattr(_event, "widget", None)
            serial = next((value for value, candidate in self.device_grid_flow_trees.items()
                           if candidate is tree), "")
            if not serial:
                selected = self.selected_profiles()
                serial = str(selected[0].get("serial", "")) if selected else ""
                tree = self.device_grid_flow_trees.get(serial)
            panel = str(getattr(tree, "grid_panel", "")) if tree else self._grid_panel_for_serial(serial)
            if serial and tree and panel and panel != "__unassigned__":
                self._show_grid_action_drawer(serial, panel, tree)
            else:
                self.status.set("Abra as etapas de um celular e selecione onde deseja inserir a nova etapa.")
            return "break"
        self._show_action_drawer()
        # A gaveta acabou de ganhar posição na tela; aguardar o próximo ciclo
        # evita que o foco seja perdido pelo reposicionamento do Tk.
        self.after_idle(self._focus_action_search_entry)
        return "break"

    def _focus_action_search_entry(self) -> None:
        if hasattr(self, "action_search_entry"):
            self.action_search_entry.focus_set()
            self.action_search_entry.select_range(0, "end")

    def _show_action_drawer(self) -> None:
        """Exibe a lista de etapas como uma gaveta flutuante à direita."""
        drawer = getattr(self, "action_drawer", None)
        if not drawer:
            return
        drawer.place(relx=1.0, rely=0.5, relheight=0.9, anchor="e", width=248)
        drawer.lift()
        self.action_drawer_open = True

    def _minimize_action_drawer(self) -> None:
        """Recolhe a lista para que ela não reserve espaço no editor."""
        drawer = getattr(self, "action_drawer", None)
        if drawer:
            drawer.place_forget()
        self.action_drawer_open = False

    def _show_grid_action_drawer(self, serial: str, panel: str, tree: ttk.Treeview) -> None:
        """Abre uma lista flutuante de ações, sempre no viewport visível."""
        if not self._grid_activate_tree_item(serial, panel, tree):
            self.status.set("Selecione uma etapa ou grupo no cartão antes de adicionar uma ação.")
            return
        old_drawer = getattr(self, "device_grid_action_drawer", None)
        if old_drawer and old_drawer.winfo_exists():
            old_drawer.destroy()
        # A grade vive dentro do Canvas rolável principal. Um Frame nela sai
        # da área visível junto com os cartões; esta janela pertence ao app e
        # fica posicionada no viewport, não no conteúdo rolável.
        drawer = tk.Toplevel(self)
        drawer.withdraw()
        drawer.configure(bg="#171b26", highlightthickness=1, highlightbackground="#6940a8")
        drawer.transient(self)
        drawer.title("Adicionar etapa")
        drawer.resizable(False, True)
        # As telas scrcpy são janelas nativas de outro processo. Mantemos a
        # ferramenta acima delas enquanto estiver aberta, sem escondê-las.
        drawer.wm_attributes("-topmost", True)
        drawer.protocol("WM_DELETE_WINDOW", self._close_grid_action_drawer)
        self.device_grid_action_drawer = drawer
        self._position_grid_action_drawer()
        top = tk.Frame(drawer, bg="#171b26"); top.pack(fill="x", padx=10, pady=(10, 7))
        tk.Label(top, text="Adicionar etapa", bg="#171b26", fg="#f1f5f9", font=("Segoe UI", 13, "bold")).pack(side="left")
        ctk.CTkButton(top, text="×", width=28, height=26, corner_radius=6, fg_color="#39455b",
                      command=self._close_grid_action_drawer).pack(side="right")
        query = tk.StringVar()
        entry = ctk.CTkEntry(drawer, textvariable=query, placeholder_text="Pesquisar etapa…", height=30)
        entry.pack(fill="x", padx=10, pady=(0, 8))
        list_area = tk.Frame(drawer, bg="#171b26")
        list_area.pack(fill="both", expand=True, padx=10, pady=(0, 10))
        action_canvas = tk.Canvas(list_area, bg="#171b26", highlightthickness=0, borderwidth=0)
        action_scroll = ttk.Scrollbar(list_area, orient="vertical", command=action_canvas.yview)
        action_canvas.configure(yscrollcommand=action_scroll.set)
        action_scroll.pack(side="right", fill="y")
        action_canvas.pack(side="left", fill="both", expand=True)
        holder = tk.Frame(action_canvas, bg="#171b26")
        holder_window = action_canvas.create_window((0, 0), window=holder, anchor="nw")
        holder.bind("<Configure>", lambda _event: action_canvas.configure(scrollregion=action_canvas.bbox("all")))
        action_canvas.bind("<Configure>", lambda event: action_canvas.itemconfigure(holder_window, width=event.width))
        for scroll_target in (action_canvas, holder, action_scroll):
            scroll_target.bind("<MouseWheel>",
                               lambda event, target=action_canvas: self._scroll_embedded_panel_widget(event, target), add="+")
        visible_actions = []

        def refresh(*_args) -> None:
            for child in holder.winfo_children(): child.destroy()
            visible_actions.clear()
            needle = query.get().strip().casefold()
            for button, search_text, _options, invoke in self._action_buttons:
                if needle and needle not in search_text:
                    continue
                def add(command=invoke) -> None:
                    # Fechar antes de abrir um diálogo de configuração evita
                    # que a janela flutuante cubra esse próximo diálogo.
                    self._close_grid_action_drawer()
                    command()
                    self._reload_compact_flow_tree(tree, serial, panel, getattr(tree, "grid_fallback_model", ""))
                visible_actions.append(add)
                ttk.Button(holder, text=button.cget("text"), command=add).pack(fill="x", pady=2)
        def add_first(_event=None):
            if visible_actions:
                visible_actions[0]()
            return "break"
        query.trace_add("write", refresh); entry.bind("<Return>", add_first); refresh()
        self.bind("<Configure>", lambda _event: self._position_grid_action_drawer(), add="+")
        drawer.deiconify()
        self._position_grid_action_drawer()
        entry.focus_set()

    def _position_grid_action_drawer(self) -> None:
        """Centraliza a lista de etapas no viewport, independente da rolagem."""
        drawer = getattr(self, "device_grid_action_drawer", None)
        if not drawer or not drawer.winfo_exists():
            return
        try:
            margin = 18
            width = min(330, max(180, self.winfo_width() - margin * 2))
            height = min(690, max(160, self.winfo_height() - margin * 2))
            x = self.winfo_rootx() + max(margin, self.winfo_width() - width - margin)
            y = self.winfo_rooty() + max(margin, (self.winfo_height() - height) // 2)
            drawer.geometry(f"{width}x{height}+{x}+{y}")
            drawer.lift()
        except tk.TclError:
            pass

    def _close_grid_action_drawer(self) -> None:
        drawer = getattr(self, "device_grid_action_drawer", None)
        if drawer and drawer.winfo_exists(): drawer.destroy()
        self.device_grid_action_drawer = None

    def add_first_filtered_action(self, _event=None):
        """Adiciona a primeira etapa encontrada ao pressionar Enter na busca."""
        query = self.action_search_var.get().strip()
        if not query:
            return "break"
        filtered = getattr(self, "_filtered_action_buttons", [])
        if filtered:
            filtered[0][3]()
        return "break"

    @property
    def actions(self) -> list[Action]:
        return [action for group in self.macros[self.flow_var.get()] for action in group["actions"]]

    def push_undo(self, selection: tuple[str, ...] | None = None, focus: str | None = None) -> None:
        if selection is None:
            selection = tuple(self.tree.selection()) if hasattr(self, "tree") else ()
        if focus is None:
            focus = self.tree.focus() if hasattr(self, "tree") else ""
        self.undo_stack.append((self.flow_var.get(), self.device_model, copy.deepcopy(self.macros[self.flow_var.get()]), selection, focus))
        if len(self.undo_stack) > 60:
            self.undo_stack.pop(0)
        # Qualquer edição nova cria uma linha do tempo diferente; portanto não
        # existe mais um estado coerente para refazer.
        self.redo_stack.clear()

    def _restore_history_entry(self, entry: tuple[str, str, list[dict], tuple[str, ...], str]) -> None:
        """Restaura um estado completo da macro, incluindo seleção e foco."""
        flow, model, snapshot, selection, focus = entry
        self.flow_var.set(flow)
        self.device_model = model
        self.macros[flow] = snapshot
        self.active_group = len(snapshot) - 1 if snapshot else None
        self.refresh_tree()
        restored = [item for item in selection if self.tree.exists(item)]
        if restored:
            self.tree.selection_set(restored)
            target = focus if focus in restored else restored[0]
            self.tree.focus(target); self.tree.see(target)
        if self.adb.serial:
            self.save_macro(quiet=True)

    def undo(self, _event=None):
        if not self.undo_stack:
            self.status.set("Nada para desfazer.")
            return "break"
        current = (self.flow_var.get(), self.device_model,
                   copy.deepcopy(self.macros[self.flow_var.get()]),
                   tuple(self.tree.selection()), self.tree.focus())
        self.redo_stack.append(current)
        if len(self.redo_stack) > 60:
            self.redo_stack.pop(0)
        self._restore_history_entry(self.undo_stack.pop())
        self.status.set("Última alteração desfeita.")
        return "break"

    def redo(self, _event=None):
        """Refaz a alteração mais recente que foi desfeita com Ctrl+Z."""
        if not self.redo_stack:
            self.status.set("Nada para refazer.")
            return "break"
        current = (self.flow_var.get(), self.device_model,
                   copy.deepcopy(self.macros[self.flow_var.get()]),
                   tuple(self.tree.selection()), self.tree.focus())
        self.undo_stack.append(current)
        if len(self.undo_stack) > 60:
            self.undo_stack.pop(0)
        self._restore_history_entry(self.redo_stack.pop())
        self.status.set("Alteração refeita.")
        return "break"

    def new_group(self, name: str | None = None) -> int:
        # A criação foi disparada pela gaveta de etapas: assim que a inclusão
        # for aceita, devolvemos toda a largura ao editor.
        if getattr(self, "action_drawer_open", False):
            self.after_idle(self._minimize_action_drawer)
        if not self.recording_undo_active:
            self.push_undo()
        groups = self.macros[self.flow_var.get()]
        # A regra de encaixe é a mesma da lista inteira: cabeçalho aberto
        # recebe o novo bloco como primeiro filho; fechado recebe um irmão;
        # uma etapa recebe o novo bloco logo abaixo dela.
        selected = self.tree.selection()
        if len(selected) == 1:
            parts = selected[0].split(":")
            group_name = name or f"Grupo {sum(len(item['actions']) for item in groups) + 1}"
            if parts[0] == "g":
                group_index = int(parts[1])
                if not 0 <= group_index < len(groups):
                    return self.active_group or 0
                if self._container_accepts_first_child(selected[0], groups[group_index]["actions"]):
                    groups[group_index]["actions"].insert(0, Action("subgroup", label=group_name, delay_ms=0, nested_actions=[]))
                    item = f"a:{group_index}:0"
                    self.active_group = group_index
                    self.refresh_tree(); self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
                    return group_index
                groups.insert(group_index + 1, {"name": group_name, "enabled": True, "actions": []})
                self.active_group = group_index + 1
                self.refresh_tree()
                item = f"g:{self.active_group}"
                self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
                return self.active_group
            if parts[0] == "a" or parts[0].startswith("s"):
                action = Action("subgroup", label=group_name, delay_ms=0, nested_actions=[])
                group_index, action_index = self._insert_new_action(action)
                item = getattr(self, "last_inserted_tree_item", f"a:{group_index}:{action_index}")
                self.refresh_tree(); self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
                return group_index
        group_name = name or f"Grupo {len(groups) + 1}"
        groups.append({"name": group_name, "enabled": True, "actions": []})
        self.active_group = len(groups) - 1
        self.refresh_tree()
        return self.active_group

    def _selected_subgroup_actions(self) -> list[Action] | None:
        """Retorna as etapas do subgrupo selecionado, convertendo macros antigas se preciso."""
        selected = self.tree.selection()
        if len(selected) != 1:
            return None
        # A seleção pode estar em qualquer profundidade: s, ss, sss...
        # Se for o cabeçalho de um contêiner, a nova etapa entra nele. Se
        # for uma etapa comum dentro de um contêiner, entra entre as irmãs.
        location = self._tree_action_container(selected[0])
        if location is not None:
            _group_index, parent_values, selected_index = location
            if 0 <= selected_index < len(parent_values):
                selected_action = parent_values[selected_index]
                values = self._container_actions(selected_action)
                if values is not None:
                    # O cabeçalho aberto é a intenção explícita de gravar
                    # DENTRO do grupo. Fechado, ele se comporta como um bloco
                    # concluído e a gravação segue como irmã, abaixo dele.
                    if self._container_accepts_first_child(selected[0], values):
                        return values
                    return None
                if selected[0].split(":")[0].startswith("s"):
                    return parent_values
        parts = selected[0].split(":")
        # Uma etapa filha selecionada continua pertencendo ao mesmo contêiner.
        # Assim, adicionar ou gravar depois da última linha ainda insere dentro
        # do subgrupo/Nav aberto, em vez de criar uma etapa irmã dele.
        if len(parts) == 4 and parts[0] == "s":
            location = self._tree_action_container(selected[0])
            if location is None:
                return None
            _group_index, parent_values, selected_index = location
            # Ao selecionar o cabeçalho de um grupo interno, a próxima etapa
            # precisa ir PARA DENTRO dele. Antes retornávamos sempre o
            # contêiner-pai, fazendo as etapas parecerem irmãs do XML.
            selected_action = parent_values[selected_index]
            if selected_action.kind == "subgroup":
                values = selected_action.nested_actions or []
                converted = [item if isinstance(item, Action) else Action(**item) for item in values]
                selected_action.nested_actions = converted
                return converted
            if selected_action.kind == "xml_logic":
                values = selected_action.branch_actions or []
                converted = [item if isinstance(item, Action) else Action(**item) for item in values]
                selected_action.branch_actions = converted
                return converted
            return parent_values
        if len(parts) != 3 or parts[0] != "a":
            return None
        try:
            group_index, action_index = int(parts[1]), int(parts[2])
            action = self.macros[self.flow_var.get()][group_index]["actions"][action_index]
        except (IndexError, ValueError):
            return None
        if action.kind == "subgroup":
            values = action.nested_actions or []
        elif action.kind == "xml_logic":
            values = action.branch_actions or []
        else:
            return None
        converted = [item if isinstance(item, Action) else Action(**item) for item in values]
        if action.kind == "subgroup":
            action.nested_actions = converted
        else:
            action.branch_actions = converted
        return converted

    def _selected_inline_nav_actions(self) -> list[dict] | None:
        """Etapas gravadas de um Nav-R/Nav-S inserido diretamente no fluxo."""
        selected = self.tree.selection()
        if len(selected) != 1:
            return None
        parts = selected[0].split(":")
        try:
            groups = self.macros[self.flow_var.get()]
            if len(parts) == 3 and parts[0] == "a":
                action = groups[int(parts[1])]["actions"][int(parts[2])]
            elif len(parts) == 4 and parts[0] == "s":
                # Selecionar qualquer etapa já dentro do Nav também significa
                # adicionar a próxima etapa dentro dele, não fora dele.
                action = groups[int(parts[1])]["actions"][int(parts[2])]
            else:
                return None
        except (IndexError, ValueError):
            return None
        if action.kind not in ("navigate_r", "navigate_s", "navigate_rc"):
            return None
        if action.kind == "navigate_rc":
            if action.nav_rc_actions is None:
                action.nav_rc_actions = []
            return action.nav_rc_actions
        if action.nav_actions is None:
            action.nav_actions = []
        return action.nav_actions

    def _container_actions(self, action: Action) -> list[Action] | None:
        """Normaliza e devolve as etapas internas de qualquer tipo de grupo."""
        field = ("nested_actions" if action.kind == "subgroup" else
                 "branch_actions" if action.kind in ("xml_logic", "xml_any_tap", "xml_list") else
                 "nav_rc_actions" if action.kind == "navigate_rc" else
                 "nav_actions" if action.kind in ("navigate_r", "navigate_s") else None)
        if field is None:
            return None
        # Não substitua uma lista vazia por outra lista: Nav-R-C compartilha a
        # própria lista interna com o Nav-R pai e precisa manter essa referência
        # ao receber novas etapas.
        values = getattr(action, field)
        if values is None:
            values = []
        converted = values if all(isinstance(value, Action) for value in values) else [
            value if isinstance(value, Action) else Action(**value) for value in values
        ]
        setattr(action, field, converted)
        return converted

    def _container_accepts_first_child(self, item: str, children: list[Action]) -> bool:
        """Um grupo vazio ainda é um grupo aberto para fins de inserção.

        O Treeview não mostra a seta de expandir quando um grupo acabou de ser
        criado e não tem filhos. Antes isso fazia o primeiro clique em
        ``+ Etapa`` virar irmão do Grupo XML condicional, em vez de filho.
        """
        return not children or bool(self.tree.item(item, "open"))

    def _tree_action_container(self, item: str) -> tuple[int, list[Action], int] | None:
        """Localiza uma etapa da árvore, inclusive quando ela está dentro de um contêiner."""
        parts = item.split(":")
        groups = self.macros[self.flow_var.get()]
        try:
            if len(parts) == 3 and parts[0] == "a":
                group_index, action_index = int(parts[1]), int(parts[2])
                return group_index, groups[group_index]["actions"], action_index
            # s, ss, sss... representam níveis ilimitados da árvore.
            if parts and parts[0] and set(parts[0]) == {"s"}:
                depth = len(parts[0])
                if len(parts) != depth + 3:
                    return None
                group_index = int(parts[1])
                path = [int(value) for value in parts[2:]]
                values: list[Action] = groups[group_index]["actions"]
                for container_index in path[:-1]:
                    values = self._container_actions(values[container_index])
                    if values is None:
                        return None
                return group_index, values, path[-1]
            if len(parts) == 4 and parts[0] == "s":
                group_index, parent_index, action_index = (int(parts[1]), int(parts[2]), int(parts[3]))
                parent = groups[group_index]["actions"][parent_index]
                values = (parent.nested_actions if parent.kind == "subgroup" else
                          parent.branch_actions if parent.kind == "xml_logic" else
                          parent.nav_rc_actions if parent.kind == "navigate_rc" else parent.nav_actions)
                if values is None:
                    return None
                # Só converte macros antigas uma vez. Recriar uma lista nova a
                # cada item selecionado fazia duas etapas do mesmo Nav-S
                # parecerem pertencer a contêineres diferentes ao apagar ou
                # mover em conjunto.
                converted = values if all(isinstance(value, Action) for value in values) else [
                    value if isinstance(value, Action) else Action(**value) for value in values
                ]
                if parent.kind == "subgroup":
                    parent.nested_actions = converted
                elif parent.kind == "xml_logic":
                    parent.branch_actions = converted
                elif parent.kind in ("navigate_r", "navigate_s"):
                    # Mantém objetos enquanto a pessoa reorganiza; ao salvar,
                    # asdict converte novamente para JSON.
                    parent.nav_actions = converted
                elif parent.kind == "navigate_rc":
                    parent.nav_rc_actions = converted
                else:
                    return None
                return group_index, converted, action_index
            if len(parts) == 5 and parts[0] == "ss":
                group_index, parent_index, xml_index, action_index = (int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4]))
                parent = groups[group_index]["actions"][parent_index]
                parent_values = (parent.nested_actions if parent.kind == "subgroup" else
                                 parent.branch_actions if parent.kind == "xml_logic" else
                                 parent.nav_actions)
                if parent_values is None:
                    return None
                parent_values = [value if isinstance(value, Action) else Action(**value) for value in parent_values]
                if parent.kind == "subgroup": parent.nested_actions = parent_values
                elif parent.kind == "xml_logic": parent.branch_actions = parent_values
                else: parent.nav_actions = parent_values
                xml_action = parent_values[xml_index]
                if xml_action.kind != "xml_logic":
                    return None
                values = [value if isinstance(value, Action) else Action(**value) for value in (xml_action.branch_actions or [])]
                xml_action.branch_actions = values
                return group_index, values, action_index
        except (IndexError, ValueError):
            return None
        return None

    def add_subgroup(self) -> None:
        """Cria um contÃªiner de etapas no ponto selecionado do fluxo."""
        if not self.tree.selection():
            messagebox.showwarning("Subgrupo", "Selecione um grupo ou uma etapa onde deseja criar o subgrupo.", parent=self)
            return
        name = simpledialog.askstring("Subgrupo", "Nome do subgrupo:", parent=self)
        if not name or not name.strip():
            return
        self.push_undo()
        action = Action("subgroup", label=name.strip(), delay_ms=0, nested_actions=[])
        group_index, action_index = self._insert_new_action(action)
        item = getattr(self, "last_inserted_tree_item", f"a:{group_index}:{action_index}")
        self.refresh_tree(); self.tree.selection_set(item); self.tree.focus(item)
        self.save_macro(quiet=True)
        self.status.set(f"Subgrupo ‘{name.strip()}’ criado. Selecione-o e grave ou adicione as etapas dentro dele.")

    def configure_inline_xml_logic_action(self, action: Action, tree_item: str | None = None) -> None:
        """Edita uma rota XML interna sem substituir as etapas da rota."""
        dialog = tk.Toplevel(self)
        dialog.title("Configurar rota especial XML")
        dialog.geometry("660x300")
        dialog.resizable(False, False)
        dialog.configure(bg="#171b26")
        dialog.transient(self)
        dialog.grab_set()

        query = tk.StringVar(value=action.selector_value or "")
        blocked = tk.StringVar(value=action.selector_blocked_text or "")
        timeout = tk.StringVar(value=f"{max(0.1, float(action.timeout_s or 1)):g}")

        body = ctk.CTkFrame(dialog, fg_color="transparent")
        body.pack(fill="both", expand=True, padx=22, pady=(20, 12))
        ctk.CTkLabel(body, text="Rota especial XML", font=("Segoe UI", 17, "bold")).grid(
            row=0, column=0, columnspan=2, sticky="w", pady=(0, 12))
        ctk.CTkLabel(body, text="XML para detectar:").grid(row=1, column=0, sticky="w", pady=5)
        query_entry = ctk.CTkEntry(body, textvariable=query, height=32, corner_radius=8,
                                   fg_color="#222938", border_color="#465166", text_color="#f8fafc")
        query_entry.grid(row=1, column=1, sticky="ew", padx=(14, 0), pady=5)
        ctk.CTkLabel(body, text="Ignorar se também houver (vírgulas):").grid(row=2, column=0, sticky="w", pady=5)
        ctk.CTkEntry(body, textvariable=blocked, height=32, corner_radius=8,
                     fg_color="#222938", border_color="#465166", text_color="#f8fafc").grid(
            row=2, column=1, sticky="ew", padx=(14, 0), pady=5)
        ctk.CTkLabel(body, text="Esperar até (segundos):").grid(row=3, column=0, sticky="w", pady=5)
        ctk.CTkEntry(body, textvariable=timeout, width=100, height=32, corner_radius=8,
                     fg_color="#222938", border_color="#465166", text_color="#f8fafc").grid(
            row=3, column=1, sticky="w", padx=(14, 0), pady=5)
        ctk.CTkLabel(body, text="As etapas já colocadas dentro desta rota serão preservadas.",
                     text_color="#a8b2c4").grid(row=4, column=0, columnspan=2, sticky="w", pady=(10, 0))
        body.grid_columnconfigure(1, weight=1)

        def save() -> None:
            value = query.get().strip()
            if not value:
                messagebox.showwarning("Rota especial XML", "Informe o XML ou texto que deve acionar esta rota.", parent=dialog)
                return
            selector_type = "search"
            if value.startswith("{"):
                try:
                    exact = json.loads(value)
                    if not isinstance(exact, dict) or not exact:
                        raise ValueError
                    selector_type = "exact_xml"
                except (json.JSONDecodeError, ValueError):
                    messagebox.showwarning("Rota especial XML", "O XML exato precisa ser um objeto JSON válido.", parent=dialog)
                    return
            try:
                wait_seconds = max(0.1, float(timeout.get().strip()))
            except ValueError:
                messagebox.showwarning("Rota especial XML", "Informe um tempo de espera válido.", parent=dialog)
                return
            self.push_undo()
            action.selector_type = selector_type
            action.selector_value = value
            action.selector_blocked_text = blocked.get().strip()
            action.timeout_s = wait_seconds
            self.refresh_tree()
            if tree_item and self.tree.exists(tree_item):
                self.tree.selection_set(tree_item); self.tree.focus(tree_item); self.tree.see(tree_item)
            self.save_macro(quiet=True)
            self.status.set("Rota especial XML atualizada.")
            dialog.destroy()

        controls = ctk.CTkFrame(dialog, fg_color="transparent")
        controls.pack(fill="x", padx=22, pady=(0, 18))
        ctk.CTkButton(controls, text="Cancelar", command=dialog.destroy, width=100, height=34,
                      fg_color="#39455b", hover_color="#4a5870").pack(side="right", padx=(8, 0))
        ctk.CTkButton(controls, text="Salvar", command=save, width=100, height=34,
                      fg_color="#6d35ba", hover_color="#8347d0").pack(side="right")
        dialog.bind("<Control-Return>", lambda _event: save())
        dialog.after(100, query_entry.focus_set)

    def configure_selected_special_group(self) -> None:
        selected = self.tree.selection()
        if len(selected) != 1:
            messagebox.showwarning("Configurar", "Selecione uma etapa XML ou um grupo configurável.", parent=self)
            return
        parts = selected[0].split(":")
        # Nav-R/Nav-S também podem estar dentro de qualquer quantidade de
        # subgrupos. Nessas linhas o id começa com s, ss, sss...; resolvemos a
        # ação pelo caminho da árvore antes de decidir a configuração.
        if parts[0] not in ("g", "a"):
            location = self._tree_action_container(selected[0])
            if location is None:
                return
            group_index, actions, action_index = location
            if not 0 <= action_index < len(actions):
                return
            action = actions[action_index]
            if action.kind in ("xml_tap", "xml_group_gate", "xml_restart_loop"):
                self.add_xml_action(gate_group=action.kind == "xml_group_gate",
                                    restart_loop=action.kind == "xml_restart_loop",
                                    tree_ref=selected[0])
                return
            if action.kind == "xml_logic":
                self.configure_inline_xml_logic_action(action, selected[0])
                return
            if action.kind == "xml_any_tap":
                self.add_xml_any_tap_group(action_override=action, tree_item=selected[0])
                return
            if action.kind == "xml_list":
                self.add_xml_list_action(action_override=action, tree_item=selected[0])
                return
            if action.kind == "subgroup":
                self.configure_subgroup_action(group_index, action_index, action_override=action, tree_item=selected[0])
                return
            if action.kind == "schedule_divider":
                self.configure_schedule_divider(action)
                return
            if action.kind in ("navigate_r", "navigate_s"):
                self.configure_inline_navigation_action(group_index, action_index,
                                                        action_override=action,
                                                        tree_item=selected[0])
                return
            if action.kind == "navigate_rc":
                self.configure_inline_nav_rc_action(action, selected[0])
                return
            if action.kind in ("smspool_order", "smspool_code"):
                self.configure_number_api_action(action, selected[0])
                return
            if action.kind in ("pc_automation", "pc_copy_link_to_phone"):
                # A automação do PC pode estar em qualquer profundidade.
                # Editá-la por índice do grupo principal quebra em subgrupos.
                self.add_pc_automation_action(action_override=action, tree_item=selected[0])
                return
            if action.kind == "browser_invite":
                self.configure_browser_invite_action(action, selected[0])
                return
            messagebox.showwarning("Configurar", "Esta etapa interna não possui configuração própria. Use F5 para variações ou edite a espera na coluna.", parent=self)
            return
        group_index = int(parts[1])
        group = self.macros[self.flow_var.get()][group_index]
        if parts[0] == "g" and group.get("schedule_divider_group"):
            actions = group.get("actions") or []
            if actions:
                divider = actions[0]
                if isinstance(divider, dict):
                    divider = Action(**divider)
                    group["actions"][0] = divider
                if isinstance(divider, Action):
                    self.configure_schedule_divider(divider)
                    return
        if parts[0] == "a":
            action_index = int(parts[2])
            action = group["actions"][action_index]
            if action.kind == "subgroup":
                self.configure_subgroup_action(group_index, action_index)
                return
            if action.kind == "schedule_divider":
                self.configure_schedule_divider(action)
                return
            if action.kind in ("navigate_r", "navigate_s"):
                self.configure_inline_navigation_action(group_index, action_index)
                return
            if action.kind == "navigate_rc":
                self.configure_inline_nav_rc_action(action, selected[0])
                return
            if action.kind in ("xml_tap", "xml_group_gate", "xml_restart_loop"):
                self.add_xml_action(gate_group=action.kind == "xml_group_gate",
                                    restart_loop=action.kind == "xml_restart_loop",
                                    action_ref=(group_index, action_index))
                return
            if action.kind == "xml_logic":
                self.configure_inline_xml_logic_action(action, selected[0])
                return
            if action.kind == "xml_any_tap":
                self.add_xml_any_tap_group(action_override=action, tree_item=selected[0])
                return
            if action.kind == "xml_list":
                self.add_xml_list_action(action_override=action, tree_item=selected[0])
                return
            if action.kind == "nav_rc_type":
                self.configure_nav_rc_type_action(group_index, action_index)
                return
            if action.kind == "configure_proxy":
                self.add_proxy_action(action_ref=(group_index, action_index))
                return
            if action.kind in ("smspool_order", "smspool_code"):
                self.configure_number_api_action(action, selected[0])
                return
            if action.kind in ("pc_automation", "pc_copy_link_to_phone"):
                self.add_pc_automation_action(action_ref=(group_index, action_index))
                return
            if action.kind == "browser_invite":
                self.configure_browser_invite_action(action, selected[0])
                return
            if action.kind in ("instagram_ready", "launch_app") and (action.package_name or "com.instagram.android") == "com.instagram.android":
                self.configure_instagram_action(group_index, action_index)
                return
            messagebox.showwarning("Configurar", "Esta etapa não possui configuração própria.", parent=self)
            return
        if group.get("navigation_r"):
            self.add_navigate_r_group(group_index)
            return
        if group.get("training_loop"):
            self.add_training_loop_group(group_index)
            return
        if group.get("validation_loop"):
            self.add_validation_loop_group(group_index)
            return
        if group.get("xml_restart_loop_group"):
            self.add_xml_restart_loop_group(group_index)
            return
        if group.get("navigation_rc"):
            self.add_navigate_rc_group(group_index)
            return
        if group.get("navigation_s"):
            self.add_navigate_s_group(group_index)
            return
        if group.get("xml_logic_group"):
            self.add_xml_logic_action(group_index)
            return
        if group.get("xml_any_tap_group"):
            self.add_xml_any_tap_group(group_index)
            return
        self.configure_group_execution_chance(group_index)

    def configure_group_execution_chance(self, group_index: int) -> None:
        """Configura a probabilidade de entrada de um grupo comum do fluxo."""
        groups = self.macros[self.flow_var.get()]
        if not 0 <= group_index < len(groups):
            return
        group = groups[group_index]
        dialog = tk.Toplevel(self)
        dialog.title("Chance do grupo")
        dialog.geometry("440x215"); dialog.resizable(False, False)
        dialog.configure(bg="#171b26"); dialog.transient(self); dialog.grab_set()
        chance = tk.StringVar(value=f"{float(group.get('execution_chance_pct', 100)):g}")
        ctk.CTkLabel(dialog, text=f"Grupo: {group.get('name', 'Grupo')}", font=("Segoe UI", 16, "bold")).pack(anchor="w", padx=22, pady=(22, 12))
        row = ctk.CTkFrame(dialog, fg_color="transparent")
        row.pack(fill="x", padx=22)
        ctk.CTkLabel(row, text="Chance de executar (%):").pack(side="left")
        ctk.CTkEntry(row, textvariable=chance, width=90, height=32, corner_radius=8,
                     fg_color="#222938", border_color="#465166", text_color="#f8fafc").pack(side="left", padx=(12, 0))
        ctk.CTkLabel(dialog, text="Quando não for sorteado, o grupo inteiro é ignorado e o fluxo segue para o próximo.",
                     wraplength=390, text_color="#a8b2c4").pack(anchor="w", padx=22, pady=(14, 0))

        def save() -> None:
            try:
                value = float(chance.get().strip())
                if not 0 <= value <= 100:
                    raise ValueError
            except ValueError:
                messagebox.showwarning("Chance do grupo", "Informe um valor entre 0 e 100.", parent=dialog)
                return
            self.push_undo()
            group["execution_chance_pct"] = value
            self.refresh_tree()
            item = f"g:{group_index}"
            if self.tree.exists(item):
                self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
            self.save_macro(quiet=True)
            self.status.set(f"Chance do grupo ‘{group.get('name', 'Grupo')}’ definida em {value:g}%.")
            dialog.destroy()

        controls = ctk.CTkFrame(dialog, fg_color="transparent")
        controls.pack(fill="x", padx=22, pady=18)
        ctk.CTkButton(controls, text="Cancelar", command=dialog.destroy, width=96, height=32,
                      fg_color="#39455b", hover_color="#4a5870").pack(side="right", padx=(8, 0))
        ctk.CTkButton(controls, text="Salvar", command=save, width=96, height=32,
                      fg_color="#2f6fed", hover_color="#4b82ee").pack(side="right")
        dialog.bind("<Control-Return>", lambda _event: save())

    def configure_subgroup_action(self, group_index: int, action_index: int,
                                  action_override: Action | None = None,
                                  tree_item: str | None = None) -> None:
        """Edita o contêiner sem mexer nas etapas já gravadas dentro dele."""
        groups = self.macros[self.flow_var.get()]
        if action_override is not None:
            action = action_override
        else:
            try:
                action = groups[group_index]["actions"][action_index]
            except IndexError:
                return
        if action.kind != "subgroup":
            return
        dialog = tk.Toplevel(self)
        dialog.title("Configurar subgrupo")
        dialog.geometry("460x300")
        dialog.resizable(False, False)
        dialog.configure(bg="#171b26")
        dialog.transient(self); dialog.grab_set()
        name = tk.StringVar(value=action.label or "Subgrupo")
        enabled = tk.BooleanVar(value=bool(action.enabled))
        chance = tk.StringVar(value=f"{float(action.execution_chance_pct):g}")
        ctk.CTkLabel(dialog, text="Nome do subgrupo:").pack(anchor="w", padx=22, pady=(22, 6))
        ctk.CTkEntry(dialog, textvariable=name, height=32, corner_radius=8,
                     fg_color="#222938", border_color="#465166", text_color="#f8fafc").pack(fill="x", padx=22)
        ctk.CTkCheckBox(dialog, text="Executar este subgrupo", variable=enabled,
                        onvalue=True, offvalue=False).pack(anchor="w", padx=22, pady=(16, 4))
        chance_row = ctk.CTkFrame(dialog, fg_color="transparent")
        chance_row.pack(fill="x", padx=22, pady=(8, 2))
        ctk.CTkLabel(chance_row, text="Chance de executar o grupo (%):").pack(side="left")
        ctk.CTkEntry(chance_row, textvariable=chance, width=82, height=30, corner_radius=8,
                     fg_color="#222938", border_color="#465166", text_color="#f8fafc").pack(side="left", padx=(12, 0))
        ctk.CTkLabel(dialog, text=f"{len(action.nested_actions or [])} etapa(s) dentro deste subgrupo.",
                     text_color="#a8b2c4").pack(anchor="w", padx=22, pady=(2, 0))

        def save() -> None:
            value = name.get().strip()
            try:
                chance_value = float(chance.get().strip())
            except ValueError:
                chance_value = -1
            if not value or not 0 <= chance_value <= 100:
                messagebox.showwarning("Subgrupo", "Informe um nome e uma chance entre 0 e 100%.", parent=dialog)
                return
            self.push_undo()
            action.label, action.enabled, action.execution_chance_pct = value, bool(enabled.get()), chance_value
            self.refresh_tree()
            item = tree_item or f"a:{group_index}:{action_index}"
            if self.tree.exists(item):
                self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
            self.save_macro(quiet=True)
            self.status.set(f"Subgrupo ‘{value}’ atualizado ({chance_value:g}% de chance).")
            dialog.destroy()

        controls = ctk.CTkFrame(dialog, fg_color="transparent")
        controls.pack(fill="x", padx=22, pady=(18, 20))
        ctk.CTkButton(controls, text="Cancelar", command=dialog.destroy, width=96, height=32,
                      fg_color="#39455b", hover_color="#4a5870").pack(side="right", padx=(8, 0))
        ctk.CTkButton(controls, text="Salvar", command=save, width=96, height=32,
                      fg_color="#2f6fed", hover_color="#4b82ee").pack(side="right")

    def configure_inline_nav_rc_action(self, action: Action, tree_item: str) -> None:
        """Edita o Nav-R-C que fica dentro de um Nav-R."""
        if action.kind != "navigate_rc":
            return
        dialog = tk.Toplevel(self)
        dialog.title("Configurar Nav-R-C")
        dialog.geometry("620x570"); dialog.minsize(560, 520)
        dialog.configure(bg="#171b26"); dialog.transient(self); dialog.grab_set()
        legacy_wait = int(action.nav_rc_scroll_wait_ms or 1000)
        fields = [
            ("Nome", "label", str(action.label or "Nav-R-C"), "text"),
            ("Chance de executar (%)", "nav_rc_chance_pct", str(action.nav_rc_chance_pct), "float"),
            ("Palavra antes do comentário", "nav_rc_marker", str(action.nav_rc_marker or "disse"), "text"),
            ("Idade máxima do comentário (dias)", "nav_rc_max_age_days", str(action.nav_rc_max_age_days), "int"),
            ("Mínimo de comentários", "nav_rc_min_comments", str(action.nav_rc_min_comments), "int"),
            ("Máximo de arrastos", "nav_rc_max_scrolls", str(action.nav_rc_max_scrolls), "int"),
            ("Espera após arrasto mín. (ms)", "nav_rc_scroll_wait_min_ms", str(action.nav_rc_scroll_wait_min_ms if action.nav_rc_scroll_wait_min_ms is not None else legacy_wait), "int"),
            ("Espera após arrasto máx. (ms)", "nav_rc_scroll_wait_max_ms", str(action.nav_rc_scroll_wait_max_ms if action.nav_rc_scroll_wait_max_ms is not None else legacy_wait), "int"),
        ]
        values: dict[str, tk.StringVar] = {}
        for row, (label, key, initial, _kind) in enumerate(fields):
            values[key] = tk.StringVar(value=initial)
            ctk.CTkLabel(dialog, text=label + ":").grid(row=row, column=0, padx=20, pady=8, sticky="w")
            ctk.CTkEntry(dialog, textvariable=values[key], width=210, height=30, corner_radius=8,
                         fg_color="#222938", border_color="#465166", text_color="#f8fafc").grid(row=row, column=1, padx=10, pady=8, sticky="w")

        def save() -> None:
            try:
                parsed: dict[str, object] = {}
                for _label, key, _initial, kind in fields:
                    raw = values[key].get().strip()
                    parsed[key] = raw if kind == "text" else (float(raw) if kind == "float" else int(raw))
                if (not str(parsed["label"]).strip() or not str(parsed["nav_rc_marker"]).strip() or
                        not 0 <= float(parsed["nav_rc_chance_pct"]) <= 100 or
                        int(parsed["nav_rc_max_age_days"]) < 0 or int(parsed["nav_rc_min_comments"]) < 0 or
                        int(parsed["nav_rc_max_scrolls"]) < 0 or int(parsed["nav_rc_scroll_wait_min_ms"]) < 0 or
                        int(parsed["nav_rc_scroll_wait_max_ms"]) < int(parsed["nav_rc_scroll_wait_min_ms"])):
                    raise ValueError
            except (ValueError, TypeError):
                messagebox.showwarning("Nav-R-C", "Confira os valores informados.", parent=dialog)
                return
            self.push_undo()
            for key, value in parsed.items():
                setattr(action, key, value)
            action.nav_rc_scroll_wait_ms = int(parsed["nav_rc_scroll_wait_min_ms"])
            # Mantém o Nav-R pai sincronizado: ele é o controlador que executa o filho.
            parent_item = self.tree.parent(tree_item)
            parent_location = self._tree_action_container(parent_item) if parent_item else None
            if parent_location is not None:
                _group_index, parent_actions, parent_index = parent_location
                parent = parent_actions[parent_index]
                if parent.kind == "navigate_r":
                    parent.nav_rc_actions = action.nav_rc_actions
                    for key in ("nav_rc_chance_pct", "nav_rc_marker", "nav_rc_max_age_days",
                                "nav_rc_min_comments", "nav_rc_max_scrolls", "nav_rc_scroll_wait_ms",
                                "nav_rc_scroll_wait_min_ms", "nav_rc_scroll_wait_max_ms"):
                        setattr(parent, key, getattr(action, key))
            self.refresh_tree()
            if self.tree.exists(tree_item):
                self.tree.selection_set(tree_item); self.tree.focus(tree_item); self.tree.see(tree_item)
            self.save_macro(quiet=True); self.status.set("Nav-R-C atualizado.")
            dialog.destroy()

        controls = ctk.CTkFrame(dialog, fg_color="transparent")
        controls.grid(row=len(fields), column=0, columnspan=2, padx=20, pady=22, sticky="e")
        ctk.CTkButton(controls, text="Cancelar", command=dialog.destroy, width=96, height=32,
                      fg_color="#39455b", hover_color="#4a5870").pack(side="right", padx=(8, 0))
        ctk.CTkButton(controls, text="Salvar", command=save, width=96, height=32,
                      fg_color="#2f6fed", hover_color="#4b82ee").pack(side="right")

    def configure_inline_navigation_action(self, group_index: int, action_index: int,
                                           action_override: Action | None = None,
                                           tree_item: str | None = None) -> None:
        """Configura um Nav-R/Nav-S inserido como etapa, sem recriar suas ações internas."""
        if action_override is not None:
            action = action_override
        else:
            try:
                action = self.macros[self.flow_var.get()][group_index]["actions"][action_index]
            except IndexError:
                return
        if action.kind not in ("navigate_r", "navigate_s"):
            return
        is_nav_s = action.kind == "navigate_s"
        title = "Configurar Nav-S" if is_nav_s else "Configurar Nav-R"
        dialog = tk.Toplevel(self)
        dialog.title(title); dialog.geometry("700x900"); dialog.minsize(620, 760)
        dialog.configure(bg="#171b26"); dialog.transient(self); dialog.grab_set()
        fields = [("Nome", "label", str(action.label or ("Nav-S" if is_nav_s else "Nav-R")), "text"),
                  ("Tempo total mínimo (s)", "nav_min_s", str(action.nav_min_s), "float"),
                  ("Tempo total máximo (s)", "nav_max_s", str(action.nav_max_s), "float"),
                  ("Pausa entre ciclos mín. (ms)", "nav_pause_min_ms", str(action.nav_pause_min_ms), "int"),
                  ("Pausa entre ciclos máx. (ms)", "nav_pause_max_ms", str(action.nav_pause_max_ms), "int")]
        if is_nav_s:
            fields += [("Limite de cada verificação XML (s)", "nav_s_verify_timeout_s", str(action.nav_s_verify_timeout_s), "float"),
                       ("Intervalo entre toques mín. (ms)", "nav_tap_interval_min_ms", str(action.nav_tap_interval_min_ms), "int"),
                       ("Intervalo entre toques máx. (ms)", "nav_tap_interval_max_ms", str(action.nav_tap_interval_max_ms), "int"),
                       ("Chance do toque (%)", "nav_first_tap_chance_pct", str(action.nav_first_tap_chance_pct), "float")]
        else:
            fields += [("Duração do arrasto mín. (ms)", "nav_swipe_min_ms", str(action.nav_swipe_min_ms), "int"),
                       ("Duração do arrasto máx. (ms)", "nav_swipe_max_ms", str(action.nav_swipe_max_ms), "int"),
                       ("Intervalo toque duplo mín. (ms)", "nav_double_tap_min_ms", str(action.nav_double_tap_min_ms), "int"),
                       ("Intervalo toque duplo máx. (ms)", "nav_double_tap_max_ms", str(action.nav_double_tap_max_ms), "int"),
                       ("Chance do toque duplo (%)", "nav_double_tap_chance_pct", str(action.nav_double_tap_chance_pct), "float"),
                       ("Chance do Nav-R-C (%)", "nav_rc_chance_pct", str(action.nav_rc_chance_pct), "float"),
                       ("Palavra antes do comentário", "nav_rc_marker", str(action.nav_rc_marker or "disse"), "text"),
                       ("Idade máx. do comentário (dias)", "nav_rc_max_age_days", str(action.nav_rc_max_age_days), "int"),
                       ("Mínimo de comentários", "nav_rc_min_comments", str(action.nav_rc_min_comments), "int"),
                       ("Máximo de arrastos do Nav-R-C", "nav_rc_max_scrolls", str(action.nav_rc_max_scrolls), "int"),
                       ("Espera após arrasto do Nav-R-C mín. (ms)", "nav_rc_scroll_wait_min_ms", str(action.nav_rc_scroll_wait_min_ms if action.nav_rc_scroll_wait_min_ms is not None else action.nav_rc_scroll_wait_ms), "int"),
                       ("Espera após arrasto do Nav-R-C máx. (ms)", "nav_rc_scroll_wait_max_ms", str(action.nav_rc_scroll_wait_max_ms if action.nav_rc_scroll_wait_max_ms is not None else action.nav_rc_scroll_wait_ms), "int")]
        fields.append(("Variação de posição (px)", "nav_position_variation_px", str(action.nav_position_variation_px), "int"))
        values: dict[str, tk.StringVar] = {}
        for row, (label, key, initial, _kind) in enumerate(fields):
            values[key] = tk.StringVar(value=initial)
            ctk.CTkLabel(dialog, text=label + ":").grid(row=row, column=0, padx=20, pady=7, sticky="w")
            ctk.CTkEntry(dialog, textvariable=values[key], width=180, height=30, corner_radius=8,
                         fg_color="#222938", border_color="#465166", text_color="#f8fafc").grid(row=row, column=1, padx=10, pady=7, sticky="w")
        xml_queries = None
        extra_row = len(fields)
        if not is_nav_s:
            ctk.CTkLabel(dialog, text="Verificações XML (uma por linha):", text_color="#e4e9f2").grid(
                row=extra_row, column=0, padx=20, pady=(10, 4), sticky="nw"
            )
            xml_queries = tk.Text(dialog, height=5, width=42, bg="#222938", fg="#f8fafc",
                                  insertbackground="#ffffff", highlightthickness=1,
                                  highlightbackground="#465166", borderwidth=0, wrap="word")
            xml_queries.insert("1.0", "\n".join(self._normalise_xml_query_lines(action.nav_r_xml_queries)))
            xml_queries.grid(row=extra_row, column=1, padx=10, pady=(10, 4), sticky="w")
            extra_row += 1
        note = "Os toques, arrastos e XMLs que já estão dentro deste Nav-S serão preservados." if is_nav_s else "Os toques, arrasto, XMLs e Nav-R-C internos serão preservados."
        ctk.CTkLabel(dialog, text=note, wraplength=610, text_color="#a8b2c4").grid(row=extra_row, column=0, columnspan=2, padx=20, pady=(16, 4), sticky="w")

        def save() -> None:
            try:
                parsed: dict[str, object] = {}
                for _label, key, _initial, kind in fields:
                    value = values[key].get().strip()
                    parsed[key] = value if kind == "text" else (float(value) if kind == "float" else int(value))
                if (not str(parsed["label"]).strip() or float(parsed["nav_min_s"]) <= 0 or
                        float(parsed["nav_max_s"]) < float(parsed["nav_min_s"]) or
                        int(parsed["nav_pause_min_ms"]) < 0 or int(parsed["nav_pause_max_ms"]) < int(parsed["nav_pause_min_ms"]) or
                        int(parsed["nav_position_variation_px"]) < 0):
                    raise ValueError
                if is_nav_s:
                    if (float(parsed["nav_s_verify_timeout_s"]) <= 0 or int(parsed["nav_tap_interval_min_ms"]) < 0 or
                            int(parsed["nav_tap_interval_max_ms"]) < int(parsed["nav_tap_interval_min_ms"]) or
                            not 0 <= float(parsed["nav_first_tap_chance_pct"]) <= 100): raise ValueError
                elif (int(parsed["nav_swipe_min_ms"]) < 1 or int(parsed["nav_swipe_max_ms"]) < int(parsed["nav_swipe_min_ms"]) or
                      not 40 <= int(parsed["nav_double_tap_min_ms"]) <= int(parsed["nav_double_tap_max_ms"]) <= 250 or
                      not 0 <= float(parsed["nav_double_tap_chance_pct"]) <= 100 or
                      not 0 <= float(parsed["nav_rc_chance_pct"]) <= 100 or
                      not str(parsed["nav_rc_marker"]).strip() or
                      int(parsed["nav_rc_max_age_days"]) < 0 or int(parsed["nav_rc_min_comments"]) < 0 or
                      int(parsed["nav_rc_max_scrolls"]) < 0 or int(parsed["nav_rc_scroll_wait_min_ms"]) < 0 or
                      int(parsed["nav_rc_scroll_wait_max_ms"]) < int(parsed["nav_rc_scroll_wait_min_ms"])): raise ValueError
            except (ValueError, TypeError):
                messagebox.showwarning(title, "Confira os valores informados.", parent=dialog)
                return
            self.push_undo()
            for key, value in parsed.items():
                setattr(action, key, value)
            if xml_queries is not None:
                # Keep this on the Nav-R action itself.  The executor reads this
                # exact field, including when the Nav-R is nested in subgroups.
                action.nav_r_xml_queries = self._normalise_xml_query_lines(
                    xml_queries.get("1.0", "end")
                )
            # O Nav-R-C é filho deste Nav-R. Mantém seus parâmetros espelhados
            # no cabeçalho e no filho que aparece na árvore.
            if not is_nav_s:
                for child_index, child in enumerate(action.nav_actions or []):
                    if isinstance(child, dict):
                        child = Action(**child)
                        action.nav_actions[child_index] = child
                    if child.kind != "navigate_rc":
                        continue
                    for key in ("nav_rc_chance_pct", "nav_rc_marker", "nav_rc_max_age_days",
                                "nav_rc_min_comments", "nav_rc_max_scrolls", "nav_rc_scroll_wait_min_ms",
                                "nav_rc_scroll_wait_max_ms"):
                        setattr(child, key, getattr(action, key))
                    child.nav_rc_scroll_wait_ms = action.nav_rc_scroll_wait_min_ms
                    if action.nav_rc_actions is None:
                        action.nav_rc_actions = child.nav_rc_actions
                    child.nav_rc_actions = action.nav_rc_actions
                    break
            self.refresh_tree(); item = tree_item or f"a:{group_index}:{action_index}"
            if self.tree.exists(item): self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
            self.save_macro(quiet=True); self.status.set(f"{title.replace('Configurar ', '')} atualizado.")
            dialog.destroy()

        controls = ctk.CTkFrame(dialog, fg_color="transparent")
        controls.grid(row=extra_row + 1, column=0, columnspan=2, padx=20, pady=20, sticky="e")
        ctk.CTkButton(controls, text="Cancelar", command=dialog.destroy, width=96, height=32,
                      fg_color="#39455b", hover_color="#4a5870").pack(side="right", padx=(8, 0))
        ctk.CTkButton(controls, text="Salvar", command=save, width=96, height=32,
                      fg_color="#2f6fed", hover_color="#4b82ee").pack(side="right")
        dialog.bind("<Control-Return>", lambda _event: save())

    def add_navigate_rc_group(self, group_index: int | None = None) -> None:
        """Cria o fluxo auxiliar de comentários usado pelo Nav-R."""
        groups = self.macros[self.flow_var.get()]
        editing = group_index is not None and 0 <= group_index < len(groups)
        existing = groups[group_index] if editing else {}
        inline_parent: Action | None = None
        inline_parent_item = ""
        inline_parent_group: int | None = None
        selected = self.tree.selection()
        if not editing and len(selected) == 1:
            location = self._tree_action_container(selected[0])
            if location is not None:
                _parent_group, actions, parent_index = location
                if 0 <= parent_index < len(actions) and actions[parent_index].kind == "navigate_r":
                    inline_parent = actions[parent_index]
                    inline_parent_item = selected[0]
                    inline_parent_group = _parent_group
        if not editing and inline_parent is None:
            messagebox.showwarning("Nav-R-C", "Selecione o Nav-R pai antes de criar o Nav-R-C.", parent=self)
            return
        name = simpledialog.askstring("Nav-R-C", "Nome do grupo auxiliar:",
                                      initialvalue=str(existing.get("name", f"Nav-R-C {sum(bool(g.get('navigation_rc')) for g in groups) + 1}")), parent=self)
        if not name or not name.strip():
            return
        chance = simpledialog.askfloat("Nav-R-C", "Chance de executar o Nav-R-C (%):",
                                       initialvalue=float(existing.get("nav_rc_chance_pct", 20)), minvalue=0, maxvalue=100, parent=self)
        if chance is None:
            return
        days = simpledialog.askinteger("Nav-R-C", "Idade máxima do comentário, em dias (inclusive):",
                                       initialvalue=int(existing.get("nav_rc_max_age_days", 2)), minvalue=0, maxvalue=365, parent=self)
        if days is None:
            return
        marker = simpledialog.askstring("Nav-R-C", "Palavra que vem antes do texto a extrair:",
                                        initialvalue=str(existing.get("nav_rc_marker", "disse")), parent=self)
        if not marker or not marker.strip():
            return
        min_comments = simpledialog.askinteger(
            "Nav-R-C", "Quantidade mínima de comentários para permitir o Nav-R-C:",
            initialvalue=int(existing.get("nav_rc_min_comments", 0)), minvalue=0, maxvalue=10000000, parent=self,
        )
        if min_comments is None:
            return
        max_scrolls = simpledialog.askinteger(
            "Nav-R-C", "Máximo de arrastos para procurar outro comentário válido:",
            initialvalue=int(existing.get("nav_rc_max_scrolls", 0)), minvalue=0, maxvalue=1000, parent=self,
        )
        if max_scrolls is None:
            return
        legacy_wait = int(existing.get("nav_rc_scroll_wait_ms", 1000))
        scroll_wait_min_ms = simpledialog.askinteger(
            "Nav-R-C", "Espera mínima após cada arrasto, antes de verificar novamente (ms):",
            initialvalue=int(existing.get("nav_rc_scroll_wait_min_ms", legacy_wait)), minvalue=0, maxvalue=60000, parent=self,
        )
        if scroll_wait_min_ms is None:
            return
        scroll_wait_max_ms = simpledialog.askinteger(
            "Nav-R-C", "Espera máxima após cada arrasto, antes de verificar novamente (ms):",
            initialvalue=int(existing.get("nav_rc_scroll_wait_max_ms", legacy_wait)), minvalue=scroll_wait_min_ms, maxvalue=60000, parent=self,
        )
        if scroll_wait_max_ms is None:
            return
        available_routes = [group["name"] for group in groups if group is not existing and not group.get("navigation_r") and not group.get("navigation_rc")]
        route_help = "\n".join(f"• {route}" for route in available_routes) or "(nenhum grupo disponível)"
        fallback_group = simpledialog.askstring(
            "Nav-R-C", "Grupo executado se nenhum comentário válido for encontrado após os arrastos.\n"
                       "Deixe vazio para não usar rota alternativa.\n\nGrupos disponíveis:\n" + route_help,
            initialvalue=str(existing.get("nav_rc_fallback_group") or ""), parent=self,
        )
        if fallback_group is None:
            return
        fallback_group = fallback_group.strip()
        if fallback_group and fallback_group not in available_routes:
            messagebox.showwarning("Nav-R-C", "O grupo informado não existe entre as rotas disponíveis.", parent=self)
            return
        self.push_undo()
        if fallback_group:
            next(group for group in groups if group["name"] == fallback_group)["branch_only"] = True
        config = {"name": name.strip(), "enabled": bool(existing.get("enabled", True)), "navigation_rc": True,
                  "branch_only": True, "nav_rc_chance_pct": chance, "nav_rc_max_age_days": days,
                  "nav_rc_marker": marker.strip(), "nav_rc_min_comments": min_comments,
                  "nav_rc_max_scrolls": max_scrolls, "nav_rc_scroll_wait_ms": scroll_wait_min_ms,
                  "nav_rc_scroll_wait_min_ms": scroll_wait_min_ms, "nav_rc_scroll_wait_max_ms": scroll_wait_max_ms,
                  "nav_rc_fallback_group": fallback_group or None}
        if editing:
            groups[group_index].update(config)
        else:
            parent = inline_parent
            if parent.nav_actions is None:
                parent.nav_actions = []
            nav_rc = Action("navigate_rc", label=name.strip(), nav_rc_actions=[],
                            nav_rc_chance_pct=chance, nav_rc_max_age_days=days,
                            nav_rc_marker=marker.strip(), nav_rc_min_comments=min_comments,
                            nav_rc_max_scrolls=max_scrolls, nav_rc_scroll_wait_ms=scroll_wait_min_ms,
                            nav_rc_scroll_wait_min_ms=scroll_wait_min_ms, nav_rc_scroll_wait_max_ms=scroll_wait_max_ms,
                            nav_rc_fallback_group=fallback_group or None, delay_ms=0)
            # O Nav-R-C fica visualmente dentro do Nav-R e o mesmo conjunto
            # de etapas é usado pelo controlador do Nav-R quando a chance cai.
            parent.nav_actions.append(nav_rc)
            parent.nav_rc_actions = nav_rc.nav_rc_actions
            parent.nav_rc_chance_pct = chance
            parent.nav_rc_max_age_days = days
            parent.nav_rc_marker = marker.strip()
            parent.nav_rc_min_comments = min_comments
            parent.nav_rc_max_scrolls = max_scrolls
            parent.nav_rc_scroll_wait_ms = scroll_wait_min_ms
            parent.nav_rc_scroll_wait_min_ms = scroll_wait_min_ms
            parent.nav_rc_scroll_wait_max_ms = scroll_wait_max_ms
            parent.nav_rc_fallback_group = fallback_group or None
            group_index = inline_parent_group if inline_parent_group is not None else 0
        self.active_group = group_index
        target = f"g:{group_index}" if editing else inline_parent_item
        self.refresh_tree(); self.tree.selection_set(target); self.tree.focus(target); self.tree.see(target)
        self.save_macro(quiet=True)
        self.status.set("Nav-R-C configurado. Grave o arrasto, selecione-o e use ‘Nav-R-C: usar arrasto na busca’.")

    def add_nav_rc_extract_action(self) -> None:
        self._append_special_action(Action("nav_rc_extract", delay_ms=400, label="Extrair e validar comentário"),
                                    "Etapa para extrair e validar o comentário adicionada.")

    def add_nav_rc_type_action(self) -> None:
        self._append_special_action(Action("nav_rc_type", delay_ms=400, label="Digitar comentário extraído"),
                                    "Etapa para digitar o comentário extraído adicionada.")
        selected = self.tree.selection()
        if selected and selected[0].startswith("a:"):
            _, group_index, action_index = selected[0].split(":")
            self.configure_nav_rc_type_action(int(group_index), int(action_index))

    def configure_nav_rc_type_action(self, group_index: int, action_index: int) -> None:
        """Configura complementos aleatórios para o comentário extraído."""
        groups = self.macros[self.flow_var.get()]
        if group_index >= len(groups) or action_index >= len(groups[group_index]["actions"]):
            return
        action = groups[group_index]["actions"][action_index]
        if action.kind != "nav_rc_type":
            return
        dialog = ctk.CTkToplevel(self)
        dialog.title("Complementos do comentário")
        dialog.geometry("590x450")
        dialog.minsize(480, 360)
        dialog.transient(self)
        dialog.grab_set()
        ctk.CTkLabel(dialog, text="Texto extraído + complemento aleatório", font=("Segoe UI Semibold", 16)).pack(anchor="w", padx=18, pady=(18, 5))
        ctk.CTkLabel(dialog, text="Escreva um complemento por linha. Em cada execução, um será sorteado e colocado após o comentário extraído. Deixe vazio para digitar somente o comentário.",
                     justify="left", wraplength=550, text_color="#aebbd0").pack(anchor="w", padx=18)
        editor = ctk.CTkTextbox(dialog, wrap="word", fg_color="#202737", text_color="#e7edf7")
        editor.pack(fill="both", expand=True, padx=18, pady=14)
        editor.insert("1.0", "\n".join(action.text_options or []))

        def save() -> None:
            options = [line.strip() for line in editor.get("1.0", "end").splitlines() if line.strip()]
            self.push_undo()
            action.text_options = options or None
            item = f"a:{group_index}:{action_index}"
            self.refresh_tree(); self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
            self.save_macro(quiet=True)
            self.status.set("Complementos do comentário salvos." if options else "A etapa digitará somente o comentário extraído.")
            dialog.destroy()

        controls = ctk.CTkFrame(dialog, fg_color="transparent")
        controls.pack(fill="x", padx=18, pady=(0, 18))
        ctk.CTkButton(controls, text="Salvar", command=save, width=100, height=32, corner_radius=8,
                      fg_color="#2f6fed", hover_color="#4b82ee").pack(side="right")
        ctk.CTkButton(controls, text="Cancelar", command=dialog.destroy, width=100, height=32, corner_radius=8,
                      fg_color="#39455b", hover_color="#4a5870").pack(side="right", padx=(0, 8))

    def set_nav_rc_scroll_action(self) -> None:
        """Reserva um arrasto gravado para procurar mais comentários no Nav-R-C."""
        selected = self.tree.selection()
        if len(selected) != 1 or not selected[0].startswith("a:"):
            messagebox.showwarning("Nav-R-C", "Selecione o arrasto gravado que será usado para rolar os comentários.", parent=self)
            return
        _kind, group_text, action_text = selected[0].split(":")
        group_index, action_index = int(group_text), int(action_text)
        group = self.macros[self.flow_var.get()][group_index]
        action = group["actions"][action_index]
        if not group.get("navigation_rc") or action.kind not in ("swipe", "nav_rc_scroll"):
            messagebox.showwarning("Nav-R-C", "Escolha um arrasto que esteja dentro de um grupo Nav-R-C.", parent=self)
            return
        self.push_undo()
        for candidate in group["actions"]:
            if candidate.kind == "nav_rc_scroll":
                candidate.kind = "swipe"
        action.kind = "nav_rc_scroll"
        action.label = "Arrasto para procurar comentários"
        self.refresh_tree(); self.tree.selection_set(f"a:{group_index}:{action_index}"); self.tree.focus(f"a:{group_index}:{action_index}")
        self.save_macro(quiet=True)
        self.status.set("Arrasto do Nav-R-C definido. Ele será repetido até o limite configurado enquanto não houver comentário válido.")

    def add_navigate_r_group(self, group_index: int | None = None) -> None:
        """Cria um grupo especial: grave nele um arrasto seguido de dois toques."""
        groups_for_flow = self.macros[self.flow_var.get()]
        editing = group_index is not None and 0 <= group_index < len(groups_for_flow)
        selected = self.tree.selection()
        inline_after: tuple[int, int] | None = None
        inline_child: tuple[int, int, int] | None = None
        if not editing and len(selected) == 1:
            parts = selected[0].split(":")
            if len(parts) == 3 and parts[0] == "a":
                try:
                    candidate = (int(parts[1]), int(parts[2]))
                    if candidate[0] < len(groups_for_flow):
                        inline_after = candidate
                except ValueError:
                    pass
            elif len(parts) == 4 and parts[0] == "s":
                if self._tree_action_container(selected[0]) is not None:
                    inline_child = (int(parts[1]), int(parts[2]), int(parts[3]))
        existing = groups_for_flow[group_index] if editing else {}
        dialog = tk.Toplevel(self)
        dialog.title("Nav-R")
        dialog.geometry("640x960")
        dialog.minsize(590, 900)
        dialog.configure(bg="#171b26")
        dialog.transient(self); dialog.grab_set()
        previous = existing if editing else self.settings.get("navigate_r_defaults", {})
        if not isinstance(previous, dict): previous = {}
        def last(key: str, default: str) -> str:
            group_keys = {"min_s": "nav_min_s", "max_s": "nav_max_s", "pause_min": "nav_pause_min_ms", "pause_max": "nav_pause_max_ms",
                          "swipe_min": "nav_swipe_min_ms", "swipe_max": "nav_swipe_max_ms", "double_min": "nav_double_tap_min_ms",
                          "double_max": "nav_double_tap_max_ms", "double_chance": "nav_double_tap_chance_pct", "position": "nav_position_variation_px"}
            return str(previous.get(group_keys[key] if editing else key, default))
        values = {
            "name": tk.StringVar(value=str(existing.get("name", f"Nav-R {sum(bool(g.get('navigation_r')) for g in groups_for_flow) + 1}"))),
            "min_s": tk.StringVar(value=last("min_s", "12")), "max_s": tk.StringVar(value=last("max_s", "20")),
            "pause_min": tk.StringVar(value=last("pause_min", "350")), "pause_max": tk.StringVar(value=last("pause_max", "750")),
            "swipe_min": tk.StringVar(value=last("swipe_min", "320")), "swipe_max": tk.StringVar(value=last("swipe_max", "620")),
            "double_min": tk.StringVar(value=last("double_min", "80")), "double_max": tk.StringVar(value=last("double_max", "150")),
            "double_chance": tk.StringVar(value=last("double_chance", "100")), "position": tk.StringVar(value=last("position", "8")),
        }
        fields = (("Nome do grupo", "name"), ("Tempo total mínimo (s)", "min_s"), ("Tempo total máximo (s)", "max_s"),
                  ("Pausa entre ciclos mín. (ms)", "pause_min"), ("Pausa entre ciclos máx. (ms)", "pause_max"),
                  ("Duração arrasto mín. (ms)", "swipe_min"), ("Duração arrasto máx. (ms)", "swipe_max"),
                  ("Intervalo toque duplo mín. (ms)", "double_min"), ("Intervalo toque duplo máx. (ms)", "double_max"),
                  ("Chance do toque duplo (%)", "double_chance"), ("Variação de posição (px)", "position"))
        for row, (label, key) in enumerate(fields):
            ttk.Label(dialog, text=label + ":").grid(row=row, column=0, padx=18, pady=8, sticky="w")
            ctk.CTkEntry(dialog, textvariable=values[key], width=150, height=30, corner_radius=8,
                         fg_color="#222938", border_color="#465166", text_color="#f8fafc").grid(row=row, column=1, padx=8, pady=8, sticky="w")
        saved_queries = self._normalise_xml_query_lines(
            existing.get("nav_r_xml_queries", previous.get("xml_queries", []))
        )
        ttk.Label(dialog, text="Verificações XML (uma por linha):").grid(row=11, column=0, padx=18, pady=(10, 4), sticky="nw")
        xml_queries = tk.Text(dialog, height=6, width=42, bg="#222938", fg="#f8fafc", insertbackground="#ffffff",
                              highlightthickness=1, highlightbackground="#465166", borderwidth=0, wrap="word")
        xml_queries.insert("1.0", "\n".join(str(query) for query in saved_queries if str(query).strip()))
        xml_queries.grid(row=11, column=1, padx=8, pady=(10, 4), sticky="w")
        rc_group = tk.StringVar(value=str(existing.get("nav_rc_group") or "Nenhum Nav-R-C"))
        rc_groups = [group["name"] for group in groups_for_flow if group.get("navigation_rc")]
        ttk.Label(dialog, text="Grupo auxiliar Nav-R-C:").grid(row=12, column=0, padx=18, pady=(10, 4), sticky="w")
        ttk.Combobox(dialog, textvariable=rc_group, state="readonly", values=["Nenhum Nav-R-C", *rc_groups], width=32).grid(row=12, column=1, padx=8, pady=(10, 4), sticky="w")
        ttk.Label(dialog, text="O Nav-R executa ciclos somente até acabar o tempo total. Depois segue diretamente para o próximo grupo.", wraplength=560).grid(row=13, column=0, columnspan=2, padx=18, pady=(10, 4), sticky="w")

        def create():
            try:
                minimum, maximum = float(values["min_s"].get()), float(values["max_s"].get())
                pause_min, pause_max = int(values["pause_min"].get()), int(values["pause_max"].get())
                swipe_min, swipe_max = int(values["swipe_min"].get()), int(values["swipe_max"].get())
                double_min, double_max = int(values["double_min"].get()), int(values["double_max"].get())
                chance, position = float(values["double_chance"].get()), int(values["position"].get())
                if minimum <= 0 or maximum < minimum or pause_min < 0 or pause_max < pause_min or swipe_min < 1 or swipe_max < swipe_min or not 40 <= double_min <= double_max <= 250 or not 0 <= chance <= 100 or position < 0:
                    raise ValueError
            except ValueError:
                messagebox.showwarning("Nav-R", "Confira os intervalos e a chance.", parent=dialog); return
            self.push_undo()
            groups = self.macros[self.flow_var.get()]
            selected_rc = rc_group.get() if rc_group.get() != "Nenhum Nav-R-C" else None
            queries = self._normalise_xml_query_lines(xml_queries.get("1.0", "end"))
            config = {"name": values["name"].get().strip() or "Nav-R", "enabled": bool(existing.get("enabled", True)), "navigation_r": True,
                      "nav_min_s": minimum, "nav_max_s": maximum, "nav_pause_min_ms": pause_min, "nav_pause_max_ms": pause_max,
                      "nav_swipe_min_ms": swipe_min, "nav_swipe_max_ms": swipe_max, "nav_double_tap_min_ms": double_min,
                      "nav_double_tap_max_ms": double_max, "nav_double_tap_chance_pct": chance,
                      "nav_position_variation_px": position, "nav_min_rounds": 1, "nav_max_rounds": 1,
                      "nav_after_group": None, "nav_r_xml_queries": queries, "nav_rc_group": selected_rc}
            if editing:
                groups[group_index].update(config)
            elif len(self.tree.selection()) == 1:
                # A mesma regra vale para todo nível: cabeçalho aberto recebe
                # como primeiro filho; fechado recebe um irmão; uma etapa recebe
                # a nova etapa logo abaixo. Centralizar em _insert_new_action
                # evita Nav-R se comportar diferente dos demais grupos.
                new_nav = Action(
                    "navigate_r", label=config["name"], nav_actions=[],
                    nav_r_xml_queries=queries, nav_rc_group_index=None,
                    nav_rc_chance_pct=0, nav_min_s=minimum, nav_max_s=maximum,
                    nav_pause_min_ms=pause_min, nav_pause_max_ms=pause_max,
                    nav_swipe_min_ms=swipe_min, nav_swipe_max_ms=swipe_max,
                    nav_double_tap_min_ms=double_min, nav_double_tap_max_ms=double_max,
                    nav_double_tap_chance_pct=chance, nav_position_variation_px=position,
                    nav_min_rounds=1, nav_max_rounds=1, delay_ms=0,
                )
                group_index, _action_index = self._insert_new_action(new_nav)
                target_item = getattr(self, "last_inserted_tree_item", f"a:{group_index}:{_action_index}")
            else:
                groups.append({**config, "actions": []})
            self.settings["navigate_r_defaults"] = {key: values[key].get().strip() for key in values if key != "name"}
            self.settings["navigate_r_defaults"]["xml_queries"] = queries
            self._save_settings()
            self.active_group = group_index if (editing or len(self.tree.selection()) == 1) else len(groups) - 1
            target_item = (target_item if 'target_item' in locals() else f"g:{self.active_group}")
            self.refresh_tree(); self.tree.selection_set(target_item); self.tree.focus(target_item); self.tree.see(target_item)
            self.save_macro(); dialog.destroy()
            self.status.set("Nav-R configurado." if editing else "Nav-R criado. Grave nele um arrasto e os dois toques.")
        ctk.CTkButton(dialog, text="Salvar grupo" if editing else "Criar Nav-R", command=create, width=130, height=32, corner_radius=8,
                      fg_color="#2f6fed", hover_color="#4b82ee").grid(row=14, column=1, padx=18, pady=18, sticky="e")
        dialog.bind("<Control-Return>", lambda _event: create())

    def add_training_loop_group(self, group_index: int | None = None) -> None:
        """Cria um grupo que repete um Nav-R inteiro uma quantidade aleatória de vezes."""
        groups = self.macros[self.flow_var.get()]
        editing = group_index is not None and 0 <= group_index < len(groups)
        existing = groups[group_index] if editing else {}
        name = simpledialog.askstring("Treino", "Nome do grupo Treino:",
                                      initialvalue=str(existing.get("name", f"Treino {sum(bool(group.get('training_loop')) for group in groups) + 1}")), parent=self)
        if not name or not name.strip():
            return
        minimum = simpledialog.askinteger("Treino", "Mínimo de repetições do fluxo inteiro do Treino:",
                                          initialvalue=max(1, int(existing.get("training_min_rounds", 1))), minvalue=1, maxvalue=1000, parent=self)
        if minimum is None:
            return
        maximum = simpledialog.askinteger("Treino", "Máximo de repetições do fluxo inteiro do Treino:",
                                          initialvalue=max(minimum, int(existing.get("training_max_rounds", max(1, minimum)))), minvalue=1, maxvalue=1000, parent=self)
        if maximum is None:
            return
        if maximum < minimum:
            messagebox.showwarning("Treino", "O máximo deve ser maior ou igual ao mínimo.", parent=self)
            return
        self.push_undo()
        config = {"name": name.strip(), "enabled": bool(existing.get("enabled", True)), "training_loop": True,
                  "training_nav_r_group": str(existing.get("training_nav_r_group") or "").strip(), "training_min_rounds": minimum,
                  "training_max_rounds": maximum}
        if editing:
            groups[group_index].update(config)
        else:
            groups.append({**config, "actions": []})
            group_index = len(groups) - 1
        self.active_group = group_index
        item = f"g:{group_index}"
        self.refresh_tree(); self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
        self.save_macro(quiet=True)
        self.status.set(f"Treino configurado: as etapas e subgrupos dentro dele serão repetidos de {minimum} a {maximum} vez(es).")

    def add_validation_loop_group(self, group_index: int | None = None) -> None:
        """Cria um grupo que repete seu próprio fluxo enquanto o XML existir."""
        groups = self.macros[self.flow_var.get()]
        editing = group_index is not None and 0 <= group_index < len(groups)
        existing = groups[group_index] if editing else {}
        name = simpledialog.askstring(
            "Validar número", "Nome do grupo:",
            initialvalue=str(existing.get("name", f"Validar número {sum(bool(g.get('validation_loop')) for g in groups) + 1}")), parent=self,
        )
        if not name or not name.strip():
            return
        query = simpledialog.askstring(
            "Validar número", "Texto/XML que mantém o loop repetindo:",
            initialvalue=str(existing.get("validation_loop_query", "")), parent=self,
        )
        if not query or not query.strip():
            messagebox.showwarning("Validar número", "Informe o texto do XML que será verificado no fim do ciclo.", parent=self)
            return
        blocked = simpledialog.askstring(
            "Validar numero", "Ignorar se também houver (separe por vírgula, opcional):",
            initialvalue=str(existing.get("validation_loop_blocked_text", "")), parent=self,
        )
        if blocked is None:
            return
        timeout = simpledialog.askfloat(
            "Validar número", "Verificar por quantos segundos ao fim de cada ciclo?",
            initialvalue=max(0.1, float(existing.get("validation_loop_timeout_s", 10))), minvalue=0.1, maxvalue=120, parent=self,
        )
        if timeout is None:
            return
        self.push_undo()
        config = {
            "name": name.strip(), "enabled": bool(existing.get("enabled", True)), "validation_loop": True,
            "validation_loop_query": query.strip(), "validation_loop_blocked_text": blocked.strip(),
            "validation_loop_timeout_s": float(timeout),
        }
        if editing:
            groups[group_index].update(config)
        else:
            groups.append({**config, "actions": []})
            group_index = len(groups) - 1
        self.active_group = group_index
        item = f"g:{group_index}"
        self.refresh_tree(); self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
        self.save_macro(quiet=True)
        self.status.set("Validar número criado: as etapas internas rodam e, ao final, repetem somente se o XML continuar presente.")

    def add_xml_any_tap_group(self, group_index: int | None = None,
                              action_override: Action | None = None,
                              tree_item: str | None = None) -> None:
        """Cria um grupo que toca no primeiro entre vários XMLs encontrados."""
        groups = self.macros[self.flow_var.get()]
        editing_group = group_index is not None and 0 <= group_index < len(groups)
        editing = editing_group or action_override is not None
        existing = action_override if action_override is not None else (groups[group_index] if editing_group else {})
        def existing_value(key: str, default=None):
            if not isinstance(existing, Action):
                return existing.get(key, default)
            if key in ("xml_any_special_query", "xml_any_special_blocked_text"):
                route = next((item if isinstance(item, Action) else Action(**item)
                              for item in (existing.branch_actions or [])
                              if (item if isinstance(item, Action) else Action(**item)).kind == "xml_logic"
                              and (item if isinstance(item, Action) else Action(**item)).label == "Rota especial XML"), None)
                if route is not None:
                    return route.selector_value if key.endswith("query") else route.selector_blocked_text
            return getattr(existing, key, default)
        name = simpledialog.askstring(
            "XML: clicar qualquer",
            "Nome do grupo:",
            initialvalue=str(existing_value("label") or existing_value("name", f"XML clicar {sum(bool(g.get('xml_any_tap_group')) for g in groups) + 1}")),
            parent=self,
        )
        if not name or not name.strip():
            return
        max_rounds = simpledialog.askinteger(
            "XML: clicar qualquer", "Máximo de verificações/repetições:",
            initialvalue=max(1, int(existing_value("xml_any_max_rounds", 1))),
            minvalue=1, maxvalue=10000, parent=self,
        )
        if max_rounds is None:
            return
        special_query = simpledialog.askstring(
            "XML: clicar qualquer",
            "XML especial (opcional). Se encontrado, executa a rota especial e volta a verificar:",
            initialvalue=str(existing_value("xml_any_special_query", "")), parent=self,
        )
        if special_query is None:
            return
        special_blocked = ""
        if special_query.strip():
            special_blocked = simpledialog.askstring(
                "XML: clicar qualquer", "Ignorar no XML especial se também houver (separe por vírgula, opcional):",
                initialvalue=str(existing_value("xml_any_special_blocked_text", "")), parent=self,
            )
            if special_blocked is None:
                return
        special_selector_type = "search"
        if special_query.strip().startswith("{"):
            try:
                exact_candidate = json.loads(special_query.strip())
                if not isinstance(exact_candidate, dict) or not exact_candidate:
                    raise ValueError
                special_selector_type = "exact_xml"
            except (json.JSONDecodeError, ValueError):
                messagebox.showwarning("XML: clicar qualquer", "O XML especial em JSON precisa ser um objeto válido, por exemplo {\"text\": \"Avançar\", \"class\": \"android.widget.Button\"}.", parent=self)
                return
        self.push_undo()
        config = {
            "name": name.strip(), "enabled": bool(existing_value("enabled", True)),
            "xml_any_tap_group": True,
            "xml_any_max_rounds": int(max_rounds),
            "xml_any_special_query": special_query.strip(),
            "xml_any_special_blocked_text": special_blocked.strip(),
        }
        if editing_group:
            config.update({
                "use_variation": bool(existing_value("use_variation", False)),
                "delay_variation_min_ms": existing_value("delay_variation_min_ms"),
                "delay_variation_max_ms": existing_value("delay_variation_max_ms"),
                "delay_variation_pct": existing_value("delay_variation_pct"),
                "position_variation_px": existing_value("position_variation_px"),
                "end_position_variation_px": existing_value("end_position_variation_px"),
                "speed_variation_pct": existing_value("speed_variation_pct"),
            })
        elif action_override is None:
            defaults = Action("xml_any_tap")
            self._set_action_variation_defaults(defaults)
            config.update({
                "use_variation": defaults.use_variation,
                "delay_variation_min_ms": defaults.delay_variation_min_ms,
                "delay_variation_max_ms": defaults.delay_variation_max_ms,
                "delay_variation_pct": defaults.delay_variation_pct,
                "position_variation_px": defaults.position_variation_px,
                "end_position_variation_px": defaults.end_position_variation_px,
                "speed_variation_pct": defaults.speed_variation_pct,
            })
        def sync_special_route(values: list[Action] | list[dict]) -> list[Action]:
            """Atualiza a rota especial, preservando os XMLs normais do grupo."""
            normalized = [item if isinstance(item, Action) else Action(**item) for item in values]
            special_index = next((index for index, item in enumerate(normalized)
                                  if item.kind == "xml_logic" and item.label == "Rota especial XML"), None)
            if special_query.strip():
                if special_index is None:
                    normalized.append(Action("xml_logic", label="Rota especial XML", selector_type=special_selector_type,
                                             selector_value=special_query.strip(), selector_blocked_text=special_blocked.strip(),
                                             timeout_s=10, delay_ms=0, branch_actions=[]))
                else:
                    special = normalized[special_index]
                    special.selector_type = special_selector_type
                    special.selector_value = special_query.strip()
                    special.selector_blocked_text = special_blocked.strip()
            elif special_index is not None:
                normalized.pop(special_index)
            return normalized

        if action_override is not None:
            action_override.label = name.strip()
            action_override.xml_any_max_rounds = int(max_rounds)
            action_override.branch_actions = sync_special_route(action_override.branch_actions or [])
            selected = tree_item or ""
        elif editing_group:
            groups[group_index].update(config)
            groups[group_index]["actions"] = sync_special_route(groups[group_index].setdefault("actions", []))
            selected = f"g:{group_index}"
        elif len(self.tree.selection()) == 1:
            # Dentro de um grupo/subgrupo, XML clicar qualquer é uma etapa
            # contêiner, não um Subgrupo comum nem um grupo solto no fim.
            special_action = Action("xml_any_tap", label=name.strip(), delay_ms=0,
                                    xml_any_max_rounds=int(max_rounds),
                                    branch_actions=sync_special_route([]))
            self._set_action_variation_defaults(special_action)
            group_index, action_index = self._insert_new_action(special_action)
            self.active_group = group_index
            selected = getattr(self, "last_inserted_tree_item", f"a:{group_index}:{action_index}")
        else:
            # Este é um controlador de XML do fluxo, como Nav-S: mantém as
            # etapas XML em seu próprio grupo e evita misturá-las ao grupo
            # anterior quando a seleção atual for uma etapa interna.
            special_actions = []
            if special_query.strip():
                special_actions.append(Action("xml_logic", label="Rota especial XML", selector_type=special_selector_type, selector_value=special_query.strip(),
                                              selector_blocked_text=special_blocked.strip(), timeout_s=10, delay_ms=0,
                                              branch_actions=[]))
            groups.append({**config, "actions": special_actions})
            group_index = len(groups) - 1
            self.active_group = group_index
            selected = f"g:{group_index}"
        self.refresh_tree()
        self.tree.selection_set(selected); self.tree.focus(selected); self.tree.see(selected)
        self.save_macro(quiet=True)
        self.status.set("Grupo XML salvo. As etapas XML comuns são tocadas; a Rota especial XML recebe as etapas que devem rodar antes de verificar novamente.")

    def add_xml_restart_loop_group(self, group_index: int | None = None) -> None:
        """Cria um loop finito cujas validações XML podem reiniciar o ciclo."""
        groups = self.macros[self.flow_var.get()]
        editing = group_index is not None and 0 <= group_index < len(groups)
        existing = groups[group_index] if editing else {}
        name = simpledialog.askstring(
            "Loop XML", "Nome do grupo de loop:",
            initialvalue=str(existing.get("name", f"Loop XML {sum(bool(g.get('xml_restart_loop_group')) for g in groups) + 1}")),
            parent=self,
        )
        if not name or not name.strip():
            return
        minimum = simpledialog.askinteger(
            "Loop XML", "Mínimo de ciclos:",
            initialvalue=max(1, int(existing.get("xml_restart_loop_min_rounds", 1))), minvalue=1, maxvalue=10000, parent=self,
        )
        if minimum is None:
            return
        maximum = simpledialog.askinteger(
            "Loop XML", "Máximo de ciclos:",
            initialvalue=max(minimum, int(existing.get("xml_restart_loop_max_rounds", minimum))), minvalue=minimum, maxvalue=10000, parent=self,
        )
        if maximum is None:
            return
        self.push_undo()
        config = {
            "name": name.strip(), "enabled": bool(existing.get("enabled", True)),
            "xml_restart_loop_group": True,
            "xml_restart_loop_min_rounds": int(minimum),
            "xml_restart_loop_max_rounds": int(maximum),
        }
        if editing:
            groups[group_index].update(config)
        else:
            groups.append({**config, "actions": []})
            group_index = len(groups) - 1
        self.active_group = group_index
        item = f"g:{group_index}"
        self.refresh_tree(); self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
        self.save_macro(quiet=True)
        self.status.set("Loop XML configurado. Adicione etapas e use ‘XML: reiniciar loop’ nos pontos onde o ciclo deve recomeçar.")

    def add_xml_restart_loop_action(self) -> None:
        """Adiciona uma validação que interrompe o ciclo atual e volta ao início."""
        selected = self.tree.selection()
        if len(selected) != 1:
            messagebox.showwarning("Loop XML", "Selecione o grupo Loop XML ou uma etapa dentro dele.", parent=self)
            return
        item = selected[0]
        try:
            group_index = int(item.split(":")[1])
        except (IndexError, ValueError):
            return
        groups = self.macros[self.flow_var.get()]
        if not 0 <= group_index < len(groups) or not groups[group_index].get("xml_restart_loop_group"):
            messagebox.showwarning("Loop XML", "Esta validação só pode ser adicionada dentro de um grupo Loop XML.", parent=self)
            return
        self.add_xml_action(restart_loop=True)

    def add_training_nav_r_action(self) -> None:
        """Insere no ponto selecionado o Nav-R configurado pelo grupo Treino."""
        selected = self.tree.selection()
        if not selected:
            messagebox.showwarning("Treino", "Selecione o grupo Treino ou uma etapa dentro dele.", parent=self)
            return
        parts = selected[0].split(":")
        if parts[0] not in ("g", "a"):
            return
        group_index = int(parts[1])
        groups = self.macros[self.flow_var.get()]
        if group_index >= len(groups) or not groups[group_index].get("training_loop"):
            messagebox.showwarning("Treino", "Selecione uma etapa dentro do grupo Treino onde deseja inserir o Nav-R.", parent=self)
            return
        existing_index = next((index for index, action in enumerate(groups[group_index]["actions"])
                               if action.kind == "training_nav_r"), None)
        if existing_index is not None:
            item = f"a:{group_index}:{existing_index}"
            self.refresh_tree(); self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
            self.status.set("Este Treino já possui um Nav-R. Use as setas para movê-lo ao ponto desejado.")
            return
        nav_name = str(groups[group_index].get("training_nav_r_group") or "Nav-R")
        self.push_undo()
        inserted_group, action_index = self._insert_new_action(Action("training_nav_r", delay_ms=0, label=f"Nav-R: {nav_name}"))
        item = getattr(self, "last_inserted_tree_item", f"a:{inserted_group}:{action_index}")
        self.refresh_tree(); self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
        self.save_macro(quiet=True)
        self.status.set("Nav-R inserido dentro do Treino. Mova a etapa para o ponto desejado.")

    def add_navigate_s_group(self, group_index: int | None = None) -> None:
        """Cria um ciclo que verifica XML e usa dois toques gravados quando encontrar."""
        groups_for_flow = self.macros[self.flow_var.get()]
        editing = group_index is not None and 0 <= group_index < len(groups_for_flow)
        selected = self.tree.selection()
        inline_after: tuple[int, int] | None = None
        inline_child: tuple[int, int, int] | None = None
        if not editing and len(selected) == 1:
            parts = selected[0].split(":")
            if len(parts) == 3 and parts[0] == "a":
                try:
                    candidate = (int(parts[1]), int(parts[2]))
                    if candidate[0] < len(groups_for_flow):
                        inline_after = candidate
                except ValueError:
                    pass
            elif len(parts) == 4 and parts[0] == "s":
                if self._tree_action_container(selected[0]) is not None:
                    inline_child = (int(parts[1]), int(parts[2]), int(parts[3]))
        existing = groups_for_flow[group_index] if editing else {}
        dialog = tk.Toplevel(self)
        dialog.title("Nav-S")
        dialog.geometry("660x940")
        dialog.minsize(600, 890)
        dialog.configure(bg="#171b26")
        dialog.transient(self); dialog.grab_set()
        previous = existing if editing else self.settings.get("navigate_s_defaults", {})
        if not isinstance(previous, dict): previous = {}
        def last(key: str, default: str) -> str:
            group_keys = {
                "verify_timeout": "nav_s_verify_timeout_s", "min_s": "nav_min_s", "max_s": "nav_max_s",
                "pause_min": "nav_pause_min_ms", "pause_max": "nav_pause_max_ms", "tap_interval_min": "nav_tap_interval_min_ms",
                "tap_interval_max": "nav_tap_interval_max_ms", "first_chance": "nav_first_tap_chance_pct",
                "position": "nav_position_variation_px",
            }
            return str(previous.get(group_keys[key] if editing else key, default))
        values = {
            "name": tk.StringVar(value=str(existing.get("name", f"Nav-S {sum(bool(g.get('navigation_s')) for g in groups_for_flow) + 1}"))),
            "verify_timeout": tk.StringVar(value=last("verify_timeout", "10")),
            "min_s": tk.StringVar(value=last("min_s", "12")), "max_s": tk.StringVar(value=last("max_s", "20")),
            "pause_min": tk.StringVar(value=last("pause_min", "350")), "pause_max": tk.StringVar(value=last("pause_max", "750")),
            "tap_interval_min": tk.StringVar(value=last("tap_interval_min", "120")), "tap_interval_max": tk.StringVar(value=last("tap_interval_max", "250")),
            "first_chance": tk.StringVar(value=last("first_chance", "100")),
            "position": tk.StringVar(value=last("position", "8")),
        }
        fields = (
            ("Nome do grupo", "name"), ("Limite da verificação XML (s)", "verify_timeout"),
            ("Tempo total mínimo (s)", "min_s"), ("Tempo total máximo (s)", "max_s"),
            ("Pausa entre ciclos mín. (ms)", "pause_min"), ("Pausa entre ciclos máx. (ms)", "pause_max"),
            ("Intervalo entre os toques mín. (ms)", "tap_interval_min"), ("Intervalo entre os toques máx. (ms)", "tap_interval_max"),
            ("Chance do toque gravado (%)", "first_chance"),
            ("Variação de posição (px)", "position"),
        )
        for row, (label, key) in enumerate(fields):
            ttk.Label(dialog, text=label + ":").grid(row=row, column=0, padx=18, pady=6, sticky="w")
            ctk.CTkEntry(dialog, textvariable=values[key], width=220, height=30, corner_radius=8,
                         fg_color="#222938", border_color="#465166", text_color="#f8fafc").grid(row=row, column=1, padx=8, pady=6, sticky="w")
        ttk.Label(dialog, text="O Nav-S confere todas as etapas XML na ordem. A 1ª (Curtir) executa o primeiro toque quando a chance passar; se falhar, o Nav-S continua até o fim. Se a 2ª ou qualquer posterior também estiver na tela, ela prevalece e executa somente o arrasto gravado. Ao acabar o tempo, ele faz uma última consulta: se achar qualquer XML e houver mais de um toque gravado, executa somente o último toque do grupo uma vez. A rota alternativa já é criada no final do Nav-S e só é ignorada se nenhum XML for encontrado.", wraplength=560).grid(row=13, column=0, columnspan=2, padx=18, pady=(8, 2), sticky="w")

        def create():
            try:
                verify_timeout = float(values["verify_timeout"].get())
                minimum, maximum = float(values["min_s"].get()), float(values["max_s"].get())
                pause_min, pause_max = int(values["pause_min"].get()), int(values["pause_max"].get())
                interval_min, interval_max = int(values["tap_interval_min"].get()), int(values["tap_interval_max"].get())
                first_chance = float(values["first_chance"].get())
                position = int(values["position"].get())
                if verify_timeout <= 0 or minimum <= 0 or maximum < minimum or pause_min < 0 or pause_max < pause_min or interval_min < 0 or interval_max < interval_min or not 0 <= first_chance <= 100 or position < 0:
                    raise ValueError
            except ValueError:
                messagebox.showwarning("Nav-S", "Confira os intervalos e as chances.", parent=dialog); return
            self.push_undo()
            groups = self.macros[self.flow_var.get()]
            config = {"name": values["name"].get().strip() or "Nav-S", "enabled": bool(existing.get("enabled", True)), "navigation_s": True,
                      "nav_s_verify_timeout_s": verify_timeout, "nav_min_s": minimum, "nav_max_s": maximum,
                      "nav_pause_min_ms": pause_min, "nav_pause_max_ms": pause_max, "nav_tap_interval_min_ms": interval_min,
                      "nav_tap_interval_max_ms": interval_max, "nav_first_tap_chance_pct": first_chance,
                      "nav_position_variation_px": position}
            if editing:
                groups[group_index].update(config)
                if not any(isinstance(item, Action) and item.nav_s_alternative_group
                           for item in groups[group_index].get("actions", [])):
                    groups[group_index].setdefault("actions", []).append(
                        Action("subgroup", label="Rota alternativa", delay_ms=0,
                               nav_s_alternative_group=True, nested_actions=[])
                    )
            elif inline_after is not None:
                inline_group, inline_index = inline_after
                groups[inline_group]["actions"].insert(inline_index + 1, Action(
                    "navigate_s", label=config["name"], nav_actions=[
                        Action("subgroup", label="Rota alternativa", delay_ms=0,
                               nav_s_alternative_group=True, nested_actions=[])
                    ],
                    nav_s_query="", nav_s_third_query="", nav_s_verify_timeout_s=verify_timeout,
                    nav_min_s=minimum, nav_max_s=maximum, nav_pause_min_ms=pause_min,
                    nav_pause_max_ms=pause_max, nav_tap_interval_min_ms=interval_min,
                    nav_tap_interval_max_ms=interval_max, nav_first_tap_chance_pct=first_chance,
                    nav_position_variation_px=position, delay_ms=0,
                ))
                group_index = inline_group
            elif inline_child is not None:
                inline_group, parent_index, child_index = inline_child
                location = self._tree_action_container(f"s:{inline_group}:{parent_index}:{child_index}")
                if location is None:
                    return
                _unused_group, container, _unused_index = location
                container.insert(child_index + 1, Action(
                    "navigate_s", label=config["name"], nav_actions=[
                        Action("subgroup", label="Rota alternativa", delay_ms=0,
                               nav_s_alternative_group=True, nested_actions=[])
                    ],
                    nav_s_query="", nav_s_third_query="", nav_s_verify_timeout_s=verify_timeout,
                    nav_min_s=minimum, nav_max_s=maximum, nav_pause_min_ms=pause_min,
                    nav_pause_max_ms=pause_max, nav_tap_interval_min_ms=interval_min,
                    nav_tap_interval_max_ms=interval_max, nav_first_tap_chance_pct=first_chance,
                    nav_position_variation_px=position, delay_ms=0,
                ))
                group_index = inline_group
            else:
                groups.append({**config, "actions": [
                    Action("subgroup", label="Rota alternativa", delay_ms=0,
                           nav_s_alternative_group=True, nested_actions=[])
                ]})
            self.settings["navigate_s_defaults"] = {key: values[key].get().strip() for key in values if key != "name"}
            self._save_settings()
            self.active_group = group_index if (editing or inline_after is not None or inline_child is not None) else len(groups) - 1
            target_item = (f"a:{group_index}:{inline_after[1] + 1}" if inline_after is not None else
                           f"s:{inline_child[0]}:{inline_child[1]}:{inline_child[2] + 1}" if inline_child is not None else
                           f"g:{self.active_group}")
            self.refresh_tree(); self.tree.selection_set(target_item); self.tree.focus(target_item); self.tree.see(target_item)
            self.save_macro(); dialog.destroy()
            self.status.set("Nav-S configurado." if editing else "Nav-S criado. Grave nele um toque e adicione uma etapa XML.")
        ctk.CTkButton(dialog, text="Salvar grupo" if editing else "Criar grupo", command=create, width=130, height=32, corner_radius=8,
                      fg_color="#2f6fed", hover_color="#4b82ee").grid(row=14, column=1, padx=18, pady=16, sticky="e")

    @staticmethod
    def _merge_gesture_fragment(previous: Action, current: Action) -> bool:
        """Une contatos imediatamente consecutivos que pertencem ao mesmo swipe."""
        if previous.kind not in ("tap", "swipe") or current.kind not in ("tap", "swipe"):
            return False
        if current.delay_ms > 140:
            return False
        px = previous.x2 if previous.kind == "swipe" else previous.x
        py = previous.y2 if previous.kind == "swipe" else previous.y
        if abs((px or 0) - current.x) + abs((py or 0) - current.y) > 130:
            return False
        # Dois contatos que se encostam e têm movimento são tratados como um
        # único gesto contínuo, preservando início e final mais externos.
        if previous.kind == "swipe" or current.kind == "swipe":
            previous.kind = "swipe"
            previous.x2 = current.x2 if current.kind == "swipe" else current.x
            previous.y2 = current.y2 if current.kind == "swipe" else current.y
            previous.duration_ms += current.duration_ms
            return True
        return False

    def _set_action_variation_defaults(self, action: Action, force_enabled: bool | None = None) -> None:
        """Registra na etapa os valores de variação vigentes no momento da criação."""
        action.use_variation = self.variations_enabled.get() if force_enabled is None else force_enabled
        if not action.use_variation:
            return
        try:
            action.delay_variation_min_ms = max(0, float(self.delay_jitter_down.get()))
            action.delay_variation_max_ms = max(0, float(self.delay_jitter_up.get()))
            action.delay_variation_pct = None
            action.position_variation_px = max(0, int(self.position_jitter.get()))
            action.end_position_variation_px = max(0, int(self.end_position_jitter.get()))
            action.speed_variation_pct = max(0, float(self.speed_jitter.get()))
        except ValueError:
            # A validação normal da execução continua avisando o usuário; aqui
            # mantemos a etapa compatível com os valores globais atuais.
            action.delay_variation_pct = None
            action.delay_variation_min_ms = None
            action.delay_variation_max_ms = None
            action.position_variation_px = None
            action.end_position_variation_px = None
            action.speed_variation_pct = None

    @staticmethod
    def _delay_variation_offsets(action: Action) -> tuple[float, float]:
        """Retorna quanto a pausa pode reduzir/aumentar, em milissegundos."""
        if not action.use_variation:
            return 0.0, 0.0
        # O valor legado era percentual simétrico; só macros antigas chegam
        # aqui sem os novos limites em ms.
        legacy = max(0.0, action.delay_ms * float(action.delay_variation_pct or 0) / 100)
        down = max(0.0, float(action.delay_variation_min_ms if action.delay_variation_min_ms is not None else legacy))
        up = max(0.0, float(action.delay_variation_max_ms if action.delay_variation_max_ms is not None else legacy))
        return down, up

    def apply_variation_to_selected(self) -> None:
        """Aplica os valores atuais às etapas ou grupos selecionados."""
        try:
            delay_min = max(0, float(self.delay_jitter_down.get()))
            delay_max = max(0, float(self.delay_jitter_up.get()))
            position = max(0, int(self.position_jitter.get()))
            end_position = max(0, int(self.end_position_jitter.get()))
            speed = max(0, float(self.speed_jitter.get()))
        except ValueError:
            messagebox.showwarning("Variações", "Confira os valores de pausa, posição e duração.")
            return
        selected = self.tree.selection()
        if not selected:
            self.status.set("Selecione uma ou mais etapas ou grupos para aplicar as variações.")
            return
        groups = self.macros[self.flow_var.get()]
        targets: list[Action] = []
        seen: set[int] = set()
        updated_group_variations = False

        def include(action: Action) -> None:
            """Inclui a etapa e todos os descendentes, sem limite de nível."""
            if id(action) in seen:
                return
            seen.add(id(action))
            targets.append(action)
            values = self._container_actions(action)
            if values:
                for child in values:
                    include(child)

        for item in selected:
            parts = item.split(":")
            if parts[0] == "g":
                group_index = int(parts[1])
                group = groups[group_index]
                if group.get("xml_any_tap_group"):
                    group["use_variation"] = self.variations_enabled.get()
                    group["delay_variation_min_ms"] = delay_min if group["use_variation"] else None
                    group["delay_variation_max_ms"] = delay_max if group["use_variation"] else None
                    group["delay_variation_pct"] = None
                    group["position_variation_px"] = position if group["use_variation"] else None
                    group["end_position_variation_px"] = end_position if group["use_variation"] else None
                    group["speed_variation_pct"] = speed if group["use_variation"] else None
                    updated_group_variations = True
                for action in groups[group_index]["actions"]:
                    include(action)
            elif parts[0] == "a":
                group_index, action_index = int(parts[1]), int(parts[2])
                include(groups[group_index]["actions"][action_index])
            elif parts[0].startswith("s"):
                location = self._tree_action_container(item)
                if location is not None:
                    _group_index, actions, action_index = location
                    if 0 <= action_index < len(actions):
                        include(actions[action_index])
        if not targets and not updated_group_variations:
            self.status.set("A seleção não contém etapas para atualizar.")
            return
        self.push_undo()
        for action in targets:
            action.use_variation = self.variations_enabled.get()
            action.delay_variation_min_ms = delay_min if action.use_variation else None
            action.delay_variation_max_ms = delay_max if action.use_variation else None
            action.delay_variation_pct = None
            action.position_variation_px = position if action.use_variation else None
            action.end_position_variation_px = end_position if action.use_variation else None
            action.speed_variation_pct = speed if action.use_variation else None
        self.refresh_tree()
        self.save_macro(quiet=True)
        self.status.set(f"Variações aplicadas a {len(targets)} etapa(s) selecionada(s).")

    def append_recorded_action(self, action: Action) -> None:
        # Uma sessao inteira de gravacao deve ser desfeita com um unico Ctrl+Z.
        self._set_action_variation_defaults(action)
        if not self.recording_undo_active:
            self.push_undo()
        if self.record_inline_nav_actions is not None:
            self.record_inline_nav_actions.append(asdict(action))
            self.refresh_tree()
            if self.adb.serial: self.save_macro(quiet=True)
            return
        if self.record_subgroup_actions is not None:
            nested = self.record_subgroup_actions
            insert_at = max(0, min(self.record_subgroup_insert_index if self.record_subgroup_insert_index is not None else len(nested), len(nested)))
            previous = nested[insert_at - 1] if insert_at else None
            if previous and self._merge_gesture_fragment(previous, action):
                if self.record_subgroup_tree_prefix:
                    self.last_recorded_item = f"{self.record_subgroup_tree_prefix}:{insert_at - 1}"
                self.refresh_tree()
                if self.adb.serial: self.save_macro(quiet=True)
                return
            nested.insert(insert_at, action)
            self.record_subgroup_insert_index = insert_at + 1
            if self.record_subgroup_tree_prefix:
                self.last_recorded_item = f"{self.record_subgroup_tree_prefix}:{insert_at}"
            self.refresh_tree()
            if self.adb.serial: self.save_macro(quiet=True)
            return
        if self.record_insert is not None:
            group_index, action_index = self.record_insert
            groups = self.macros[self.flow_var.get()]
            if group_index < len(groups):
                previous = groups[group_index]["actions"][action_index - 1] if action_index else None
                if previous and self._merge_gesture_fragment(previous, action):
                    self.last_recorded_item = f"a:{group_index}:{action_index - 1}"
                    self.refresh_tree()
                    if self.adb.serial: self.save_macro(quiet=True)
                    return
                groups[group_index]["actions"].insert(action_index, action)
                self.record_insert = (group_index, action_index + 1)
                self.active_group = group_index
                self.last_recorded_item = f"a:{group_index}:{action_index}"
                self.refresh_tree()
                if self.adb.serial: self.save_macro(quiet=True)
                return
        if self.active_group is None or self.active_group >= len(self.macros[self.flow_var.get()]):
            self.new_group()
        actions = self.macros[self.flow_var.get()][self.active_group]["actions"]
        if actions and self._merge_gesture_fragment(actions[-1], action):
            self.last_recorded_item = f"a:{self.active_group}:{len(actions) - 1}"
            self.refresh_tree()
            if self.adb.serial: self.save_macro(quiet=True)
            return
        actions.append(action)
        self.last_recorded_item = f"a:{self.active_group}:{len(actions) - 1}"
        self.refresh_tree()
        if self.adb.serial:
            self.save_macro(quiet=True)

    def _xml_target_group(self) -> int:
        selected = self.tree.selection()
        if selected:
            parts = selected[0].split(":")
            if parts[0] == "g": return int(parts[1])
            if parts[0] == "a": return int(parts[1])
        groups = self.macros[self.flow_var.get()]
        if self.active_group is not None and self.active_group < len(groups):
            return self.active_group
        if groups:
            return 0
        return self.new_group("Grupo 1")

    def select_active_group(self, _event=None) -> None:
        selected = self.tree.selection()
        if not selected:
            return
        # O destaque verde pertence somente ao resultado que está sendo
        # escolhido no popup de XML. Ao trocar a seleção principal, ele não
        # pode continuar preso ao último XML escolhido.
        if self.live_xml_marker_bounds is not None:
            self.live_xml_marker_bounds = None
            self.live_xml_marker_source_size = None
        parts = selected[0].split(":")
        if parts[0] in ("g", "a"):
            self.active_group = int(parts[1])
        self.update_action_preview(parts)
        self._update_live_touch_marker()
        # O scrcpy Ã© uma janela nativa e pode concluir um resize depois do
        # evento da Ã¡rvore. Uma segunda passagem curta impede que ela fique
        # por cima da mÃ¡scara recÃ©m-selecionada.
        self.after(45, self._update_live_touch_marker)
        self._render_execution_state()

    def toggle_selected_tree_groups(self, _event=None):
        """Ctrl+E expande/recolhe todos os grupos ou subgrupos selecionados."""
        selected = self.tree.selection()
        containers = [item for item in selected if self.tree.exists(item) and self.tree.get_children(item)]
        if not containers:
            self.status.set("Selecione um ou mais grupos/subgrupos para expandir ou recolher.")
            return "break"
        # Se algum estiver fechado, a intenção é abrir todos; se todos já
        # estiverem abertos, recolhe todos numa única ação.
        open_all = any(not bool(self.tree.item(item, "open")) for item in containers)
        for item in containers:
            self.tree.item(item, open=open_all)
        self.status.set(f"{len(containers)} grupo(s) {'expandido(s)' if open_all else 'recolhido(s)'}.")
        return "break"

    @staticmethod
    def _action_coordinate_screen(action: Action, macro_screen: tuple[int, int], raw_size: object) -> tuple[int, int]:
        """A referência de todas as etapas é sempre a tela da macro.

        ``raw_size`` descreve apenas o sensor usado durante a gravação. Ele
        não pode ser usado para adivinhar cada toque depois: em aparelhos cujo
        sensor é maior que a tela, um toque válido cabe nas duas escalas e
        passaria a mudar de lugar ao reiniciar o programa.
        """
        return macro_screen

    @classmethod
    def _normalize_legacy_action_coordinates(cls, action: Action, macro_screen: tuple[int, int], raw_size: object) -> None:
        """Converte somente etapas antigas que ficaram fora da tela da macro.

        Versões anteriores permitiam que a edição pela prévia salvasse alguns
        pontos na escala bruta do sensor. Esses pontos são identificáveis porque
        ultrapassam a tela registrada. Etapas dentro dela já estão corretas e
        nunca são alteradas aqui.
        """
        # Coordenadas gravadas são dados imutáveis fora de uma edição
        # explícita. Esta migração antiga não é mais aplicada, nem mesmo para
        # pontos fora da tela, pois uma inferência automática jamais pode
        # prevalecer sobre a posição que a pessoa gravou.
        return
        try:
            raw_w, raw_h = (int(float(value)) for value in raw_size)
        except (TypeError, ValueError):
            raw_w = raw_h = 0
        macro_w, macro_h = macro_screen
        if raw_w > 0 and raw_h > 0 and macro_w > 0 and macro_h > 0 and (raw_w, raw_h) != (macro_w, macro_h):
            points = [(action.x, action.y)]
            if action.kind in ("swipe", "nav_rc_scroll"):
                points.append((action.x2 if action.x2 is not None else action.x,
                               action.y2 if action.y2 is not None else action.y))
            outside_macro = any(x >= macro_w or y >= macro_h or x < 0 or y < 0 for x, y in points)
            inside_raw = all(0 <= x < raw_w and 0 <= y < raw_h for x, y in points)
            if outside_macro and inside_raw:
                def convert(value: int | None, source: int, target: int) -> int | None:
                    if value is None:
                        return None
                    return max(0, min(target - 1, round(value * max(0, target - 1) / max(1, source - 1))))
                action.x = convert(action.x, raw_w, macro_w) or 0
                action.y = convert(action.y, raw_h, macro_h) or 0
                if action.kind in ("swipe", "nav_rc_scroll"):
                    action.x2 = convert(action.x2, raw_w, macro_w)
                    action.y2 = convert(action.y2, raw_h, macro_h)

        for field in ("nav_actions", "branch_actions", "nav_after_actions", "nav_rc_actions", "nav_rc_fallback_actions", "nested_actions"):
            values = getattr(action, field, None)
            if not values:
                continue
            normalized: list[dict] = []
            for item in values:
                nested = item if isinstance(item, Action) else Action(**item)
                cls._normalize_legacy_action_coordinates(nested, macro_screen, raw_size)
                normalized.append(asdict(nested))
            setattr(action, field, normalized)

    @classmethod
    def _scale_actions_to_target_screen(cls, actions: list[Action], macro_screen: tuple[int, int], raw_size: object,
                                        target_screen: tuple[int, int]) -> list[Action]:
        """Converte coordenadas gravadas para a tela do telefone que executará.

        A gravação pode vir da escala física ou da escala lógica exposta pelo
        touchscreen. A prévia já identifica isso; a execução deve usar a mesma
        regra, principalmente depois de reiniciar o app ou trocar de aparelho.
        """
        def scale(value: int | None, source: int, target: int) -> int | None:
            if value is None:
                return None
            return max(0, min(target - 1, round(value * max(0, target - 1) / max(1, source - 1))))

        nested_fields = ("nav_actions", "branch_actions", "nav_after_actions", "nav_rc_actions", "nav_rc_fallback_actions", "nested_actions")

        def convert(action: Action) -> Action:
            result = copy.deepcopy(action)
            source_w, source_h = macro_screen
            if result.kind in ("tap", "swipe", "nav_rc_scroll"):
                result.x = scale(result.x, source_w, target_screen[0]) or 0
                result.y = scale(result.y, source_h, target_screen[1]) or 0
                if result.kind in ("swipe", "nav_rc_scroll"):
                    result.x2 = scale(action.x2 if action.x2 is not None else action.x, source_w, target_screen[0])
                    result.y2 = scale(action.y2 if action.y2 is not None else action.y, source_h, target_screen[1])
            for field in nested_fields:
                values = getattr(result, field, None)
                if values:
                    setattr(result, field, [asdict(convert(item if isinstance(item, Action) else Action(**item))) for item in values])
            return result

        return [convert(action) for action in actions]

    def _retry_warm_live_view(self, serial: str) -> None:
        """Repete a reserva que falhou ao abrir, sem duplicar o serial."""
        serial = str(serial)
        if not serial or serial in self.warm_scrcpy_retry_pending:
            return
        attempt = self.warm_scrcpy_retry_attempts.get(serial, 0)
        # O sexto servidor scrcpy pode receber uma resposta transitória do ADB
        # durante a subida simultânea. Três tentativas faziam justamente o
        # último aparelho (com frequência o já selecionado) sumir da reserva
        # para o restante daquela abertura.
        if attempt >= 8:
            return
        self.warm_scrcpy_retry_attempts[serial] = attempt + 1
        self.warm_scrcpy_retry_pending.add(serial)

        def retry() -> None:
            self.warm_scrcpy_retry_pending.discard(serial)
            if getattr(self, "_closing_now", False):
                return
            current = self.warm_scrcpy_processes.get(serial)
            if current and current.poll() is None:
                return
            connected = any(
                str(profile.get("serial", "")) == serial and profile.get("state") == "device"
                for profile in self.device_profiles.values()
            )
            if connected and serial not in self.warm_scrcpy_queue:
                self.warm_scrcpy_queue.append(serial)
                self._start_next_warm_live_view()

        self.after(350 * (attempt + 1), retry)

    @staticmethod
    def _trace_scrcpy_recovery(serial: str, detail: str) -> None:
        """Registro curto para diagnosticar reconexões que fecham o scrcpy."""
        try:
            stamp = datetime.now().strftime("%H:%M:%S.%f")[:-3]
            with (RUNTIME_DIR / f"scrcpy_recovery_{serial}.log").open("a", encoding="utf-8") as log:
                log.write(f"[{stamp}] {detail}\n")
        except OSError:
            pass

    def _set_device_visual_pool_loading(self, loading: bool) -> None:
        """Esconde a lista até todas as reservas visuais ficarem prontas."""
        if not hasattr(self, "device_list_content"):
            return
        self.device_visual_pool_loading = bool(loading)
        if loading:
            self.device_list_content.place_forget()
            if not hasattr(self, "device_visual_pool_notice"):
                self.device_visual_pool_notice = tk.Label(
                    self.device_area, bg="#111925", fg="#aebbd0",
                    font=("Segoe UI", 10),
                    text="Preparando as telas de todos os celulares…",
                )
            self.device_visual_pool_notice.place(x=0, y=0, relwidth=1, height=112)
            if hasattr(self, "view_devices_button"):
                self.view_devices_button.configure(state="disabled")
            return
        if hasattr(self, "device_visual_pool_notice"):
            self.device_visual_pool_notice.place_forget()
        self.device_list_content.place(x=0, y=0, relwidth=1, height=112)
        if hasattr(self, "view_devices_button"):
            self.view_devices_button.configure(state="normal")

    def _prepare_all_device_visuals(self, profiles: list[dict]) -> None:
        """Só libera a lista quando todo serial conectado tem sua janela SDL."""
        if not getattr(self, "app_view_var", None) or self.app_view_var.get() != "fluxo":
            return
        profiles_by_serial = {
            str(profile.get("serial", "")): profile for profile in profiles
            if profile.get("state") == "device" and str(profile.get("serial", ""))
        }
        # The Tk list can be between rebuilds while the cable watcher runs.
        # Reserve from the ADB-connected serial set, never from a transient
        # selection or a partially rebuilt list.
        try:
            adb_connected = {str(serial) for serial, state in self.adb.devices() if state == "device"}
        except (OSError, RuntimeError, subprocess.SubprocessError):
            adb_connected = set()
        for serial in adb_connected:
            profiles_by_serial.setdefault(serial, {"serial": serial, "state": "device"})
        profiles = list(profiles_by_serial.values())
        expected = {
            str(profile.get("serial", "")) for profile in profiles
            if profile.get("state") == "device" and str(profile.get("serial", ""))
        }
        # Uma prévia que sobreviveu à reconstrução da interface também é a
        # reserva desse serial. Registrá-la antes de montar a fila impede que
        # o telefone já selecionado seja tratado como uma tela separada.
        primary = self.scrcpy_process
        primary_serial = str(self.scrcpy_serial or "")
        if (primary_serial in expected and primary is not None
                and primary.poll() is None
                and self._scrcpy_process_matches_serial(primary, primary_serial)):
            self.warm_scrcpy_processes[primary_serial] = primary
            hwnd = int(self.scrcpy_window_handle or 0)
            if not self._window_belongs_to_process(hwnd, primary.pid):
                hwnd = self._window_for_process(primary.pid, include_hidden=True)
            if hwnd:
                self.warm_scrcpy_windows[primary_serial] = hwnd

        expected_changed = expected != self.device_visual_pool_expected
        self.device_visual_pool_expected = expected
        # Atualizações repetidas durante o início não podem reiniciar a
        # contagem e deixar a tela de preparação presa indefinidamente.
        if expected_changed or not self.device_visual_pool_loading:
            self.device_visual_pool_started_at = time.monotonic()
        if not expected:
            self._set_device_visual_pool_loading(False)
            return
        self._set_device_visual_pool_loading(True)
        self._warm_connected_live_views(profiles)
        if not self.device_visual_pool_wait_scheduled:
            self.device_visual_pool_wait_scheduled = True
            self.after(100, self._finish_device_visual_pool_when_ready)

    def _finish_device_visual_pool_when_ready(self) -> None:
        self.device_visual_pool_wait_scheduled = False
        if (not getattr(self, "app_view_var", None) or self.app_view_var.get() != "fluxo"
                or getattr(self, "_closing_now", False)):
            return
        expected = set(self.device_visual_pool_expected)
        ready = True
        for serial in expected:
            process = self.warm_scrcpy_processes.get(serial)
            if process and not self._scrcpy_process_matches_serial(process, serial):
                self.warm_scrcpy_processes.pop(serial, None)
                self.warm_scrcpy_windows.pop(serial, None)
                process = None
            if (not process or process.poll() is not None) and str(self.scrcpy_serial or "") == serial:
                primary = self.scrcpy_process
                if (primary is not None and primary.poll() is None
                        and self._scrcpy_process_matches_serial(primary, serial)):
                    process = primary
                    self.warm_scrcpy_processes[serial] = primary
            if not process or process.poll() is not None:
                ready = False
                continue
            hwnd = self._window_for_process(process.pid, include_hidden=True)
            if not hwnd:
                ready = False
                continue
            self.warm_scrcpy_windows[serial] = hwnd
        if not ready:
            profiles = [profile for profile in self.device_profiles.values()
                        if str(profile.get("serial", "")) in expected]
            self._warm_connected_live_views(profiles)
            elapsed = time.monotonic() - self.device_visual_pool_started_at
            # Reconciliação obrigatória: a primeira rodada de abertura pode
            # perder um item ao reconstruir a lista. Todo serial conectado que
            # ainda não possui um processo scrcpy próprio volta para a fila;
            # não confiamos apenas na primeira programação da fila.
            missing_processes = []
            for serial in expected:
                candidate = self.warm_scrcpy_processes.get(serial)
                if (candidate is None or candidate.poll() is not None
                        or not self._scrcpy_process_matches_serial(candidate, serial)):
                    self.warm_scrcpy_processes.pop(serial, None)
                    self.warm_scrcpy_windows.pop(serial, None)
                    self.warm_scrcpy_retry_pending.discard(serial)
                    if serial not in self.warm_scrcpy_queue:
                        self.warm_scrcpy_queue.append(serial)
                    missing_processes.append(serial)
            if missing_processes and not self.warm_scrcpy_starting:
                self.after(0, self._start_next_warm_live_view)
            # Com um único telefone conectado não existe outra reserva a
            # aguardar. Se a fila não criou a janela em alguns segundos,
            # liberamos somente esse serial para o caminho direto, que vira a
            # sua reserva normal em seguida. Isso cobre exatamente o caso do
            # Note 12 sem mudar o carregamento coletivo com vários celulares.
            if len(expected) == 1 and elapsed >= 5:
                serial = next(iter(expected))
                process = self.warm_scrcpy_processes.get(serial)
                if not process or process.poll() is not None:
                    self.warm_scrcpy_processes.pop(serial, None)
                    self.warm_scrcpy_windows.pop(serial, None)
                    self.warm_scrcpy_queue = [item for item in self.warm_scrcpy_queue if item != serial]
                    self.warm_scrcpy_retry_pending.discard(serial)
                    self.warm_scrcpy_starting_serials.discard(serial)
                    self._set_device_visual_pool_loading(False)
                    self.after_idle(lambda target=serial:
                                    self._start_live_view_when_preview_ready(target))
                    return
            # Readiness is all-or-nothing: retry the affected serial instead
            # of releasing a partial list after an arbitrary timeout.
            self.device_visual_pool_wait_scheduled = True
            self.after(120, self._finish_device_visual_pool_when_ready)
            return
        # A prévia inicial tem de passar pela mesma seleção que um clique na
        # lista. Antes, se já houvesse uma seleção preservada enquanto a lista
        # era reconstruída, o telefone restaurado podia ficar apenas como
        # reserva e nunca receber o encaixe final.
        selected = self.selected_profiles()
        remembered = self._last_selected_device_for_panel()
        selected_serial = (
            str(selected[0].get("serial", ""))
            if len(selected) == 1 and selected[0].get("state") == "device"
            else ""
        )
        target = remembered if remembered in expected else selected_serial
        if target not in expected:
            target = next(iter(expected), "")
        if not target:
            self._set_device_visual_pool_loading(False)
            return
        for index in range(self.device_list.size()):
            profile = self.device_profiles.get(self.device_list.get(index), {})
            if str(profile.get("serial", "")) != target:
                continue
            self.device_list.selection_clear(0, tk.END)
            self.device_list.selection_set(index)
            self.device_list.activate(index)
            self.device_list.see(index)
            self._set_device_visual_pool_loading(False)
            # Esta é a mesma rotina acionada pelo clique do usuário. Só ela
            # agenda o encaixe, depois da reserva daquele serial estar pronta.
            self.populate_profile()
            # Na abertura, a lista pode restaurar a seleção antes de a janela
            # SDL deste mesmo serial existir. A rotina abaixo espera somente a
            # reserva do telefone escolhido (não a dos demais) e então força o
            # encaixe da prévia. Antes ela existia, mas não era chamada aqui.
            self.after_idle(lambda target=target:
                            self._start_initial_live_view_when_pool_ready(target))
            return
        self._set_device_visual_pool_loading(False)

    def _warm_pool_is_ready(self, profiles: list[dict]) -> bool:
        """Confirma uma janela SDL preparada para cada celular conectado."""
        for profile in profiles:
            if profile.get("state") != "device":
                continue
            serial = str(profile.get("serial", ""))
            process = self.warm_scrcpy_processes.get(serial)
            if not process or process.poll() is not None:
                return False
            hwnd = int(self.warm_scrcpy_windows.get(serial, 0) or 0)
            if not hwnd:
                return False
        return True

    def _start_initial_live_view_when_pool_ready(self, serial: str, attempt: int = 0) -> None:
        """Fixa a prévia já selecionada assim que a reserva dela estiver pronta."""
        if not getattr(self, "app_view_var", None) or self.app_view_var.get() != "fluxo":
            return
        # A lista pode ter restaurado a seleção persistida enquanto as janelas
        # eram preparadas. Use a escolha atual agora, não o primeiro serial
        # que existia quando a abertura começou.
        selected = self.selected_profiles()
        current = (str(selected[0].get("serial", ""))
                   if len(selected) == 1 and selected[0].get("state") == "device"
                   else str(serial))
        if not current:
            return
        process = self.warm_scrcpy_processes.get(current)
        hwnd = (int(self.warm_scrcpy_windows.get(current, 0) or 0)
                if process and process.poll() is None else 0)
        if not hwnd and process and process.poll() is None:
            hwnd = self._window_for_process(process.pid, include_hidden=True)
            if hwnd:
                self.warm_scrcpy_windows[current] = hwnd
        # Só a reserva do celular selecionado importa aqui. Esperar todos os
        # seis fazia a prévia inicial nunca aparecer quando um outro aparelho
        # demorava a criar sua própria janela.
        if not hwnd:
            if attempt < 100:
                self.after(100, lambda target=current, count=attempt + 1:
                           self._start_initial_live_view_when_pool_ready(target, count))
            return
        # A reserva do scrcpy pode estar pronta antes de o Tk terminar de
        # desenhar o quadro da prévia na abertura. Chamar ``start_live_view``
        # diretamente nesse instante deixa a janela SDL fora do painel (e
        # visível na barra de tarefas) até um clique manual. Passe sempre pelo
        # verificador do quadro, exatamente como o clique da lista faz.
        self._start_live_view_when_preview_ready(current)

    def _queue_warm_live_view(self, serial: str) -> None:
        """Request one shared scrcpy reservation for ``serial``.

        This is deliberately the only path that queues a new process.  A
        reservation is identified by its immutable ``--serial`` argument, not
        by a window title or by whichever panel requested it.
        """
        serial = str(serial or "")
        if not serial:
            return
        process = self.warm_scrcpy_processes.get(serial)
        if process and self._scrcpy_process_matches_serial(process, serial):
            if process.poll() is None:
                return
            self.warm_scrcpy_processes.pop(serial, None)
            self.warm_scrcpy_windows.pop(serial, None)
        if (serial not in self.warm_scrcpy_queue
                and serial not in self.warm_scrcpy_starting_serials
                and serial not in self.warm_scrcpy_retry_pending):
            self.warm_scrcpy_queue.append(serial)
            self._trace_scrcpy_recovery(serial, "enfileirado")
        if not self.warm_scrcpy_starting:
            self.after(0, self._start_next_warm_live_view)

    def _scrcpy_port_for_serial(self, serial: str) -> int:
        """Return a stable, exclusive local scrcpy tunnel port per serial."""
        serial = str(serial)
        existing = self.warm_scrcpy_ports.get(serial)
        if existing:
            return existing
        used = set(self.warm_scrcpy_ports.values())
        for port in range(27183, 27200):
            if port not in used:
                self.warm_scrcpy_ports[serial] = port
                return port
        raise RuntimeError("Não há porta scrcpy disponível para outro celular.")

    def _warm_connected_live_views(self, profiles: list[dict]) -> None:
        """Prepara uma reserva oculta para cada telefone conectado."""
        if not getattr(self, "app_view_var", None) or self.app_view_var.get() != "fluxo":
            return
        # Só exclua a prévia se ela ainda tiver um processo vivo. O serial
        # selecionado pode sobreviver no estado após um scrcpy encerrar; usar
        # somente ``scrcpy_serial`` nesse caso pulava justamente aquele
        # telefone da pré-carga e deixava a barreira esperando para sempre.
        active_primary = self.scrcpy_process
        primary_serial = (
            str(self.scrcpy_serial or "")
            if (active_primary is not None and active_primary.poll() is None
                and self.live_view_mode
                and self._scrcpy_process_matches_serial(active_primary, str(self.scrcpy_serial or "")))
            else ""
        )
        if primary_serial:
            # A prévia ativa é uma reserva válida do mesmo serial. Mantém
            # exatamente um processo por celular, inclusive na inicialização.
            self.warm_scrcpy_processes[primary_serial] = active_primary
            hwnd = int(self.scrcpy_window_handle or 0)
            if not self._window_belongs_to_process(hwnd, active_primary.pid):
                hwnd = self._window_for_process(active_primary.pid, include_hidden=True)
            if hwnd:
                self.warm_scrcpy_windows[primary_serial] = hwnd
        for profile in profiles:
            if profile.get("state") != "device":
                continue
            serial = str(profile.get("serial", ""))
            # A prévia já visível não precisa de uma segunda reserva; os
            # demais, inclusive o celular apenas selecionado, são preparados.
            # Mesmo a prévia atual passa por esta verificação. Se ela já tiver
            # processo próprio, ``current`` abaixo impede duplicata; excluí-la
            # aqui fazia justamente o último/selecionado nunca entrar na fila.
            if not serial:
                continue
            current = self.warm_scrcpy_processes.get(serial)
            if current and not self._scrcpy_process_matches_serial(current, serial):
                self.warm_scrcpy_processes.pop(serial, None)
                self.warm_scrcpy_windows.pop(serial, None)
                current = None
            if not (current and current.poll() is None):
                self._queue_warm_live_view(serial)
        # Cada sessão segue independente depois de iniciada. Só espaçamos as
        # criações para não tentar instalar seis servidores scrcpy no mesmo
        # instante no ADB/USB — cenário em que o último processo podia fechar
        # antes de criar sua janela, embora o telefone estivesse conectado.
        # A transmissão e a execução seguem paralelas; apenas a criação do
        # servidor scrcpy é sequencial. A verificação da barreira chama esta
        # rotina várias vezes por segundo; agendar a fila inteira em cada uma
        # dessas chamadas anulava qualquer espaçamento e deixava um telefone
        # aleatório sem janela SDL.
        if self.warm_scrcpy_queue and not self.warm_scrcpy_starting:
            self.after(0, self._start_next_warm_live_view)

    def _warm_uiautomator2_servers(self, profiles: list[dict]) -> None:
        """Inicia em fila os servidores XML dos telefones conectados."""
        connected = {
            str(profile.get("serial", "")) for profile in profiles
            if profile.get("state") == "device" and str(profile.get("serial", ""))
        }
        self.uiautomator2_ready_serials.intersection_update(connected)
        self.uiautomator2_start_queue = [
            serial for serial in self.uiautomator2_start_queue if serial in connected
        ]
        if self.uiautomator2_starting_serial and self.uiautomator2_starting_serial not in connected:
            self.uiautomator2_starting_serial = ""
        for serial in sorted(connected):
            if (serial not in self.uiautomator2_ready_serials
                    and serial != self.uiautomator2_starting_serial
                    and serial not in self.uiautomator2_start_queue):
                self.uiautomator2_start_queue.append(serial)
        self._start_next_uiautomator2_server()

    def _start_next_uiautomator2_server(self) -> None:
        if self.uiautomator2_starting_serial or not self.uiautomator2_start_queue:
            return
        serial = self.uiautomator2_start_queue.pop(0)
        self.uiautomator2_starting_serial = serial

        def start_server(target: str = serial) -> None:
            error_text = ""
            try:
                adb = Adb()
                adb.path, adb.serial = self.adb.path, target
                adb.ensure_uiautomator2_server(timeout=15)
            except Exception as error:
                error_text = str(error)
            self.events.put(("uiautomator2_server", (target, error_text)))

        self._thread(start_server)

    def _start_next_warm_live_view(self) -> None:
        if self.warm_scrcpy_starting:
            return
        if not self.warm_scrcpy_queue:
            return
        executable = APP_DIR / "tools" / "scrcpy" / "scrcpy-win64-v4.1" / "scrcpy.exe"
        if not executable.exists():
            return
        # A grade pode ter assumido uma reserva que ainda constava na fila.
        # Revalide aqui, imediatamente antes de abrir o processo, para nunca
        # criar um segundo scrcpy para o mesmo telefone.
        serial = ""
        while self.warm_scrcpy_queue:
            candidate = self.warm_scrcpy_queue.pop(0)
            current = self.warm_scrcpy_processes.get(candidate)
            if (current and current.poll() is None
                    and self._scrcpy_process_matches_serial(current, candidate)):
                continue
            if current and not self._scrcpy_process_matches_serial(current, candidate):
                self.warm_scrcpy_processes.pop(candidate, None)
                self.warm_scrcpy_windows.pop(candidate, None)
            serial = candidate
            break
        if not serial:
            return
        self._trace_scrcpy_recovery(serial, "iniciando processo")
        self.warm_scrcpy_starting_serials.add(serial)
        self.warm_scrcpy_starting = True
        port = self._scrcpy_port_for_serial(serial)
        # Creating the sixth scrcpy can block in Windows/ADB.  Never perform
        # that operation on Tk's event thread: it prevented the final queued
        # serial from ever being dispatched.
        def launch_in_worker(target=serial, tunnel_port=port) -> None:
            # Quando uma conexão recém-restaurada fecha antes de criar a SDL,
            # o scrcpy só explica a razão no stderr. Registrar por serial
            # permite recuperar esse caso sem travar a interface nem abrir
            # uma janela de console.
            log_path = RUNTIME_DIR / f"scrcpy_{target}.log"
            try:
                with log_path.open("ab") as log_file:
                    process = subprocess.Popen(
                        [str(executable), f"--serial={target}", f"--port={tunnel_port}", "--force-adb-forward",
                         "--window-title", f"iggents pronto {target}",
                         "--window-borderless", "--window-x", "-32000", "--window-y", "-32000", "--no-audio",
                         "--max-size=540", "--max-fps=20", "--video-bit-rate=2M", "--render-driver=opengl"],
                        cwd=str(executable.parent), stdout=log_file, stderr=log_file,
                        creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0), startupinfo=None,
                    )
                self.events.put(("warm_scrcpy_process", (target, process, None)))
            except OSError as error:
                self.events.put(("warm_scrcpy_process", (target, None, error)))

        self._thread(launch_in_worker)
        return
        try:
            process = subprocess.Popen(
                [str(executable), "--serial", serial, "--window-title", f"iggents pronto {serial}",
                 "--window-borderless", "--window-x", "-32000", "--window-y", "-32000", "--no-audio",
                 "--max-size=540", "--max-fps=20", "--video-bit-rate=2M", "--render-driver=opengl"],
                cwd=str(executable.parent), stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                # Mover a janela para fora da tela já impede qualquer flash.
                # Não a inicie com SW_HIDE: em alguns Windows/SDL ela deixa de
                # ser enumerável como SDL_app e a reserva fica viva, porém
                # impossível de encaixar na prévia.
                startupinfo=None,
            )
            self.warm_scrcpy_processes[serial] = process
        except OSError:
            self.warm_scrcpy_starting_serials.discard(serial)
            self.warm_scrcpy_starting = bool(self.warm_scrcpy_starting_serials)
            self._retry_warm_live_view(serial)
            if self.warm_scrcpy_queue:
                self.after(80, self._start_next_warm_live_view)
            return

        # Process launch and SDL discovery are separate state transitions.  A
        # slow or missing SDL for one device must never hold the queue hostage
        # and prevent a later serial from receiving its own process.
        def release_launch_slot(candidate=process, current_serial=serial) -> None:
            if self.warm_scrcpy_processes.get(current_serial) is candidate:
                self.warm_scrcpy_starting_serials.discard(current_serial)
            self.warm_scrcpy_starting = bool(self.warm_scrcpy_starting_serials)
            self._start_next_warm_live_view()

        self.after(500, release_launch_slot)

        def finish(candidate=process, attempt=0):
            if candidate.poll() is not None:
                try:
                    _stdout, stderr = candidate.communicate(timeout=0)
                    detail = stderr.decode("utf-8", "replace") if isinstance(stderr, bytes) else str(stderr or "")
                    (RUNTIME_DIR / f"scrcpy_start_{serial}.log").write_text(detail, encoding="utf-8")
                except (OSError, subprocess.SubprocessError):
                    pass
                if self.warm_scrcpy_processes.get(serial) is candidate:
                    self.warm_scrcpy_processes.pop(serial, None)
                    self.warm_scrcpy_windows.pop(serial, None)
                self.warm_scrcpy_starting_serials.discard(serial)
                self.warm_scrcpy_starting = bool(self.warm_scrcpy_starting_serials)
                self._retry_warm_live_view(serial)
                if self.warm_scrcpy_queue:
                    self.after(120, self._start_next_warm_live_view)
                return
            # A reserva nasce com SW_HIDE para nunca aparecer na barra de
            # tarefas; portanto também precisa ser encontrada ainda oculta.
            hwnd = self._window_for_process(candidate.pid, include_hidden=True)
            # Alguns aparelhos terminam a instalação do servidor antes de
            # criar a primeira janela SDL. Não encerre uma reserva saudável
            # cedo demais: isso era justamente o que fazia o celular já
            # selecionado só aparecer depois, ao abrir a grade.
            if not hwnd and attempt < 180:
                self.after(160, lambda: finish(candidate, attempt + 1)); return
            if hwnd:
                self.warm_scrcpy_windows[serial] = hwnd
                self.warm_scrcpy_retry_attempts.pop(serial, None)
                try:
                    user32 = ctypes.windll.user32
                    # A reserva continua sendo uma janela do Iggents: não
                    # recebe botão próprio na barra de tarefas e não rouba
                    # foco enquanto fica fora da área de prévia.
                    user32.SetWindowLongPtrW(wintypes.HWND(hwnd), -8, wintypes.HWND(self.winfo_id()))
                    style = int(user32.GetWindowLongPtrW(wintypes.HWND(hwnd), -20))
                    user32.SetWindowLongPtrW(wintypes.HWND(hwnd), -20, style | 0x80 | 0x08000000)
                    user32.SetWindowPos(wintypes.HWND(hwnd), 0, -32000, -32000, 2, 2, 0x0010 | 0x0040)
                except (AttributeError, OSError):
                    pass
                # Na abertura, todos os celulares terminam primeiro a própria
                # reserva. O selecionado não recebe um caminho especial nem
                # tenta encaixar cedo: a barreira final o chamará pelo mesmo
                # caminho usado por qualquer clique posterior na lista.
                if (not self.device_visual_pool_loading
                        and getattr(self, "app_view_var", None)
                        and self.app_view_var.get() == "fluxo"):
                    selected = self.selected_profiles()
                    if (len(selected) == 1 and selected[0].get("state") == "device"
                            and str(selected[0].get("serial", "")) == serial):
                        self.after(0, lambda target=serial:
                                   self._start_live_view_when_preview_ready(target))
            else:
                # Não encerre uma sessão viva só porque o Windows ainda não a
                # enumerou como SDL_app. Em alguns aparelhos a janela aparece
                # mais tarde; matar o processo aqui era a origem do celular
                # que "sumia" da prévia e só voltava ao abrir Celulares.
                # Mantemos a reserva e deixamos a sondagem normal encontrá-la
                # quando for solicitada, sem criar uma cópia do mesmo serial.
                self._recover_warm_live_view(serial, candidate)
                return
            self.warm_scrcpy_starting_serials.discard(serial)
            self.warm_scrcpy_starting = bool(self.warm_scrcpy_starting_serials)
            if self.warm_scrcpy_queue:
                self.after(0, self._start_next_warm_live_view)
        self.after(160, finish)

    def _release_warm_launch_slot(self, serial: str) -> None:
        self.warm_scrcpy_starting_serials.discard(serial)
        self.warm_scrcpy_starting = bool(self.warm_scrcpy_starting_serials)
        self._start_next_warm_live_view()

    def _warm_scrcpy_process_started(self, serial: str, process: subprocess.Popen | None, error: OSError | None) -> None:
        """Accept a worker-created process and wait for its PID-owned SDL."""
        if error is not None or process is None:
            self._trace_scrcpy_recovery(serial, f"falhou ao criar: {error}")
            self._release_warm_launch_slot(serial)
            self._retry_warm_live_view(serial)
            return
        current = self.warm_scrcpy_processes.get(serial)
        if current is not None and current.poll() is None:
            self._trace_scrcpy_recovery(serial, f"novo PID {process.pid} encerrado; reserva {current.pid} já existe")
            self._release_warm_launch_slot(serial)
            try:
                process.terminate()
            except OSError:
                pass
            return
        self.warm_scrcpy_processes[serial] = process
        self._trace_scrcpy_recovery(serial, f"PID {process.pid} aceito")
        # Só libera o próximo celular quando esta instância realmente criou a
        # sua janela SDL. Abrir duas inicializações de vídeo ao mesmo tempo
        # fazia a segunda (com frequência a previamente selecionada) cair antes
        # de formar a textura.

        def watch(attempt: int = 0) -> None:
            if self.warm_scrcpy_processes.get(serial) is not process:
                return
            if process.poll() is not None:
                self._trace_scrcpy_recovery(serial, f"PID {process.pid} encerrou, código {process.returncode}")
                self.warm_scrcpy_processes.pop(serial, None)
                self.warm_scrcpy_windows.pop(serial, None)
                self._release_warm_launch_slot(serial)
                self._retry_warm_live_view(serial)
                return
            hwnd = self._window_for_process(process.pid, include_hidden=True)
            if not hwnd:
                if attempt < 180:
                    self.after(160, lambda: watch(attempt + 1))
                else:
                    self._release_warm_launch_slot(serial)
                    self._recover_warm_live_view(serial, process)
                return
            self.warm_scrcpy_windows[serial] = hwnd
            self.warm_scrcpy_retry_attempts.pop(serial, None)
            self._trace_scrcpy_recovery(serial, f"PID {process.pid} pronto")
            self._release_warm_launch_slot(serial)
            try:
                user32 = ctypes.windll.user32
                user32.SetWindowLongPtrW(wintypes.HWND(hwnd), -8, wintypes.HWND(self.winfo_id()))
                style = int(user32.GetWindowLongPtrW(wintypes.HWND(hwnd), -20))
                user32.SetWindowLongPtrW(wintypes.HWND(hwnd), -20, style | 0x80 | 0x08000000)
                user32.SetWindowPos(wintypes.HWND(hwnd), 0, -32000, -32000, 2, 2, 0x0010 | 0x0040)
            except (AttributeError, OSError):
                pass
            # Uma reconexão pode levar mais tempo que a primeira tentativa da
            # grade. Assim que a janela SDL finalmente existe, entregue a mesma
            # reserva diretamente ao cartão atual; antes ela só era encaixada
            # ao abrir a prévia do Fluxo ou trocar de aba.
            if (getattr(self, "app_view_var", None) and self.app_view_var.get() == "celulares"
                    and serial in self.device_grid_hosts):
                self.grid_scrcpy_processes[serial] = process
                session = self.grid_view_session
                self.after(0, lambda target=serial, pid=process.pid, token=session:
                           self._place_grid_live_view(target, pid, token))

        self.after(160, watch)

    def _recover_warm_live_view(self, serial: str, process: subprocess.Popen) -> None:
        """Discard and restart only a reservation whose PID never got SDL."""
        if self.warm_scrcpy_processes.get(serial) is not process:
            return
        self.warm_scrcpy_processes.pop(serial, None)
        self.warm_scrcpy_windows.pop(serial, None)
        try:
            if process.poll() is None:
                process.terminate()
        except OSError:
            pass
        self._retry_warm_live_view(serial)

    def _stop_warm_live_views(self) -> None:
        processes = list(self.warm_scrcpy_processes.values())
        self.warm_scrcpy_processes.clear()
        self.warm_scrcpy_windows.clear(); self.warm_scrcpy_queue.clear(); self.warm_scrcpy_starting = False
        self.warm_scrcpy_starting_serials.clear()
        self.warm_scrcpy_retry_attempts.clear()
        self.warm_scrcpy_retry_pending.clear()
        for process in processes:
            if process is self.scrcpy_process or process.poll() is not None:
                continue
            try:
                process.terminate()
            except OSError:
                pass

    def start_live_view(self, preferred_serial: str | None = None, coordinate_edit: bool = False,
                        reservation_attempt: int = 0) -> None:
        """Abre o scrcpy encaixado dentro da área fixa da prévia."""
        profiles = self.selected_profiles()
        serial = str(preferred_serial or "")
        if not serial:
            serial = str(profiles[0].get("serial", "")) if len(profiles) == 1 else str(self.adb.serial or "")
        if not serial:
            messagebox.showwarning("Visualização ao vivo", "Selecione um único telefone conectado.", parent=self)
            return
        # Chamadas atrasadas são normais enquanto uma reserva cria a janela
        # SDL. Elas só podem encaixar a tela que continua selecionada no
        # Fluxo. Sem essa trava, uma tentativa antiga voltava depois de a
        # pessoa trocar de telefone — e podia parar/ocultar a prévia nova ou
        # até iniciar a tela antiga ao entrar em Celulares.
        if not coordinate_edit and getattr(self, "app_view_var", None):
            if self.app_view_var.get() != "fluxo":
                return
            selected_serial = (
                str(profiles[0].get("serial", ""))
                if len(profiles) == 1 and profiles[0].get("state") == "device"
                else ""
            )
            if selected_serial and selected_serial != serial:
                return
        executable = APP_DIR / "tools" / "scrcpy" / "scrcpy-win64-v4.1" / "scrcpy.exe"
        if not executable.exists():
            messagebox.showerror("Visualização ao vivo", "O scrcpy não foi encontrado na pasta tools.", parent=self)
            return
        # Vários caminhos da interface pedem para garantir a tela ao vivo
        # (troca de seleção, painel, janela XML, atualização de aparelhos).
        # Se já é o mesmo telefone, reaproveite o scrcpy atual: reiniciá-lo
        # aqui causava piscadas, atraso e a janela aparecendo no centro.
        current_process = self.scrcpy_process
        if (self.live_view_mode and str(self.scrcpy_serial) == serial
                and current_process is not None and current_process.poll() is None
                and self._scrcpy_process_matches_serial(current_process, serial)):
            self.live_view_edit_mode = bool(coordinate_edit)
            # O canvas é reconstruído ao abrir o programa e ao trocar de
            # painel. A sessão do telefone já selecionado pode existir, mas
            # sua janela ainda estar fora da tela. Reencontre-a pelo PID e
            # encaixe-a novamente em vez de apenas tentar redimensionar uma
            # posição que pertencia ao canvas anterior.
            hwnd = int(self.scrcpy_window_handle or 0)
            if not self._window_belongs_to_process(hwnd, current_process.pid):
                hwnd = self._window_for_process(current_process.pid, include_hidden=True)
            if hwnd:
                self.scrcpy_window_handle = hwnd
                if self.live_view_uses_warm_pool:
                    self.warm_scrcpy_processes[serial] = current_process
                    self.warm_scrcpy_windows[serial] = hwnd
                session = self.live_view_session
                self.after(0, lambda token=session: self._embed_live_view(0, token))
            self._resize_embedded_live_view(force=True)
            self._update_live_touch_marker()
            return
        if current_process and current_process.poll() is None:
            self.stop_live_view()
        try:
            self.live_view_session += 1
            session = self.live_view_session
            warmed = self.warm_scrcpy_processes.get(serial)
            if warmed and not self._scrcpy_process_matches_serial(warmed, serial):
                # Nunca transforme um processo de outro telefone em reserva do
                # selecionado. Remover só a associação errada preserva o
                # processo verdadeiro no serial ao qual ele pertence.
                if self.warm_scrcpy_processes.get(serial) is warmed:
                    self.warm_scrcpy_processes.pop(serial, None)
                    self.warm_scrcpy_windows.pop(serial, None)
                warmed = None
            warm_hwnd = int(self.warm_scrcpy_windows.get(serial, 0) or 0)
            if warmed and warm_hwnd and not self._window_belongs_to_process(warm_hwnd, warmed.pid):
                self.warm_scrcpy_windows.pop(serial, None)
                warm_hwnd = 0
            if warmed and warmed.poll() is None:
                warm_hwnd = warm_hwnd or self._window_for_process(warmed.pid, include_hidden=True)
                if not warm_hwnd:
                    # A reserva já existe; aguarde-a terminar de criar SDL em
                    # vez de iniciar um segundo scrcpy ao trocar a seleção.
                    if reservation_attempt < 240:
                        self.after(100, lambda target=serial, count=reservation_attempt + 1:
                                   self.start_live_view(target, reservation_attempt=count))
                    else:
                        # A reserva continua viva. Não a encerre por um tempo
                        # limite da prévia: isso fazia justamente o celular
                        # inicial variar a cada abertura, pois a sua tentativa
                        # atrasada matava o único scrcpy daquele serial.
                        self.after(250, lambda target=serial:
                                   self.start_live_view(target, reservation_attempt=0))
                    return
                else:
                    self.warm_scrcpy_windows[serial] = warm_hwnd
                    self.scrcpy_process = warmed
                    self.scrcpy_window_handle = warm_hwnd
                    self.scrcpy_serial = serial
                    self.live_view_mode = True
                    self.live_view_edit_mode = bool(coordinate_edit)
                    self.live_view_uses_warm_pool = True
                    self.scrcpy_window_title = f"iggents pronto {serial}"
                    self.preview_session += 1
                    # Usa o mesmo encaixe completo da prévia recém-aberta. Isso
                    # reaplica dono, camada e tamanho antes de exibir a reserva.
                    self.after(0, lambda token=session: self._embed_live_view(0, token))
                    self.after(80, lambda: self._resize_embedded_live_view(force=True))
                    self.status.set(f"Visualização pronta para {serial}.")
                    return
            if (serial in self.warm_scrcpy_queue
                    or serial in self.warm_scrcpy_starting_serials
                    or serial in self.warm_scrcpy_retry_pending):
                # O serial já está reservado para a pré-carga, só ainda não
                # recebeu PID. Selecioná-lo não pode criar uma cópia.
                if reservation_attempt < 240:
                    self.after(100, lambda target=serial, count=reservation_attempt + 1:
                                   self.start_live_view(target, reservation_attempt=count))
                return
            # The preview never has a private creation path.  Request the
            # same per-serial reservation used by startup and the grid, then
            # wait for its PID-owned SDL window (also in coordinate mode).
            self._queue_warm_live_view(serial)
            self.after(100, lambda target=serial, count=reservation_attempt + 1:
                       self.start_live_view(target, coordinate_edit=coordinate_edit,
                                            reservation_attempt=count))
            return
            flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
            self.live_view_uses_warm_pool = False
            self.scrcpy_window_title = f"iggents — {serial}"
            self.scrcpy_serial = serial
            # O scrcpy cria a janela antes de o Tk ter chance de encaixá-la.
            # Ela nasce fora da área visível e só aparece depois de o canvas
            # de prévia estar pronto, evitando o salto para o centro da tela.
            command = [str(executable), "--serial", serial, "--window-title", self.scrcpy_window_title,
                       "--window-borderless", "--window-x", "-32000", "--window-y", "-32000", "--no-audio",
                       "--max-size=540", "--max-fps=20", "--video-bit-rate=2M", "--render-driver=opengl"]
            if coordinate_edit:
                command.append("--no-control")
            self.scrcpy_process = subprocess.Popen(
                command,
                cwd=str(executable.parent), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                creationflags=flags,
                startupinfo=self._hidden_scrcpy_startupinfo(),
            )
            if not coordinate_edit:
                # A primeira prévia também passa a ser a reserva deste
                # celular, para a troca posterior ao painel Celulares não
                # iniciar outra conexão.
                self.warm_scrcpy_processes[serial] = self.scrcpy_process
                self.live_view_uses_warm_pool = True
            self.live_view_mode = True
            self.live_view_edit_mode = coordinate_edit
            # A janela do scrcpy preserva a proporção do telefone e pode deixar
            # barras laterais/superior-inferior dentro do quadro da prévia.
            # Carrega o tamanho real desde o início para o mapa de toques não
            # depender da resolução do aparelho exibido anteriormente.
            if serial not in self.device_calibrations:
                def load_live_screen() -> None:
                    try:
                        adb = Adb(); adb.path, adb.serial = self.adb.path, serial
                        self.events.put(("live_screen_size", (session, serial, adb.screen_size(timeout=8))))
                    except (OSError, RuntimeError):
                        pass
                self._thread(load_live_screen)
            if getattr(self, "preview_edit_button", None):
                self.preview_edit_button.configure(text="Editar na prévia")
            self.preview_session += 1
            if getattr(self, "preview_edit_button", None):
                self.preview_edit_button.configure(text="Voltar ao controle" if coordinate_edit else "Editar toque / arrasto")
            self.preview_photo = None
            self.preview_context = None
            self._set_preview_message("Iniciando visualização\nao vivo…")
            # O SDL do scrcpy cria a janela alguns instantes depois do processo.
            # Reencaixamos mais de uma vez: a primeira posição padrão do
            # scrcpy é o centro da tela e não pode permanecer visível ali.
            for delay in (80, 260, 700, 1400):
                self.after(delay, lambda token=session: self._embed_live_view(0, token))
            self.after(1200, lambda token=session: self._check_live_view_started(token))
            self.status.set(f"Visualização ao vivo iniciada para {serial}.")
        except OSError as error:
            messagebox.showerror("Visualização ao vivo", f"Não foi possível iniciar o scrcpy: {error}", parent=self)

    def _start_live_view_when_preview_ready(self, serial: str, attempt: int = 0) -> None:
        """Inicia a prévia somente quando o quadro correto já foi exibido."""
        if not getattr(self, "app_view_var", None) or self.app_view_var.get() != "fluxo":
            return
        chosen = self.selected_profiles()
        if len(chosen) != 1 or str(chosen[0].get("serial", "")) != str(serial):
            return
        if not hasattr(self, "preview_canvas") or not self.preview_canvas.winfo_ismapped():
            if attempt < 30:
                self.after(80, lambda: self._start_live_view_when_preview_ready(serial, attempt + 1))
            return
        if self.preview_canvas.winfo_width() < 50 or self.preview_canvas.winfo_height() < 50:
            if attempt < 30:
                self.after(80, lambda: self._start_live_view_when_preview_ready(serial, attempt + 1))
            return
        process = self.scrcpy_process
        keep_warm = bool(self.live_view_uses_warm_pool)
        if (self.live_view_mode and self.scrcpy_serial == serial
                and process is not None and process.poll() is None
                and self._scrcpy_process_matches_serial(process, serial)):
            # Na abertura inicial o telefone restaurado pode já ter o processo
            # vivo, porém o canvas acabou de ser recriado. Reencaixá-lo aqui é
            # essencial: só redimensionar preservava a posição fora da tela.
            hwnd = int(self.scrcpy_window_handle or 0)
            if not self._window_belongs_to_process(hwnd, process.pid):
                hwnd = self._window_for_process(process.pid, include_hidden=True)
            if hwnd:
                self.scrcpy_window_handle = hwnd
                if self.live_view_uses_warm_pool:
                    self.warm_scrcpy_processes[serial] = process
                    self.warm_scrcpy_windows[serial] = hwnd
                session = self.live_view_session
                self.after(0, lambda token=session: self._embed_live_view(0, token))
            self._resize_embedded_live_view(force=True)
            # Trocar apenas o painel não exige criar outro scrcpy. Atualiza a
            # máscara imediatamente sobre o vídeo que já está em tempo real.
            self._update_live_touch_marker()
            return
        self.start_live_view(serial)

    def stop_live_view(self) -> None:
        self.live_view_session += 1
        process = self.scrcpy_process
        window_handle = int(self.scrcpy_window_handle or 0)
        keep_warm = bool(self.live_view_uses_warm_pool)
        # Uma janela reservada continua pertencendo ao Iggents, apenas sai da
        # área visível da prévia. As demais são encerradas normalmente.
        if window_handle and keep_warm:
            try:
                ctypes.windll.user32.SetWindowPos(
                    wintypes.HWND(window_handle), 0, -32000, -32000, 2, 2, 0x0010 | 0x0040
                )
            except (AttributeError, OSError):
                pass
        elif window_handle:
            try:
                ctypes.windll.user32.ShowWindow(window_handle, 0)
            except (AttributeError, OSError):
                pass
        self.live_view_mode = False
        self.live_view_edit_mode = False
        self._live_ctrl_record_start = None
        self._live_ctrl_record_mouse_down = False
        self._set_scrcpy_alt_passthrough(False)
        self._hide_live_touch_marker()
        self._live_marker_in_foreground = False
        self.scrcpy_process = None
        self.scrcpy_window_handle = 0
        self.scrcpy_window_title = ""
        self.scrcpy_window_bounds = None
        self.scrcpy_client_bounds = None
        self.scrcpy_serial = ""
        self.live_view_uses_warm_pool = False
        if keep_warm:
            self.status.set("Visualização ao vivo devolvida à pré-carga.")
            return
        if process is None or process.poll() is not None:
            self.status.set("Nenhuma visualização ao vivo estava ativa.")
            return
        try:
            process.terminate()
        except OSError:
            pass
        # Não aguarde o SDL encerrar aqui: trocar de celular ou abrir a grade
        # precisa devolver o controle à interface imediatamente.
        try:
            subprocess.Popen(["taskkill", "/PID", str(process.pid), "/T", "/F"],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                             creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        except OSError:
            pass
        self.status.set("Visualização ao vivo encerrada.")

    def _embed_live_view(self, attempt: int = 0, session: int | None = None) -> None:
        """Posiciona a janela do scrcpy sobre o quadro de prévia.

        Reparentear a janela SDL como filha do Tk torna o scrcpy instável em
        alguns Windows. O próprio scrcpy cria uma janela sem moldura; aqui só
        posicionamos essa janela sobre o canvas, sem alterar seu estilo.
        """
        if session is not None and session != self.live_view_session:
            return
        process = self.scrcpy_process
        if not process or process.poll() is not None or not self.live_view_mode:
            return
        try:
            user32 = ctypes.windll.user32
            # A prévia recém-criada ainda está oculta até receber sua posição
            # no canvas. Procurar só janelas visíveis a deixava presa para
            # sempre em “Iniciando visualização”.
            hwnd = self._window_for_process(process.pid, include_hidden=True)
            if not hwnd:
                if attempt < 35:
                    self.after(80, lambda: self._embed_live_view(attempt + 1, session))
                return
            self.scrcpy_window_handle = hwnd
            if self.live_view_uses_warm_pool:
                self.warm_scrcpy_windows[self.scrcpy_serial] = hwnd
            # É uma janela pertencente ao iggents, não uma janela independente:
            # por isso não ganha ícone próprio na barra de tarefas, mas continua
            # sendo SDL/top-level e não perde o vídeo como ocorria com SetParent.
            user32.SetWindowLongPtrW(wintypes.HWND(hwnd), -8, wintypes.HWND(self.winfo_id()))  # GWL_HWNDPARENT (owner)
            style = int(user32.GetWindowLongPtrW(wintypes.HWND(hwnd), -20))
            user32.SetWindowLongPtrW(wintypes.HWND(hwnd), -20, style | 0x08000000)  # WS_EX_NOACTIVATE
            # Não revele a janela até o canvas existir de fato. Sem isso, em
            # trocas rápidas de painel ela pode permanecer no centro do desktop.
            if (not self.preview_canvas.winfo_ismapped()
                    or self.preview_canvas.winfo_width() < 50
                    or self.preview_canvas.winfo_height() < 50):
                if attempt < 35:
                    self.after(80, lambda: self._embed_live_view(attempt + 1, session))
                return
            for delay in (0, 120, 450):
                self.after(delay, lambda force=True: self._resize_embedded_live_view(force=force))
            self.status.set("Visualização ao vivo fixada na prévia.")
        except (AttributeError, OSError, tk.TclError):
            if attempt < 35:
                self.after(80, lambda: self._embed_live_view(attempt + 1, session))

    @staticmethod
    def _window_for_process(process_id: int, include_hidden: bool = False) -> int:
        """Encontra a janela principal do scrcpy pelo PID, não pelo título.

        Com ``--window-borderless`` alguns SDL/Windows não expõem o título
        para ``FindWindowW``. O PID é estável e identifica a janela certa.
        """
        try:
            user32 = ctypes.windll.user32
            found = ctypes.c_void_p()
            callback_type = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)

            @callback_type
            def visit(hwnd, _lparam):
                owner_pid = ctypes.c_ulong()
                user32.GetWindowThreadProcessId(hwnd, ctypes.byref(owner_pid))
                # O scrcpy pode criar janelas auxiliares do IME no mesmo PID.
                # Apenas a SDL_app contém o vídeo; a IME aparecia primeiro e
                # era encaixada no cartão em vez da tela do telefone.
                class_name = ctypes.create_unicode_buffer(128)
                user32.GetClassNameW(wintypes.HWND(hwnd), class_name, len(class_name))
                if (owner_pid.value == process_id and class_name.value == "SDL_app"
                        and (include_hidden or user32.IsWindowVisible(hwnd))):
                    found.value = hwnd
                    return False
                return True

            user32.EnumWindows(visit, 0)
            return int(found.value or 0)
        except (AttributeError, OSError):
            return 0

    @staticmethod
    def _window_belongs_to_process(hwnd: int, process_id: int) -> bool:
        """Confirma o PID de um HWND antes de reutilizá-lo em um cartão."""
        try:
            owner_pid = ctypes.c_ulong()
            ctypes.windll.user32.GetWindowThreadProcessId(
                wintypes.HWND(hwnd), ctypes.byref(owner_pid)
            )
            return int(owner_pid.value) == int(process_id)
        except (AttributeError, OSError):
            return False

    @staticmethod
    def _scrcpy_process_matches_serial(process: subprocess.Popen | None, serial: str) -> bool:
        """Confirma o serial real passado ao scrcpy antes de reaproveitá-lo.

        ``scrcpy_serial`` representa a prévia solicitada e pode ficar defasado
        durante uma troca rápida. O comando do processo, por outro lado, é a
        identidade imutável da sessão. Sem esta confirmação uma reserva de um
        celular podia ser registrada sob o serial do selecionado e deixá-lo sem
        processo próprio.
        """
        if process is None or not serial:
            return False
        try:
            args = process.args
            values = list(args) if isinstance(args, (list, tuple)) else str(args).split()
            expected = str(serial)
            if f"--serial={expected}" in values:
                return True
            index = values.index("--serial")
            return index + 1 < len(values) and str(values[index + 1]) == expected
        except (AttributeError, ValueError, TypeError):
            return False

    def _check_live_view_started(self, session: int | None = None) -> None:
        if session is not None and session != self.live_view_session:
            return
        process = self.scrcpy_process
        if not process or process.poll() is None or not self.live_view_mode:
            return
        self.scrcpy_process = None
        self.scrcpy_window_handle = 0
        self.scrcpy_window_bounds = None
        self.scrcpy_client_bounds = None
        self.scrcpy_serial = ""
        self._set_preview_message("A visualização ao vivo\nfoi encerrada pelo scrcpy")
        self.status.set("A visualização ao vivo não permaneceu aberta. Verifique o telefone e a autorização ADB.")

    def _resize_embedded_live_view(self, _event=None, force: bool = False) -> None:
        """Mantém a visualização viva exatamente do tamanho do canvas."""
        hwnd = int(getattr(self, "scrcpy_window_handle", 0) or 0)
        if not hwnd or not hasattr(self, "preview_canvas"):
            return
        if self._live_views_hidden_by_minimize or self.state() == "iconic":
            try:
                ctypes.windll.user32.ShowWindow(wintypes.HWND(hwnd), 0)
            except (AttributeError, OSError):
                pass
            return
        try:
            width = self.preview_canvas.winfo_width()
            height = self.preview_canvas.winfo_height()
            # Durante a construção/redimensionamento o Tk informa 1×1 por um
            # instante. Nunca encolha o renderizador do scrcpy a esse valor.
            if width < 50 or height < 50:
                return
            left = self.preview_canvas.winfo_rootx()
            top = self.preview_canvas.winfo_rooty()
            bounds = (left, top, width, height)
            if bounds == self.scrcpy_window_bounds and not force:
                return
            self.scrcpy_window_bounds = bounds
            # SWP_NOACTIVATE | SWP_SHOWWINDOW | SWP_FRAMECHANGED. A janela
            # fica sempre sobre o canvas, não sobre os controles abaixo dele.
            z_order = 1 if self._visible_user_popup_open() else 0  # HWND_BOTTOM / HWND_TOP
            ctypes.windll.user32.SetWindowPos(
                wintypes.HWND(hwnd), wintypes.HWND(z_order), left, top, width, height, 0x0010 | 0x0040
            )
            # Não use o retângulo pedido acima para mapear o mouse. Em alguns
            # monitores/DPIs ele difere da área cliente que o SDL efetivamente
            # desenha. Fazemos a medição depois de o Windows confirmar o resize.
            self.scrcpy_client_bounds = None
            self.after(0, self._sync_live_view_client_bounds)
            self.after(90, self._sync_live_view_client_bounds)
            self._update_live_touch_marker()
            # SetWindowPos do SDL Ã© assÃ­ncrono em alguns aparelhos. Esta
            # confirmaÃ§Ã£o curta mantÃ©m a camada da etapa acima do vÃ­deo ao
            # terminar a troca de celular ou o redimensionamento da prÃ©via.
            self.after(55, self._update_live_touch_marker)
        except (AttributeError, OSError, tk.TclError):
            self.scrcpy_window_handle = 0

    def _sync_live_view_client_bounds(self) -> None:
        """Lê a área de vídeo real do scrcpy em coordenadas físicas da tela.

        ``GetCursorPos`` também usa pixels físicos. Usar ``winfo_rooty``
        (unidades Tk) junto com ele fazia um clique salvo logo abaixo do ponto
        escolhido em certos reinícios/reconexões e escalas de monitor.
        """
        hwnd = int(getattr(self, "scrcpy_window_handle", 0) or 0)
        if not hwnd or not self.live_view_mode:
            return
        try:
            user32 = ctypes.windll.user32
            rect = wintypes.RECT()
            origin = wintypes.POINT(0, 0)
            handle = wintypes.HWND(hwnd)
            if not user32.GetClientRect(handle, ctypes.byref(rect)):
                return
            if not user32.ClientToScreen(handle, ctypes.byref(origin)):
                return
            width, height = int(rect.right - rect.left), int(rect.bottom - rect.top)
            if width < 50 or height < 50:
                return
            self.scrcpy_client_bounds = (int(origin.x), int(origin.y), width, height)
            self._update_live_touch_marker()
        except (AttributeError, OSError, tk.TclError):
            pass

    def _selected_touch_action(self, tree_item: str | None = None) -> Action | None:
        selected = self.tree.selection() if hasattr(self, "tree") else ()
        item = tree_item or (selected[0] if len(selected) == 1 else self.running_tree_item)
        if not item:
            return None
        location = self._tree_action_container(item)
        if location is None:
            return None
        _group, actions, index = location
        if not 0 <= index < len(actions):
            return None
        action = actions[index]
        return action if action.kind in ("tap", "swipe") else None

    def _flow_live_view_is_current_editor(self) -> bool:
        """Confirma que Ctrl/Alt pertencem Ã  lista ativa do Fluxo."""
        if not getattr(self, "app_view_var", None) or self.app_view_var.get() != "fluxo":
            return False
        selected = self.selected_profiles()
        return bool(
            len(selected) == 1
            and selected[0].get("state") == "device"
            and str(selected[0].get("serial", "")) == str(self.scrcpy_serial)
        )

    def _live_content_bounds(self, bounds: tuple[int, int, int, int] | None = None,
                             screen: tuple[int, int] | None = None) -> tuple[int, int, int, int, int, int] | None:
        """Área útil do telefone dentro da janela do scrcpy.

        O scrcpy mantém a proporção original, enquanto o quadro do iggents é
        livre. Portanto, a imagem do celular não ocupa necessariamente toda a
        janela: usar a janela inteira deslocava os toques, principalmente no
        eixo Y, após trocar/reabrir aparelhos de resoluções diferentes.
        """
        # Quando disponível, a área cliente medida vence o tamanho solicitado
        # ao scrcpy. Chamadores antigos ainda passam ``scrcpy_window_bounds``;
        # tratamos isso como pedido para usar a área medida.
        if bounds is None or bounds == self.scrcpy_window_bounds:
            bounds = self.scrcpy_client_bounds or self.scrcpy_window_bounds
        if not bounds:
            return None
        left, top, width, height = bounds
        cached = self.device_calibrations.get(str(self.scrcpy_serial))
        screen_w, screen_h = screen or (cached[0] if cached else self.screen)
        try:
            screen_w, screen_h = int(screen_w), int(screen_h)
        except (TypeError, ValueError):
            return None
        if min(width, height, screen_w, screen_h) <= 0:
            return None
        scale = min(width / screen_w, height / screen_h)
        image_w, image_h = max(1, round(screen_w * scale)), max(1, round(screen_h * scale))
        return (left + (width - image_w) // 2, top + (height - image_h) // 2,
                image_w, image_h, screen_w, screen_h)

    def _ensure_live_marker(self) -> tk.Canvas | None:
        if self.live_marker_window and self.live_marker_window.winfo_exists() and self.live_marker_canvas:
            return self.live_marker_canvas
        try:
            overlay = tk.Toplevel(self)
            overlay.withdraw(); overlay.overrideredirect(True)
            overlay.configure(bg="#010203")
            overlay.wm_attributes("-transparentcolor", "#010203")
            overlay.wm_attributes("-topmost", True)
            canvas = tk.Canvas(overlay, bg="#010203", highlightthickness=0, borderwidth=0)
            canvas.pack(fill="both", expand=True)
            # Normalmente a máscara é só visual. No seletor de XML ela passa
            # a receber o clique, para que o scrcpy nunca o envie ao telefone.
            canvas.bind("<Button-1>", self._handle_live_xml_picker_click, add="+")
            overlay.update_idletasks()
            hwnd = wintypes.HWND(overlay.winfo_id())
            user32 = ctypes.windll.user32
            style = user32.GetWindowLongPtrW(hwnd, -20)
            user32.SetWindowLongPtrW(hwnd, -20, style | 0x20 | 0x08000000)  # transparente ao mouse / sem foco
            self.live_marker_window, self.live_marker_canvas = overlay, canvas
            return canvas
        except (AttributeError, OSError, tk.TclError):
            self.live_marker_window = None; self.live_marker_canvas = None
            return None

    def _hide_live_touch_marker(self) -> None:
        if self.live_marker_window and self.live_marker_window.winfo_exists():
            self.live_marker_window.withdraw()

    def _set_live_marker_mouse_intercept(self, enabled: bool) -> None:
        """Faz a máscara capturar o clique somente durante a escolha de XML."""
        if not self.live_marker_window or not self.live_marker_window.winfo_exists():
            return
        try:
            user32 = ctypes.windll.user32
            overlay = self.live_marker_window
            canvas = self.live_marker_canvas
            # ``-transparentcolor`` cria buracos também para o mouse no Windows.
            # Assim, embora a borda fosse visível, o clique no centro ainda
            # atravessava a máscara e chegava ao scrcpy. Durante a escolha XML
            # usamos uma película quase invisível, porém sólida, que recebe o
            # mouse; ao finalizar, voltamos à máscara totalmente transparente.
            if enabled:
                overlay.wm_attributes("-transparentcolor", "")
                overlay.wm_attributes("-alpha", 0.02)
                if canvas:
                    canvas.configure(bg="#010204")
            else:
                overlay.wm_attributes("-alpha", 1.0)
                overlay.wm_attributes("-transparentcolor", "#010203")
                if canvas:
                    canvas.configure(bg="#010203")
            hwnd = wintypes.HWND(overlay.winfo_id())
            style = int(user32.GetWindowLongPtrW(hwnd, -20))
            updated = (style & ~0x20) if enabled else (style | 0x20)
            if updated != style:
                user32.SetWindowLongPtrW(hwnd, -20, updated)
        except (AttributeError, OSError, tk.TclError):
            pass

    def _finish_live_xml_picker(self, point) -> bool:
        """Resolve a escolha XML sem permitir que o clique alcance o aparelho."""
        picker = self.live_xml_picker
        if not picker or not self.live_view_mode or str(picker.get("serial", "")) != str(self.scrcpy_serial):
            return False
        bounds = self.scrcpy_window_bounds
        if not bounds:
            return False
        device_point = self._live_view_point_to_device(point, bounds)
        if device_point is None:
            return False
        x, y = device_point
        matches: list[tuple[int, dict[str, str]]] = []
        for attrs in picker.get("elements", []):
            values = list(map(int, re.findall(r"\d+", attrs.get("bounds", ""))))
            if len(values) == 4 and values[0] <= x <= values[2] and values[1] <= y <= values[3]:
                matches.append(((values[2] - values[0]) * (values[3] - values[1]), attrs))
        callback = picker.get("callback")
        self.live_xml_picker = None
        self._set_live_marker_mouse_intercept(False)
        self._set_scrcpy_alt_passthrough(False)
        self._hide_live_touch_marker()
        self.status.set(f"{len(matches)} elemento(s) XML encontrado(s) no ponto escolhido.")
        if callable(callback):
            values = [attrs for _area, attrs in sorted(matches, key=lambda item: item[0])]
            self.after(0, lambda: callback(values))
        return True

    def _handle_live_xml_picker_click(self, event) -> str | None:
        """Recebe o clique da máscara (antes do scrcpy) no modo de escolha."""
        point = wintypes.POINT(int(event.x_root), int(event.y_root))
        if self._finish_live_xml_picker(point):
            return "break"
        return None

    def _live_view_has_foreground(self) -> bool:
        """A máscara só pertence ao iggents (ou ao scrcpy encaixado nele)."""
        try:
            user32 = ctypes.windll.user32
            foreground = int(user32.GetForegroundWindow() or 0)
            if not foreground:
                return False
            # Pop-ups do Tk possuem outra janela-raiz. Enquanto um popup de
            # XML está aberto, ele ainda pertence ao processo do iggents e a
            # máscara deve continuar visível sobre a tela ao vivo.
            foreground_pid = ctypes.c_ulong()
            user32.GetWindowThreadProcessId(wintypes.HWND(foreground), ctypes.byref(foreground_pid))
            if foreground_pid.value == os.getpid():
                return True
            app_root = int(user32.GetAncestor(wintypes.HWND(self.winfo_id()), 2) or self.winfo_id())
            scrcpy = int(self.scrcpy_window_handle or 0)
            if foreground in (app_root, scrcpy):
                return True
            return int(user32.GetAncestor(wintypes.HWND(foreground), 2) or 0) == app_root
        except (AttributeError, OSError, tk.TclError):
            return False

    def _update_live_touch_marker(self, tree_item: str | None = None) -> None:
        """Desenha uma máscara leve da etapa ativa/selecionada sobre o scrcpy vivo."""
        action = self._selected_touch_action(tree_item)
        bounds = self.scrcpy_client_bounds or self.scrcpy_window_bounds
        xml_bounds = self.live_xml_marker_bounds
        picker_active = bool(self.live_xml_picker and str(self.live_xml_picker.get("serial", "")) == str(self.scrcpy_serial))
        try:
            user32 = ctypes.windll.user32
            modifier_active = bool((user32.GetAsyncKeyState(0x11) | user32.GetAsyncKeyState(0x12)) & 0x8000)
        except (AttributeError, OSError):
            modifier_active = False
        if not self.live_view_mode or not bounds or (action is None and xml_bounds is None and not picker_active and not modifier_active) or not self._live_view_has_foreground():
            self._hide_live_touch_marker(); return
        canvas = self._ensure_live_marker()
        if canvas is None or not self.live_marker_window:
            return
        left, top, width, height = bounds
        try:
            flow = self.flow_var.get()
            recorded_screen = tuple(self.live_xml_marker_source_size or self.macro_devices.get(flow, {}).get("screen", self.screen))
            if len(recorded_screen) != 2:
                recorded_screen = self.screen
            coordinate_screen = (recorded_screen if xml_bounds else
                                 self._action_coordinate_screen(action, recorded_screen, self.macro_devices.get(flow, {}).get("raw_size")))
            content = self._live_content_bounds(bounds)
            if content is None:
                self._hide_live_touch_marker(); return
            image_left, image_top, image_width, image_height, _device_w, _device_h = content
            offset_x, offset_y = image_left - left, image_top - top
            def point(x: int, y: int) -> tuple[int, int]:
                return (offset_x + round(x * max(0, image_width - 1) / max(1, coordinate_screen[0] - 1)),
                        offset_y + round(y * max(0, image_height - 1) / max(1, coordinate_screen[1] - 1)))
            canvas.configure(width=width, height=height)
            canvas.delete("all")
            self._set_live_marker_mouse_intercept(picker_active or modifier_active)
            if picker_active:
                canvas.create_rectangle(2, 2, width - 3, height - 3, outline="#36d399", width=2)
                canvas.create_text(width // 2, 20, text="Clique para escolher o elemento XML",
                                   fill="#36d399", font=("Segoe UI", 10, "bold"))
            if xml_bounds:
                x1, y1 = point(xml_bounds[0], xml_bounds[1])
                x2, y2 = point(xml_bounds[2], xml_bounds[3])
                canvas.create_rectangle(x1, y1, x2, y2, outline="#36d399", width=4)
                canvas.create_rectangle(x1 + 3, y1 + 3, x2 - 3, y2 - 3, outline="#ffd23f", width=1)
                canvas.create_text(x1 + 7, max(12, y1 - 9), text="XML", anchor="w", fill="#36d399",
                                   font=("Segoe UI", 10, "bold"))
            elif action is not None:
                start = point(action.x, action.y)
                if action.kind == "tap":
                    radius = 13
                    canvas.create_oval(start[0] - radius, start[1] - radius, start[0] + radius, start[1] + radius,
                                       outline="#ffd23f", width=3)
                    canvas.create_line(start[0] - 18, start[1], start[0] + 18, start[1], fill="#ff5a78", width=2)
                    canvas.create_line(start[0], start[1] - 18, start[0], start[1] + 18, fill="#ff5a78", width=2)
                else:
                    end = point(action.x2 if action.x2 is not None else action.x, action.y2 if action.y2 is not None else action.y)
                    canvas.create_line(*start, *end, fill="#ffd23f", width=4)
                    for x, y, color in ((*start, "#36d399"), (*end, "#ff5a78")):
                        canvas.create_oval(x - 9, y - 9, x + 9, y + 9, fill=color, outline="#121722", width=2)
            self.live_marker_window.geometry(f"{width}x{height}+{left}+{top}")
            self.live_marker_window.deiconify()
            # ``lift`` sozinho sÃ³ reorganiza janelas Tk. O scrcpy Ã© uma
            # janela SDL/top-level, portanto reafirmamos a mÃ¡scara como
            # topmost sem ativÃ¡-la nem tomar o foco do editor.
            ctypes.windll.user32.SetWindowPos(
                wintypes.HWND(self.live_marker_window.winfo_id()), wintypes.HWND(-1),
                left, top, width, height, 0x0010 | 0x0040,
            )
            self.live_marker_window.lift()
        except (AttributeError, OSError, TypeError, ValueError, tk.TclError):
            self._hide_live_touch_marker()

    def show_live_xml_element(self, attrs: dict[str, str], source_size: tuple[int, int] | None = None) -> None:
        """Destaca na tela ao vivo os limites exatos de um elemento XML."""
        values = tuple(map(int, re.findall(r"\d+", attrs.get("bounds", ""))))
        if len(values) != 4:
            return
        self.live_xml_marker_bounds = values
        self.live_xml_marker_source_size = source_size or tuple(self.screen)
        self._update_live_touch_marker()

    def show_live_xml_bounds(self, bounds: tuple[int, int, int, int], source_size: tuple[int, int]) -> None:
        self.live_xml_marker_bounds = bounds
        self.live_xml_marker_source_size = source_size
        self._update_live_touch_marker()

    def _set_scrcpy_alt_passthrough(self, enabled: bool) -> None:
        """Enquanto Alt está pressionado, o scrcpy não recebe o clique."""
        if enabled == self._live_alt_passthrough:
            return
        hwnd = int(self.scrcpy_window_handle or 0)
        if not hwnd:
            return
        try:
            user32 = ctypes.windll.user32
            handle = wintypes.HWND(hwnd)
            if enabled:
                self._scrcpy_original_exstyle = int(user32.GetWindowLongPtrW(handle, -20))
                user32.SetWindowLongPtrW(handle, -20, self._scrcpy_original_exstyle | 0x20 | 0x08000000)
            elif self._scrcpy_original_exstyle is not None:
                user32.SetWindowLongPtrW(handle, -20, self._scrcpy_original_exstyle)
            self._live_alt_passthrough = enabled
        except (AttributeError, OSError):
            self._live_alt_passthrough = False

    def toggle_preview_editing(self) -> None:
        """Alterna entre a tela ao vivo e a prévia estática clicável."""
        if not self.live_view_mode:
            self.start_live_view()
            return
        # O scrcpy permanece visível. No modo de edição ele é iniciado sem
        # controle do telefone, e o clique reposiciona a etapa selecionada.
        self.status.set("Na tela ao vivo: segure Ctrl para gravar toque/arrasto ou Alt para reposicionar a etapa selecionada.")

    def _live_view_point_to_device(self, point, bounds: tuple[int, int, int, int]) -> tuple[int, int] | None:
        """Converte o cursor na tela ao vivo para a coordenada real do aparelho."""
        cached = self.device_calibrations.get(self.scrcpy_serial)
        if cached:
            screen_w, screen_h = cached[0]
        else:
            adb = Adb(); adb.path, adb.serial = self.adb.path, self.scrcpy_serial
            screen_w, screen_h = adb.screen_size(timeout=3)
            self.device_calibrations[self.scrcpy_serial] = ((screen_w, screen_h), (screen_w, screen_h))
        content = self._live_content_bounds(bounds, (screen_w, screen_h))
        if content is None:
            return None
        left, top, width, height, _screen_w, _screen_h = content
        if not (left <= point.x < left + width and top <= point.y < top + height):
            return None
        return (
            max(0, min(screen_w - 1, round((point.x - left) * (screen_w - 1) / max(1, width - 1)))),
            max(0, min(screen_h - 1, round((point.y - top) * (screen_h - 1) / max(1, height - 1)))),
        )

    def _macro_coordinate_screen(self) -> tuple[int, int]:
        """Retorna a resolução-base imutável da macro atualmente editada."""
        try:
            stored = self.macro_devices.get(self.flow_var.get(), {}).get("screen")
            if isinstance(stored, (list, tuple)) and len(stored) == 2:
                width, height = int(stored[0]), int(stored[1])
                if width > 0 and height > 0:
                    return width, height
        except (AttributeError, TypeError, ValueError):
            pass
        try:
            width, height = int(self.screen[0]), int(self.screen[1])
            if width > 0 and height > 0:
                return width, height
        except (TypeError, ValueError, IndexError):
            pass
        return (1080, 1920)

    def _live_view_point_to_macro(self, point, bounds: tuple[int, int, int, int]) -> tuple[int, int] | None:
        """Converte o clique do vídeo para a base da macro, não para o vídeo.

        O scrcpy mostra a resolução atual do telefone, mas uma macro já pode
        ter sido gravada com outra altura lógica. Salvar a coordenada atual
        diretamente misturava as duas escalas e deslocava todas as edições
        seguintes após uma reconexão.
        """
        device_point = self._live_view_point_to_device(point, bounds)
        if device_point is None:
            return None
        cached = self.device_calibrations.get(self.scrcpy_serial)
        current_screen = cached[0] if cached else self._macro_coordinate_screen()
        macro_w, macro_h = self._macro_coordinate_screen()
        current_w, current_h = int(current_screen[0]), int(current_screen[1])
        return (
            max(0, min(macro_w - 1, round(device_point[0] * (macro_w - 1) / max(1, current_w - 1)))),
            max(0, min(macro_h - 1, round(device_point[1] * (macro_h - 1) / max(1, current_h - 1)))),
        )

    def _append_live_preview_gesture(self, start: tuple[int, int, float, int], end: tuple[int, int]) -> None:
        """Inclui uma etapa criada sobre o scrcpy no mesmo ponto das gravações."""
        # Execuções são controladas por painel. A antiga referência
        # ``run_thread`` não existe mais e falhava justamente ao soltar o mouse.
        current_panel_running = self.flow_var.get() in self.panel_runs
        pending_only = self.execution_refresh_pending and not self.panel_runs
        if current_panel_running or pending_only:
            self.status.set("Pare a execução antes de gravar uma etapa pela tela ao vivo.")
            return
        sx, sy, began, ctrl_wait_ms = start
        ex, ey = end
        ended = time.monotonic()
        distance = abs(ex - sx) + abs(ey - sy)
        duration = max(40, round((ended - began) * 1000))
        delay = ctrl_wait_ms
        if distance < 35:
            action = Action("tap", sx, sy, duration_ms=duration, delay_ms=delay)
        else:
            action = Action("swipe", sx, sy, ex, ey, duration_ms=duration, delay_ms=delay)
        self._set_action_variation_defaults(action)
        self.push_undo()
        group_index, action_index = self._insert_new_action(action)
        item = getattr(self, "last_inserted_tree_item", f"a:{group_index}:{action_index}")
        self._live_ctrl_record_previous_end = ended
        self.refresh_tree()
        self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
        self.save_macro(quiet=True)
        self.status.set("Toque gravado pela tela ao vivo." if action.kind == "tap" else "Arrasto gravado pela tela ao vivo.")
        self._update_live_touch_marker(item)

    def _poll_live_coordinate_editing(self) -> None:
        """Converte cliques na tela viva sem controle em coordenadas da etapa."""
        try:
            in_foreground = self._live_view_has_foreground()
            if not in_foreground:
                self._hide_live_touch_marker()
            elif not self._live_marker_in_foreground:
                self._update_live_touch_marker()
            self._live_marker_in_foreground = in_foreground
            down = bool(ctypes.windll.user32.GetAsyncKeyState(0x01) & 0x8000)
            alt_down = bool(ctypes.windll.user32.GetAsyncKeyState(0x12) & 0x8000)
            ctrl_down = bool(ctypes.windll.user32.GetAsyncKeyState(0x11) & 0x8000)
            now = time.monotonic()
            if ctrl_down:
                if self._live_ctrl_held_since is None:
                    self._live_ctrl_held_since = now
            else:
                self._live_ctrl_held_since = None
            picker = self.live_xml_picker
            picker_active = bool(picker and self.live_view_mode
                                 and str(picker.get("serial", "")) == str(self.scrcpy_serial))
            flow_editor = self._flow_live_view_is_current_editor()
            # Durante a escolha de XML, o clique não pode alcançar o telefone:
            # ele serve exclusivamente para escolher o nó sob o cursor.
            modifier_blocking = (alt_down or ctrl_down or picker_active) and self.live_view_mode and (flow_editor or picker_active)
            self._set_scrcpy_alt_passthrough(modifier_blocking)
            self._set_live_marker_mouse_intercept(modifier_blocking)
            can_edit = flow_editor and self.live_view_mode and (self.live_view_edit_mode or alt_down)
            if self._live_ctrl_record_start is not None and not down:
                point = wintypes.POINT()
                ctypes.windll.user32.GetCursorPos(ctypes.byref(point))
                end = self._live_view_point_to_macro(point, self.scrcpy_window_bounds) if self.scrcpy_window_bounds else None
                start = self._live_ctrl_record_start
                self._live_ctrl_record_start = None
                self._live_ctrl_record_mouse_down = False
                if end is not None and flow_editor:
                    self._append_live_preview_gesture(start, end)
                elif end is not None:
                    self.status.set("Gravação cancelada: a lista ativa do Fluxo mudou durante o gesto.")
            if down and not self._live_edit_mouse_down and self.scrcpy_window_bounds:
                point = wintypes.POINT()
                ctypes.windll.user32.GetCursorPos(ctypes.byref(point))
                content = self._live_content_bounds(self.scrcpy_window_bounds)
                if content is None:
                    self._live_edit_mouse_down = down
                    return
                left, top, width, height, _screen_w, _screen_h = content
                inside_live_view = left <= point.x < left + width and top <= point.y < top + height
                if picker_active and inside_live_view:
                    self._finish_live_xml_picker(point)
                elif flow_editor and ctrl_down and not alt_down and inside_live_view:
                    start = self._live_view_point_to_macro(point, self.scrcpy_window_bounds)
                    if start is not None:
                        began = time.monotonic()
                        held_since = self._live_ctrl_held_since if self._live_ctrl_held_since is not None else began
                        self._live_ctrl_record_start = (start[0], start[1], began, max(0, round((began - held_since) * 1000)))
                        self._live_ctrl_record_mouse_down = True
                        self.status.set("Gravando pela tela ao vivo: solte o mouse para salvar o toque ou arrasto.")
                elif can_edit and inside_live_view:
                    selected = self.tree.selection()
                    if len(selected) != 1:
                        self._live_edit_mouse_down = down
                        return
                    location = self._tree_action_container(selected[0])
                    if location is not None:
                        _group, actions, index = location
                        action = actions[index]
                        if action.kind in ("tap", "swipe"):
                            macro_point = self._live_view_point_to_macro(point, self.scrcpy_window_bounds)
                            if macro_point is None:
                                self._live_edit_mouse_down = down
                                return
                            x, y = macro_point
                            sw, sh = self._macro_coordinate_screen()
                            self.push_undo()
                            if action.kind == "tap":
                                action.x, action.y = x, y
                            else:
                                dx, dy = (action.x2 or action.x) - action.x, (action.y2 or action.y) - action.y
                                action.x, action.y = x, y
                                action.x2, action.y2 = max(0, min(sw - 1, x + dx)), max(0, min(sh - 1, y + dy))
                            self.refresh_tree(); self.tree.selection_set(selected[0]); self.tree.focus(selected[0]); self.tree.see(selected[0])
                            self.save_macro(quiet=True)
                            self.status.set("Posicao atualizada na tela ao vivo.")
                            self._update_live_touch_marker()
            self._live_edit_mouse_down = down
        except (AttributeError, OSError, tk.TclError, RuntimeError):
            self._live_edit_mouse_down = False
        finally:
            self._poll_grid_coordinate_editing()
            # Ctrl/Alt na janela nativa do scrcpy precisa de uma leitura mais
            # frequente que a prévia comum para não perder um clique rápido.
            grid_open = bool(getattr(self, "app_view_var", None) and self.app_view_var.get() == "celulares")
            # A janela do scrcpy é nativa: não recebemos seu evento de mouse
            # pelo Tk. Com 45 ms, toques curtos com Ctrl podiam ocorrer
            # inteiros entre duas leituras e pareciam falhar ao acaso. Enquanto
            # houver uma prévia ao vivo, use a mesma cadência curta da grade.
            live_recording_surface = bool(self.live_view_mode and self.scrcpy_window_bounds)
            self.after(8 if grid_open or live_recording_surface else 45, self._poll_live_coordinate_editing)

    def enable_preview_editing(self) -> None:
        """Troca a visualização em tempo real pela imagem clicável da etapa."""
        self.live_view_mode = False
        if self.scrcpy_process and self.scrcpy_process.poll() is None:
            self.stop_live_view()
        if getattr(self, "preview_edit_button", None):
            self.preview_edit_button.configure(text="Voltar à tela ao vivo")
        selected = self.tree.selection()
        if not selected:
            self._set_preview_message("Selecione uma etapa\nde toque ou arrasto\npara editar")
            self.status.set("Prévia para edição ativada.")
            return
        self.status.set("Prévia para edição ativada: clique na imagem para ajustar a etapa.")
        self.update_action_preview(selected[0].split(":"))

    def update_action_preview(self, parts: list[str]) -> None:
        """Mostra uma miniatura atual do telefone com a etapa destacada."""
        self.preview_session += 1
        session = self.preview_session
        if not hasattr(self, "preview_canvas"):
            return
        if self.live_view_mode:
            self.preview_photo = None
            self.preview_context = None
            if not self.scrcpy_window_handle:
                self._set_preview_message("Iniciando visualização\nao vivo…")
            return
        if not parts or parts[0] not in ("a",) and not (parts[0] and set(parts[0]) == {"s"}):
            self.preview_photo = None
            self.preview_context = None
            self._set_preview_message("Selecione uma\netapa")
            return
        # A árvore usa ``a:grupo:etapa`` para etapas principais e
        # ``s:grupo:contêiner:etapa`` para qualquer etapa interna.  Resolver
        # ambas pelo mesmo caminho impede que toques de Nav-R/Nav-S/subgrupos
        # fiquem sem marcador na prévia.
        item = ":".join(parts)
        location = self._tree_action_container(item)
        if location is None:
            return
        group_index, actions, action_index = location
        if action_index < 0 or action_index >= len(actions):
            return
        action = copy.deepcopy(actions[action_index])
        if action.kind not in ("tap", "swipe"):
            self.preview_photo = None
            self.preview_context = None
            self._set_preview_message("Prévia disponível\npara toque e arrasto")
            return
        targets = [profile for profile in self.selected_profiles() if profile["state"] == "device"]
        serial = targets[0]["serial"] if targets else self.adb.serial
        if not serial:
            self.preview_photo = None
            self.preview_context = None
            self._set_preview_message("Selecione um telefone\nconectado")
            return
        flow = self.flow_var.get()
        recorded_screen = tuple(self.screen)
        if len(recorded_screen) != 2 or not all(isinstance(value, (int, float)) and value > 0 for value in recorded_screen):
            recorded_screen = (1080, 1920)
        recorded_raw = self.macro_devices.get(flow, {}).get("raw_size")
        coordinate_screen = self._action_coordinate_screen(action, recorded_screen, recorded_raw)
        self.preview_photo = None
        cached = self.preview_screens.get(serial)

        def render(source_image: Image.Image):
            try:
                image = source_image.copy()
                actual_screen = image.size
                image.thumbnail((190, 350), Image.Resampling.LANCZOS)
                # A etapa foi gravada na resolução da macro; a imagem pode ser
                # de qualquer outro celular. Cada eixo é escalado de forma
                # independente para o marcador permanecer no ponto equivalente.
                sx, sy = image.width / coordinate_screen[0], image.height / coordinate_screen[1]
                draw = ImageDraw.Draw(image)
                start = (round(action.x * sx), round(action.y * sy))
                if action.kind == "tap":
                    radius = 8
                    draw.ellipse((start[0] - radius - 2, start[1] - radius - 2, start[0] + radius + 2, start[1] + radius + 2),
                                 outline="#121722", width=2)
                    draw.ellipse((start[0] - radius, start[1] - radius, start[0] + radius, start[1] + radius),
                                 outline="#ffd23f", width=2)
                    draw.ellipse((start[0] - 3, start[1] - 3, start[0] + 3, start[1] + 3), fill="#ff4055")
                else:
                    end = (round((action.x2 or action.x) * sx), round((action.y2 or action.y) * sy))
                    draw.line((start, end), fill="#121722", width=6)
                    draw.line((start, end), fill="#ffd23f", width=3)
                    radius = 7
                    draw.ellipse((start[0] - radius, start[1] - radius, start[0] + radius, start[1] + radius), fill="#36d399", outline="#121722", width=2)
                    draw.ellipse((end[0] - radius, end[1] - radius, end[0] + radius, end[1] + radius), fill="#ff4055", outline="#121722", width=2)
                context = {"flow": flow, "group": group_index, "action": action_index,
                           "item": item,
                           "screen": actual_screen, "action_screen": coordinate_screen,
                           "image_size": image.size}
                self.events.put(("preview", (session, image, context)))
            except Exception as error:
                self.events.put(("preview_error", (session, str(error))))

        # Uma prévia já capturada aparece na troca de etapa sem esperar ADB.
        if cached:
            self._thread(lambda image=cached[1]: render(image))
            if time.monotonic() - cached[0] < 1.5:
                return
        else:
            self._set_preview_message("Atualizando\nprévia…")

        def capture_job():
            try:
                adb = Adb()
                adb.path, adb.serial = self.adb.path, serial
                image = Image.open(io.BytesIO(adb.screenshot())).convert("RGB")
                self.preview_screens[serial] = (time.monotonic(), image)
                render(image)
            except Exception as error:
                self.events.put(("preview_error", (session, str(error))))
        self._thread(capture_job)

    def preview_xml_element(self, attrs: dict[str, str]) -> None:
        """Destaca na prévia os limites do elemento selecionado no XML."""
        numbers = list(map(int, re.findall(r"\d+", attrs.get("bounds", ""))))
        if len(numbers) != 4 or not hasattr(self, "preview_canvas"):
            return
        targets = [profile for profile in self.selected_profiles() if profile["state"] == "device"]
        serial = targets[0]["serial"] if targets else self.adb.serial
        if not serial:
            return
        if getattr(self, "app_view_var", None) and self.app_view_var.get() == "celulares":
            # A lista XML do cartão usa a própria tela daquele telefone como
            # prévia. Selecionar uma linha só desenha a marcação; não envia
            # toque algum ao Android.
            serial = str(serial)
            source_size = self._grid_screen_size(serial) or tuple(self.screen)
            self.grid_xml_inspection_serial = serial
            self.grid_xml_marker_bounds[serial] = (tuple(numbers), tuple(source_size))
            process = self.grid_scrcpy_processes.get(serial)
            if process and process.poll() is None:
                self._place_grid_live_view(serial, process.pid, self.grid_view_session)
            self._update_grid_touch_marker(serial)
            return
        # XML e marcador precisam usar a resolução física do telefone que
        # forneceu a captura, não a resolução gravada na macro.
        calibration = self.device_calibrations.get(str(serial))
        source_size = calibration[0] if calibration else tuple(self.screen)
        self.show_live_xml_element(attrs, source_size)
        # A visualização estática era a implementação antiga. Com scrcpy
        # ativo, ela substituía a tela viva logo depois de desenhar o marcador,
        # fazendo parecer que a seleção não tinha sido destacada.
        if self.live_view_mode:
            return
        self.preview_session += 1
        session = self.preview_session
        bounds = tuple(numbers)

        def render(source_image: Image.Image):
            try:
                image = source_image.copy()
                actual_screen = image.size
                image.thumbnail((190, 350), Image.Resampling.LANCZOS)
                sx, sy = image.width / actual_screen[0], image.height / actual_screen[1]
                left, top, right, bottom = (round(bounds[0] * sx), round(bounds[1] * sy),
                                            round(bounds[2] * sx), round(bounds[3] * sy))
                draw = ImageDraw.Draw(image, "RGBA")
                draw.rectangle((left, top, right, bottom), fill=(47, 111, 237, 72), outline="#ffd23f", width=4)
                center_x, center_y = (left + right) // 2, (top + bottom) // 2
                draw.ellipse((center_x - 5, center_y - 5, center_x + 5, center_y + 5), fill="#ff4055", outline="#121722", width=2)
                context = {"flow": self.flow_var.get(), "screen": actual_screen, "image_size": image.size, "xml_preview": True}
                self.events.put(("preview", (session, image, context)))
            except Exception as error:
                self.events.put(("preview_error", (session, str(error))))

        cached = self.preview_screens.get(serial)
        if cached:
            self._thread(lambda image=cached[1]: render(image))
            if time.monotonic() - cached[0] < 1.5:
                return
        else:
            self._set_preview_message("Atualizando\nprévia…")

        def capture_job():
            try:
                adb = Adb()
                adb.path, adb.serial = self.adb.path, serial
                image = Image.open(io.BytesIO(adb.screenshot())).convert("RGB")
                self.preview_screens[serial] = (time.monotonic(), image)
                render(image)
            except Exception as error:
                self.events.put(("preview_error", (session, str(error))))
        self._thread(capture_job)

    def _set_preview_message(self, message: str) -> None:
        """Mostra uma mensagem centralizada quando não há imagem de prévia."""
        self.preview_canvas.delete("all")
        self.preview_image_item = None
        self.preview_base_image = None
        self.preview_message_item = self.preview_canvas.create_text(
            self.preview_canvas.winfo_width() // 2, self.preview_canvas.winfo_height() // 2,
            text=message, justify="center", fill="#9eafc4", font=("Segoe UI", 9),
        )

    def _show_preview_image(self, image: Image.Image) -> None:
        """Guarda a miniatura e a ajusta integralmente ao espaço disponível."""
        self.preview_canvas.delete("all")
        self.preview_base_image = image
        self.preview_photo = None
        self.preview_image_item = None
        self.preview_message_item = None
        self._layout_preview_canvas()

    def _layout_preview_canvas(self, _event=None) -> None:
        if not self.preview_base_image or not self.preview_context:
            if getattr(self, "preview_message_item", None):
                self.preview_canvas.coords(
                    self.preview_message_item,
                    self.preview_canvas.winfo_width() // 2,
                    self.preview_canvas.winfo_height() // 2,
                )
            return
        canvas_w = max(1, self.preview_canvas.winfo_width())
        canvas_h = max(1, self.preview_canvas.winfo_height())
        base_w, base_h = self.preview_base_image.size
        scale = min(canvas_w / base_w, canvas_h / base_h)
        image_w, image_h = max(1, round(base_w * scale)), max(1, round(base_h * scale))
        display = self.preview_base_image.resize((image_w, image_h), Image.Resampling.LANCZOS)
        self.preview_photo = ImageTk.PhotoImage(display)
        offset_x = (canvas_w - image_w) // 2
        offset_y = (canvas_h - image_h) // 2
        if self.preview_image_item:
            self.preview_canvas.itemconfigure(self.preview_image_item, image=self.preview_photo)
            self.preview_canvas.coords(self.preview_image_item, offset_x, offset_y)
        else:
            self.preview_image_item = self.preview_canvas.create_image(offset_x, offset_y, image=self.preview_photo, anchor="nw")
        self.preview_context["image_size"] = (image_w, image_h)
        self.preview_context["image_offset"] = (offset_x, offset_y)

    def show_xml_preview_picker(self, elements: list[dict[str, str]], on_pick) -> None:
        """Escolhe nós XML diretamente na tela ao vivo, sem prévia estática."""
        targets = [profile for profile in self.selected_profiles() if profile["state"] == "device"]
        serial = targets[0]["serial"] if targets else self.adb.serial
        if not serial:
            messagebox.showwarning("XML", "Selecione um telefone conectado primeiro.", parent=self)
            return
        if getattr(self, "app_view_var", None) and self.app_view_var.get() == "celulares":
            # Na grade, a própria tela do cartão vira a prévia. A máscara
            # intercepta o clique, portanto escolher um nó XML jamais toca no
            # aparelho.
            self.grid_xml_picker = {"serial": str(serial), "elements": elements, "callback": on_pick}
            self._grid_action_drawer_hides_live_views = False
            hwnd = self.grid_scrcpy_windows.get(str(serial))
            if hwnd:
                try:
                    ctypes.windll.user32.ShowWindow(wintypes.HWND(hwnd), 8)  # SW_SHOWNA
                except (AttributeError, OSError):
                    pass
            self._update_grid_touch_marker(str(serial))
            self.status.set("Escolher XML ativo: clique no elemento na tela do celular; o toque será bloqueado.")
            return
        self.live_xml_picker = {"serial": str(serial), "elements": elements, "callback": on_pick}
        # A tela viva acompanha o telefone usado pelo diálogo. Caso tenha sido
        # trocado, reinicia uma única vez no serial certo e mantém o pedido de
        # escolha pendente até a janela encaixar no quadro da prévia.
        if not self.live_view_mode or str(self.scrcpy_serial) != str(serial):
            self.start_live_view(str(serial))
        else:
            self._set_scrcpy_alt_passthrough(True)
            self._update_live_touch_marker()
        # Quando a tela precisou reiniciar, espere a área real do scrcpy ser
        # medida antes de colocar a máscara que bloqueia os cliques.
        self.after(180, self._update_live_touch_marker)
        self.status.set("Escolher XML ativo: clique no elemento desejado na tela ao vivo.")

    def handle_preview_click(self, event) -> None:
        context = self.preview_context
        if context and context.get("xml_picker"):
            image_w, image_h = context["image_size"]
            offset_x, offset_y = context.get("image_offset", (0, 0))
            local_x, local_y = event.x - offset_x, event.y - offset_y
            if not (0 <= local_x < image_w and 0 <= local_y < image_h):
                return
            x, y = self._preview_point_to_screen(local_x, local_y, image_w, image_h, *context["screen"])
            matches: list[tuple[int, dict[str, str]]] = []
            for attrs in context.get("xml_elements", []):
                values = list(map(int, re.findall(r"\d+", attrs.get("bounds", ""))))
                if len(values) != 4 or not (values[0] <= x <= values[2] and values[1] <= y <= values[3]):
                    continue
                matches.append(((values[2] - values[0]) * (values[3] - values[1]), attrs))
            callback = context.get("xml_pick_callback")
            if callback:
                callback([attrs for _area, attrs in sorted(matches, key=lambda item: item[0])])
            return
        self.adjust_action_from_preview(event)

    def adjust_action_from_preview(self, event) -> None:
        """Reposiciona a etapa clicada usando as coordenadas da miniatura."""
        context = self.preview_context
        if not context or context["flow"] != self.flow_var.get() or context.get("xml_preview"):
            return
        image_w, image_h = context["image_size"]
        offset_x, offset_y = context.get("image_offset", (0, 0))
        local_x, local_y = event.x - offset_x, event.y - offset_y
        if not (0 <= local_x < image_w and 0 <= local_y < image_h):
            return
        item = context.get("item")
        if not item:
            return
        location = self._tree_action_container(item)
        if location is None:
            return
        _group_index, actions, action_index = location
        if action_index < 0 or action_index >= len(actions):
            return
        action = actions[action_index]
        if action.kind not in ("tap", "swipe"):
            return
        action_screen = tuple(context.get("action_screen", context["screen"]))
        x, y = self._preview_point_to_screen(local_x, local_y, image_w, image_h, *action_screen)
        self.push_undo()
        # A captura é a fonte de verdade para a tela atual. Isso impede que
        # macros antigas, salvas com uma altura diferente, cortem o toque ao
        # executar depois de ele ser ajustado na prévia.
        if action.kind == "tap":
            action.x, action.y = x, y
        else:
            screen_w, screen_h = action_screen
            delta_x, delta_y = (action.x2 or action.x) - action.x, (action.y2 or action.y) - action.y
            action.x, action.y = x, y
            action.x2 = max(0, min(screen_w - 1, x + delta_x))
            action.y2 = max(0, min(screen_h - 1, y + delta_y))
        self.refresh_tree()
        self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
        self.save_macro(quiet=True)
        self.status.set("Posição da etapa atualizada pela prévia.")
        self.update_action_preview(item.split(":"))

    @staticmethod
    def _preview_point_to_screen(local_x: int, local_y: int, image_w: int, image_h: int,
                                 screen_w: int, screen_h: int) -> tuple[int, int]:
        """Converte um pixel da miniatura para o pixel equivalente da tela.

        Usar ``tamanho - 1`` mantém os quatro cantos alinhados: o último pixel
        da imagem reduzida corresponde ao último pixel da captura, sem o desvio
        crescente que ocorria perto da borda direita e inferior.
        """
        x = round(local_x * max(0, screen_w - 1) / max(1, image_w - 1))
        y = round(local_y * max(0, screen_h - 1) / max(1, image_h - 1))
        return max(0, min(screen_w - 1, x)), max(0, min(screen_h - 1, y))

    def _record_insertion_point(self) -> tuple[int, int] | None:
        selected = self.tree.selection()
        if not selected: return None
        parts = selected[0].split(":")
        groups = self.macros[self.flow_var.get()]
        if parts[0] == "g" and int(parts[1]) < len(groups):
            group_index = int(parts[1])
            # Cabeçalho aberto: a gravação começa como primeira etapa dele,
            # igual às etapas adicionadas pelos botões laterais.
            return group_index, 0 if self._container_accepts_first_child(selected[0], groups[group_index]["actions"]) else len(groups[group_index]["actions"])
        if parts[0] == "a" and int(parts[1]) < len(groups):
            return int(parts[1]), int(parts[2]) + 1
        return None

    def _insert_new_action(self, action: Action) -> tuple[int, int]:
        """Insere uma etapa logo após a linha selecionada.

        Selecionar um grupo significa inserir no fim dele; selecionar uma etapa
        significa inserir imediatamente depois dela. Sem seleção, preserva o
        comportamento anterior de usar o grupo ativo.
        """
        if getattr(self, "action_drawer_open", False):
            self.after_idle(self._minimize_action_drawer)
        groups = self.macros[self.flow_var.get()]
        selected = self.tree.selection()
        if len(selected) == 1:
            item = selected[0]
            parts = item.split(":")
            if parts[0] == "g":
                group_index = int(parts[1])
                if 0 <= group_index < len(groups):
                    if self._container_accepts_first_child(item, groups[group_index]["actions"]):
                        groups[group_index]["actions"].insert(0, action)
                        self.last_inserted_tree_item = f"a:{group_index}:0"
                        self.active_group = group_index
                        return group_index, 0
                    # Não existe etapa solta fora de um grupo na estrutura da
                    # macro. Portanto, para preservar o item como irmão do
                    # grupo fechado, cria-se um grupo irmão que a contém.
                    sibling_name = f"Grupo {len(groups) + 1}"
                    groups.insert(group_index + 1, {"name": sibling_name, "enabled": True, "actions": [action]})
                    self.last_inserted_tree_item = f"a:{group_index + 1}:0"
                    self.active_group = group_index + 1
                    return group_index + 1, 0
            location = self._tree_action_container(item)
            if location is not None:
                group_index, siblings, selected_index = location
                selected_action = siblings[selected_index]
                children = self._container_actions(selected_action)
                # Um grupo aberto recebe a etapa como filho. Fechado, ele é
                # tratado como um bloco fechado: a nova etapa entra abaixo,
                # no mesmo nível, sem ficar escondida dentro dele.
                if children is not None and self._container_accepts_first_child(item, children):
                    children.insert(0, action)
                    self._tree_open_after_refresh = getattr(self, "_tree_open_after_refresh", set())
                    self._tree_open_after_refresh.add(item)
                    self.last_inserted_tree_item = item
                    self.active_group = group_index
                    return group_index, 0
                siblings.insert(selected_index + 1, action)
                parts = item.split(":")
                if parts[0].startswith("s"):
                    self.last_inserted_tree_item = ":".join([parts[0], *parts[1:-1], str(selected_index + 1)])
                else:
                    self.last_inserted_tree_item = f"a:{group_index}:{selected_index + 1}"
                self.active_group = group_index
                return group_index, selected_index + 1
        point = self._record_insertion_point()
        if point is None:
            if self.active_group is None or self.active_group >= len(groups):
                self.new_group()
            point = (self.active_group or 0, len(groups[self.active_group or 0]["actions"]))
        group_index, action_index = point
        actions = groups[group_index]["actions"]
        action_index = max(0, min(action_index, len(actions)))
        actions.insert(action_index, action)
        self.active_group = group_index
        self.last_inserted_tree_item = f"a:{group_index}:{action_index}"
        return group_index, action_index

    def _selected_start_index(self, prefer_focus: bool = False) -> int | None:
        selected = self.tree.selection()
        focused = self.tree.focus()
        if prefer_focus and focused in selected:
            selected = (focused,)
        if not selected: return None
        positions = []
        groups = self.macros[self.flow_var.get()]

        def executable_count(group: dict) -> int:
            """Quantidade que o grupo ocupa depois de ser preparado para execução.

            Grupos especiais aparecem com várias linhas na árvore para que sejam
            configuráveis, mas são uma única ação no fluxo executado.
            """
            if group.get("branch_only"):
                return 0
            if group.get("xml_logic_group") or group.get("xml_any_tap_group") or group.get("navigation_r") or group.get("navigation_s") or group.get("training_loop") or group.get("validation_loop") or group.get("xml_restart_loop_group"):
                return 1
            return len(group["actions"])

        for item in selected:
            parts = item.split(":")
            if parts[0] not in ("g", "a"): continue
            group_index = int(parts[1])
            if group_index >= len(groups): continue
            group = groups[group_index]
            before = sum(executable_count(previous) for previous in groups[:group_index])
            if parts[0] == "g" or group.get("xml_logic_group") or group.get("xml_any_tap_group") or group.get("navigation_r") or group.get("navigation_s") or group.get("training_loop") or group.get("validation_loop") or group.get("xml_restart_loop_group"):
                positions.append(before)
            else:
                positions.append(before + int(parts[2]))
        return min(positions) if positions else None

    def tree_item_for_action(self, position: int) -> str | None:
        remaining = position
        for group_index, group in enumerate(self.macros[self.flow_var.get()]):
            if group.get("branch_only"):
                continue
            special_group = bool(group.get("xml_logic_group") or group.get("xml_any_tap_group") or group.get("navigation_r") or group.get("navigation_s") or group.get("navigation_rc") or group.get("training_loop") or group.get("validation_loop") or group.get("xml_restart_loop_group"))
            count = 1 if special_group else len(group["actions"])
            if remaining < count:
                if special_group:
                    return f"g:{group_index}"
                return f"a:{group_index}:{remaining}"
            remaining -= count
        return None

    def _execution_state_serial(self) -> str:
        selected = self.selected_profiles()
        if len(selected) == 1:
            return str(selected[0].get("serial", ""))
        return str(self.adb.serial or "")

    def _render_execution_state(self) -> None:
        """Aplica à árvore o estado do telefone selecionado no momento."""
        serial = self._execution_state_serial()
        state = self.device_execution_states.get(serial, {})
        running = state.get("running")
        state_panel = str(state.get("panel", "") or "")
        # Um telefone pode executar o painel atribuído enquanto a pessoa edita
        # outro. IDs como ``a:0:1`` existem nos dois fluxos, mas representam
        # etapas diferentes; nesse caso não destaque uma linha enganosa.
        if state_panel and state_panel != self.flow_var.get():
            running = None
        def walk(parent: str = ""):
            for tree_item in self.tree.get_children(parent):
                yield tree_item
                yield from walk(tree_item)

        for tree_item in walk():
                tags = tuple(tag for tag in self.tree.item(tree_item, "tags") if tag != "running")
                self.tree.item(tree_item, tags=tags)
        def normalized_tree_item(item: str | None) -> str | None:
            """Aceita ids antigos de etapas profundas e os converte ao id atual."""
            if not item:
                return None
            parts = item.split(":")
            if parts and parts[0] and set(parts[0]) == {"s"}:
                # O número de índices depois do grupo define a profundidade,
                # não o prefixo eventualmente gravado por uma versão anterior.
                expected_depth = max(1, len(parts) - 3)
                item = ":".join(["s" * expected_depth, *parts[1:]])
            return item

        previous = self.running_tree_item
        running = normalized_tree_item(running)
        self.running_tree_item = running if running and self.tree.exists(running) else None
        # Ao encerrar, mantém o último contexto aberto. O recolhimento
        # automático só acontece durante a transição entre etapas/irmãos,
        # jamais como efeito colateral de finalizar a execução.
        if not self.running_tree_item:
            return
        # Depois de Esc podem ainda chegar eventos que já estavam na fila. Eles
        # podem atualizar o destaque da linha, mas nunca devem fechar qualquer
        # contêiner enquanto o encerramento estiver em andamento.
        if self.flow_var.get() in self.stopping_panels:
            current_tags = tuple(tag for tag in self.tree.item(self.running_tree_item, "tags") if tag != "running")
            self.tree.item(self.running_tree_item, tags=(*current_tags, "running"))
            return
        # Os grupos abertos automaticamente acompanham somente a ação atual.
        # Ao sair de um ramo, fecha exclusivamente os que foram abertos pela
        # execução, preservando os grupos que a pessoa abriu para editar.
        def execution_path(item: str | None) -> set[str]:
            """Contêineres que precisam ficar visíveis para a etapa atual."""
            result: set[str] = set()
            # Quando a própria linha em execução é um grupo (ou um Nav-R,
            # subgrupo, XML condicional etc.), ela também precisa abrir para
            # exibir as etapas que estão sendo executadas dentro dela.
            if item and self.tree.exists(item) and self.tree.get_children(item):
                result.add(item)
            while item and self.tree.exists(item):
                item = self.tree.parent(item)
                if item:
                    result.add(item)
            return result
        current_ancestors = execution_path(self.running_tree_item)
        # Fecha também os contêineres do caminho que acabou de terminar. Isso
        # não depende de como o grupo estava aberto antes da execução: quando
        # o fluxo sai dele para um irmão, ele sempre é recolhido.
        finished_ancestors = execution_path(previous) - current_ancestors
        to_collapse = (self.execution_open_items - current_ancestors) | finished_ancestors
        for item in tuple(to_collapse):
            if self.tree.exists(item):
                self.tree.item(item, open=False)
            self.execution_open_items.discard(item)
        current_tags = tuple(tag for tag in self.tree.item(self.running_tree_item, "tags") if tag != "running")
        self.tree.item(self.running_tree_item, tags=(*current_tags, "running"))
        for container in current_ancestors:
            if self.tree.exists(container):
                self.tree.item(container, open=True)
                self.execution_open_items.add(container)
        # A lista precisa acompanhar a etapa em execução, mas não podemos
        # trocar a seleção real a cada passo: isso dispara o carregamento de
        # prévia e deixa os eventos de ciclos/loops atrasados. O foco interno
        # e a rolagem são suficientes para manter a linha visível.
        self.tree.focus(self.running_tree_item)
        self.tree.see(self.running_tree_item)
        self.tree.focus_set()

    def _render_grid_running_step(self, serial: str, source_item: str | None) -> None:
        """Espelha a etapa atual na árvore compacta daquele celular."""
        tree = self.device_grid_flow_trees.get(serial)
        if not tree or not tree.winfo_exists():
            return
        try:
            match = ""
            for item in tree.get_children(""):
                stack = [item]
                while stack:
                    current = stack.pop()
                    tags = tuple(tag for tag in tree.item(current, "tags") if tag != "running")
                    tree.item(current, tags=tags)
                    if source_item and getattr(tree, "grid_source_items", {}).get(current) == source_item:
                        match = current
                    stack.extend(tree.get_children(current))
            if not match:
                return
            parent = tree.parent(match)
            while parent:
                tree.item(parent, open=True)
                parent = tree.parent(parent)
            tags = tuple(tag for tag in tree.item(match, "tags") if tag != "running")
            tree.item(match, tags=(*tags, "running"))
            # Abrir os pais recalcula a altura somente no próximo ciclo do Tk.
            # A rolagem imediata às vezes ocorria antes disso e a etapa ficava
            # fora da área visível no painel compacto.
            tree.focus(match)
            tree.see(match)
            tree.after_idle(lambda target=match, widget=tree: (
                widget.see(target) if widget.winfo_exists() and widget.exists(target) else None
            ))
        except tk.TclError:
            return

    def _collapse_finished_grid_containers(self, serial: str, previous_item: str | None) -> None:
        """Recolhe pais cujo último filho acabou de terminar no cartão."""
        if not previous_item:
            return
        tree = self.device_grid_flow_trees.get(serial)
        if not tree or not tree.winfo_exists():
            return
        try:
            reverse = {source: compact for compact, source in tree.grid_source_items.items()}
            current = reverse.get(previous_item, "")
            while current:
                parent = tree.parent(current)
                if not parent or tree.next(current):
                    break
                tree.item(parent, open=False)
                current = parent
        except tk.TclError:
            pass

    def _collapse_finished_main_containers(self, previous_item: str | None) -> None:
        """Aplica ao Fluxo o mesmo recolhimento ao terminar o último filho."""
        if not previous_item or not self.tree.exists(previous_item):
            return
        try:
            current = previous_item
            while current:
                parent = self.tree.parent(current)
                if not parent or self.tree.next(current):
                    break
                self.tree.item(parent, open=False)
                current = parent
        except tk.TclError:
            pass

    def set_running_item(self, item: str | None, serial: str | None = None,
                         panel: str | None = None) -> None:
        """Registra a linha atual separadamente para cada telefone."""
        # Cada etapa troca o destaque visual. A marcação XML é válida somente
        # para a etapa que a encontrou, portanto não pode permanecer sobre a
        # próxima ação comum.
        self.live_xml_marker_bounds = None
        self.live_xml_marker_source_size = None
        serial = str(serial or self._execution_state_serial())
        # Uma área XML só vale para a ação que acabou de encontrá-la; ao passar
        # para qualquer outra etapa o desenho daquele cartão é removido.
        if serial:
            self.grid_xml_marker_bounds.pop(serial, None)
        if serial:
            state = self.device_execution_states.setdefault(serial, {"running": None})
            previous_item = state.get("running")
            if previous_item and previous_item != item:
                grid_tree = self.device_grid_flow_trees.get(serial)
                grid_panel = str(getattr(grid_tree, "grid_panel", "") or "") if grid_tree else ""
                if not grid_panel or not panel or grid_panel == panel:
                    self._collapse_finished_grid_containers(serial, str(previous_item))
                if not panel or panel == self.flow_var.get():
                    self._collapse_finished_main_containers(str(previous_item))
            state["running"] = item
            if panel:
                state["panel"] = str(panel)
            self._refresh_device_grid_title(serial)
        # Na grade, redesenhar a árvore principal oculta a cada evento de cada
        # aparelho consome o ciclo do Tk e faz os cartões parecerem travados.
        # Cada cartão tem sua própria árvore e é o único widget que precisa ser
        # atualizado nessa tela.
        in_grid = bool(getattr(self, "app_view_var", None) and self.app_view_var.get() == "celulares")
        if not in_grid:
            self._render_execution_state()
        if serial:
            tree = self.device_grid_flow_trees.get(serial)
            tree_panel = str(getattr(tree, "grid_panel", "") or "") if tree else ""
            self._render_grid_running_step(serial, item if not tree_panel or not panel or tree_panel == panel else None)
        # A máscara é atualizada no mesmo evento que troca o destaque da
        # árvore; não há captura extra de tela nem custo perceptível.
        if in_grid and serial:
            self._update_grid_touch_marker(serial, item)
        elif not in_grid:
            self._update_live_touch_marker(item)

    def _request_execution_ui_commit(self) -> None:
        """Agenda uma única atualização visual para o próximo ciclo livre.

        As etapas XML podem publicar muitos eventos seguidos. Atualizar a
        árvore e o Text imediatamente dentro do leitor da fila mantinha o Tk
        ocupado e o Windows só pintava tudo após um clique. O estado fica
        guardado e é aplicado em `after_idle`, sem bloquear a execução ADB.
        """
        if self._execution_ui_commit_scheduled:
            return
        self._execution_ui_commit_scheduled = True
        try:
            # Em loops com XML nunca hÃ¡ uma janela de ociosidade garantida;
            # after_idle pode ficar pendente atÃ© a pessoa clicar na janela.
            # after(0) continua agrupando os eventos, mas pinta no prÃ³ximo
            # ciclo real do Tk mesmo com a fila sempre recebendo mensagens.
            self.after(0, self._commit_execution_ui)
        except tk.TclError:
            self._execution_ui_commit_scheduled = False

    def _commit_execution_ui(self) -> None:
        self._execution_ui_commit_scheduled = False
        pending = self._pending_running_items
        self._pending_running_items = {}
        try:
            # N\u00e3o agrupa telefones diferentes em uma \u00fanica linha. Cada estado
            # pendente \u00e9 aplicado no mesmo ciclo visual, preservando o destaque
            # de todos os celulares que executam em paralelo.
            for serial, (item, panel) in pending.items():
                try:
                    self.set_running_item(item, serial or None, panel)
                except (tk.TclError, KeyError, ValueError):
                    continue
        except Exception:
            # Uma linha da árvore pode ser recriada enquanto a execução roda.
            # Isso nunca pode impedir a atualização visual do log.
            pass
        try:
            self._flush_execution_log_widgets()
        except tk.TclError:
            return
        except Exception:
            # A fila principal seguirá ativa mesmo se um widget for recriado
            # durante uma troca de painel ou de visualização.
            return

    def _focus_task_tree_for_execution(self, panel: str) -> None:
        """Dá visibilidade imediata à etapa atual ao iniciar um painel."""
        if panel != self.flow_var.get() or not hasattr(self, "tree"):
            return
        try:
            self.tree.focus_set()
            if self.running_tree_item and self.tree.exists(self.running_tree_item):
                self.tree.see(self.running_tree_item)
        except tk.TclError:
            pass

    def set_running_step(self, position: int | None) -> None:
        self.set_running_item(self.tree_item_for_action(position) if position is not None else None)

    def select_running_step(self) -> None:
        """Mantém a etapa em execução selecionada ao interromper a macro."""
        item = self.running_tree_item
        if item and self.tree.exists(item):
            self.tree.selection_set(item)
            self.tree.focus(item)
            self.tree.see(item)
            self.active_group = int(item.split(":")[1])

    def _ensure_xml_device(self) -> bool:
        selected = self.selected_profiles()
        if len(selected) == 1:
            self.adb.serial = selected[0]["serial"]
            self.device_model = selected[0]["group"]
        if not self.adb.serial:
            messagebox.showwarning("XML", "Selecione um único telefone antes de capturar o XML.")
            return False
        return True

    def show_current_xml_viewer(self) -> None:
        """Abre uma consulta somente leitura do XML atual do telefone."""
        if not self._ensure_xml_device():
            return
        dialog = tk.Toplevel(self)
        dialog.title("XML atual do telefone")
        dialog.geometry("820x620")
        dialog.minsize(700, 500)
        dialog.configure(bg="#171b26")
        dialog.transient(self)
        dialog.grid_rowconfigure(2, weight=1)
        dialog.grid_columnconfigure(0, weight=1)
        query = tk.StringVar()
        info = tk.StringVar(value="Atualizando XML do telefone…")
        captured: list[dict[str, str]] = []
        visible: list[dict[str, str]] = []
        refreshing = False
        capture_serial = str(self.adb.serial)
        capture_source = ""

        ttk.Label(dialog, text="Pesquisar no XML atual:").grid(row=0, column=0, padx=18, pady=(16, 6), sticky="w")
        ctk.CTkEntry(dialog, textvariable=query, width=600, height=32, corner_radius=8,
                     fg_color="#222938", border_color="#465166", text_color="#f8fafc").grid(row=1, column=0, padx=18, pady=(0, 8), sticky="ew")
        elements = tk.Listbox(dialog, bg="#202737", fg="#e7edf7", selectbackground="#2d5eb8",
                              highlightthickness=0, borderwidth=0, activestyle="none")
        elements.grid(row=2, column=0, padx=18, pady=(4, 8), sticky="nsew")
        ttk.Label(dialog, textvariable=info, wraplength=760).grid(row=3, column=0, padx=18, pady=(0, 8), sticky="w")

        def render(*_args) -> None:
            term = query.get().strip()
            visible.clear()
            elements.delete(0, tk.END)
            for attrs in captured:
                if not self._xml_query_matches(self._xml_searchable(attrs), term):
                    continue
                visible.append(attrs)
                shown = attrs.get("text") or attrs.get("content-desc") or attrs.get("resource-id") or attrs.get("class", "elemento")
                elements.insert(tk.END, f"{shown}   [{attrs.get('class', '')}]")
            source_text = (f" XML capturado via {xml_capture_source_label(capture_source)}."
                           if capture_source else "")
            info.set(f"{len(visible)} elemento(s). Clique em um para localizá-lo na prévia.{source_text}")

        def refresh() -> None:
            nonlocal refreshing
            if refreshing:
                return
            refreshing = True
            info.set("Lendo XML do telefone…")
            refresh_button.configure(state="disabled")

            def capture() -> None:
                nonlocal capture_source
                values: list[dict[str, str]] = []
                truncated = False
                error_text = ""
                try:
                    # Uma tela específica do A14s pode demorar a responder;
                    # nunca bloqueie o ciclo visual do Tk durante a captura.
                    adb = Adb()
                    adb.path, adb.serial = self.adb.path, capture_serial
                    xml = adb.capture_ui_xml(retries=4)
                    capture_source = adb.last_xml_capture_source
                    for node in ET.fromstring(xml).iter("node"):
                        attrs = dict(node.attrib)
                        if not self._xml_searchable(attrs):
                            continue
                        values.append(attrs)
                        if len(values) >= 10_000:
                            truncated = True
                            break
                except Exception as error:
                    error_text = str(error)

                def finish() -> None:
                    nonlocal refreshing
                    if not dialog.winfo_exists():
                        return
                    refreshing = False
                    refresh_button.configure(state="normal")
                    if error_text:
                        info.set(f"Não foi possível ler o XML: {error_text}")
                        return
                    captured[:] = values
                    render()
                    if truncated:
                        info.set(f"{len(visible)} elemento(s) exibido(s), limitado a 10.000 para manter o programa estável.")

                self.after(0, finish)

            self._thread(capture)

        def choose(_event=None) -> None:
            if not elements.curselection() or not visible:
                return
            attrs = visible[elements.curselection()[0]]
            self.preview_xml_element(attrs)
            details = " • ".join(f"{key}={value}" for key, value in attrs.items()
                                  if key in ("text", "content-desc", "resource-id", "class", "clickable", "scrollable", "bounds") and value)
            info.set(f"Elemento na prévia: {details or 'sem detalhes'}.")

        query.trace_add("write", render)
        elements.bind("<<ListboxSelect>>", choose)
        refresh_button = ctk.CTkButton(dialog, text="Atualizar XML", command=refresh, width=135, height=32, corner_radius=8,
                                       fg_color="#39455b", hover_color="#4a5870")
        refresh_button.grid(row=4, column=0, padx=18, pady=(4, 16), sticky="w")
        refresh()

    def show_nav_rc_debug_xml(self) -> None:
        """Mostra exatamente os XMLs analisados na última execução do Nav-R-C."""
        selected = self.selected_profiles()
        if len(selected) != 1:
            messagebox.showinfo("Nav-R-C", "Selecione exatamente um telefone para ver os XMLs capturados por ele.", parent=self)
            return
        serial = selected[0]["serial"]
        captures: list[tuple[str, str]] = list(self.nav_rc_debug_xml.get(serial, []))
        if not captures:
            debug_dir = RUNTIME_DIR / re.sub(r"[^A-Za-z0-9_.-]", "_", serial) / "nav_rc_debug"
            for path in sorted(debug_dir.glob("*.json"))[-20:]:
                try:
                    saved = json.loads(path.read_text(encoding="utf-8"))
                    captures.append((str(saved["label"]), str(saved["xml"])))
                except (OSError, KeyError, TypeError, json.JSONDecodeError):
                    continue
        if not captures:
            messagebox.showinfo("Nav-R-C", "Ainda não há XML capturado. Execute novamente o Nav-R-C e abra este botão depois que aparecer no log ‘XML de depuração salvo’.", parent=self)
            return
        dialog = tk.Toplevel(self)
        dialog.title("XML usado pelo Nav-R-C")
        dialog.geometry("900x680")
        dialog.minsize(720, 520)
        dialog.configure(bg="#171b26")
        dialog.transient(self)
        dialog.grid_rowconfigure(4, weight=1)
        dialog.grid_columnconfigure(0, weight=1)
        labels = [label for label, _xml in captures]
        selected_capture = tk.StringVar(value=labels[-1])
        query = tk.StringVar()
        info = tk.StringVar()
        visible: list[dict[str, str]] = []

        ttk.Label(dialog, text="Captura analisada pelo Nav-R-C:").grid(row=0, column=0, padx=18, pady=(16, 5), sticky="w")
        ttk.Combobox(dialog, textvariable=selected_capture, values=labels, state="readonly", width=85).grid(
            row=1, column=0, padx=18, pady=(0, 9), sticky="ew"
        )
        ctk.CTkEntry(dialog, textvariable=query, placeholder_text="Pesquisar nesta captura XML", height=32,
                     corner_radius=8, fg_color="#222938", border_color="#465166", text_color="#f8fafc").grid(
                         row=2, column=0, padx=18, pady=(0, 8), sticky="ew"
                     )
        elements = tk.Listbox(dialog, bg="#202737", fg="#e7edf7", selectbackground="#2d5eb8",
                              highlightthickness=0, borderwidth=0, activestyle="none")
        elements.grid(row=3, column=0, padx=18, pady=(0, 8), sticky="nsew")
        ttk.Label(dialog, textvariable=info, wraplength=850).grid(row=4, column=0, padx=18, pady=(0, 14), sticky="w")

        def current_xml() -> str:
            position = labels.index(selected_capture.get()) if selected_capture.get() in labels else len(captures) - 1
            return captures[position][1]

        def render(*_args) -> None:
            visible.clear(); elements.delete(0, tk.END)
            try:
                nodes = [dict(node.attrib) for node in ET.fromstring(current_xml()).iter("node")]
            except ET.ParseError as error:
                info.set(f"XML inválido: {error}")
                return
            term = query.get().strip()
            for attrs in nodes:
                if not self._xml_searchable(attrs) or not self._xml_query_matches(self._xml_searchable(attrs), term):
                    continue
                visible.append(attrs)
                shown = attrs.get("text") or attrs.get("content-desc") or attrs.get("resource-id") or attrs.get("class", "elemento")
                elements.insert(tk.END, f"{shown}   [{attrs.get('class', '')}]")
            info.set(f"{len(visible)} elemento(s) nesta captura. O título informa se o programa considerou o comentário válido.")

        def choose(_event=None) -> None:
            if not elements.curselection() or not visible:
                return
            attrs = visible[elements.curselection()[0]]
            self.preview_xml_element(attrs)
            details = " • ".join(f"{key}={value}" for key, value in attrs.items()
                                 if key in ("text", "content-desc", "resource-id", "class", "bounds") and value)
            info.set(details or "Elemento sem detalhes.")

        selected_capture.trace_add("write", render)
        query.trace_add("write", render)
        elements.bind("<<ListboxSelect>>", choose)
        render()

    def add_email_action(self) -> None:
        """Adiciona uma etapa que apenas digita o e-mail da identidade atual."""
        self.push_undo()
        group_index, action_index = self._insert_new_action(Action("generated_email", delay_ms=400, label="Digitar e-mail da conta"))
        item = getattr(self, "last_inserted_tree_item", f"a:{group_index}:{action_index}")
        self.refresh_tree()
        self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
        self.save_macro(quiet=True)
        self.status.set("Etapa para digitar o e-mail da conta atual adicionada.")

    def _append_special_action(self, action: Action, status: str) -> None:
        self._set_action_variation_defaults(action)
        self.push_undo()
        group_index, action_index = self._insert_new_action(action)
        item = getattr(self, "last_inserted_tree_item", f"a:{group_index}:{action_index}")
        self.refresh_tree()
        self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
        self.save_macro(quiet=True)
        self.status.set(status)

    @staticmethod
    def _instagram_apk_file() -> Path | None:
        """Usa o APK do Instagram já incluído na pasta do programa."""
        candidates = [path for path in APK_DIR.glob("*.apk") if "instagram" in path.name.casefold()]
        return max(candidates, key=lambda path: path.stat().st_size) if candidates else None

    def add_instagram_ready_action(self) -> None:
        apk = self._instagram_apk_file()
        if not apk:
            messagebox.showwarning("Instagram", "Não encontrei um APK do Instagram em assets/apk.", parent=self)
            return
        self._append_special_action(
            Action("instagram_ready", delay_ms=400, package_name="com.instagram.android", apk_file=apk.name,
                   label="Instagram: instalar e abrir"),
            "Etapa para verificar, instalar e abrir o Instagram adicionada."
        )

    def configure_instagram_action(self, group_index: int, action_index: int) -> None:
        groups = self.macros[self.flow_var.get()]
        action = groups[group_index]["actions"][action_index]
        attempts = simpledialog.askinteger("Instagram", "Máximo de tentativas para abrir:",
                                           initialvalue=max(1, action.app_open_attempts), minvalue=1, maxvalue=20, parent=self)
        if attempts is None:
            return
        seconds = simpledialog.askinteger("Instagram", "Confirmar que ficou aberto por quantos segundos:",
                                          initialvalue=max(1, action.app_open_confirm_s), minvalue=1, maxvalue=120, parent=self)
        if seconds is None:
            return
        install = action.install_if_missing
        if action.kind == "instagram_ready":
            install = messagebox.askyesno("Instagram", "Instalar o Instagram se ele não estiver no telefone?", parent=self)
        self.push_undo()
        action.app_open_attempts, action.app_open_confirm_s, action.install_if_missing = attempts, seconds, install
        item = getattr(self, "last_inserted_tree_item", f"a:{group_index}:{action_index}")
        self.refresh_tree(); self.tree.selection_set(item); self.tree.focus(item); self.tree.see(item)
        self.save_macro(quiet=True)
        self.status.set("Etapa de Instagram configurada.")

    def add_instagram_code_action(self) -> None:
        timeout = simpledialog.askinteger(
            "Obter código", "Aguardar o código do Instagram por até quantos segundos?",
            initialvalue=120, minvalue=10, maxvalue=600, parent=self
        )
        if timeout is None:
            return
        self._append_special_action(
            Action("instagram_code", delay_ms=400, timeout_s=timeout, label="Obter e digitar código"),
            "Etapa para obter e digitar o código adicionada."
        )

    def configure_smspool(self) -> None:
        """Abre o gerenciador dos provedores de números/SMS."""
        dialog = ctk.CTkToplevel(self)
        dialog.title("APIs de número")
        dialog.geometry("680x440")
        dialog.minsize(590, 360)
        dialog.transient(self)
        dialog.grab_set()

        ctk.CTkLabel(dialog, text="APIs de número", font=("Segoe UI Semibold", 19)).pack(anchor="w", padx=20, pady=(18, 2))
        ctk.CTkLabel(dialog, text="Cada API usa um script próprio salvo em data/apis_numeros. Escolha a API ao criar as etapas de comprar número e obter código.",
                     wraplength=635, justify="left", text_color="#aebbd0").pack(anchor="w", padx=20, pady=(0, 14))

        content = ctk.CTkFrame(dialog, fg_color="transparent")
        content.pack(fill="both", expand=True, padx=20, pady=(0, 12))
        tree = ttk.Treeview(content, columns=("name", "script", "default"), show="headings", selectmode="browse", height=9)
        tree.heading("name", text="API")
        tree.heading("script", text="Script salvo")
        tree.heading("default", text="Padrão")
        tree.column("name", width=210, anchor="w")
        tree.column("script", width=260, anchor="w")
        tree.column("default", width=90, anchor="center")
        tree.pack(side="left", fill="both", expand=True)
        scrollbar = ttk.Scrollbar(content, orient="vertical", command=tree.yview)
        scrollbar.pack(side="right", fill="y")
        tree.configure(yscrollcommand=scrollbar.set)

        def selected_profile() -> dict | None:
            selected = tree.selection()
            if not selected:
                return None
            return next((item for item in self._number_api_profiles() if str(item.get("id")) == selected[0]), None)

        def refresh(select_id: str | None = None) -> None:
            tree.delete(*tree.get_children())
            default_id = str(self.settings.get("default_number_api", "smspool"))
            for profile in self._number_api_profiles():
                profile_id = str(profile.get("id"))
                tree.insert("", "end", iid=profile_id, values=(
                    str(profile.get("name") or profile_id), str(profile.get("script") or "—"),
                    "Sim" if profile_id == default_id else "",
                ))
            target = select_id or default_id
            if tree.exists(target):
                tree.selection_set(target); tree.focus(target)

        def edit_profile(profile: dict | None = None) -> None:
            is_new = profile is None
            current = dict(profile or {})
            name = simpledialog.askstring("API de número", "Nome para mostrar no programa:",
                                          initialvalue=str(current.get("name") or ""), parent=dialog)
            if name is None or not name.strip():
                return
            if is_new:
                script_source = filedialog.askopenfilename(parent=dialog, title="Escolha o script da API",
                                                           filetypes=[("Script Python", "*.py")])
                if not script_source:
                    return
                base_id = re.sub(r"[^a-z0-9_-]+", "_", name.casefold()).strip("_") or "api_numero"
                used_ids = {str(item.get("id")) for item in self._number_api_profiles()}
                provider_id = base_id
                while provider_id in used_ids:
                    provider_id = f"{base_id}_{uuid.uuid4().hex[:4]}"
                script_name = f"{provider_id}.py"
                try:
                    shutil.copy2(script_source, NUMBER_APIS_DIR / script_name)
                except OSError as error:
                    messagebox.showerror("API de número", f"Não consegui salvar o script: {error}", parent=dialog)
                    return
                current.update({"id": provider_id, "script": script_name})
            key = simpledialog.askstring("API de número", "Chave/API key (vazia se esta API não usar chave):",
                                         initialvalue=str(current.get("api_key") or ""), show="*", parent=dialog)
            if key is None:
                return
            current["name"] = name.strip()
            current["api_key"] = key.strip()
            profiles = self._number_api_profiles()
            index = next((i for i, item in enumerate(profiles) if str(item.get("id")) == str(current.get("id"))), -1)
            if index >= 0:
                profiles[index] = current
            else:
                profiles.append(current)
            self.settings["number_apis"] = profiles
            if str(current.get("id")) == "smspool":
                self.settings["smspool_api_key"] = current["api_key"]
            self._save_settings()
            refresh(str(current["id"]))

        def set_default() -> None:
            profile = selected_profile()
            if not profile:
                return
            self.settings["default_number_api"] = str(profile.get("id"))
            self._save_settings()
            refresh(str(profile.get("id")))

        def remove_selected() -> None:
            profile = selected_profile()
            if not profile:
                return
            if str(profile.get("id")) == "smspool":
                messagebox.showwarning("API de número", "O perfil SMSPool padrão não pode ser removido.", parent=dialog)
                return
            if not messagebox.askyesno("Remover API", f"Remover ‘{profile.get('name')}’? O script salvo não será apagado.", parent=dialog):
                return
            self.settings["number_apis"] = [item for item in self._number_api_profiles()
                                             if str(item.get("id")) != str(profile.get("id"))]
            if self.settings.get("default_number_api") == profile.get("id"):
                self.settings["default_number_api"] = "smspool"
            self._save_settings()
            refresh()

        actions = ctk.CTkFrame(dialog, fg_color="transparent")
        actions.pack(fill="x", padx=20, pady=(0, 18))
        ctk.CTkButton(actions, text="+ Nova API por script", command=lambda: edit_profile(), width=160).pack(side="left")
        ctk.CTkButton(actions, text="Editar", command=lambda: edit_profile(selected_profile()) if selected_profile() else None,
                      width=95, fg_color="#39455b", hover_color="#4a5870").pack(side="left", padx=8)
        ctk.CTkButton(actions, text="Usar como padrão", command=set_default, width=145,
                      fg_color="#39455b", hover_color="#4a5870").pack(side="left")
        ctk.CTkButton(actions, text="Remover", command=remove_selected, width=95,
                      fg_color="#7b3847", hover_color="#914354").pack(side="left", padx=8)
        ctk.CTkButton(actions, text="Fechar", command=dialog.destroy, width=95).pack(side="right")
        refresh()
        self._prepare_popup_window(dialog)

    def _choose_number_api(self, title: str, initial_id: str | None = None) -> dict | None:
        profiles = self._number_api_profiles()
        if not profiles:
            messagebox.showwarning("API de número", "Configure uma API de número antes de criar esta etapa.", parent=self)
            return None
        default = self._number_api_profile(initial_id)
        choices = "\n".join(f"• {item.get('name')} ({item.get('id')})" for item in profiles)
        selected = simpledialog.askstring(title, f"Escolha a API pelo nome ou identificador:\n{choices}",
                                          initialvalue=str(default.get("name") or default.get("id")), parent=self)
        if selected is None:
            return None
        needle = selected.strip().casefold()
        profile = next((item for item in profiles if needle in (str(item.get("id", "")).casefold(), str(item.get("name", "")).casefold())), None)
        if profile is None:
            messagebox.showwarning("API de número", "API não encontrada. Use o nome ou identificador mostrado na lista.", parent=self)
        return profile

    def add_smspool_order_action(self) -> None:
        provider = self._choose_number_api("Comprar número")
        if provider is None:
            return
        provider_name = str(provider.get("name") or provider.get("id"))
        is_5sim = str(provider.get("id", "")).casefold() == "5sim"
        service = simpledialog.askstring("Comprar número", (f"Produto em {provider_name} (ex.: instagram):" if is_5sim else f"Serviço ou ID do serviço em {provider_name}:"), initialvalue="instagram" if is_5sim else "Instagram", parent=self)
        if service is None or not service.strip():
            return
        country = simpledialog.askstring("Comprar número", "País da 5sim (ex.: brazil, any):" if is_5sim else "País (código ISO ou ID):", initialvalue="brazil" if is_5sim else "US", parent=self)
        if country is None or not country.strip():
            return
        operator = ""
        if is_5sim:
            operator = simpledialog.askstring("Comprar número", "Operadora da 5sim (use any para qualquer uma):", initialvalue="any", parent=self)
            if operator is None or not operator.strip():
                return
        price = simpledialog.askfloat("Comprar número", "Preço máximo em USD (opcional; 0 = sem limite):", initialvalue=0, minvalue=0, parent=self)
        if price is None:
            return
        self._append_special_action(
            Action("smspool_order", delay_ms=400, sms_service=service.strip(), sms_country=country.strip(),
                   sms_operator=operator.strip(),
                   sms_max_price=price or None, sms_provider_id=str(provider["id"]),
                   label=f"{provider_name}: comprar número"),
            f"Etapa {provider_name} para comprar e digitar um número adicionada.",
        )

    def add_smspool_code_action(self) -> None:
        provider = self._choose_number_api("Obter código")
        if provider is None:
            return
        timeout = simpledialog.askinteger("Obter código", "Aguardar o SMS por até quantos segundos?", initialvalue=120, minvalue=10, maxvalue=600, parent=self)
        if timeout is None:
            return
        provider_name = str(provider.get("name") or provider.get("id"))
        self._append_special_action(
            Action("smspool_code", delay_ms=400, timeout_s=timeout, sms_provider_id=str(provider["id"]),
                   label=f"{provider_name}: obter e digitar código"),
            f"Etapa {provider_name} para obter e digitar o código adicionada.",
        )

    def add_number_code_not_received_action(self) -> None:
        """Cria a rota condicional de recuperação do código SMS."""
        self._append_special_action(
            Action("subgroup", delay_ms=0, label="Código não chegou", number_code_failure_group=True,
                   nested_actions=[Action("restart_parent_group", delay_ms=0, label="Reiniciar grupo pai")]),
            "Grupo ‘Código não chegou’ adicionado. Coloque nele os passos de retorno antes de ‘Reiniciar grupo pai’.",
        )

    def configure_number_api_action(self, action: Action, tree_item: str | None = None) -> None:
        """Troca a API de uma etapa de número sem recriar o fluxo."""
        provider = self._choose_number_api("Configurar etapa de número", action.sms_provider_id)
        if provider is None:
            return
        self.push_undo()
        action.sms_provider_id = str(provider["id"])
        provider_name = str(provider.get("name") or provider.get("id"))
        action.label = (f"{provider_name}: comprar número" if action.kind == "smspool_order"
                        else f"{provider_name}: obter e digitar código")
        self.refresh_tree()
        if tree_item and self.tree.exists(tree_item):
            self.tree.selection_set(tree_item); self.tree.focus(tree_item); self.tree.see(tree_item)
        self.save_macro(quiet=True)
        self.status.set(f"Etapa configurada para usar {provider_name}.")

    def add_whisper_capture_action(self) -> None:
        model = simpledialog.askstring(
            "Capturar código Whisper", "Modelo Whisper (small.en ou medium.en):",
            initialvalue="small.en", parent=self
        )
        if model is None:
            return
        model = model.strip().lower()
        if model not in {"small.en", "medium.en"}:
            messagebox.showwarning("Capturar código Whisper", "Use o modelo small.en ou medium.en.")
            return
        duration = simpledialog.askinteger(
            "Capturar código Whisper", "Quantos segundos de áudio devem ser capturados?",
            initialvalue=10, minvalue=1, maxvalue=120, parent=self
        )
        if duration is None:
            return
        self._append_special_action(
            Action(
                "whisper_capture", delay_ms=400, whisper_model=model, audio_duration_s=duration,
                label="Capturar código Whisper"
            ),
            "Etapa para capturar o código por áudio adicionada."
        )

    def add_whisper_type_action(self) -> None:
        self._append_special_action(
            Action("whisper_type", delay_ms=400, label="Digitar código Whisper"),
            "Etapa para digitar {WHISPER_CODE} adicionada."
        )

    def add_password_action(self) -> None:
        self._append_special_action(
            Action("generated_password", delay_ms=400, label="Digitar senha gerada"),
            "Etapa para digitar a senha adicionada."
        )

    def add_full_name_action(self) -> None:
        self._append_special_action(
            Action("generated_full_name", delay_ms=400, label="Digitar nome e sobrenome"),
            "Etapa para digitar nome e sobrenome adicionada."
        )

    def add_random_name_action(self) -> None:
        self._append_special_action(
            Action("random_name", delay_ms=400, label="Sortear e digitar nome"),
            "Etapa para sortear e digitar um nome da lista de nomes adicionada."
        )

    def add_unlink_identity_action(self) -> None:
        self._append_special_action(
            Action("unlink_identity", delay_ms=400, label="Criar nova identidade"),
            "Etapa para criar e vincular uma nova identidade ao celular adicionada."
        )

    def add_waiting_identity_action(self) -> None:
        self._append_special_action(
            Action("add_waiting_identity", delay_ms=400, label="Adicionar nome a Aguardando"),
            "Etapa para adicionar o nome e sobrenome atuais à lista Aguardando adicionada."
        )

    def add_training_username_action(self) -> None:
        self._append_special_action(
            Action("training_random_username", delay_ms=400, label="Digitar usuário aleatório treino"),
            "Etapa para sortear e digitar um usuário aleatório de treino adicionada."
        )

    def manage_training_users(self) -> None:
        """Mostra o usuário de treino do telefone e permite manter sua lista."""
        try:
            users = [dict(user) for user in load_random_users()]
        except RuntimeError as error:
            messagebox.showerror("Usuários de treino", str(error), parent=self)
            return
        selected_profiles = self.selected_profiles()
        serial = str(selected_profiles[0].get("serial", "")) if selected_profiles else str(self.adb.serial or "")
        current = ""
        if serial:
            try:
                current = str(RuntimeVariables(serial, RUNTIME_DIR).get("USUARIO_ALEATORIO_TREINO", "")).strip()
            except (OSError, RuntimeError, ValueError):
                pass

        dialog = tk.Toplevel(self)
        dialog.title("Usuários aleatórios de treino")
        dialog.geometry("560x500")
        dialog.minsize(500, 420)
        dialog.configure(bg="#171b26")
        dialog.transient(self); dialog.grab_set()
        current_text = (f"Usuário atual deste celular: {current}" if current
                        else "Usuário atual deste celular: ainda não foi sorteado nesta sessão.")
        current_var = tk.StringVar(value=current_text)
        ttk.Label(dialog, textvariable=current_var, wraplength=520).pack(anchor="w", padx=18, pady=(18, 8))
        ttk.Label(dialog, text="Lista usada pela etapa ‘Usuário aleatório treino’:").pack(anchor="w", padx=18)
        list_frame = ttk.Frame(dialog)
        list_frame.pack(fill="both", expand=True, padx=18, pady=(8, 12))
        user_list = tk.Listbox(list_frame, exportselection=False, background="#202737", foreground="#e7edf7",
                               selectbackground="#6d3cc2", highlightthickness=0, borderwidth=0, activestyle="none")
        scrollbar = ttk.Scrollbar(list_frame, orient="vertical", command=user_list.yview)
        user_list.configure(yscrollcommand=scrollbar.set)
        user_list.pack(side="left", fill="both", expand=True); scrollbar.pack(side="right", fill="y")
        name_var = tk.StringVar()

        def refresh(select_index: int | None = None) -> None:
            user_list.delete(0, tk.END)
            for user in users:
                user_list.insert(tk.END, str(user.get("nome", "")))
            if users:
                index = min(max(0, select_index or 0), len(users) - 1)
                user_list.selection_set(index); user_list.activate(index); name_var.set(str(users[index].get("nome", "")))
            else:
                name_var.set("")

        def selected_index() -> int | None:
            picked = user_list.curselection()
            return int(picked[0]) if picked else None

        def show_selected(_event=None) -> None:
            index = selected_index()
            if index is not None:
                name_var.set(str(users[index].get("nome", "")))

        edit_frame = ttk.Frame(dialog)
        edit_frame.pack(fill="x", padx=18, pady=(0, 10))
        ttk.Label(edit_frame, text="Usuário:").pack(side="left")
        entry = ctk.CTkEntry(edit_frame, textvariable=name_var, height=32, corner_radius=8,
                             fg_color="#222938", border_color="#465166", text_color="#f8fafc")
        entry.pack(side="left", fill="x", expand=True, padx=(8, 0))

        def save_selected() -> None:
            index = selected_index()
            value = name_var.get().strip()
            if index is None or not value:
                messagebox.showwarning("Usuários de treino", "Selecione e informe um usuário válido.", parent=dialog)
                return
            users[index]["nome"] = value
            save_random_users(users); refresh(index)
            self.status.set("Lista de usuários aleatórios de treino salva.")

        def add_user() -> None:
            value = name_var.get().strip() or "novo_usuario"
            users.append({"nome": value, "link": "", "arquivos": []})
            save_random_users(users); refresh(len(users) - 1)

        def delete_user() -> None:
            index = selected_index()
            if index is None:
                return
            if len(users) == 1:
                messagebox.showwarning("Usuários de treino", "A lista precisa manter ao menos um usuário.", parent=dialog)
                return
            value = str(users[index].get("nome", ""))
            if messagebox.askyesno("Remover usuário", f"Remover ‘{value}’ da lista?", parent=dialog):
                users.pop(index); save_random_users(users); refresh(index - 1)
                self.status.set(f"Usuário de treino ‘{value}’ removido da lista.")

        buttons = ttk.Frame(dialog); buttons.pack(fill="x", padx=18, pady=(0, 18))
        ttk.Button(buttons, text="Salvar edição", command=save_selected).pack(side="left")
        ttk.Button(buttons, text="Adicionar", command=add_user).pack(side="left", padx=8)
        ttk.Button(buttons, text="Remover", command=delete_user).pack(side="left")
        ctk.CTkButton(buttons, text="Fechar", command=dialog.destroy, width=100, height=32, corner_radius=8,
                      fg_color="#39455b", hover_color="#4a5870").pack(side="right")
        user_list.bind("<<ListboxSelect>>", show_selected)
        refresh()
        self._prepare_popup_window(dialog)

    def manage_used_identities(self) -> None:
        """Permite liberar identidades específicas que já foram reservadas."""
        dialog = tk.Toplevel(self)
        dialog.title("Usuários já usados")
        dialog.geometry("950x500")
        dialog.minsize(760, 380)
        dialog.configure(bg="#171b26")
        dialog.transient(self)
        dialog.grab_set()

        header = ttk.Frame(dialog, padding=(16, 14, 16, 8))
        header.pack(fill="x")
        ttk.Label(header, text="Usuários já usados", style="Heading.TLabel").pack(anchor="w")
        ttk.Label(
            header,
            text="Selecione uma identidade e remova apenas essa reserva para poder usá-la novamente. "
                 "A identidade atualmente vinculada a um celular não é alterada.",
            wraplength=850,
        ).pack(anchor="w", pady=(5, 0))

        filter_var = tk.StringVar()
        filter_row = ttk.Frame(dialog, padding=(16, 0, 16, 8))
        filter_row.pack(fill="x")
        ttk.Label(filter_row, text="Pesquisar:").pack(side="left")
        search = ctk.CTkEntry(filter_row, textvariable=filter_var, placeholder_text="Nome, @, e-mail ou celular...",
                              width=360, height=30, corner_radius=7, fg_color="#222938",
                              border_color="#465166", text_color="#f8fafc")
        search.pack(side="left", padx=(8, 0))

        table_frame = ttk.Frame(dialog, padding=(16, 0, 16, 10))
        table_frame.pack(fill="both", expand=True)
        columns = ("nome", "usuario", "email", "celular", "data")
        table = ttk.Treeview(table_frame, columns=columns, show="headings", selectmode="browse")
        headings = {
            "nome": ("Nome", 190), "usuario": ("@", 180), "email": ("E-mail", 245),
            "celular": ("Celular", 170), "data": ("Registrado em", 145),
        }
        for column, (title, width) in headings.items():
            table.heading(column, text=title)
            table.column(column, width=width, minwidth=90, stretch=column in ("nome", "email"))
        scroll = ttk.Scrollbar(table_frame, orient="vertical", command=table.yview)
        table.configure(yscrollcommand=scroll.set)
        table.pack(side="left", fill="both", expand=True)
        scroll.pack(side="right", fill="y")

        identities: list[dict[str, str]] = []
        visible: list[dict[str, str]] = []

        def refresh() -> None:
            nonlocal identities, visible
            try:
                identities = load_used_identities()
            except RuntimeError as error:
                messagebox.showerror("Usuários já usados", str(error), parent=dialog)
                identities = []
            query = filter_var.get().strip().casefold()
            visible = [
                item for item in identities
                if not query or query in " ".join(str(item.get(key, "")) for key in ("nome", "sobrenome", "usuario", "email", "celular")).casefold()
            ]
            table.delete(*table.get_children())
            for index, item in enumerate(visible):
                full_name = f"{item.get('nome', '')} {item.get('sobrenome', '')}".strip()
                user = str(item.get("usuario", "")).strip()
                table.insert("", "end", iid=str(index), values=(full_name, f"@{user}" if user else "—",
                    item.get("email", "") or "—", item.get("celular", "") or "—", item.get("reservado_em", "") or "—"))

        def release_selected() -> None:
            selected = table.selection()
            if not selected:
                messagebox.showinfo("Usuários já usados", "Selecione uma identidade para liberar.", parent=dialog)
                return
            item = visible[int(selected[0])]
            full_name = f"{item.get('nome', '')} {item.get('sobrenome', '')}".strip()
            user = str(item.get("usuario", "")).strip()
            label = f"{full_name}{' (@' + user + ')' if user else ''}".strip()
            if not messagebox.askyesno(
                "Liberar usuário",
                f"Liberar {label} para poder criar/usar novamente?\n\n"
                "Isso remove somente o registro de já usado; não altera o celular que possa estar usando essa identidade agora.",
                parent=dialog,
            ):
                return
            try:
                released = release_used_identity(str(item.get("nome", "")), str(item.get("sobrenome", "")))
            except (RuntimeError, ValueError) as error:
                messagebox.showerror("Usuários já usados", str(error), parent=dialog)
                return
            if released:
                self.status.set(f"Identidade {label} liberada para reutilização.")
                refresh()

        buttons = ttk.Frame(dialog, padding=(16, 0, 16, 14))
        buttons.pack(fill="x")
        ctk.CTkButton(buttons, text="Liberar selecionado", command=release_selected, width=150, height=32,
                      corner_radius=8, fg_color="#7c3aed", hover_color="#8b5cf6").pack(side="left")
        ttk.Button(buttons, text="Atualizar", command=refresh).pack(side="left", padx=8)
        ctk.CTkButton(buttons, text="Fechar", command=dialog.destroy, width=100, height=32, corner_radius=8,
                      fg_color="#39455b", hover_color="#4a5870").pack(side="right")
        filter_var.trace_add("write", lambda *_args: refresh())
        table.bind("<Delete>", lambda _event: release_selected())
        refresh()
        search.focus_set()
        self._prepare_popup_window(dialog)

    def manage_identities(self) -> None:
        """Edita as listas soltas de nomes, sobrenomes e links das identidades."""
        try:
            names = [str(profile["nome"]) for profile in load_name_profiles()]
            surnames = load_last_names()
            links = load_identity_links()
        except (RuntimeError, ValueError) as error:
            messagebox.showerror("Gerenciar identidades", str(error), parent=self)
            return
        dialog = ctk.CTkToplevel(self)
        dialog.title("Gerenciar identidades")
        dialog.geometry("950x560")
        dialog.transient(self); dialog.grab_set()
        ctk.CTkLabel(dialog, text="Identidades aleatórias", font=("Segoe UI Semibold", 19)).pack(anchor="w", padx=18, pady=(18, 3))
        ctk.CTkLabel(dialog, text="Nomes e sobrenomes são combinados ao criar uma identidade. Links são uma lista geral, sem vínculo com nome, sobrenome, pasta ou celular.", text_color="#aebbd0", wraplength=900).pack(anchor="w", padx=18, pady=(0, 12))
        columns = ctk.CTkFrame(dialog, fg_color="transparent")
        columns.pack(fill="both", expand=True, padx=18, pady=(0, 12))
        columns.grid_columnconfigure((0, 1, 2), weight=1)
        editors: dict[str, ctk.CTkTextbox] = {}
        descriptions = {
            "names": ("Nomes", "Um por linha."),
            "surnames": ("Sobrenomes", "Um por linha. Não permite a mesma sequência inicial de 3 letras."),
            "links": ("Links gerais", "Um por linha. Cada uso sorteia um link desta lista."),
        }
        for column, (key, (title, description)) in enumerate(descriptions.items()):
            frame = ctk.CTkFrame(columns, fg_color="#171b26", corner_radius=8)
            frame.grid(row=0, column=column, sticky="nsew", padx=(0 if column == 0 else 6, 0 if column == 2 else 6))
            ctk.CTkLabel(frame, text=title, font=("Segoe UI Semibold", 15)).pack(anchor="w", padx=12, pady=(12, 2))
            ctk.CTkLabel(frame, text=description, text_color="#aebbd0", wraplength=270, justify="left").pack(anchor="w", padx=12, pady=(0, 8))
            editor = ctk.CTkTextbox(frame, fg_color="#202737", text_color="#e7edf7")
            editor.pack(fill="both", expand=True, padx=12, pady=(0, 12))
            editors[key] = editor
        editors["names"].insert("1.0", "\n".join(names))
        editors["surnames"].insert("1.0", "\n".join(surnames))
        editors["links"].insert("1.0", "\n".join(links))

        def entries(key: str) -> list[str]:
            return [line.strip() for line in editors[key].get("1.0", "end").splitlines() if line.strip()]

        def save() -> None:
            try:
                name_values = entries("names")
                if not name_values:
                    raise ValueError("Mantenha ao menos um nome.")
                save_name_profiles([{"nome": name} for name in name_values])
                save_last_names(entries("surnames"))
                save_identity_links(entries("links"))
            except (RuntimeError, ValueError) as error:
                messagebox.showwarning("Gerenciar identidades", str(error), parent=dialog)
                return
            self.status.set("Nomes, sobrenomes e links gerais das identidades salvos.")
            dialog.destroy()

        actions = ctk.CTkFrame(dialog, fg_color="transparent")
        actions.pack(fill="x", padx=18, pady=(0, 18))
        ctk.CTkButton(actions, text="Cancelar", command=dialog.destroy, width=100, height=32, fg_color="#39455b", hover_color="#4a5870").pack(side="left")
        ctk.CTkButton(actions, text="Salvar identidades", command=save, width=155, height=32, fg_color="#2f6fed", hover_color="#4b82ee").pack(side="right")
        self._prepare_popup_window(dialog)

    def manage_random_users(self) -> None:
        """Edita os arquivos e o link vinculados a cada nome aleatório."""
        try:
            users = [dict(user) for user in load_name_profiles()]
        except RuntimeError as error:
            messagebox.showerror("Usuários aleatórios", str(error))
            return
        dialog = tk.Toplevel(self)
        dialog.title("Gerenciar nomes aleatórios")
        dialog.geometry("760x440")
        dialog.configure(bg="#171b26")
        dialog.transient(self)
        dialog.grab_set()
        tk.Label(dialog, text="Nomes", bg="#171b26", fg="#dbe5f2").grid(row=0, column=0, padx=14, pady=(14, 4), sticky="w")
        name_search_var = tk.StringVar()
        ctk.CTkEntry(dialog, textvariable=name_search_var, placeholder_text="Filtrar nomes...", width=220, height=30,
                     corner_radius=7, fg_color="#222938", border_color="#465166", text_color="#f8fafc").grid(
                         row=0, column=1, padx=(0, 14), pady=(10, 4), sticky="w"
                     )
        user_list = tk.Listbox(dialog, width=25, exportselection=False, background="#202737", foreground="#e7edf7",
                               selectbackground="#2d5eb8", highlightthickness=0, borderwidth=0)
        user_list.grid(row=1, column=0, rowspan=5, padx=14, pady=(0, 14), sticky="nsew")
        form = ttk.Frame(dialog, padding=8)
        form.grid(row=1, column=1, padx=(0, 14), pady=(0, 14), sticky="nsew")
        dialog.grid_columnconfigure(1, weight=1); dialog.grid_rowconfigure(1, weight=1)
        name_var = tk.StringVar()
        ttk.Label(form, text="Nome:").grid(row=0, column=0, sticky="w")
        ttk.Entry(form, textvariable=name_var, width=55).grid(row=0, column=1, sticky="ew", padx=(6, 0))
        ttk.Label(form, text="Links (um por linha):").grid(row=1, column=0, pady=(8, 0), sticky="nw")
        links_editor = tk.Text(form, height=4, width=47, background="#202737", foreground="#e7edf7",
                               insertbackground="#f8fafc", highlightthickness=0, borderwidth=0)
        links_editor.grid(row=1, column=1, pady=(8, 0), sticky="ew", padx=(6, 0))
        ttk.Label(form, text="Arquivos enviados para Download:").grid(row=2, column=0, columnspan=2, pady=(14, 4), sticky="w")
        file_list = tk.Listbox(form, height=10, background="#202737", foreground="#e7edf7", selectbackground="#2d5eb8",
                               highlightthickness=0, borderwidth=0)
        file_list.grid(row=3, column=0, columnspan=2, sticky="nsew")
        form.grid_columnconfigure(1, weight=1); form.grid_rowconfigure(3, weight=1)

        visible_indexes: list[int] = []

        def render_users(select_index=None):
            query = name_search_var.get().strip().casefold()
            visible_indexes[:] = [index for index, user in enumerate(users)
                                  if not query or query in str(user["nome"]).casefold()]
            user_list.delete(0, tk.END)
            for index in visible_indexes:
                user_list.insert(tk.END, str(users[index]["nome"]))
            if visible_indexes:
                selected = select_index if select_index in visible_indexes else visible_indexes[0]
                user_list.selection_set(visible_indexes.index(selected)); show_selected()
            else:
                name_var.set(""); links_editor.delete("1.0", "end"); file_list.delete(0, tk.END)

        def selected_index():
            picked = user_list.curselection()
            return visible_indexes[picked[0]] if picked else None

        def save_fields():
            index = selected_index()
            if index is None:
                return False
            name = name_var.get().strip()
            if not name:
                messagebox.showwarning("Usuários aleatórios", "Informe um nome.", parent=dialog)
                return False
            users[index]["nome"] = name
            links = [line.strip() for line in links_editor.get("1.0", "end").splitlines() if line.strip()]
            users[index]["links"] = links
            users[index]["link"] = links[0] if links else ""
            return True

        def show_selected(_event=None):
            index = selected_index()
            if index is None:
                return
            user = users[index]
            name_var.set(str(user["nome"]))
            links_editor.delete("1.0", "end")
            links_editor.insert("1.0", "\n".join(user.get("links", []) or ([user.get("link", "")] if user.get("link") else [])))
            file_list.delete(0, tk.END)
            for path in user.get("arquivos", []):
                file_list.insert(tk.END, str(path))

        def new_user():
            if users and not save_fields():
                return
            users.append({"nome": "Novo nome", "link": "", "arquivos": []})
            render_users(len(users) - 1)

        def delete_user():
            index = selected_index()
            if index is None:
                return
            if len(users) == 1:
                messagebox.showwarning("Nomes aleatórios", "A lista precisa manter ao menos um nome.", parent=dialog)
                return
            if messagebox.askyesno("Excluir nome", f"Excluir {users[index]['nome']} e seus vínculos?", parent=dialog):
                users.pop(index); render_users(max(0, index - 1))

        def add_files():
            index = selected_index()
            if index is None or not save_fields():
                return
            paths = filedialog.askopenfilenames(parent=dialog, title="Escolha os arquivos deste nome")
            existing = users[index].setdefault("arquivos", [])
            for path in paths:
                if path not in existing:
                    existing.append(path)
            show_selected()

        def remove_file():
            index = selected_index(); picked = file_list.curselection()
            if index is None or not picked:
                return
            users[index]["arquivos"].pop(picked[0]); show_selected()

        def save_all():
            if not save_fields():
                return
            try:
                save_name_profiles(users)
            except RuntimeError as error:
                messagebox.showerror("Usuários aleatórios", str(error), parent=dialog)
                return
            self.status.set(f"{len(users)} nome(s) aleatório(s) salvos.")
            dialog.destroy()

        ttk.Button(dialog, text="Novo", command=new_user).grid(row=6, column=0, padx=14, pady=(0, 14), sticky="w")
        ttk.Button(dialog, text="Excluir", command=delete_user).grid(row=6, column=0, padx=(78, 0), pady=(0, 14), sticky="w")
