    @staticmethod
    def _select_normal_media(files: list[Path], mode: str, next_index: int) -> tuple[Path, int]:
        """Escolhe a mídia sem mudar a pasta original; devolve o próximo índice sequencial."""
        if not files:
            raise RuntimeError("A pasta configurada não possui mídias compatíveis.")
        ordered = sorted(files, key=lambda path: (path.name.casefold(), str(path).casefold()))
        if mode == "random":
            return random.choice(ordered), next_index
        index = max(0, int(next_index)) % len(ordered)
        return ordered[index], (index + 1) % len(ordered)

    def _normal_media_from_account(self, account: dict[str, object], media_type: str, mode: str,
                                   next_index: int) -> tuple[Path, int]:
        folder_key = "pasta_fotos" if media_type == "photo" else "pasta_videos"
        configured_folder = str(account.get(folder_key, "")).strip()
        kind_name = "fotos" if media_type == "photo" else "vídeos"
        if not configured_folder:
            raise RuntimeError(f"A pasta de {kind_name} desta conta normal não está configurada.")
        folder = Path(configured_folder).expanduser()
        if not folder.is_dir():
            raise RuntimeError(f"A pasta de {kind_name} desta conta normal não está configurada ou não existe: {folder}")
        extensions = ({".jpg", ".jpeg", ".png", ".webp", ".gif", ".heic", ".heif"}
                      if media_type == "photo" else {".mp4", ".mov", ".mkv", ".webm", ".3gp", ".avi", ".m4v"})
        files = [path for path in folder.iterdir() if path.is_file() and path.suffix.casefold() in extensions]
        return self._select_normal_media(files, mode, next_index)

    @staticmethod
    def _character_media_folders(characters: list[dict[str, object]]) -> dict[str, str]:
        """Pastas relativas existentes em todos os personagens cadastrados."""
        per_character: list[set[str]] = []
        for character in characters:
            root = Path(str(character.get("pasta", ""))).expanduser()
            if not root.is_dir():
                continue
            folders = {""}
            try:
                folders.update(str(path.relative_to(root)) for path in root.iterdir() if path.is_dir())
            except OSError:
                continue
            per_character.append(folders)
        if not per_character:
            return {}
        common = set.intersection(*per_character)
        return {"Raiz do personagem" if not folder else folder: folder for folder in sorted(common, key=str.casefold)}

    def _bind_random_character(self, runtime_variables: RuntimeVariables,
                               replace_current: bool = False) -> dict[str, object] | None:
        """Sorteia e persiste um personagem para a identidade atual.

        Uma nova identidade nunca herda o personagem anterior; nas demais
        etapas o vínculo já salvo é preservado sem novo sorteio.
        """
        current_name = str(runtime_variables.get("RANDOM_USER_CHARACTER", "")).strip()
        if current_name and not replace_current:
            folder = str(runtime_variables.get("RANDOM_USER_CHARACTER_FOLDER", "")).strip()
            return {"nome": current_name, "pasta": folder,
                    "links": runtime_variables.get("RANDOM_USER_CHARACTER_LINKS", [])}
        character = random_character_profile(current_name if replace_current else "")
        if character is None:
            runtime_variables.remove("RANDOM_USER_CHARACTER", "RANDOM_USER_CHARACTER_FOLDER",
                                     "RANDOM_USER_CHARACTER_LINKS")
            return None
        links = [str(link).strip() for link in character.get("links", []) if str(link).strip()]
        runtime_variables.set("RANDOM_USER_CHARACTER", str(character["nome"]))
        runtime_variables.set("RANDOM_USER_CHARACTER_FOLDER", str(character["pasta"]))
        runtime_variables.set("RANDOM_USER_CHARACTER_LINKS", links)
        return character

    def _random_media_from_character(self, runtime_variables: RuntimeVariables,
                                     relative_folder: str | None) -> tuple[Path, str]:
        """Escolhe uma mídia aleatória da pasta configurada do personagem atual."""
        root_value = str(runtime_variables.get("RANDOM_USER_CHARACTER_FOLDER", "")).strip()
        if not root_value:
            character = self._bind_random_character(runtime_variables)
            if character is None:
                raise RuntimeError("Cadastre ao menos um personagem com uma pasta em Gerenciar personagens.")
            root_value = str(character["pasta"])
        root = Path(root_value).expanduser()
        relative = str(relative_folder or "").strip()
        relative_path = Path(relative) if relative else Path()
        if relative_path.is_absolute() or ".." in relative_path.parts:
            raise RuntimeError("A pasta de mídia do personagem é inválida.")
        folder = root / relative_path
        if not folder.is_dir():
            raise RuntimeError(f"A pasta ‘{relative or 'Raiz do personagem'}’ não existe no personagem atual.")
        files = [path for path in folder.iterdir() if path.is_file() and self._is_media_file(path)]
        if not files:
            raise RuntimeError(f"A pasta ‘{relative or 'Raiz do personagem'}’ do personagem atual não possui mídias compatíveis.")
        return random.choice(files), str(relative)

