    def configure_media_processor(self) -> None:
        """Escolhe o único script Python que processará cada mídia enviada."""
        initial_dir = MEDIA_PROCESSING_DIR if MEDIA_PROCESSING_DIR.is_dir() else APP_DIR
        chosen = filedialog.askopenfilename(
            parent=self, title="Escolher script de processamento de mídia", initialdir=initial_dir,
            filetypes=[("Scripts Python", "*.py")],
        )
        if not chosen:
            return
        script = Path(chosen)
        self.settings["media_processor_script"] = str(script)
        self._save_settings()
        self.status.set(f"Processador de mídias configurado: {script.name}. Ele receberá a pasta da mídia com --dir.")

    def _media_processor_script(self) -> Path:
        configured = str(self.settings.get("media_processor_script", "")).strip()
        script = Path(configured).expanduser() if configured else None
        if not script or not script.is_file() or script.suffix.casefold() != ".py":
            raise RuntimeError("Nenhum script de mídia válido está configurado. Use ‘Configurar script de mídia’ e escolha um arquivo .py.")
        return script

    @staticmethod
    def _is_media_file(path: Path) -> bool:
        return path.suffix.casefold() in {".jpg", ".jpeg", ".png", ".webp", ".gif", ".heic", ".heif", ".mp4", ".mov", ".mkv", ".webm", ".3gp", ".avi", ".m4v"}

    def _publish_media_to_gallery(self, adb: Adb, remote_path: str) -> bool:
        """Publica uma mídia enviada no MediaStore do Android.

        Alguns aparelhos, em especial com Galeria própria, ignoram ou atrasam o
        broadcast do Media Scanner para vídeos enviados por ADB. Primeiro
        usamos a varredura padrão e, se ela não registrar o arquivo, pedimos
        uma inserção explícita na coleção de imagens/vídeos do MediaStore.
        Falhas aqui não anulam o envio do arquivo ao aparelho.
        """
        remote_path = str(remote_path)
        suffix = Path(remote_path).suffix.casefold()
        video_types = {
            ".mp4": "video/mp4", ".mov": "video/quicktime", ".mkv": "video/x-matroska",
            ".webm": "video/webm", ".3gp": "video/3gpp", ".avi": "video/x-msvideo", ".m4v": "video/x-m4v",
        }
        image_types = {
            ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".png": "image/png", ".webp": "image/webp",
            ".gif": "image/gif", ".heic": "image/heic", ".heif": "image/heif",
        }
        is_video = suffix in video_types
        mime_type = video_types.get(suffix, image_types.get(suffix, "application/octet-stream"))
        collection = "content://media/external/video/media" if is_video else "content://media/external/images/media"
        # Evita que uma marca .nomedia deixada por algum app impeça a Galeria
        # de considerar a pasta inteira.
        try:
            adb.command("shell", "rm", "-f", "/sdcard/Pictures/iggen/.nomedia", timeout=10)
        except RuntimeError:
            pass
        try:
            adb.command("shell", "am", "broadcast", "-a", "android.intent.action.MEDIA_SCANNER_SCAN_FILE",
                        "-d", "file:///sdcard/Pictures/iggen/" + quote(Path(remote_path).name), timeout=20)
        except RuntimeError:
            pass
        # Em Androids recentes o scanner pode responder ao broadcast mas não
        # criar a linha no MediaStore. Consultamos a coleção certa e fazemos
        # o registro explícito somente quando ele ainda não existir.
        try:
            found = adb.command("shell", "content", "query", "--uri", collection,
                                "--where", f"_data='{remote_path}'", timeout=12)
            if "Row:" in found or "_data=" in found:
                return True
        except RuntimeError:
            pass
        try:
            adb.command("shell", "content", "insert", "--uri", collection,
                        "--bind", f"_data:s:{remote_path}",
                        "--bind", f"_display_name:s:{Path(remote_path).name}",
                        "--bind", f"mime_type:s:{mime_type}", timeout=15)
            return True
        except RuntimeError:
            return False

    def _processed_media_folder(self, source: Path) -> Path:
        safe_name = re.sub(r"[^\w.-]+", "_", source.stem, flags=re.UNICODE).strip("._") or "midia"
        fingerprint = hashlib.sha1(str(source.resolve()).encode("utf-8", "replace")).hexdigest()[:10]
        return PROCESSED_MEDIA_DIR / f"{safe_name}_{fingerprint}"

    def _process_selected_media(self, sources: list[str]) -> dict[str, str]:
        """Processa cada mídia em sua própria pasta e devolve o caminho final."""
        processor = self._media_processor_script()
        processed: dict[str, str] = {}
        for raw_source in dict.fromkeys(sources):
            source = Path(raw_source).expanduser()
            if not source.is_file():
                raise RuntimeError(f"Mídia selecionada não encontrada: {source}")
            if not self._is_media_file(source):
                raise RuntimeError(f"O processador aceita apenas fotos e vídeos: {source.name}")
            folder = self._processed_media_folder(source)
            folder.mkdir(parents=True, exist_ok=True)
            control_path = folder / "controle.json"
            # A pasta pertence somente a esta mídia. Limpa uma tentativa anterior
            # para os dois scripts receberem exatamente um arquivo de entrada.
            for candidate in folder.iterdir():
                if candidate.is_file() and candidate.name != "controle.json":
                    candidate.unlink()
            copied = folder / source.name
            shutil.copy2(source, copied)
            control_path.write_text(json.dumps({
                "original": str(source.resolve()), "arquivo_entrada": copied.name,
                "processado_em": datetime.now().isoformat(timespec="seconds"), "status": "processando",
            }, ensure_ascii=False, indent=2), encoding="utf-8")
            processor_env = os.environ.copy()
            # Os scripts externos imprimem caracteres Unicode. Sem isto, o
            # Python do Windows pode usar cp1252 e encerrar no meio da limpeza.
            processor_env.update({"PYTHONIOENCODING": "utf-8", "PYTHONUTF8": "1"})
            command = [sys.executable, str(processor), "--dir", str(folder), "--no-pause"]
            run = subprocess.run(command, cwd=str(processor.parent), capture_output=True, text=True,
                                 encoding="utf-8", errors="replace", timeout=1800, env=processor_env,
                                 creationflags=NO_CONSOLE)
            if run.returncode:
                detail = (run.stderr or run.stdout or "sem detalhes").strip()[-600:]
                raise RuntimeError(f"{processor.name} falhou para {source.name}: {detail}")
            results = [path for path in folder.iterdir() if path.is_file() and self._is_media_file(path)]
            if len(results) != 1:
                raise RuntimeError(f"Não consegui identificar uma única mídia final para {source.name}.")
            final = results[0]
            control_path.write_text(json.dumps({
                "original": str(source.resolve()), "arquivo_entrada": copied.name,
                "arquivo_processado": str(final), "status": "concluído",
                "processado_em": datetime.now().isoformat(timespec="seconds"),
            }, ensure_ascii=False, indent=2), encoding="utf-8")
            processed[str(source)] = str(final)
        return processed

